package com.flippingrs;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.HashSet;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The history screen is read off widgets with no ids and no times, so what
 * matters is that a row yields all four facts or nothing, never a half-read
 * trade.
 */
public class GeHistoryReaderTest
{
	private final List<Widget> children = new ArrayList<>();

	private Widget item(int y, int itemId, int quantity)
	{
		final Widget w = mock(Widget.class);
		when(w.getRelativeY()).thenReturn(y);
		when(w.getItemId()).thenReturn(itemId);
		when(w.getItemQuantity()).thenReturn(quantity);
		when(w.getText()).thenReturn("");
		children.add(w);
		return w;
	}

	private Widget text(int y, String text)
	{
		final Widget w = mock(Widget.class);
		when(w.getRelativeY()).thenReturn(y);
		when(w.getItemId()).thenReturn(-1);
		when(w.getText()).thenReturn(text);
		children.add(w);
		return w;
	}

	/** The same widget, but hidden, which is how the client retires a row. */
	private static Widget hide(Widget w)
	{
		when(w.isSelfHidden()).thenReturn(true);
		return w;
	}

	private Widget list()
	{
		final Widget list = mock(Widget.class);
		when(list.getDynamicChildren()).thenReturn(children.toArray(new Widget[0]));
		return list;
	}

	private static String name(int id)
	{
		return id == 4151 ? "Abyssal whip" : "Item " + id;
	}

	/**
	 * A row keeps its own sprite when another row's has come loose.
	 *
	 * <p>A row whose texts are all hidden leaves its sprite with no line of
	 * its own, and the nearest line it can find is the next row's. That row's
	 * own sprite is nearer still, and is the one it must keep -- taking the
	 * loose one instead reports a trade against an item the player never
	 * touched, which is worse than the row being skipped.
	 */
	@Test
	public void aRowKeepsItsOwnSpriteWhenAnotherHasComeLoose()
	{
		// Whichever order the two sprites arrive in: the widget list is the
		// client's, and which of them comes first is not something to rely on.
		for (boolean looseFirst : new boolean[]{true, false})
		{
			children.clear();
			if (looseFirst)
			{
				// This row's texts are all hidden, so there is no line at 0 for
				// its sprite to belong to.
				item(10, 5280, 1);
			}
			// And this row is whole, sprite and all.
			text(40, "Bought:");
			text(40, "Toadflax seedx 8");
			text(40, "8,760 coins= 1,095 each");
			item(50, 5297, 1);
			if (!looseFirst)
			{
				item(10, 5280, 1);
			}

			final List<HistoryRow> rows =
				GeHistoryReader.read(list(), GeHistoryReaderTest::name);

			final String order = looseFirst ? "loose sprite first" : "loose sprite last";
			assertEquals(order, 1, rows.size());
			assertEquals(order + ": the row's own sprite, not the loose one",
				5297, rows.get(0).itemId);
			assertEquals(order, 8L, rows.get(0).quantity);
		}
	}

	/**
	 * A damaged screen yields rows that are right or rows that are missing,
	 * never rows that are a mixture.
	 *
	 * <p>The other property test builds screens the client would really draw
	 * and requires every row back exactly. This one breaks them on purpose --
	 * a row with its texts hidden, a row with no sprite, a row missing one of
	 * its three texts -- because that is where the reader has to choose, and a
	 * wrong choice does not look like a failure. A row read with another row's
	 * item has an item, a side, a quantity and a price, every one of them
	 * read, and goes to the server as a trade that never happened.
	 *
	 * <p>So rows are allowed to go missing and are not allowed to be invented:
	 * whatever comes back has to match one of the rows actually on the screen,
	 * every field at once. Item ids are unique per run so that a row wearing
	 * another's cannot pass as itself.
	 */
	@Test
	public void aDamagedScreenNeverYieldsARowThatIsAMixtureOfTwo()
	{
		final java.util.Random random = new java.util.Random(20260905L);
		for (int run = 0; run < 500; run++)
		{
			children.clear();
			final Set<String> onScreen = new HashSet<>();

			final int rows = 2 + random.nextInt(6);
			for (int row = 0; row < rows; row++)
			{
				final int y = row * 40;
				// Unique within the run, so a row cannot wear another's id and
				// still look like itself.
				final int itemId = 4151 + row;
				final boolean buy = random.nextBoolean();
				final long quantity = 2 + random.nextInt(500);
				final long each = 1 + random.nextInt(100_000);
				final long gross = quantity * each;
				final String itemName = ITEM_NAMES[random.nextInt(ITEM_NAMES.length)];

				// Every row on a real screen has its sprite, so every row here
				// keeps one. What varies is the texts: 0 whole, 1 all of them
				// hidden -- which leaves the sprite with no line of its own and
				// looking for the next row's -- and 2 one of them hidden, which
				// is a row the reader has to give up on.
				final int damage = random.nextInt(3);

				item(y + random.nextInt(16), itemId, 1);

				final Widget side = text(y, buy ? "Bought:" : "Sold:");
				final Widget named = text(y, itemName + "x " + group(quantity, random));
				final Widget price = text(y, group(gross, random) + " coins");
				if (damage == 1)
				{
					hide(side);
					hide(named);
					hide(price);
				}
				else if (damage == 2)
				{
					hide(random.nextBoolean() ? side : price);
				}

				onScreen.add(itemId + "/" + (buy ? "buy" : "sell") + "/" + quantity + "/" + gross);
			}

			final List<HistoryRow> read =
				GeHistoryReader.read(list(), GeHistoryReaderTest::name);

			assertTrue("run " + run + ": more rows than the screen had", read.size() <= rows);
			for (int i = 0; i < read.size(); i++)
			{
				final HistoryRow got = read.get(i);
				final String actual = got.itemId + "/" + got.side + "/" + got.quantity + "/" + got.grossValue;
				assertTrue("run " + run + ": this row is on no line of the screen: " + actual,
					onScreen.contains(actual));
				assertEquals("run " + run + ": positions run in order", i, got.position);
			}
		}
	}

	/**
	 * The screen as a live client actually lays it out: the icon on its own
	 * line, then "Sold:", the name with "x N" glued on, and a price with the
	 * tax breakdown. The gp sent is the figure before tax.
	 */
	@Test
	public void theRealLayoutIsReadWithTheGrossBeforeTax()
	{
		item(10, 5280, 1);
		text(0, "Sold:");
		text(0, "Irit seedx 6");
		text(0, "438 coins(444 - 6)= 73 each");
		item(50, 5297, 1);
		text(40, "Bought:");
		text(40, "Toadflax seedx 8");
		text(40, "8,760 coins= 1,095 each");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(2, rows.size());
		assertEquals(5280, rows.get(0).itemId);
		assertEquals("sell", rows.get(0).side);
		assertEquals(6L, rows.get(0).quantity);
		assertEquals("before tax: 444, not the 438 collected", 444L, rows.get(0).grossValue);
		assertEquals(5297, rows.get(1).itemId);
		assertEquals("buy", rows.get(1).side);
		assertEquals(8L, rows.get(1).quantity);
		assertEquals(8_760L, rows.get(1).grossValue);
	}

	/**
	 * The second thing a live client showed: an icon listed after its texts,
	 * and a single item with no count on its name at all. Neither order nor
	 * the count may be assumed.
	 */
	@Test
	public void iconsMayFollowTheirTextsAndASingleItemHasNoCount()
	{
		text(0, "Sold:");
		text(0, "Ruby bolts (e)");
		item(8, 9242, 1);
		text(0, "1,500 coins(1,530 - 30)= 1,530 each");
		item(48, 5296, 1);
		text(40, "Sold:");
		text(40, "Toadflax seedx 8");
		text(40, "8,760 coins(8,936 - 176)= 1,095 each");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(2, rows.size());
		assertEquals(9242, rows.get(0).itemId);
		assertEquals(1L, rows.get(0).quantity);
		assertEquals(1_530L, rows.get(0).grossValue);
		assertEquals(5296, rows.get(1).itemId);
		assertEquals(8L, rows.get(1).quantity);
		assertEquals(8_936L, rows.get(1).grossValue);
	}

	/** An icon with no line near it belongs to nothing, and a line with no icon has no item. */
	@Test
	public void anIconFarFromEveryLineIsNotForcedOntoOne()
	{
		item(200, 4151, 10);
		text(0, "Bought:");
		text(0, "Abyssal whipx 10");
		text(0, "15,000,000 coins= 1,500,000 each");

		assertTrue(GeHistoryReader.read(list(), GeHistoryReaderTest::name).isEmpty());
	}

	/** With no "x N" and no stack, the quantity is the total over the per-item price. */
	@Test
	public void theQuantityFallsBackToTheTotalOverThePerItemPrice()
	{
		item(0, 4151, 0);
		text(0, "Bought:");
		text(0, "Abyssal whip");
		text(0, "4,500,000 coins= 1,500,000 each");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(3L, rows.get(0).quantity);
	}

	@Test
	public void rowsAreReadTopToBottomWithAllFourFacts()
	{
		item(0, 4151, 10);
		text(0, "Bought");
		text(0, "<col=ff981f>Abyssal whip</col>");
		text(0, "15,000,000 coins");
		item(40, 4151, 3);
		text(40, "Sold");
		text(40, "4,560,000 coins");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(2, rows.size());
		assertEquals(0, rows.get(0).position);
		assertEquals(4151, rows.get(0).itemId);
		assertEquals("Abyssal whip", rows.get(0).itemName);
		assertEquals("buy", rows.get(0).side);
		assertEquals(10L, rows.get(0).quantity);
		assertEquals(15_000_000L, rows.get(0).grossValue);
		assertEquals(1, rows.get(1).position);
		assertEquals("sell", rows.get(1).side);
		assertEquals(3L, rows.get(1).quantity);
		assertEquals(4_560_000L, rows.get(1).grossValue);
	}

	/** A quantity written in the text rather than on the icon still counts. */
	@Test
	public void aQuantityInTheTextIsUsedWhenTheIconHasNone()
	{
		item(0, 4151, 1);
		text(0, "Bought x 25");
		text(0, "37,500,000 coins");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(25L, rows.get(0).quantity);
	}

	/** Without a "coins" label the price is the largest number on the line. */
	@Test
	public void thePriceFallsBackToTheLargestNumberOnTheLine()
	{
		item(0, 4151, 10);
		text(0, "Sold 10");
		text(0, "15,000,000");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(15_000_000L, rows.get(0).grossValue);
	}

	/**
	 * A row whose price is missing must be skipped, not have its item count
	 * read as one. The largest-number fallback is for a layout that writes the
	 * price without the word "coins"; a layout that puts the price somewhere
	 * else entirely leaves the count as the only number on the line, and
	 * "Abyssal whipx 10" must not become ten whips for ten coins -- all four
	 * facts present, every one of them read, and the trade wrong.
	 */
	@Test
	public void aRowWithNoPriceIsNotGivenItsQuantityAsOne()
	{
		item(0, 4151, 10);
		text(0, "Bought");
		text(0, "Abyssal whipx 10");

		assertTrue("a row with no price is not a trade",
			GeHistoryReader.read(list(), GeHistoryReaderTest::name).isEmpty());
	}

	/**
	 * No count on the name, no stack on the icon and no per-item price: one
	 * item is the only reading left, and the row is a real trade that must not
	 * be dropped for want of a number the screen never wrote.
	 */
	@Test
	public void aRowWithNoCountAnywhereIsOneItem()
	{
		item(0, 4151, 1);
		text(0, "Bought");
		text(0, "Abyssal whip");
		text(0, "1,500,000 coins");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(1, rows.size());
		assertEquals(1L, rows.get(0).quantity);
		assertEquals(1_500_000L, rows.get(0).grossValue);
	}

	/**
	 * A row scrolled out of view is still in the widget list, and reads
	 * perfectly well. Reading it would send the site a trade the screen was
	 * not showing.
	 */
	@Test
	public void aRowScrolledOutOfViewIsNotRead()
	{
		hidden(item(0, 4151, 10));
		hidden(text(0, "Bought"));
		hidden(text(0, "15,000,000 coins"));

		assertTrue("a row nobody can see is not on the screen",
			GeHistoryReader.read(list(), GeHistoryReaderTest::name).isEmpty());
	}

	private static Widget hidden(Widget w)
	{
		when(w.isSelfHidden()).thenReturn(true);
		return w;
	}

	/**
	 * Without a side there is no trade, whatever else the row says. The case
	 * below skips its bad row for want of a price; this one has a price and a
	 * count and still cannot say whether the gp came in or went out.
	 */
	@Test
	public void aRowThatDoesNotSayBoughtOrSoldIsSkipped()
	{
		item(0, 4151, 10);
		text(0, "Abyssal whipx 10");
		text(0, "15,000,000 coins");

		assertTrue("a row that cannot say which way the gp went is not a trade",
			GeHistoryReader.read(list(), GeHistoryReaderTest::name).isEmpty());
	}

	/** A row missing a side or a price is skipped, not sent half-read. */
	@Test
	public void anUnreadableRowIsSkippedNotGuessed()
	{
		item(0, 4151, 10);
		text(0, "Abyssal whip");
		item(40, 4151, 2);
		text(40, "Bought");
		text(40, "3,000,000 coins");

		final List<HistoryRow> rows = GeHistoryReader.read(list(), GeHistoryReaderTest::name);

		assertEquals(1, rows.size());
		assertEquals("the one good row is first, since the bad one was not numbered", 0, rows.get(0).position);
		assertEquals(2L, rows.get(0).quantity);
	}

	@Test
	public void anEmptyOrMissingListIsNoRows()
	{
		assertTrue(GeHistoryReader.read(null, GeHistoryReaderTest::name).isEmpty());
		assertTrue(GeHistoryReader.read(list(), GeHistoryReaderTest::name).isEmpty());
	}

	/**
	 * The plugin warns when a screen with items on it yields no rows, since
	 * that means the layout has changed under the reader. An empty history
	 * must not trip that, or every new player would see the warning.
	 */
	@Test
	public void aScreenWithIconsShowsItemsAndAnEmptyOneDoesNot()
	{
		assertFalse(GeHistoryReader.showsItems(null));
		assertFalse("no children at all", GeHistoryReader.showsItems(list()));

		text(0, "You have no Grand Exchange history.");
		assertFalse("text but no item icon", GeHistoryReader.showsItems(list()));

		item(10, 4151, 1);
		assertTrue(GeHistoryReader.showsItems(list()));
	}
	/**
	 * Any screenful of well-formed rows is read back exactly: the same items,
	 * the same sides, the same counts, the same gp before tax, in the same
	 * order.
	 *
	 * <p>The cases above each pin one decision. This one varies everything the
	 * screen is allowed to vary -- whether the icon comes before or after its
	 * texts and how far below them it sits, whether the count is written on the
	 * name or left to the icon's stack, whether the side has a colon, whether
	 * the price carries a tax breakdown, whether the numbers are written with
	 * separators, and whether the name is wrapped in colour tags -- because a
	 * reader built out of regular expressions goes wrong on combinations rather
	 * than on cases, and a wrong row here is a wrong trade in a journal.
	 */
	@Test
	public void anyWellFormedScreenIsReadBackExactly()
	{
		final java.util.Random random = new java.util.Random(20260903L);
		for (int run = 0; run < 2000; run++)
		{
			children.clear();
			final List<long[]> expected = new ArrayList<>();

			final int rows = 1 + random.nextInt(8);
			for (int row = 0; row < rows; row++)
			{
				// Rows sit forty apart, and an icon belongs to the line it is
				// nearest to, so it stays well inside half that.
				final int y = row * 40;
				final int itemId = 4151 + random.nextInt(50);
				final boolean buy = random.nextBoolean();
				final long each = 1 + random.nextInt(2_000_000);
				// One of the three ways the screen can say how many: written on
				// the name, left to the icon's stack, or only implied by the
				// total over the per-item price. Exactly one per row, so a row
				// cannot be read right by a path this one was not testing.
				final int says = random.nextInt(3);
				final long quantity = says == 1 ? 2 + random.nextInt(999) : 1 + random.nextInt(1000);
				final long gross = quantity * each;
				final long tax = buy ? 0 : Math.min(gross - 1, random.nextInt(1000));

				// "Toadflax" ends in an x, which is exactly what the count is
				// written with, so it belongs in here.
				final String itemName = ITEM_NAMES[random.nextInt(ITEM_NAMES.length)];

				// Rows sit forty apart, and an icon belongs to the line it is
				// nearest to, so it stays well inside half that.
				final Widget icon = item(y + random.nextInt(16), itemId,
					says == 1 ? (int) quantity : 1);
				final boolean iconAfterItsTexts = random.nextBoolean();
				if (iconAfterItsTexts)
				{
					children.remove(icon);
				}

				text(y, (buy ? "Bought" : "Sold") + (random.nextBoolean() ? ":" : ""));
				final String named = itemName + (says == 0 ? "x " + group(quantity, random) : "");
				text(y, random.nextBoolean() ? "<col=ff981f>" + named + "</col>" : named);
				final String perItem = says == 2 ? "= " + group(each, random) + " each" : "";
				text(y, buy
					? group(gross, random) + " coins" + perItem
					: group(gross - tax, random) + " coins(" + group(gross, random) + " - "
						+ group(tax, random) + ")" + perItem);

				if (iconAfterItsTexts)
				{
					children.add(icon);
				}
				expected.add(new long[]{itemId, buy ? 1 : 0, quantity, gross});
			}

			final List<HistoryRow> read =
				GeHistoryReader.read(list(), GeHistoryReaderTest::name);

			assertEquals("run " + run + ": every row must be read", expected.size(), read.size());
			for (int i = 0; i < expected.size(); i++)
			{
				final long[] want = expected.get(i);
				final HistoryRow got = read.get(i);
				final String where = "run " + run + ", row " + i;
				assertEquals(where + ": item", want[0], got.itemId);
				assertEquals(where + ": side", want[1] == 1 ? "buy" : "sell", got.side);
				assertEquals(where + ": quantity", want[2], got.quantity);
				assertEquals(where + ": gp before tax", want[3], got.grossValue);
				assertEquals(where + ": position", i, got.position);
			}
		}
	}

	private static final String[] ITEM_NAMES = {
		"Abyssal whip", "Toadflax seed", "Ruby bolts (e)", "Zulrah's scales", "Xerician fabric",
	};

	/** A number as the screen might write it, with or without separators. */
	private static String group(long n, java.util.Random random)
	{
		return random.nextBoolean() ? String.format(java.util.Locale.ROOT, "%,d", n) : Long.toString(n);
	}
}

package com.flippingrs;

import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.annotation.Nullable;

/**
 * A {@link PanelActions} whose hooks a test can replace one at a time.
 *
 * <p>The panel takes its actions in the constructor, so a test that only cares
 * about one button still has to supply the rest. Every field here starts as a
 * no-op and a test assigns the one it wants to watch, which keeps a panel test
 * about the panel rather than about the eleven things it is not exercising.
 */
final class TestPanelActions implements PanelActions
{
	Runnable sendNow = () ->
	{
	};
	Runnable retrySetAside = () ->
	{
	};
	Runnable reconnect = () ->
	{
	};
	Runnable accountChosen = () ->
	{
	};
	Runnable watchlistChosen = () ->
	{
	};
	IntConsumer openItem = id ->
	{
	};
	IntConsumer removeItem = id ->
	{
	};
	Runnable findFlips = () ->
	{
	};
	Close closePosition = (id, price, qty) ->
	{
	};
	Consumer<String> deletePosition = id ->
	{
	};
	Runnable shown = () ->
	{
	};
	Runnable hidden = () ->
	{
	};

	/** The close hook, with the panel's own three arguments. */
	interface Close
	{
		void close(String positionId, long sellPrice, @Nullable Long sellQty);
	}

	@Override
	public void sendNow()
	{
		sendNow.run();
	}

	@Override
	public void retrySetAside()
	{
		retrySetAside.run();
	}

	@Override
	public void reconnect()
	{
		reconnect.run();
	}

	@Override
	public void accountChosen()
	{
		accountChosen.run();
	}

	@Override
	public void watchlistChosen()
	{
		watchlistChosen.run();
	}

	@Override
	public void openItem(int itemId)
	{
		openItem.accept(itemId);
	}

	@Override
	public void removeItem(int itemId)
	{
		removeItem.accept(itemId);
	}

	@Override
	public void findFlips()
	{
		findFlips.run();
	}

	@Override
	public void closePosition(String positionId, long sellPrice, @Nullable Long sellQty)
	{
		closePosition.close(positionId, sellPrice, sellQty);
	}

	@Override
	public void deletePosition(String positionId)
	{
		deletePosition.accept(positionId);
	}

	@Override
	public void shown()
	{
		shown.run();
	}

	@Override
	public void hidden()
	{
		hidden.run();
	}
}

package com.flippingrs;

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Getting a price in front of somebody who is looking at the item.
 *
 * <p>The refresh runs every thirty seconds, which is the right cadence for a
 * price that is already on screen and quite the wrong one for a price that is
 * not. Two things put an item on screen with no price against it -- opening a
 * screen the last refresh knew nothing about, and a fetch that failed -- and
 * in both cases waiting out the tick is half a minute of blank, which is
 * indistinguishable from the plugin not working.
 */
public class WatchlistsQuotesTest
{
	private static final int WHIP = 4151;
	private static final long SECOND = TimeUnit.SECONDS.toNanos(1);

	private FlippingRsApi api;
	private Watchlists watchlists;

	/** How long each retry was asked to wait, in the order they were asked. */
	private final List<Long> waits = new ArrayList<>();

	/** Retries waiting to run, so a test can let time pass on purpose. */
	private final Deque<Runnable> pending = new ArrayDeque<>();

	/** Whether the net thread is still there, which a shutdown makes false. */
	private boolean netThreadAlive = true;

	@Before
	public void setUp()
	{
		final FlippingRsConfig config = mock(FlippingRsConfig.class);
		when(config.setupOverlay()).thenReturn(true);
		when(config.apiKey()).thenReturn("a-key");
		api = mock(FlippingRsApi.class);

		watchlists = new Watchlists(mock(Client.class), mock(ItemManager.class), mock(ClientThread.class),
			config, mock(ProfileStore.class), () -> api, action ->
		{
		}, id -> "Abyssal whip", () ->
		{
		},
			// The net thread, run inline: these tests are about which
			// requests get made and when, not about which thread makes them.
			Runnable::run,
			(wait, work) ->
			{
				waits.add(wait);
				if (netThreadAlive)
				{
					pending.add(work);
				}
				return netThreadAlive;
			},
			id ->
			{
			});
		watchlists.exchangeOpen(true);
	}

	/** Lets every retry that has been scheduled run, and whatever they schedule. */
	private void letTimePass()
	{
		while (!pending.isEmpty())
		{
			pending.poll().run();
		}
	}

	private void showing(int... itemIds)
	{
		final Set<Integer> items = new HashSet<>();
		for (int itemId : itemIds)
		{
			items.add(itemId);
		}
		watchlists.showingOffers(items);
	}

	private void serverAnswers(int itemId) throws IOException
	{
		final Quote quote = new Quote();
		quote.id = itemId;
		quote.instantSell = 1_480_000;
		quote.instantBuy = 1_520_000;
		final PanelData data = new PanelData();
		data.quotes = Collections.singletonList(quote);
		// doReturn rather than when(...), because these tests re-stub a mock
		// that is currently set to throw, and when(...) would call it to find
		// out what to stub -- and be thrown at.
		doReturn(data).when(api).quotes(anyString(), any(), any());
	}

	private void serverIsDown() throws IOException
	{
		doThrow(new IOException("connection reset")).when(api).quotes(anyString(), any(), any());
	}

	/**
	 * A screen with an item nobody has a price for is asked about now rather
	 * than on the next refresh.
	 */
	@Test
	public void openingAScreenWithSomethingUnpricedAsksAtOnce() throws IOException
	{
		serverAnswers(WHIP);

		showing(WHIP);

		verify(api, times(1)).quotes(anyString(), any(), any());
	}

	/**
	 * And a screen whose items are already priced is not, because the price on
	 * it is the one the refresh is already keeping current.
	 */
	@Test
	public void aScreenOfItemsAlreadyPricedCostsNothing() throws IOException
	{
		serverAnswers(WHIP);
		showing(WHIP);

		// The same item again, arrived at from somewhere else in the exchange.
		showing();
		showing(WHIP);

		verify(api, times(1)).quotes(anyString(), any(), any());
	}

	/**
	 * A fetch that fails is tried again, waiting longer each time.
	 *
	 * <p>The failures worth retrying are a dropped connection, which clears in
	 * a second, and a server coming back up, which takes closer to a minute.
	 * Doubling covers both without hammering one that is properly down.
	 */
	@Test
	public void aFailedFetchIsTriedAgain() throws IOException
	{
		serverIsDown();

		showing(WHIP);
		letTimePass();

		assertEquals(Arrays.asList(2 * SECOND, 4 * SECOND, 8 * SECOND), waits);
		verify(api, times(4)).quotes(anyString(), any(), any());
	}

	/**
	 * And then it gives up, leaving the ordinary refresh to it. A server that
	 * is down costs a few requests rather than a client hammering it for the
	 * rest of the session.
	 */
	@Test
	public void andThenLeavesItToTheRefresh() throws IOException
	{
		serverIsDown();
		showing(WHIP);
		letTimePass();
		waits.clear();

		// The refresh comes round, fails, and gets its own tries -- a run of
		// failures must not leave the retry spent for the whole session.
		watchlists.fetchOnDemand();
		letTimePass();

		assertEquals(Arrays.asList(2 * SECOND, 4 * SECOND, 8 * SECOND), waits);
	}

	/** A fetch that works puts the allowance back for whatever fails next. */
	@Test
	public void oneThatWorksRestoresTheAllowance() throws IOException
	{
		serverIsDown();
		showing(WHIP);
		pending.poll().run();
		waits.clear();

		serverAnswers(WHIP);
		watchlists.fetchOnDemand();
		pending.clear();

		serverIsDown();
		watchlists.fetchOnDemand();
		letTimePass();

		assertEquals("three again, not the one that was left",
			Arrays.asList(2 * SECOND, 4 * SECOND, 8 * SECOND), waits);
	}

	/**
	 * A retry scheduled into a thread that has already stopped is a shutdown,
	 * not a failure: nothing is left half-counted for a plugin that is not
	 * going to run again.
	 */
	@Test
	public void aShutdownMidRetryIsNotAFailedTry() throws IOException
	{
		serverIsDown();
		netThreadAlive = false;

		showing(WHIP);

		assertEquals("asked once, and told the thread was gone", 1, waits.size());
		verify(api, times(1)).quotes(anyString(), any(), any());
	}
}

package com.flippingrs;

import com.google.gson.Gson;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The closed-positions part, parsed from what flippingrs.com actually sends.
 *
 * <p>Every other test here builds the objects directly, which proves the panel
 * draws what it is given and proves nothing at all about whether the server
 * gives it that. A field renamed on either side would leave those tests green
 * and the tab empty -- the same shape of failure as a plugin whose tests
 * encoded its own wrong assumption about how examine works, and which passed
 * for exactly as long as nobody ran it.
 *
 * <p>So the JSON below is copied from a live reply rather than composed here.
 */
public class ClosedPositionsWireTest
{
	/** A reply from the server, verbatim. */
	private static final String REPLY = "{"
		+ "\"closedPositions\": {"
		+ "  \"positions\": [{"
		+ "    \"id\": \"lZxYhBMnKbenJaFddWcjMQ\", \"itemId\": 4151, \"itemName\": \"Abyssal whip\","
		+ "    \"buyPrice\": 1480000, \"buyQty\": 10, \"sellPrice\": 1520000, \"sellQty\": 10,"
		+ "    \"taxPaid\": 304000, \"netProfit\": 96000, \"roi\": 0.006486486486486486,"
		+ "    \"hoursHeld\": 167, \"timesKnown\": true"
		+ "  }],"
		+ "  \"summary\": { \"closedPositions\": 3, \"realisedProfit\": 73800, \"taxPaid\": 308200 }"
		+ "}}";

	private static PanelData parse(String json)
	{
		return new Gson().fromJson(json, PanelData.class);
	}

	/** Every field the card reads, off the wire. */
	@Test
	public void aClosedLotArrivesWithEverythingTheCardShows()
	{
		final ClosedPositions closed = parse(REPLY).getClosedPositions();
		assertEquals(1, closed.getPositions().size());
		final ClosedPosition whip = closed.getPositions().get(0);

		assertEquals("lZxYhBMnKbenJaFddWcjMQ", whip.getId());
		assertEquals(4151, whip.getItemId());
		assertEquals("Abyssal whip", whip.getItemName());
		assertEquals(1_480_000, whip.getBuyPrice());
		assertEquals(10, whip.getBuyQty());
		assertEquals(1_520_000, whip.getSellPrice());
		assertEquals(10, whip.getSellQty());
		assertEquals(304_000, whip.getTaxPaid());
		assertEquals("after tax, which is most of the gross here",
			96_000, whip.getNetProfit());
		assertEquals(0.006486486486486486, whip.getRoi(), 1e-12);
		assertEquals("hours, as a number that may or may not have a fraction",
			167d, whip.getHoursHeld(), 1e-9);
		assertTrue(whip.isTimesKnown());

		assertEquals("Bought 1,480,000 · Sold 1,520,000", FlippingRsPanel.closedPrices(whip));
		assertEquals("10 sold · held 6d 23h", FlippingRsPanel.closedHeld(whip));
		assertEquals("P&L +96,000 (0.6%) · tax 304,000", FlippingRsPanel.closedResult(whip));
	}

	/** The totals are of the rows sent, and they reconcile against them. */
	@Test
	public void theSummaryDescribesTheRowsUnderIt()
	{
		final ClosedPositions.Summary totals = parse(REPLY).getClosedPositions().getSummary();

		assertEquals(3, totals.getClosedPositions());
		assertEquals(73_800, totals.getRealisedProfit());
		assertEquals(308_200, totals.getTaxPaid());
	}

	/**
	 * A loss keeps its sign, through the row and through the total.
	 *
	 * <p>The card is red or green on this one number, and an absolute value
	 * would paint a losing flip as a winning one.
	 */
	@Test
	public void aLossStaysNegative()
	{
		final String json = "{\"closedPositions\": {\"positions\": [{"
			+ "\"itemId\": 5296, \"itemName\": \"Ranarr seed\","
			+ "\"buyPrice\": 40000, \"buyQty\": 5, \"sellPrice\": 36000, \"sellQty\": 5,"
			+ "\"taxPaid\": 3600, \"netProfit\": -24000, \"roi\": -0.109,"
			+ "\"hoursHeld\": 3, \"timesKnown\": true}],"
			+ "\"summary\": {\"closedPositions\": 1, \"realisedProfit\": -24000, \"taxPaid\": 3600}}}";

		final ClosedPositions closed = parse(json).getClosedPositions();

		assertEquals(-24_000, closed.getPositions().get(0).getNetProfit());
		assertEquals(-24_000, closed.getSummary().getRealisedProfit());
		assertEquals("P&L -24,000 (-10.9%) · tax 3,600",
			FlippingRsPanel.closedResult(closed.getPositions().get(0)));
	}

	/**
	 * A flip the plugin found already done says so, rather than showing a hold
	 * nobody measured.
	 *
	 * <p>The server floors the duration at zero for these, because both legs
	 * adopted in one batch can land a hair out of order and subtract to a
	 * negative. That makes the field safe, not meaningful -- the card is what
	 * has to be honest about it, and this list is ordered by when a lot sold,
	 * so a recovered lot adopted a moment ago is likely the first card there
	 * is.
	 */
	@Test
	public void aRecoveredFlipSaysWhyItHasNoHold()
	{
		final String json = "{\"closedPositions\": {\"positions\": [{"
			+ "\"itemId\": 561, \"itemName\": \"Nature rune\","
			+ "\"buyPrice\": 100, \"buyQty\": 100, \"sellPrice\": 120, \"sellQty\": 100,"
			+ "\"taxPaid\": 0, \"netProfit\": 1800, \"roi\": 0.18,"
			+ "\"hoursHeld\": 0, \"timesKnown\": false}],"
			+ "\"summary\": {\"closedPositions\": 1, \"realisedProfit\": 1800, \"taxPaid\": 0}}}";

		final ClosedPosition runes = parse(json).getClosedPositions().getPositions().get(0);

		assertFalse(runes.isTimesKnown());
		assertEquals("100 sold · recovered, time unknown", FlippingRsPanel.closedHeld(runes));
		assertEquals("and the profit is still the real one",
			"P&L +1,800 (18.0%)", FlippingRsPanel.closedResult(runes));
	}

	/**
	 * A server with nothing to say leaves the part out, and that is not the
	 * same as a server saying there are none.
	 *
	 * <p>The whole closed section hangs off this: absent hides it, empty says
	 * you have closed nothing. Getting them the same way round would tell
	 * somebody with a year of finished flips that they have never finished
	 * one.
	 */
	@Test
	public void anOlderServerSaysNothingRatherThanNone()
	{
		assertNull("an older flippingrs.com, which has no such part",
			parse("{\"week\": null, \"positions\": null}").getClosedPositions());
		assertNull(parse("{\"closedPositions\": null}").getClosedPositions());

		final ClosedPositions none = parse(
			"{\"closedPositions\": {\"positions\": [], \"summary\": {\"closedPositions\": 0}}}")
			.getClosedPositions();
		assertTrue("but an empty list is an answer", none.getPositions().isEmpty());
		assertEquals("No closed positions yet.", FlippingRsPanel.closedSummaryLine(none));
	}

	/**
	 * A part that arrives without its pieces still answers rather than
	 * throwing, on the same terms as every other wire shape here.
	 */
	@Test
	public void aPartWithoutItsPiecesIsStillAnswerable()
	{
		final ClosedPositions bare = parse("{\"closedPositions\": {}}").getClosedPositions();

		final List<ClosedPosition> positions = bare.getPositions();
		assertTrue(positions.isEmpty());
		assertEquals(0, bare.getSummary().getClosedPositions());
		assertEquals("No closed positions yet.", FlippingRsPanel.closedSummaryLine(bare));
	}
}

package com.flippingrs;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.InvocationTargetException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.List;
import java.util.Random;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The panel is where a wrong answer is silent: it is the only thing telling the
 * user which journal their trades are going to, so a selection that quietly
 * moves is worse than one that visibly fails.
 */
public class FlippingRsPanelTest
{
	private static GameAccount account(String id, String label, boolean isDefault)
	{
		final GameAccount a = new GameAccount();
		a.id = id;
		a.label = label;
		a.isDefault = isDefault;
		return a;
	}

	/** Swing state must be touched on the Swing thread, including in a test. */
	private static void onEdt(Runnable body) throws InterruptedException, InvocationTargetException
	{
		SwingUtilities.invokeAndWait(body);
	}

	// ------------------------------------------------------------ gp format

	/**
	 * String.format follows the JVM's locale. On a machine set to most of
	 * Europe this produced "1,50M", and a decimal comma reads as a thousands
	 * separator -- 1.5M looks like 150M at a glance, in a panel whose entire
	 * job is reporting money.
	 */
	@Test
	public void gpIsFormattedTheSameInEveryLocale()
	{
		final Locale original = Locale.getDefault();
		try
		{
			for (Locale locale : new Locale[]{Locale.UK, Locale.GERMANY, Locale.FRANCE})
			{
				Locale.setDefault(locale);
				assertEquals(locale.toString(), "1.50M", FlippingRsPanel.gp(1_500_000));
				assertEquals(locale.toString(), "2.40B", FlippingRsPanel.gp(2_400_000_000L));
				assertEquals(locale.toString(), "1.5K", FlippingRsPanel.gp(1_500));
			}
		}
		finally
		{
			Locale.setDefault(original);
		}
	}

	@Test
	public void gpKeepsSmallAmountsExact()
	{
		assertEquals("999gp", FlippingRsPanel.gp(999));
		assertEquals("0gp", FlippingRsPanel.gp(0));
		assertEquals("-500gp", FlippingRsPanel.gp(-500));
		// Losses are money too, and the sign has to survive the shortening.
		assertTrue(FlippingRsPanel.gp(-1_500_000).startsWith("-"));
	}

	/**
	 * A journal that has loaded must stop saying it has not. The summary is
	 * written as the reply arrives and then written over by whichever of the
	 * three "nothing to show" lines applies, so the flag saying one has
	 * arrived is what decides which of the two the user reads.
	 */
	@Test
	public void aLoadedJournalStopsSayingNotLoadedYet() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			assertTrue(panel.journalSummaryForTest(), panel.journalSummaryForTest().contains("Not loaded yet"));

			final Analytics week = new Analytics();
			week.completedFlips = 12;
			week.realisedProfit = 1_200_000;
			week.winRate = 0.75;
			final Positions open = new Positions();
			open.positions = new ArrayList<>();
			open.summary = new Positions.Summary();

			panel.setJournal(week, open);

			final String shown = panel.journalSummaryForTest();
			assertTrue("a journal that has arrived must not still say it has not: " + shown,
				!shown.contains("Not loaded"));
			assertTrue(shown, shown.contains("12 flips"));
		});
	}

	/**
	 * The exact points where the shortening changes unit. A formatter goes
	 * wrong on its own boundaries or nowhere, and every one of these is a
	 * figure a person reads as money.
	 */
	@Test
	public void gpChangesUnitAtExactlyTheRightAmounts()
	{
		assertEquals("999gp", FlippingRsPanel.gp(999));
		assertEquals("1.0K", FlippingRsPanel.gp(1_000));
		assertEquals("1.00M", FlippingRsPanel.gp(1_000_000));
		assertEquals("1.00B", FlippingRsPanel.gp(1_000_000_000L));
		// And a count, which shortens on the same boundaries but is not money.
		assertEquals("999", FlippingRsPanel.count(999));
		assertEquals("1.0K", FlippingRsPanel.count(1_000));
		assertEquals("1.0M", FlippingRsPanel.count(1_000_000));
	}

	// ------------------------------------------------------- account picker

	@Test
	public void theCurrentSelectionSurvivesAReload() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			final List<GameAccount> accounts = Arrays.asList(
				account("a1", "Main", true),
				account("a2", "Alt", false));

			panel.setAccounts(accounts, "a2");

			assertEquals("a reconnect must not silently move somebody's journal",
				"a2", panel.selectedAccountId());
		});
	}

	@Test
	public void theDefaultIsChosenWhenNothingIsRemembered() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);

			panel.setAccounts(Arrays.asList(
				account("a1", "Main", false),
				account("a2", "Alt", true)), null);

			assertEquals("a2", panel.selectedAccountId());
		});
	}

	/**
	 * The remembered journal is gone from the list. Selecting the first entry
	 * instead would have the panel naming a journal the plugin is not filing
	 * under, which is the one lie this panel exists to not tell.
	 */
	@Test
	public void aRememberedJournalThatIsGoneSelectsNothing() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			panel.setAccounts(Arrays.asList(
				account("a1", "Main", true),
				account("a2", "Alt", false)), "deleted");
			assertNull(panel.selectedAccountId());
		});
	}

	@Test
	public void anEmptyListSelectsNothingRatherThanGuessing() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			panel.setAccounts(Collections.emptyList(), "a1");
			assertNull(panel.selectedAccountId());
		});
	}

	/**
	 * A malformed row from the server must not take the panel down, and must
	 * not become a selectable entry that cannot be filed against.
	 */
	@Test
	public void rowsWithoutAnIdAreIgnored() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			final List<GameAccount> accounts = new ArrayList<>();
			accounts.add(account(null, "No id", false));
			accounts.add(null);
			accounts.add(account("a2", "Real", false));

			panel.setAccounts(accounts, null);

			assertEquals("a2", panel.selectedAccountId());
		});
	}

	/**
	 * Repopulating a combo box fires a selection event. If that reaches the
	 * listener it looks exactly like the user picking an account, and the
	 * plugin writes the choice back to config on every reconnect -- which is
	 * how a remembered journal silently becomes whichever one sorted first.
	 */
	@Test
	public void reloadingTheListDoesNotLookLikeTheUserChoosing() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			final AtomicInteger chosen = new AtomicInteger();
			actions.accountChosen = chosen::incrementAndGet;

			panel.setAccounts(Arrays.asList(
				account("a1", "Main", true),
				account("a2", "Alt", false)), "a2");

			assertEquals("repopulating is not a user choice", 0, chosen.get());
		});
	}

	@Test
	public void theListenerStillFiresForARealChoice() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			panel.setAccounts(Arrays.asList(
				account("a1", "Main", true),
				account("a2", "Alt", false)), "a1");

			final AtomicInteger chosen = new AtomicInteger();
			actions.accountChosen = chosen::incrementAndGet;
			panel.setSelectedForTest("a2");

			assertEquals(1, chosen.get());
			assertEquals("a2", panel.selectedAccountId());
		});
	}

	// ------------------------------------------------------------- watchlist

	private static Watchlist watchlist(String id, String name)
	{
		final Watchlist w = new Watchlist();
		w.id = id;
		w.name = name;
		return w;
	}

	@Test
	public void theWatchlistRendersTheServersOrder() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);

			panel.setWatchlists(Arrays.asList(watchlist("wl_1", "Plan"), watchlist("wl_2", "Bonds")), "wl_2");
			panel.setWatchlistItems(Arrays.asList(
				new FlippingRsPanel.WatchedItem(11802, "Armadyl godsword", null, 12_000_000, 8, 0, "Buying 1/1 at 12.00M", null),
				new FlippingRsPanel.WatchedItem(4151, "Abyssal whip", null, 1_500_000, 70, 72_000, null, quote(4151))));

			assertEquals("wl_2", panel.selectedWatchlistId());
			assertEquals(Arrays.asList(11802, 4151), panel.watchlistForTest());

			panel.setWatchlistItems(Collections.emptyList());
			assertTrue(panel.watchlistForTest().isEmpty());
		});
	}

	/** A fill on a watched item touches only that card's offer line. */
	@Test
	public void aWatchedItemsOfferLineIsUpdatedInPlace() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			panel.setWatchlists(Arrays.asList(watchlist("wl_1", "Plan")), "wl_1");
			panel.setWatchlistItems(Arrays.asList(
				new FlippingRsPanel.WatchedItem(4151, "Abyssal whip", null, 0, 0, 0, "Buying 4/10 at 1.50M", null),
				new FlippingRsPanel.WatchedItem(11802, "Armadyl godsword", null, 0, 0, 0, null, null)));

			panel.updateWatchedOffer(4151, "Buying 6/10 at 1.50M");
			assertEquals("Buying 6/10 at 1.50M", panel.watchlistOfferForTest(4151));

			panel.updateWatchedOffer(11802, "Selling 1/1 at 12.00M");
			assertEquals("Selling 1/1 at 12.00M", panel.watchlistOfferForTest(11802));

			panel.updateWatchedOffer(4151, null);
			assertNull(panel.watchlistOfferForTest(4151));
			assertEquals("the list itself is untouched", Arrays.asList(4151, 11802), panel.watchlistForTest());
		});
	}

	/** Recording off shows why the tabs are empty, until data arrives again. */
	@Test
	public void pausingShowsTheReasonUntilDataArrives() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			panel.setPaused("Recording is off.");
