	// ----------------------------------------------------------------- width

	/**
	 * Every wrapped line has to fit the width it is given.
	 *
	 * <p>A label that wraps is told how wide to wrap at, in pixels, and the
	 * figure is not one Swing works out -- it is written into the HTML. Get it
	 * too small and every line breaks early and every card is taller than it
	 * needs to be; get it too big and the end of the line is simply cut off,
	 * and these are lines that end in a price. Neither shows up in a test that
	 * only reads the text back, because both render the same string.
	 *
	 * <p>So this lays the panel out at the width RuneLite gives a side panel
	 * and checks the one thing that is silently wrong: a line asking for more
	 * room than it has. It covers every tab, with content wide enough to wrap.
	 *
	 * <p>PANEL_WIDTH is the right width to lay out at, and it is worth saying
	 * why, because the number RuneLite reserves for a side panel is that plus
	 * the scrollbar. The panel goes inside a scroll pane inside a wrapper of
	 * PANEL_WIDTH + SCROLLBAR_WIDTH, so with a scrollbar showing -- which it
	 * is, for a sidebar with anything on it -- the panel itself gets exactly
	 * PANEL_WIDTH. Without one it gets more, so this is the narrow case, which
	 * is the one that can clip. PluginPanel's own six-pixel border does not
	 * come into it: the panel replaces it with its own in the constructor.
	 */
	@Test
	public void nothingTheSidebarDrawsIsCutOffAtTheWidthItIsGiven() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			fillWithWideContent(panel);

			final List<String> clipped = new ArrayList<>();
			for (String tab : new String[]{"Watchlists", "Journal", "Positions", "Analytics", "Account", "Activity"})
			{
				panel.selectTabForTest(tab);
				final Container wrapped = panel.getWrappedPanel();
				wrapped.setSize(PluginPanel.PANEL_WIDTH, 4000);
				layOut(wrapped);
				collectClipped(tab, wrapped, clipped);
			}

			assertTrue("these lines are wider than the room they are drawn in:\n"
				+ String.join("\n", clipped), clipped.isEmpty());
		});
	}

	/**
	 * And a wrapped line uses most of the room it is given.
	 *
	 * <p>The check above passes just as well if every line wraps at one pixel,
	 * so it cannot be the only one. A card's lines get 193 pixels of the 225
	 * the panel has, and the figure they wrapped at was a flat 150 for every
	 * line on every tab -- which, once Swing has scaled it, was 44 pixels wider
	 * than the title beside a card's sprite and ten short of a full-width line.
	 * One number could not be right for both. This is the other half of the
	 * bound: each line runs nearly the width of its own row.
	 */
	@Test
	public void aWrappedLineUsesMostOfTheRoomItIsGiven() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			fillWithWideContent(panel);

			final List<String> wasteful = new ArrayList<>();
			int checked = 0;
			for (String tab : new String[]{"Watchlists", "Journal", "Positions", "Analytics", "Account", "Activity"})
			{
				panel.selectTabForTest(tab);
				final Container wrapped = panel.getWrappedPanel();
				wrapped.setSize(PluginPanel.PANEL_WIDTH, 4000);
				layOut(wrapped);

				final List<JLabel> wrapping = new ArrayList<>();
				collectWrapping(wrapped, wrapping);
				checked += wrapping.size();
				for (JLabel label : wrapping)
				{
					// A card's lines and a full-width line share one width, and
					// the card is the narrower, so a full-width line is allowed
					// to fall short of its row by that difference.
					final int spare = label.getWidth() - label.getPreferredSize().width;
					if (spare > 20)
					{
						wasteful.add(tab + ": has " + label.getWidth() + " uses only "
							+ label.getPreferredSize().width + "  " + plain(label));
					}
				}
			}

			assertTrue("expected wrapped lines to check, found " + checked, checked > 10);
			assertTrue("these lines wrap well short of the room they have:\n"
				+ String.join("\n", wasteful), wasteful.isEmpty());
		});
	}

	/**
	 * An ordinary watchlist is drawn out of plain labels, not documents.
	 *
	 * <p>Wrapping a label means handing Swing HTML, and Swing builds a document
	 * to hold it -- about half a millisecond each against twenty microseconds
	 * for a plain label. A watchlist card is five or six lines, so drawing one
	 * every thirty seconds out of documents is what made a list of sixty cost a
	 * sixth of a second of the Swing thread.
	 *
	 * <p>Nothing here can time a redraw without being flaky, but it can count
	 * what the redraw is made of, which is the thing that decides the cost. An
	 * ordinary item name and an ordinary price line both fit their row.
	 */
	@Test
	public void anOrdinaryWatchlistIsDrawnWithoutBuildingADocumentPerLine() throws Exception
	{
		onEdt(() ->
		{
			final TestPanelActions actions = new TestPanelActions();
			final FlippingRsPanel panel = new FlippingRsPanel(actions);
			final List<FlippingRsPanel.WatchedItem> items = new ArrayList<>();
			for (String name : new String[]{"Abyssal whip", "Dragon bones", "Magic logs", "Rune platebody"})
			{
				items.add(new FlippingRsPanel.WatchedItem(4151, name, null, 1_500_000, 70, 72_000,
					"Buying 4/10 at 1.50M", quote(4151)));
			}
			panel.setWatchlistItems(items);
			panel.selectTabForTest("Watchlists");
			final Container wrapped = panel.getWrappedPanel();
			wrapped.setSize(PluginPanel.PANEL_WIDTH, 4000);
			layOut(wrapped);

			final List<JLabel> all = new ArrayList<>();
			collectLabels(wrapped, all);
			final List<String> documents = new ArrayList<>();
			for (JLabel label : all)
			{
				final String text = label.getText();
				if (text != null && !text.isEmpty() && text.startsWith("<html>"))
				{
					documents.add(plain(label));
				}
			}

			// A few still have to wrap and should: the tab's hint, and the
			// line of limits, which really is a shade wider than a card.
			assertTrue("expected a drawn watchlist, found " + all.size() + " labels", all.size() > 20);
			assertTrue("most of these lines were built as a document:\n"
				+ String.join("\n", documents), documents.size() * 3 <= all.size());
		});
	}

	private static void collectLabels(Component c, List<JLabel> out)
	{
		if (c instanceof JLabel)
		{
			out.add((JLabel) c);
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collectLabels(child, out);
			}
		}
	}

	/** Content wide enough that every kind of line has to wrap. */
	private static void fillWithWideContent(FlippingRsPanel panel)
	{
		// Ten-digit figures throughout, because that is what these lines can
		// really carry: the exchange caps one offer at max cash, and a bow or a
		// tbow-priced position is an ordinary thing for this panel to be shown.
		// A price three characters wider is three characters closer to the edge.
		final GeTransaction tx = new GeTransaction();
		tx.side = "buy";
		tx.quantity = 2_147_483_647L;
		tx.itemName = "Ancient ceremonial legs";
		tx.grossValue = 2_147_483_647L;
		tx.estimated = true;
		tx.occurredAt = "2026-08-31T16:10:12.482Z";
		panel.setRecentTrades(Collections.singletonList(tx));
		panel.setPending(Collections.singletonList(tx));

		final Quote q = quote(4151);
		q.instantSell = 1_234_567_890L;
		q.instantBuy = 1_250_000_000L;
		q.netMargin = -12_345_678L;
		q.profitPerLimit = 1_098_765_432L;
		q.volume24h = 12_345_678L;
		panel.setWatchlistItems(Collections.singletonList(new FlippingRsPanel.WatchedItem(
			4151, "Ancient ceremonial legs", null, 2_147_483_647, 25_000, 2_147_483_647,
			"Buying 123456/123456 at 1.25B", q)));

		final Position pos = new Position();
		pos.id = "p1";
		pos.itemId = 4151;
		pos.itemName = "Ancient ceremonial legs";
		pos.buyPrice = 1_234_567_890L;
		pos.remainingQty = 123_456;
		pos.currentBuy = 1_250_000_000L;
		pos.currentSell = 1_249_999_999L;
		pos.unrealisedPnl = -1_234_567_890L;
		pos.breakEvenSell = 1_234_567_890L;
		pos.hoursHeld = 5.5;
		pos.stale = true;
		final Positions open = new Positions();
		open.positions = Collections.singletonList(pos);
		open.summary = new Positions.Summary();
		panel.setJournal(new Analytics(), open);

		panel.setStatus("Could not connect to flippingrs.com: the request timed out.", Color.WHITE);
		panel.setActivityNotice(
			"flippingrs.com couldn't accept 3 trade(s). They have been set aside.", Color.WHITE);
	}

	/** Lays a tree out the way a panel on screen would be. */
	private static void layOut(Component c)
	{
		if (c instanceof Container)
		{
			final Container container = (Container) c;
			container.doLayout();
			for (Component child : container.getComponents())
			{
				layOut(child);
			}
		}
	}

	private static void collectClipped(String tab, Component c, List<String> out)
	{
		if (c instanceof JLabel && c.getWidth() > 0)
		{
			final JLabel label = (JLabel) c;
			final int wanted = label.getPreferredSize().width;
			if (wanted > label.getWidth())
			{
				out.add(tab + ": wants " + wanted + " has " + label.getWidth()
					+ "  " + plain(label));
			}
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collectClipped(tab, child, out);
			}
		}
	}

	/** The labels that were told a width to wrap at, as opposed to plain ones. */
	private static void collectWrapping(Component c, List<JLabel> out)
	{
		if (c instanceof JLabel)
		{
			final JLabel label = (JLabel) c;
			final String text = label.getText();
			if (text != null && text.contains("width:") && label.getWidth() > 0)
			{
				out.add(label);
			}
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collectWrapping(child, out);
			}
		}
	}

	private static String plain(JLabel label)
	{
		return plainText(label.getText());
	}

	/** A wrapped label's words, without the HTML that makes it wrap. */
	private static String plainText(String text)
	{
		return text == null ? "" : text.replaceAll("<[^>]*>", "").trim();
	}
}

package com.flippingrs;

import java.awt.Rectangle;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The two full-page offer screens, written into rather than drawn on.
 *
 * <p>The setup page, where an offer is priced, and the status page you get by
 * clicking one you have already placed, where the question is whether the
 * price you chose is still the right one. They are the same screen twice as
 * far as this is concerned, and the client builds them together and hides the
 * one you are not looking at -- which is the whole reason they need separating
 * here. Both descriptions exist at all times, and both hold text.
 */
public class GeOfferScreensTest
{
	private static final int WHIP = 4151;
	private static final int SHIELD = 1540;

	private final Client client = mock(Client.class);
	private final FlippingRsConfig config = mock(FlippingRsConfig.class);
	private final Map<Integer, Quote> prices = new HashMap<>();

	private GeOfferText text;

	private static Quote priced(int itemId, int buy, int sell)
	{
		final Quote quote = new Quote();
		quote.id = itemId;
		quote.instantSell = buy;
		quote.instantBuy = sell;
		quote.netMargin = sell - buy;
		quote.dataAgeSeconds = -1;
		return quote;
	}

	/** A description line the client wrote, which remembers what is put in it. */
	private static Widget description(String said)
	{
		final Widget widget = mock(Widget.class);
		final String[] text = {said};
		when(widget.isHidden()).thenReturn(false);
		when(widget.getText()).thenAnswer(call -> text[0]);
		when(widget.setText(anyString())).thenAnswer(call ->
		{
			text[0] = call.getArgument(0);
			return widget;
		});
		return widget;
	}

	/** The status page, which carries the item of the offer being looked at. */
	private static Widget statusPageShowing(int itemId)
	{
		final Widget item = mock(Widget.class);
		when(item.isHidden()).thenReturn(false);
		when(item.getItemId()).thenReturn(itemId);
		when(item.getBounds()).thenReturn(new Rectangle(20, 20, 32, 32));

		final Widget page = mock(Widget.class);
		when(page.isHidden()).thenReturn(false);
		when(page.getItemId()).thenReturn(-1);
		when(page.getBounds()).thenReturn(new Rectangle(10, 10, 300, 200));
		when(page.getDynamicChildren()).thenReturn(new Widget[]{item});
		return page;
	}

	@Before
	public void setUp()
	{
		when(config.setupOverlay()).thenReturn(true);
		when(client.getWidget(anyInt())).thenReturn(null);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(0);
		text = new GeOfferText(client, config, prices::get);
	}

	/**
	 * Each page says what its own item is worth.
	 *
	 * <p>The failure this guards against is one record of "the line being
	 * added to" shared between them, which hands the setup page's text to the
	 * status page's description on the way past -- and prices an offer you
	 * placed yesterday at whatever you last typed into the search box.
	 */
	@Test
	public void eachPageGetsThePricesForItsOwnItem()
	{
		prices.put(WHIP, priced(WHIP, 1_480_000, 1_520_000));
		prices.put(SHIELD, priced(SHIELD, 100, 140));

		final Widget setup = description("A weapon from the abyss.");
		final Widget status = description("A medium shield.");
		when(client.getWidget(InterfaceID.GeOffers.SETUP_DESC)).thenReturn(setup);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS_DESC)).thenReturn(status);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(WHIP);
		// Built before the stubbing, not inside it: Mockito counts the when()
		// calls this makes as a stub begun and not finished.
		final Widget page = statusPageShowing(SHIELD);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(page);

		text.update();

		assertTrue(setup.getText(), setup.getText().startsWith("A weapon from the abyss.<br>"));
		assertTrue(setup.getText(), setup.getText().contains("1,480,000"));
		assertTrue("the status page is about the offer, not the search box",
			status.getText().contains("140"));
		assertTrue(status.getText(), status.getText().startsWith("A medium shield.<br>"));
	}

	/** The status page is written into exactly as the setup page is. */
	@Test
	public void theStatusPageReadsTheSameAsTheSetupPage()
	{
		prices.put(WHIP, priced(WHIP, 1_480_000, 1_520_000));

		final Widget setup = description("A weapon from the abyss.");
		final Widget status = description("A weapon from the abyss.");
		when(client.getWidget(InterfaceID.GeOffers.SETUP_DESC)).thenReturn(setup);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS_DESC)).thenReturn(status);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(WHIP);
		// Built before the stubbing, not inside it: Mockito counts the when()
		// calls this makes as a stub begun and not finished.
		final Widget page = statusPageShowing(WHIP);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(page);

		text.update();

		assertEquals(setup.getText(), status.getText());
	}

	/**
	 * A page with no price for its item keeps the description the game wrote,
	 * and does not keep the other page's.
	 */
	@Test
	public void apageWithNoPriceIsLeftAsTheGameWroteIt()
	{
		prices.put(WHIP, priced(WHIP, 1_480_000, 1_520_000));

		final Widget setup = description("A weapon from the abyss.");
		final Widget status = description("A medium shield.");
		when(client.getWidget(InterfaceID.GeOffers.SETUP_DESC)).thenReturn(setup);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS_DESC)).thenReturn(status);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(WHIP);
		// Nobody has a price for the shield yet, which is every item before
		// the first fetch lands.
		// Built before the stubbing, not inside it: Mockito counts the when()
		// calls this makes as a stub begun and not finished.
		final Widget page = statusPageShowing(SHIELD);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(page);

		text.update();

		assertEquals("A medium shield.", status.getText());
		assertTrue(setup.getText(), setup.getText().contains("1,480,000"));
	}

	/** And switching the setting off takes both additions off with it. */
	@Test
	public void turningItOffPutsBothDescriptionsBack()
	{
		prices.put(WHIP, priced(WHIP, 1_480_000, 1_520_000));

		final Widget setup = description("A weapon from the abyss.");
		final Widget status = description("A weapon from the abyss.");
		when(client.getWidget(InterfaceID.GeOffers.SETUP_DESC)).thenReturn(setup);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS_DESC)).thenReturn(status);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(WHIP);
		// Built before the stubbing, not inside it: Mockito counts the when()
		// calls this makes as a stub begun and not finished.
		final Widget page = statusPageShowing(WHIP);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(page);
		text.update();

		when(config.setupOverlay()).thenReturn(false);
		text.update();

		assertEquals("A weapon from the abyss.", setup.getText());
		assertEquals("A weapon from the abyss.", status.getText());
	}
}

package com.flippingrs;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.Dispatcher;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * The HTTP layer, against a real server.
 *
 * <p>Two things are pinned here. The surface: every call goes to
 * {@code /api/plugin}, because that is the boundary between what a plugin
 * key may do and what the Elite API sells. And the retry split: whether a
 * failure is worth trying again governs whether a trade is retried until it
 * lands or set aside, so it is pinned rather than reasoned about.
 */
public class FlippingRsApiTest
{
	private MockWebServer server;
	private FlippingRsApi api;

	@Before
	public void setUp() throws IOException
	{
		server = new MockWebServer();
		server.start();
		api = new FlippingRsApi(new OkHttpClient(), new Gson(), server.url("/"));
	}

	@After
	public void tearDown() throws IOException
	{
		server.shutdown();
	}

	private static GeTransaction fill(String id)
	{
		final GeTransaction tx = new GeTransaction();
		tx.id = id;
		tx.offerRef = "offer-1";
		tx.itemId = 4151;
		tx.itemName = "Abyssal whip";
		tx.side = "buy";
		tx.quantity = 10;
		tx.grossValue = 10_000_000;
		tx.offerPrice = 1_000_000;
		tx.offerTotal = 10;
		tx.occurredAt = "2026-08-31T12:00:00Z";
		return tx;
	}

	private List<GeTransaction> oneFill()
	{
		return Collections.singletonList(fill("t1"));
	}

	// ------------------------------------------------------------ the panel

	private static final String FULL_PANEL =
		"{\"me\":{\"displayName\":\"Jim\",\"effectiveTier\":\"pro\",\"onTrial\":true,\"trialDaysLeft\":5},"
			+ "\"accounts\":[{\"id\":\"a1\",\"label\":\"Main\",\"isDefault\":true},{\"id\":\"a2\",\"label\":\"\"}],"
			+ "\"recentTransactions\":[{\"id\":\"t2\",\"itemId\":4151,\"itemName\":\"Abyssal whip\",\"side\":\"sell\","
			+ "\"quantity\":1,\"grossValue\":1500000,\"occurredAt\":\"2026-08-31T12:05:00.123456789Z\",\"flipId\":\"f1\"}],"
			+ "\"week\":{\"completedFlips\":12,\"openFlips\":2,\"realisedProfit\":1200000,\"winRate\":0.75,\"gpPerHour\":45000},"
			+ "\"positions\":{\"positions\":[{\"itemId\":4151,\"itemName\":\"Abyssal whip\",\"remainingQty\":10,"
			+ "\"buyPrice\":1480000,\"currentSell\":1500000,\"currentBuy\":1520000,\"unrealisedPnl\":96000,\"unrealisedRoi\":0.0065,"
			+ "\"breakEvenSell\":1510204,\"hoursHeld\":5.5,\"stale\":true}],"
			+ "\"summary\":{\"openPositions\":1,\"costBasis\":14800000,\"marketValue\":15200000,\"unrealisedPnl\":96000,"
			+ "\"marketDataAvailable\":false}},"
			+ "\"watchlists\":[{\"id\":\"wl_1\",\"name\":\"Plan\",\"itemIds\":[4151,11802]},{\"id\":\"wl_2\",\"itemIds\":null}],"
			+ "\"quotes\":[{\"id\":4151,\"name\":\"Abyssal whip\",\"buyLimit\":70,\"instantBuy\":1520000,\"instantSell\":1480000,"
			+ "\"netMargin\":9600,\"roi\":0.0065,\"profitPerLimit\":672000,\"volume24h\":1234},null]}";

	/** Each tab has its own read; all of them answer in the one panel shape. */
	@Test
	public void eachTabReadsItsOwnEndpointWithTheKey() throws Exception
	{
		server.enqueue(new MockResponse().setBody(FULL_PANEL));
		final PanelData account = api.account("frs_secret");
		RecordedRequest request = server.takeRequest();
		assertEquals("GET", request.getMethod());
		assertEquals("/api/plugin/account", request.getPath());
		assertEquals("frs_secret", request.getHeader("X-Api-Key"));
		assertEquals("Pro trial, 5 days left", account.getMe().describePlan());
		assertEquals(2, account.getAccounts().size());
		assertEquals("a nameless account shows its id", "a2", account.getAccounts().get(1).toString());
		assertTrue("which journal is the default one, that a new character adopts",
			account.getAccounts().get(0).isDefault);
		assertFalse(account.getAccounts().get(1).isDefault);

		server.enqueue(new MockResponse().setBody(FULL_PANEL));
		final PanelData trades = api.trades("frs_secret", "a1");
		assertEquals("/api/plugin/trades?accountId=a1", server.takeRequest().getPath());

		server.enqueue(new MockResponse().setBody(FULL_PANEL));
		final PanelData journal = api.journal("frs_secret", "a1", 60);
		assertEquals("/api/plugin/journal?tzOffset=60&accountId=a1", server.takeRequest().getPath());
		assertEverySentFieldOfTheJournalArrived(journal);

		server.enqueue(new MockResponse().setBody(FULL_PANEL));
		final PanelData lists = api.watchlists("frs_secret", "wl_1", null);
		assertEquals("/api/plugin/watchlists?watchlistId=wl_1", server.takeRequest().getPath());
		assertEquals(Arrays.asList(4151, 11802), lists.getWatchlists().get(0).getItemIds());
		assertTrue("null items are an empty list, not an NPE", lists.getWatchlists().get(1).getItemIds().isEmpty());
		assertEquals("Plan", lists.getWatchlists().get(0).toString());
		assertEquals("a null entry in the quotes array is skipped", 1, lists.getQuotes().size());
		assertEveryFieldOfTheQuoteArrived(lists.getQuotes().get(4151));

		assertEquals("t2", trades.getRecentTransactions().get(0).id);
		final GeTransaction recent = trades.getRecentTransactions().get(0);
		assertEquals("Abyssal whip", recent.itemName);
		assertEquals("sell", recent.side);
		assertEquals(1L, recent.quantity);
		assertEquals(1_500_000L, recent.grossValue);
		assertEquals("2026-08-31T12:05:00.123456789Z", recent.occurredAt);
		assertEquals(4151, recent.itemId);
	}

	/**
	 * Every figure the Journal tab shows, read back out of one reply.
	 *
	 * <p>These are matched to the server's JSON by field name, so a name that
	 * drifts from the site's does not fail: the field stays at zero and the
	 * tab shows a break-even of nothing, an age of nothing, a return of
	 * nought per cent. A sample of the fields cannot catch that; only all of
	 * them can.
	 */
	private static void assertEverySentFieldOfTheJournalArrived(PanelData journal)
	{
		final Analytics week = journal.getWeek();
		assertEquals("completed flips", 12, week.getCompletedFlips());
		assertEquals("open flips", 2, week.getOpenFlips());
		assertEquals("realised profit", 1_200_000L, week.getRealisedProfit());
		assertEquals("win rate", 0.75, week.getWinRate(), 0.0);
		assertEquals("gp per hour", 45_000L, week.getGpPerHour());

		final Position p = journal.getPositions().getPositions().get(0);
		assertEquals("item", 4151, p.getItemId());
		assertEquals("item name", "Abyssal whip", p.getItemName());
		assertEquals("how many are left", 10L, p.getRemainingQty());
		assertEquals("what they cost", 1_480_000L, p.getBuyPrice());
		assertEquals("what a patient sale lists at", 1_520_000L, p.getCurrentBuy());
		assertEquals("what an instant sale gets", 1_500_000L, p.getCurrentSell());
		assertEquals("profit so far", 96_000L, p.getUnrealisedPnl());
		assertEquals("return so far", 0.0065, p.getUnrealisedRoi(), 0.0);
		assertEquals("the price that breaks even", 1_510_204L, p.getBreakEvenSell());
		assertEquals("how long it has been held", 5.5, p.getHoursHeld(), 0.0);
		assertTrue("whether it is stale", p.isStale());

		final Positions.Summary totals = journal.getPositions().getSummary();
		assertEquals("open positions", 1, totals.openPositions);
		assertEquals("cost basis", 14_800_000L, totals.costBasis);
		assertEquals("market value", 15_200_000L, totals.marketValue);
		assertEquals("unrealised", 96_000L, totals.unrealisedPnl);
		assertFalse("whether there are prices at all", totals.marketDataAvailable);
	}

	/** The same for a watchlist card's quote. */
	private static void assertEveryFieldOfTheQuoteArrived(Quote q)
	{
		assertEquals("id", 4151, q.getId());
		// buyAt is the site's instantSell and sellAt its instantBuy: what you
		// pay to buy now is what someone else is selling at.
		assertEquals("buy at", 1_480_000L, q.getBuyAt());
		assertEquals("sell at", 1_520_000L, q.getSellAt());
		assertEquals("margin after tax", 9_600L, q.getNetMargin());
		assertEquals("return", 0.0065, q.getRoi(), 0.0);
		assertEquals("buy limit", 70, q.getBuyLimit());
		assertEquals("profit per limit", 672_000L, q.getProfitPerLimit());
		assertEquals("how much trades in a day", 1234L, q.getVolume24h());
	}

	/**
	 * The combo boxes render toString through a JLabel, which interprets a
	 * string beginning with "<html>" as markup. A name like that must reach
	 * the label in a form Swing will not interpret, and any other name must
	 * reach it untouched.
	 */
	@Test
	public void namesThatLookLikeMarkupAreShownAsTyped()
	{
		final GameAccount account = new GameAccount();
		account.id = "a1";
		account.label = "<html><b>Main</b>";
		assertFalse(javax.swing.plaf.basic.BasicHTML.isHTMLString(account.toString()));
		assertTrue(account.toString().trim().startsWith("<html>"));

		final Watchlist watchlist = new Watchlist();
		watchlist.id = "w1";
		watchlist.name = "<HTML>Plan";
		assertFalse("the check is case-insensitive, so the guard must be too",
			javax.swing.plaf.basic.BasicHTML.isHTMLString(watchlist.toString()));

		watchlist.name = "Plan <html> not at the start";
		assertEquals("only a leading tag is touched", "Plan <html> not at the start", watchlist.toString());
		assertEquals("Plan", Wire.plain("Plan"));
		assertNull(Wire.plain(null));
	}

	/** Without a journal chosen the account parameter is simply left off. */
	@Test
