		final JsonObject body = new JsonParser().parse(request.getBody().readUtf8()).getAsJsonObject();
		assertEquals(1_520_000L, body.get("sellPrice").getAsLong());
		assertEquals(4L, body.get("sellQty").getAsLong());
	}

	/** No quantity means "everything still held", which the server applies when the field is absent. */
	@Test
	public void closingWithoutAQuantityLeavesTheFieldOut() throws Exception
	{
		server.enqueue(new MockResponse().setBody("{}"));

		api.closePosition("k", "f1", 1_520_000, null);

		final JsonObject body = new JsonParser().parse(server.takeRequest().getBody().readUtf8()).getAsJsonObject();
		assertFalse(body.has("sellQty"));
	}

	@Test
	public void deletingAPositionUsesTheDeleteMethodOnItsRoute() throws Exception
	{
		server.enqueue(new MockResponse().setBody("{\"status\":\"deleted\"}"));

		api.deletePosition("frs_secret", "f1");

		final RecordedRequest request = server.takeRequest();
		assertEquals("DELETE", request.getMethod());
		assertEquals("/api/plugin/positions/f1", request.getPath());
		assertEquals("frs_secret", request.getHeader("X-Api-Key"));
	}

	/** A refusal carries the server's own words, which the Journal tab shows. */
	@Test
	public void aRefusedCloseSurfacesTheServersMessage() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(409).setBody(
			"{\"error\":{\"code\":\"conflict\",\"message\":\"Every item in this flip has already been sold.\"}}"));

		try
		{
			api.closePosition("k", "f1", 1_000, null);
			fail("expected a failure");
		}
		catch (IOException e)
		{
			assertEquals("Every item in this flip has already been sold.", e.getMessage());
		}
	}

	// ------------------------------------------------- catching the server up

	@Test
	public void openOffersAreSentForReconciliation() throws Exception
	{
		server.enqueue(new MockResponse().setBody("{\"reconciled\":1,\"recovered\":1}"));
		final OfferState state = new OfferState();
		state.slot = 3;
		state.offerRef = "ref-1";
		state.itemId = 4151;
		state.itemName = "Abyssal whip";
		state.side = "buy";
		state.price = 1_000_000;
		state.totalQuantity = 10;
		state.quantitySold = 4;
		state.spent = 4_000_000;
		state.state = "BUYING";

		final Reconciliation result = api.submitOffers("frs_secret", "acct-1", Collections.singletonList(state));

		final RecordedRequest request = server.takeRequest();
		assertEquals("POST", request.getMethod());
		assertEquals("/api/plugin/offers", request.getPath());
		assertEquals("frs_secret", request.getHeader("X-Api-Key"));
		final JsonObject body = new JsonParser().parse(request.getBody().readUtf8()).getAsJsonObject();
		assertEquals("acct-1", body.get("accountId").getAsString());
		final JsonObject sent = body.getAsJsonArray("offers").get(0).getAsJsonObject();
		assertEquals(3, sent.get("slot").getAsInt());
		assertEquals("ref-1", sent.get("offerRef").getAsString());
		assertEquals(4, sent.get("quantitySold").getAsLong());
		assertEquals("BUYING", sent.get("state").getAsString());
		assertEquals(1, result.getRecovered());
	}

	@Test
	public void theHistoryScreenIsSentAsRead() throws Exception
	{
		server.enqueue(new MockResponse().setBody(
			"{\"matched\":1,\"added\":1,\"ignored\":1,\"problems\":[{\"row\":2,\"reason\":\"no side\"}]}"));
		final HistoryRow row = new HistoryRow();
		row.position = 0;
		row.itemId = 4151;
		row.itemName = "Abyssal whip";
		row.side = "sell";
		row.quantity = 3;
		row.grossValue = 4_560_000;

		final Reconciliation result = api.submitHistory("k", "acct-1", Collections.singletonList(row));

		final RecordedRequest request = server.takeRequest();
		assertEquals("/api/plugin/history", request.getPath());
		final JsonObject body = new JsonParser().parse(request.getBody().readUtf8()).getAsJsonObject();
		final JsonObject sent = body.getAsJsonArray("rows").get(0).getAsJsonObject();
		assertEquals("sell", sent.get("side").getAsString());
		assertEquals(4_560_000L, sent.get("grossValue").getAsLong());
		assertEquals(1, result.getAdded());
		assertEquals("structured problems are read, not fatal", 1, result.getProblems().size());
		assertTrue(result.getProblems().get(0).contains("no side"));
	}

	/**
	 * And it holds for an id that tries to climb out of the prefix.
	 *
	 * <p>The watchlist and position ids go into a path, and they come back from
	 * the server rather than from here. A slash or a dot segment in one is the
	 * shape that turns a plugin call into a call somewhere else, and the prefix
	 * is the whole of what says a plugin key cannot reach further than a plugin
	 * key should. The ordinary ids below would never show it either way.
	 */
	@Test
	public void anIdThatTriesToClimbOutStaysUnderThePrefix() throws Exception
	{
		final String[] hostile = {"..", "../..", "a/b", "%2e%2e", "a?x=1", "a#f", "/"};
		for (String id : hostile)
		{
			server.enqueue(new MockResponse().setBody("{}"));
			api.deletePosition("k", id);
			final String path = server.takeRequest().getPath();
			assertTrue("deleting " + id + " reached " + path, path.startsWith("/api/plugin/"));

			server.enqueue(new MockResponse().setBody("{\"id\":\"wl_1\"}"));
			api.updateWatchlist("k", id, Collections.singletonList(1));
			final String patched = server.takeRequest().getPath();
			assertTrue("patching " + id + " reached " + patched, patched.startsWith("/api/plugin/"));
		}
	}

	/** The whole surface, pinned: nothing outside /api/plugin is ever called. */
	@Test
	public void everyCallStaysUnderThePluginPrefix() throws Exception
	{
		for (int i = 0; i < 4; i++)
		{
			server.enqueue(new MockResponse().setBody("{}"));
		}
		server.enqueue(new MockResponse().setBody("{\"accepted\":1}"));
		server.enqueue(new MockResponse().setBody("{\"id\":\"wl_1\"}"));
		server.enqueue(new MockResponse().setBody("{\"id\":\"wl_1\"}"));
		server.enqueue(new MockResponse().setBody("{}"));
		server.enqueue(new MockResponse().setBody("{}"));

		api.account("k");
		api.trades("k", "a");
		api.journal("k", "a", 0);
		api.watchlists("k", "w", null);
		api.submit("k", "a", oneFill());
		api.createWatchlist("k", "Plan", Collections.singletonList(1));
		api.updateWatchlist("k", "wl_1", Collections.singletonList(1));
		api.submitOffers("k", "a", Collections.emptyList());
		api.submitHistory("k", "a", Collections.emptyList());
		server.enqueue(new MockResponse().setBody("{}"));
		server.enqueue(new MockResponse().setBody("{}"));
		api.closePosition("k", "f1", 1, null);
		api.deletePosition("k", "f1");

		for (int i = 0; i < 11; i++)
		{
			final String path = server.takeRequest().getPath();
			assertTrue(path, path.startsWith("/api/plugin/"));
		}
	}
}

package com.flippingrs;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The queue really is used from two threads at once: fills are appended on the
 * plugin's io thread while the sender peeks and confirms on its net thread.
 *
 * <p>Up to now that safety was argued from reading the lock structure. These
 * tests drive it instead, and check the one invariant that matters: every fill
 * ever added is either still queued or was confirmed exactly once. Losing one
 * silently drops a trade from somebody's journal; confirming one twice would
 * mean it was sent twice, and while the server de-duplicates by id, a queue
 * that can hand the same fill out twice is a queue that can also drop the
 * wrong one.
 */
public class TransactionQueueConcurrencyTest
{
	private static final int FILLS = 4000;

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final Gson gson = new Gson();

	private static GeTransaction fill(int n)
	{
		final GeTransaction tx = new GeTransaction();
		tx.id = "fill-" + n;
		tx.itemId = 4151;
		tx.itemName = "Abyssal whip";
		tx.side = "buy";
		tx.quantity = 1;
		tx.grossValue = 1000;
		tx.occurredAt = "2026-08-31T12:00:00Z";
		return tx;
	}

	@Test
	public void nothingIsLostOrDuplicatedUnderConcurrentAddAndDrain() throws Exception
	{
		final File file = new File(folder.newFolder("flippingrs"), "queue-1.json");
		final TransactionQueue queue = new TransactionQueue(gson, file);

		final Set<String> confirmed = new HashSet<>();
		final List<String> duplicates = new java.util.ArrayList<>();
		final CountDownLatch go = new CountDownLatch(1);
		final AtomicReference<Throwable> failure = new AtomicReference<>();

		// Producer: the io thread, appending fills as the game reports them.
		final Thread producer = new Thread(() ->
		{
			try
			{
				go.await();
				for (int i = 0; i < FILLS; i++)
				{
					queue.add(fill(i));
				}
			}
			catch (Throwable t)
			{
				failure.compareAndSet(null, t);
			}
		}, "producer");

		// Consumer: the net thread, draining batches the way drain() does --
		// peek, "send", confirm.
		final Thread consumer = new Thread(() ->
		{
			try
			{
				go.await();
				// Stops if the producer fell over, and stops regardless after
				// the join below would have given up. Spinning until every
				// fill arrives is right while the producer is alive; if it is
				// not, this thread never ends, and a broken queue comes out as
				// a build that hangs rather than a test that failed.
				final long deadline = System.nanoTime() + TimeUnit.MINUTES.toNanos(1);
				while (confirmed.size() < FILLS && failure.get() == null && System.nanoTime() - deadline < 0)
				{
					final List<GeTransaction> batch = queue.peek(64);
					if (batch.isEmpty())
					{
						Thread.yield();
						continue;
					}
					for (GeTransaction tx : batch)
					{
						// Recorded before the confirm, so a fill handed out
						// twice is caught even if the second hand-out races.
						if (!confirmed.add(tx.id))
						{
							duplicates.add(tx.id);
						}
					}
					queue.confirm(batch);
				}
			}
			catch (Throwable t)
			{
				failure.compareAndSet(null, t);
			}
		}, "consumer");

		// Daemons, so neither can hold the JVM open if it does get stuck.
		producer.setDaemon(true);
		consumer.setDaemon(true);
		producer.start();
		consumer.start();
		go.countDown();
		producer.join(TimeUnit.MINUTES.toMillis(1));
		consumer.join(TimeUnit.MINUTES.toMillis(1));

		assertNull("a worker threw: " + failure.get(), failure.get());
		assertTrue("no fill may be handed out twice, saw: " + duplicates, duplicates.isEmpty());
		assertEquals("every fill must be accounted for", FILLS, confirmed.size());
		assertTrue("the queue should be drained", queue.isEmpty());

		// And the file must agree with memory: a reopened queue sees nothing,
		// because everything was confirmed.
		assertTrue("confirmed fills must not come back after a restart",
			new TransactionQueue(gson, file).isEmpty());
	}

	/**
	 * The same race stopped part way through. Whatever was not confirmed has to
	 * still be on disk -- that is the entire reason the queue is persisted, and
	 * it is the case a crash actually hits.
	 */
	@Test
	public void whateverIsUnconfirmedSurvivesARestartMidDrain() throws Exception
	{
		final File file = new File(folder.newFolder("flippingrs"), "queue-1.json");
		final TransactionQueue queue = new TransactionQueue(gson, file);

		final int total = 500;
		final CountDownLatch go = new CountDownLatch(1);
		final AtomicReference<Throwable> failure = new AtomicReference<>();

		final Thread producer = new Thread(() ->
		{
			try
			{
				go.await();
				for (int i = 0; i < total; i++)
				{
					queue.add(fill(i));
				}
			}
			catch (Throwable t)
			{
				failure.compareAndSet(null, t);
			}
		}, "producer");

		producer.setDaemon(true);
		producer.start();
		go.countDown();

		// Wait for the producer to be under way first. Three peeks at a queue
		// it has not reached yet drain nothing, and this would go on to assert
		// that an undrained queue still holds everything -- true, and not what
		// the test is for.
		final long deadline = System.nanoTime() + TimeUnit.MINUTES.toNanos(1);
		while (queue.isEmpty() && System.nanoTime() - deadline < 0)
		{
			Thread.yield();
		}

		// Drain only a little, concurrently with the producer, then stop.
		final Set<String> confirmed = new HashSet<>();
		for (int round = 0; round < 3; round++)
		{
			final List<GeTransaction> batch = queue.peek(16);
			for (GeTransaction tx : batch)
			{
				confirmed.add(tx.id);
			}
			queue.confirm(batch);
		}
		producer.join(TimeUnit.MINUTES.toMillis(1));
		assertNull("producer threw: " + failure.get(), failure.get());
		assertFalse("the drain has to have overlapped the producer", confirmed.isEmpty());

		final int expectedRemaining = total - confirmed.size();
		assertEquals(expectedRemaining, queue.size());

		// Reopen, as a restarted client would.
		final TransactionQueue reopened = new TransactionQueue(gson, file);
		assertEquals("the unsent fills must all still be there",
			expectedRemaining, reopened.size());

		final Set<String> restored = new HashSet<>();
		for (GeTransaction tx : reopened.peek(total))
		{
			restored.add(tx.id);
		}
		for (String id : confirmed)
		{
			assertTrue("a confirmed fill came back: " + id, !restored.contains(id));
		}
		assertEquals(expectedRemaining, restored.size());
	}

	/**
	 * Appending is the hot path and it must stay cheap no matter how much is
	 * already waiting. This is the regression guard for the rewrite-per-add
	 * that made filling the queue quadratic.
	 */
	@Test
	public void appendingStaysCheapAsTheBacklogGrows() throws IOException
	{
		final File file = new File(folder.newFolder("flippingrs"), "queue-1.json");
		final TransactionQueue queue = new TransactionQueue(gson, file);

		final long firstThousand = timeAdds(queue, 0, 1000);
		// Now there is a real backlog in front of the next thousand.
		final long laterThousand = timeAdds(queue, 1000, 1000);

		// Quadratic behaviour made the second batch many times the cost of the
		// first. Appending makes them comparable; the bound is loose because
		// this is wall-clock on a shared machine, and it still fails by orders
		// of magnitude if the rewrite ever comes back.
		assertTrue("adds got dramatically slower as the queue grew: "
				+ firstThousand + "ms then " + laterThousand + "ms",
			laterThousand < Math.max(250, firstThousand * 10));
	}

	private long timeAdds(TransactionQueue queue, int from, int count)
	{
		final long start = System.nanoTime();
		for (int i = from; i < from + count; i++)
		{
			queue.add(fill(i));
		}
		return TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
	}
}

package com.flippingrs;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MessageNode;
import net.runelite.api.widgets.Widget;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.chat.ChatMessageManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Putting the site's prices on the end of an examine line.
 *
 * <p>The examine text says nothing about which item it is for, so the item
 * comes from the click that asked for it. Pairing the two is the whole
 * difference between a useful line and one that confidently prices the wrong
 * item, and it is not something the message itself can be checked against.
 *
 * <p>These pin how the client actually reports an examine, which is not how it
 * reads: examining an item in an interface is a plain op told apart by its
 * name, and the item is on the widget rather than on the event. An earlier
 * version of this class assumed a MenuAction of its own and read the id off
 * the event, and the tests agreed with it -- they were written from the same
 * assumption, so they passed while the feature did nothing at all.
 */
public class ExaminePricesTest
{
	private final Client client = mock(Client.class);
	private final FlippingRsConfig config = mock(FlippingRsConfig.class);
	private final ChatMessageManager chat = mock(ChatMessageManager.class);
	private final Map<Integer, Quote> quotes = new HashMap<>();
	private final List<Integer> asked = new ArrayList<>();
	private ExaminePrices examine;

	@Before
	public void setUp()
	{
		when(config.examinePrices()).thenReturn(true);
		examine = new ExaminePrices(client, config, chat, quotes::get, asked::add, id -> "Abyssal whip");

		final Quote whip = new Quote();
		whip.id = 4151;
		whip.instantSell = 1_480_000;
		whip.instantBuy = 1_520_000;
		whip.netMargin = 32_000;
		quotes.put(4151, whip);
	}

	/** Examining an item in an interface: the inventory, the bank, the exchange. */
	/** The text without its colour tags; see GeOfferTextTest. */
	private static String plain(String text)
	{
		return text.replaceAll("</?col[^>]*>", "");
	}

	private MenuOptionClicked examineInWidget(int widgetId, int slot, int itemId)
	{
		final MenuOptionClicked event = mock(MenuOptionClicked.class);
		when(event.getMenuOption()).thenReturn("Examine");
		when(event.getMenuAction()).thenReturn(MenuAction.CC_OP_LOW_PRIORITY);
		when(event.getParam1()).thenReturn(widgetId);
		when(event.getParam0()).thenReturn(slot);

		final Widget item = mock(Widget.class);
		when(item.getItemId()).thenReturn(itemId);
		final Widget container = mock(Widget.class);
		when(container.getChild(slot)).thenReturn(item);
		when(client.getWidget(widgetId)).thenReturn(container);
		return event;
	}

	/** Examining one lying on the ground, the only case that carries its own id. */
	private MenuOptionClicked examineOnGround(int itemId)
	{
		final MenuOptionClicked event = mock(MenuOptionClicked.class);
		when(event.getMenuOption()).thenReturn("Examine");
		when(event.getMenuAction()).thenReturn(MenuAction.EXAMINE_ITEM_GROUND);
		when(event.getId()).thenReturn(itemId);
		return event;
	}

	/** Any other click. */
	private MenuOptionClicked somethingElse(String option, MenuAction action)
	{
		final MenuOptionClicked event = mock(MenuOptionClicked.class);
		when(event.getMenuOption()).thenReturn(option);
		when(event.getMenuAction()).thenReturn(action);
		return event;
	}

	private ChatMessage message(ChatMessageType type, MessageNode node)
	{
		final ChatMessage event = mock(ChatMessage.class);
		when(event.getType()).thenReturn(type);
		when(event.getMessageNode()).thenReturn(node);
		return event;
	}

	private MessageNode node(String text)
	{
		final MessageNode node = mock(MessageNode.class);
		when(node.getValue()).thenReturn(text);
		return node;
	}

	@Test
	public void thePricesGoOnTheEndOfTheExamineLine()
	{
		final MessageNode node = node("A weapon from the abyss.");

		examine.clicked(examineInWidget(9764864, 3, 4151));
		examine.examined(message(ChatMessageType.ITEM_EXAMINE, node));

		final org.mockito.ArgumentCaptor<String> written =
			org.mockito.ArgumentCaptor.forClass(String.class);
		// The value, with the colours already in it. The format message is not
		// the way: update() is a no-op in this client, and the tokens it would
		// have resolved are only resolved for message types RuneLite has a
		// colour configured for -- which an item examine is not.
		org.mockito.Mockito.verify(node).setValue(written.capture());
		assertTrue(written.getValue(), plain(written.getValue()).startsWith("A weapon from the abyss."));
		assertTrue(written.getValue(), plain(written.getValue()).contains("1,480,000"));
		assertTrue(written.getValue(), plain(written.getValue()).contains("1,520,000"));
		assertTrue(written.getValue(), plain(written.getValue()).contains("+32,000"));
	}

	/**
	 * An item on the ground is an item too, and the one case where the event
	 * carries the item itself rather than naming a widget.
	 */
	@Test
	public void anItemOnTheGroundIsPricedAsWell()
	{
		final MessageNode node = node("A weapon from the abyss.");

		examine.clicked(examineOnGround(4151));
		examine.examined(message(ChatMessageType.ITEM_EXAMINE, node));

		org.mockito.Mockito.verify(node).setValue(org.mockito.ArgumentMatchers.anyString());
	}

	/**
	 * One message per click. Without that, the next examine message the client
	 * produced -- for an object, an NPC, another item -- would be handed the
	 * last item's prices.
	 */
	@Test
	public void oneClickPricesOneMessage()
	{
		examine.clicked(examineInWidget(9764864, 3, 4151));
		examine.examined(message(ChatMessageType.ITEM_EXAMINE, node("A weapon from the abyss.")));

		final MessageNode second = node("A sturdy oak tree.");
		examine.examined(message(ChatMessageType.ITEM_EXAMINE, second));

		org.mockito.Mockito.verify(second, org.mockito.Mockito.never())
			.setValue(org.mockito.ArgumentMatchers.anyString());
	}

	/**
	 * An op on the same item that is not an examine forgets it.
	 *
	 * <p>This is the case the name check exists for. Every other thing you can
	 * do to an item in an interface -- wield it, drop it, use it -- arrives as
	 * the same menu action from the same widget, and only the name tells them
	 * apart. Without that check, wielding something would have queued its
	 * prices onto whatever examine line came next.
	 */
	@Test
	public void anOpOnTheSameItemThatIsNotAnExamineForgetsIt()
	{
		examine.clicked(examineInWidget(9764864, 3, 4151));
		examine.clicked(somethingElse("Wield", MenuAction.CC_OP_LOW_PRIORITY));

		assertEquals(-1, examine.examinedForTest());

		final MessageNode node = node("A weapon from the abyss.");
		examine.examined(message(ChatMessageType.ITEM_EXAMINE, node));
		org.mockito.Mockito.verify(node, org.mockito.Mockito.never())
			.setValue(org.mockito.ArgumentMatchers.anyString());
	}

	/**
	 * An item nobody has priced says nothing now and is asked about, so the
	 * next examine of it can answer. A price arriving in the chat box after
	 * the line it belongs to has scrolled away is a line about nothing.
	 */
	@Test
	public void anUnpricedItemIsAskedAboutRatherThanGuessedAt()
	{
		final MessageNode node = node("A sturdy oak log.");

		examine.clicked(examineInWidget(9764864, 5, 1511));
		examine.examined(message(ChatMessageType.ITEM_EXAMINE, node));

		org.mockito.Mockito.verify(node, org.mockito.Mockito.never())
			.setValue(org.mockito.ArgumentMatchers.anyString());
		assertEquals("but it is asked about", java.util.Collections.singletonList(1511), asked);
	}

	/**
	 * The two ways the client reports an examine, and the ways it does not.
	 *
	 * <p>Pinned directly, because this is what was wrong: the class looked for
	 * a MenuAction of its own and read the id off the event, and neither of
	 * those is how it arrives.
	 */
	@Test
	public void anExamineIsRecognisedTheWayTheClientReportsOne()
	{
		assertEquals("an item in an interface, resolved off the widget",
			4151, ExaminePrices.itemFor(examineInWidget(9764864, 3, 4151), client::getWidget));
		assertEquals("an item on the ground, carried on the event",
			4151, ExaminePrices.itemFor(examineOnGround(4151), client::getWidget));
		assertEquals("another op on the same widget is not an examine",
			-1, ExaminePrices.itemFor(somethingElse("Wield", MenuAction.CC_OP_LOW_PRIORITY),
				client::getWidget));
		assertEquals("and neither is examining something that is not an item",
			-1, ExaminePrices.itemFor(somethingElse("Examine", MenuAction.EXAMINE_NPC),
				client::getWidget));
	}

	/** A widget the client will not resolve is not an item. */
	@Test
	public void anExamineOnAWidgetThatIsNotThereIsNotAnItem()
	{
		final MenuOptionClicked event = mock(MenuOptionClicked.class);
		when(event.getMenuOption()).thenReturn("Examine");
		when(event.getMenuAction()).thenReturn(MenuAction.CC_OP_LOW_PRIORITY);
		when(event.getParam1()).thenReturn(1234);
		when(event.getParam0()).thenReturn(0);

		assertEquals(-1, ExaminePrices.itemFor(event, client::getWidget));
	}

	/**
	 * A price that arrives after the line it belonged to is said as its own
	 * line, naming the item.
	 *
	 * <p>The first examine of an item nobody has asked the site about cannot
	 * be answered on the spot. Saying nothing at all was the first attempt at
	 * that, and it reads exactly like a broken feature: you examine a thing,
	 * and the plugin you installed to price things says nothing.
	 */
	@Test
	public void aPriceThatArrivesLateIsSaidWithTheItemsName()
	{
		examine.priced(4151);

		final org.mockito.ArgumentCaptor<net.runelite.client.chat.QueuedMessage> said =
			org.mockito.ArgumentCaptor.forClass(net.runelite.client.chat.QueuedMessage.class);
		org.mockito.Mockito.verify(chat).queue(said.capture());
		final String line = plain(said.getValue().getValue());
		assertTrue(line, line.contains("Abyssal whip"));
		assertTrue(line, line.contains("1,480,000"));
	}

	/** And an item the server had no price for says nothing at all. */
	@Test
	public void aPriceThatNeverArrivedSaysNothing()
	{
		examine.priced(1511);

		org.mockito.Mockito.verify(chat, org.mockito.Mockito.never())
			.queue(org.mockito.ArgumentMatchers.any());
	}

	/** A message that is not an item examine is left alone. */
	@Test
	public void otherChatIsLeftAlone()
	{
		final MessageNode node = node("A sturdy oak tree.");

		examine.clicked(examineInWidget(9764864, 3, 4151));
		examine.examined(message(ChatMessageType.OBJECT_EXAMINE, node));

		org.mockito.Mockito.verify(node, org.mockito.Mockito.never())
			.setValue(org.mockito.ArgumentMatchers.anyString());
	}

	/** And the setting turns it off entirely. */
	@Test
	public void theSettingTurnsItOff()
	{
		when(config.examinePrices()).thenReturn(false);
		final MessageNode node = node("A weapon from the abyss.");

		examine.clicked(examineInWidget(9764864, 3, 4151));
		examine.examined(message(ChatMessageType.ITEM_EXAMINE, node));

		org.mockito.Mockito.verify(node, org.mockito.Mockito.never())
			.setValue(org.mockito.ArgumentMatchers.anyString());
	}

	/**
	 * An examine line carries the volume as well.
	 *
	 * <p>Examine is asked from a bank or off the ground, away from the
	 * exchange and from anything else that would say whether the item moves at
	 * all -- so it is the place this number is least likely to be known
	 * already.
	 */
	@Test
	public void anExamineLineCarriesTheVolume()
	{
		final Quote quote = new Quote();
		quote.instantSell = 1_480_000;
		quote.instantBuy = 1_520_000;
		quote.netMargin = 32_000;
		quote.volume24h = 1234;

		final String plain = ExaminePrices.suffix(quote).replaceAll("<[^>]*>", "");

		assertTrue(plain, plain.endsWith(" · Volume 1.2K/24h"));

		quote.volume24h = 0;
		assertFalse("and nothing at all when the site has none",
			ExaminePrices.suffix(quote).contains("Volume"));
	}
}

package com.flippingrs;

import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * What the exchange's hover box gains when you point at something in it.
 *
 * <p>The box is the game's own, and it already says which item this is about,
 * so what goes in is only what the game does not know: the site's two prices,
 * the margin, and how your own offer sits against them.
 *
 * <p>The arithmetic is the part worth being sure about. Measuring an offer
 * against the wrong end of the spread would call every sensible offer badly
 * priced by exactly the width of it, and would do it in green.
 */
public class GeTooltipTest
{
	private static final String GOOD = "0b6b1f";
	private static final String BAD = "9b1c1c";

	/** The colour the exchange writes its hover box in: near-black on yellow. */
	private static final int BOX_TEXT = 0x1a1a1a;

	/** The lines without their colours; the colours are asserted separately. */
	private static String[] lines(String text)
	{
		return text.replaceAll("<col=[^>]*>", "").split("<br>");
	}

	private static Quote whip()
	{
		final Quote quote = new Quote();
		quote.id = 4151;
		quote.name = "Abyssal whip";
		// The site's two ends of the spread: buy at the low, sell at the high.
		quote.instantSell = 1_480_000;
		quote.instantBuy = 1_520_000;
		quote.netMargin = 32_000;
		return quote;
	}

	private static GrandExchangeOffer offer(GrandExchangeOfferState state, int price)
	{
		final GrandExchangeOffer offer = mock(GrandExchangeOffer.class);
		when(offer.getState()).thenReturn(state);
		when(offer.getPrice()).thenReturn(price);
		when(offer.getItemId()).thenReturn(4151);
		return offer;
	}

	/**
	 * Exact to the coin. The box is made as tall as it needs to be, and these
	 * are prices somebody is deciding what to type from.
	 */
	@Test
	public void anItemWithNoOfferOnItGetsThePrices()
	{
		final String[] lines = lines(GeTooltip.textFor(whip(), null, BOX_TEXT));

		assertEquals(4, lines.length);
		assertEquals("Buy 1,480,000", lines[0]);
		assertEquals("Sell 1,520,000", lines[1]);
		assertEquals("Margin +32,000", lines[2]);
		assertEquals("and how old they are, which a fresh quote still says",
			"Priced just now", lines[3]);
	}

	/** The item's name is the game's line, not one to write again under it. */
	@Test
	public void theNameIsLeftToTheBoxThatAlreadySaysIt()
	{
		assertFalse(GeTooltip.textFor(whip(), null, BOX_TEXT).contains("Abyssal whip"));
	}

	/**
	 * An item you have an offer on gains the price you asked for and how it
	 * compares with the site's for the side you are trading. Only the eight
	 * slots can say this; everywhere else the same item is just an item.
	 *
	 * <p>Named rather than signed. "-2" on its own is a difference from
	 * something unnamed, in a direction the reader has to guess, and whether
	 * it is good news depends on which side of the trade they are on; the line
	 * sits directly under the price it is measured against, so saying which
	 * price that is makes the arithmetic checkable on the spot.
	 */
	@Test
	public void yourOwnOfferIsMeasuredAgainstYourOwnSide()
	{
		final String buying = GeTooltip.textFor(whip(),
			offer(GrandExchangeOfferState.BUYING, 1_485_000), BOX_TEXT);
		assertEquals("a bid over the site's buy price fills sooner",
			"Yours 1,485,000 (5,000 over buy)", lines(buying)[3]);
		assertTrue(buying, buying.contains(GOOD));

		final String selling = GeTooltip.textFor(whip(),
			offer(GrandExchangeOfferState.SELLING, 1_600_000), BOX_TEXT);
		assertEquals("and an ask over its sell price will sit",
			"Yours 1,600,000 (80,000 over sell)", lines(selling)[3]);
		assertTrue(selling, selling.contains(BAD));
	}

	/**
	 * The other three directions, because the words invert between the two
	 * sides and a sign convention does not survive that.
	 *
	 * <p>Over is good for a buyer and bad for a seller; the same word means
	 * the opposite thing depending on which side you are on, which is exactly
	 * why the side is named and the verdict is left to the colour.
	 */
	@Test
	public void overIsGoodOnOneSideAndBadOnTheOther()
	{
		final String bidLow = GeTooltip.textFor(whip(),
			offer(GrandExchangeOfferState.BUYING, 1_470_000), BOX_TEXT);
		assertEquals("a bid under the buy price is the patient end",
			"Yours 1,470,000 (10,000 under buy)", lines(bidLow)[3]);
		assertTrue(bidLow, bidLow.contains(BAD));

		final String askLow = GeTooltip.textFor(whip(),
			offer(GrandExchangeOfferState.SELLING, 1_500_000), BOX_TEXT);
		assertEquals("an ask under the sell price fills sooner",
			"Yours 1,500,000 (20,000 under sell)", lines(askLow)[3]);
		assertTrue(askLow, askLow.contains(GOOD));

		final String exact = GeTooltip.textFor(whip(),
			offer(GrandExchangeOfferState.SELLING, 1_520_000), BOX_TEXT);
		assertEquals("and a price the site agrees with is neither over nor under",
			"Yours 1,520,000 (at sell)", lines(exact)[3]);
	}

	/** The buy limit and the price age, when the server sends them. */
	@Test
	public void whatQualifiesThePricesComesLast()
	{
		final Quote quote = whip();
		quote.limitRemaining = 3412;
		quote.dataAgeSeconds = 250;

		final String[] lines = lines(GeTooltip.textFor(quote, null, BOX_TEXT));

		assertEquals(5, lines.length);
		assertEquals("Limit 3.4K", lines[3]);
		assertEquals("Priced 4m ago", lines[4]);
	}

	/**
	 * The day's volume, which is what says whether a margin is one anybody can
	 * take.
	 *
	 * <p>A wide spread on an item that trades twice a day is not an
	 * opportunity; it is the reason the spread is wide. Nothing says that on
	 * any of the exchange's own screens.
	 */
	@Test
	public void theDaysVolumeSaysWhetherTheMarginCanBeTaken()
	{
		final Quote quote = whip();
		quote.volume24h = 1234;
		quote.dataAgeSeconds = -1;

		final String[] lines = lines(GeTooltip.textFor(quote, null, BOX_TEXT));

		assertEquals(4, lines.length);
		assertEquals("Volume 1.2K/24h", lines[3]);
	}

	/**
	 * An item the site has no volume for says nothing, rather than saying
	 * none.
	 *
	 * <p>A day with no trades and a server that does not send the figure look
	 * identical from here, and of the two readings the wrong one is much the
	 * worse: "0/24h" on an item that trades all day would talk somebody out of
	 * a good flip, and is the more likely of the two to be what happened.
	 */
	@Test
	public void anItemWithNoVolumeSaysNothingAboutIt()
	{
		final Quote quote = whip();
		quote.dataAgeSeconds = -1;

		final String text = GeTooltip.textFor(quote, null, BOX_TEXT);

		assertFalse(text, text.contains("Volume"));
		assertFalse(text, text.contains("24h"));
	}

	/** And a server that sends neither leaves both off rather than guessing. */
	@Test
	public void aServerThatSaysNeitherLeavesThemOff()
	{
		final Quote quote = whip();
		quote.dataAgeSeconds = -1;

		final String text = GeTooltip.textFor(quote, null, BOX_TEXT);

		assertFalse(text, text.contains("Limit"));
		assertFalse(text, text.contains("Priced"));
	}

	/** An empty slot is not an offer, so there is nothing of yours to compare. */
	@Test
	public void anEmptySlotHasNoOfferToMeasure()
	{
		assertNull(GeSlotText.edgeOf(offer(GrandExchangeOfferState.EMPTY, 0), whip()));
		assertNull(GeSlotText.edgeOf(null, whip()));
		assertNull("and an item with no price has nothing to measure against",
			GeSlotText.edgeOf(offer(GrandExchangeOfferState.BUYING, 1), null));
	}

	/**
	 * How much taller the box has to be made is counted from the addition
	 * itself rather than from how many lines it might have had.
	 *
	 * <p>It is the one number that decides whether the last line is inside the
	 * box or under it, and the addition is four lines, or five, or six
	 * depending on what the server sent.
	 */
	@Test
	public void theRoomMadeIsCountedFromWhatIsActuallyBeingAdded()
	{
		assertEquals("one line takes no extra row",
			0, GeTooltip.Grown.rowsIn("Buy 1"));
		assertEquals(3, GeTooltip.Grown.rowsIn(GeTooltip.textFor(whip(), null, BOX_TEXT)));

		final Quote quote = whip();
		quote.limitRemaining = 3412;
		assertEquals("a limit is another row to find room for",
			4, GeTooltip.Grown.rowsIn(GeTooltip.textFor(quote, null, BOX_TEXT)));
	}

	/**
	 * And how wide is measured from the words, not from the colours round
	 * them: a tag is an instruction to the renderer and takes no space.
	 */
	@Test
	public void aColourTagIsNotPartOfTheLineItColours()
	{
		assertEquals("Margin +32,000",
			GeTooltip.Grown.plain("<col=1a1a1a>Margin <col=0b6b1f>+32,000"));
	}

	/**
	 * The plain lines are written in whatever colour the box itself uses.
	 *
	 * <p>Not the sidebar's palette, which is built for pale text on a dark
	 * panel and is the exact opposite of this box: its white came out
	 * invisible on the yellow, which is a poor showing for the two prices.
	 * Reading the colour off the line being added to also survives Jagex
	 * recolouring the box.
	 */
	@Test
	public void thePlainLinesTakeTheColourTheBoxAlreadyUses()
	{
		final String text = GeTooltip.textFor(whip(), null, 0x1a1a1a);

		assertTrue(text, text.contains("<col=1a1a1a>Buy "));
		assertTrue("and Sell, and everything that is a value rather than a verdict",
			text.contains("<col=1a1a1a>Sell "));
		assertFalse("the sidebar's white is nowhere near it", text.contains("ffffff"));
	}

	/** A colour is written as six hex digits, whatever the client hands over. */
	@Test
	public void aColourIsAlwaysSixDigits()
	{
		assertEquals("black is not the empty string", "<col=000000>", GeTooltip.colour(0));
		assertEquals("<col=0b6b1f>", GeTooltip.colour(0x0b6b1f));
		assertEquals("and whatever the client has in the high byte is not a colour",
			"<col=ffff9b>", GeTooltip.colour(0xff_ffff9b));
	}
}

package com.flippingrs;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardOpenOption;
import java.util.Collections;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The queue is what stands between a network blip and a lost evening of flips,
 * so its two promises are worth pinning: nothing leaves before the server has
 * it, and nothing is lost across a restart.
 */
public class TransactionQueueTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final Gson gson = new Gson();

	private static GeTransaction fill(String id)
	{
		final GeTransaction tx = new GeTransaction();
		tx.id = id;
		tx.itemId = 4151;
		tx.itemName = "Abyssal whip";
		tx.side = "buy";
		tx.quantity = 1;
		tx.grossValue = 1000;
		tx.occurredAt = "2026-08-31T12:00:00Z";
		return tx;
	}

	private File file() throws IOException
	{
		return new File(folder.newFolder("flippingrs"), "queue-1.json");
	}

	/**
	 * A damaged queue file loses fills; it never invents one.
	 *
	 * <p>The file is appended to as each fill arrives, so a client killed
	 * mid-write leaves a line half-finished, and a disk that fills up or a
	 * sync that never happened can leave worse. The queue is meant to drop
	 * what it cannot read and keep the rest, which is the right trade -- but
	 * only if what it keeps is what was written. A fill restored with another
	 * fill's id would be sent under that id, and the server groups and dedupes
	 * by exactly that: the real trade would be taken for a duplicate and
	 * dropped, and the invented one kept in its place.
	 *
	 * <p>So this writes a queue, breaks the file three hundred different ways
	 * and asks only that every fill that comes back is one that went in, whole.
	 *
	 * <p>The damage is the damage a crash does: a line cut short, a line that
	 * is not JSON, a line that is JSON and not a fill, a blank line. Not a byte
	 * flipped inside a field name -- that is a disk going bad rather than a
	 * client being killed, and what it leaves behind is a line that parses
	 * cleanly into a fill with a real id and no quantity, which the queue would
	 * keep and send as a trade of nothing. The server refuses it and the user
	 * is told a trade could not be recorded, so it is confusing rather than
	 * silent, and guarding it means the queue deciding what counts as a fill.
	 */
	@Test
	public void aDamagedQueueFileLosesFillsRatherThanInventingThem() throws Exception
	{
		final java.util.Random random = new java.util.Random(20260905L);
		for (int run = 0; run < 300; run++)
		{
			final File file = new File(folder.newFolder("run" + run), "queue-1.json");
			final java.util.Map<String, String> written = new java.util.HashMap<>();
			final TransactionQueue original = new TransactionQueue(gson, file);
			final int fills = 1 + random.nextInt(8);
			for (int i = 0; i < fills; i++)
			{
				final GeTransaction tx = fill("id" + run + "_" + i);
				tx.quantity = 1 + random.nextInt(1000);
				tx.grossValue = 1 + random.nextInt(1_000_000);
				tx.itemId = 4151 + i;
				original.add(tx);
				written.put(tx.id, tx.itemId + "/" + tx.quantity + "/" + tx.grossValue);
			}

			final byte[] whole = Files.readAllBytes(file.toPath());
			final String text = new String(whole, StandardCharsets.UTF_8);
			// 0 is a client killed mid-append, which takes the tail with it.
			// The rest destroy one line and leave the others alone.
			final int kind = random.nextInt(4);
			Files.write(file.toPath(), kind == 0
				? java.util.Arrays.copyOf(whole, random.nextInt(whole.length))
				: replaceLine(text, random, brokenLine(kind)));

			final TransactionQueue reopened = new TransactionQueue(gson, file);
			final List<GeTransaction> restored = reopened.peek(1000);
			for (GeTransaction tx : restored)
			{
				final String shape = "run " + run + ": " + tx.id + " came back as "
					+ tx.itemId + "/" + tx.quantity + "/" + tx.grossValue;
				assertTrue(shape + ", which was never written", written.containsKey(tx.id));
				assertEquals(shape, written.get(tx.id), tx.itemId + "/" + tx.quantity + "/" + tx.grossValue);
			}
			if (kind != 0)
			{
				// A line per fill is the whole point of the format: one line
				// nobody can read must not cost the fills below it.
				assertTrue("run " + run + ": one broken line cost more than itself, kept "
						+ restored.size() + " of " + fills,
					restored.size() >= fills - 1);
			}
		}
	}

	/** The ways a line comes back unreadable, short of the file being cut. */
	private static String brokenLine(int kind)
	{
		switch (kind)
		{
			case 1:
				return "}{ not json at all";
			case 2:
				// Parses, and is not a fill.
				return "{\"nonsense\":true}";
			default:
				// Not damage, but it happens.
				return "";
		}
	}

	private static byte[] replaceLine(String text, java.util.Random random, String with)
	{
		final String[] lines = text.split("\\n", -1);
		lines[random.nextInt(lines.length)] = with;
		return String.join("\n", lines).getBytes(StandardCharsets.UTF_8);
	}

	/**
	 * A fill comes back off disk exactly as it went on.
	 *
	 * <p>Everything queued crosses a restart this way, which is the whole
	 * point of the file, and every field of it means something to the site.
	 * The reference is what groups a thousand partial fills into one
	 * purchase. The time is what keeps a trade from being filed as recovered
	 * when it was watched happening. The side decides whether it was a
	 * purchase at all. Whether it was an estimate says if the gp can be
	 * trusted to the coin, and whether it completed says if the offer is still
	 * open.
	 *
	 * <p>Losing any of them is silent: the fill still has an id, still goes
	 * out, and still comes back accepted. Only the journal is wrong.
	 */
	@Test
	public void aFillComesBackOffDiskExactlyAsItWentOn() throws IOException
	{
		final File file = file();
		final GeTransaction tx = fill("t1");
		// Every field something other than its default, so a field that is not
		// written cannot come back looking right anyway.
		tx.offerRef = "offer-1";
		tx.itemId = 4151;
		tx.itemName = "Abyssal whip";
		tx.side = "sell";
		tx.quantity = 25;
		tx.grossValue = 30_864_175L;
		tx.offerPrice = 1_234_567L;
		tx.offerTotal = 100L;
		tx.completed = true;
		tx.cancelled = true;
		tx.estimated = true;
		tx.slot = 5;
		tx.world = 302;
		tx.occurredAt = "2026-08-31T12:00:00Z";
		tx.source = GeTransaction.SOURCE_ADOPTED;
		new TransactionQueue(gson, file).add(tx);

		final List<GeTransaction> back = new TransactionQueue(gson, file).peek(10);

		assertEquals(1, back.size());
		final GeTransaction got = back.get(0);
		assertEquals("id", tx.id, got.id);
		assertEquals("the reference the site groups a purchase by", tx.offerRef, got.offerRef);
		assertEquals("item", tx.itemId, got.itemId);
		assertEquals("item name", tx.itemName, got.itemName);
		assertEquals("side", tx.side, got.side);
		assertEquals("quantity", tx.quantity, got.quantity);
		assertEquals("the gp that moved", tx.grossValue, got.grossValue);
		assertEquals("the offer's price", tx.offerPrice, got.offerPrice);
		assertEquals("the offer's size", tx.offerTotal, got.offerTotal);
		assertEquals("whether the offer finished", tx.completed, got.completed);
		assertEquals("whether it was cancelled", tx.cancelled, got.cancelled);
		assertEquals("whether the gp is an estimate", tx.estimated, got.estimated);
		assertEquals("slot", tx.slot, got.slot);
		assertEquals("world", tx.world, got.world);
		assertEquals("when it happened", tx.occurredAt, got.occurredAt);
		assertEquals("whether it was watched or recovered", tx.source, got.source);
	}

	@Test
	public void peekingDoesNotRemove() throws IOException
	{
		final TransactionQueue queue = new TransactionQueue(gson, file());
		queue.add(fill("a"));
		queue.add(fill("b"));

		assertEquals(2, queue.peek(10).size());
		assertEquals("peek must leave the fills in place until the server has them",
			2, queue.size());
	}

	@Test
	public void confirmingRemovesOnlyWhatWasSent() throws IOException
	{
		final TransactionQueue queue = new TransactionQueue(gson, file());
		queue.add(fill("a"));
		queue.add(fill("b"));
		queue.add(fill("c"));

		final List<GeTransaction> batch = queue.peek(2);
		queue.confirm(batch);

		assertEquals(1, queue.size());
		assertEquals("c", queue.peek(10).get(0).id);
	}

	/**
	 * Confirmation matches on id, not on object identity, so a batch that has
	 * been round-tripped through JSON still clears the right rows.
	 */
	@Test
	public void confirmingMatchesOnId() throws IOException
	{
		final TransactionQueue queue = new TransactionQueue(gson, file());
		queue.add(fill("a"));

		queue.confirm(Collections.singletonList(fill("a")));

		assertTrue(queue.isEmpty());
	}

	@Test
	public void refusedFillsAreSetAsideNotDeleted() throws IOException
	{
		final File file = file();
		final TransactionQueue queue = new TransactionQueue(gson, file);
		queue.add(fill("a"));
		queue.add(fill("b"));

		queue.reject(queue.peek(1));

		assertEquals("the refused fill must not wedge the queue", 1, queue.size());
		assertEquals("b", queue.peek(10).get(0).id);

		final File dropped = new File(file.getParentFile(), "dropped-1.json");
		final String kept = new String(Files.readAllBytes(dropped.toPath()), StandardCharsets.UTF_8);
		assertTrue("the refused fill must still be readable on disk", kept.contains("\"id\":\"a\""));
		assertEquals("and it must not come back on restart", 1, new TransactionQueue(gson, file).size());
	}

	/**
	 * A client killed between staging a rewrite and moving it into place. The
	 * staging file has a fixed name so the next rewrite overwrites it rather
	 * than leaving it behind forever.
	 */
	@Test
	public void aStaleStagingFileFromAKilledRewriteIsOverwritten() throws IOException
	{
		final File file = file();
		final File staging = new File(file.getParentFile(), file.getName() + ".tmp");
		// What a rewrite killed part way through leaves behind: a line that
		// stops in the middle, with no newline after it.
		Files.write(staging.toPath(), "half a rewrite".getBytes(StandardCharsets.UTF_8));

		final TransactionQueue queue = new TransactionQueue(gson, file);
		queue.add(fill("a"));
		queue.add(fill("b"));
		// One fill left over the rewrite, so the next thing written lands
		// where the stale bytes are. Written after them instead of over them,
		// it joins onto the end of that half line and the fill is unreadable.
		queue.confirm(queue.peek(1));

		assertFalse("the staging file must have been moved into place", staging.exists());
		final List<GeTransaction> back = new TransactionQueue(gson, file).peek(10);
		assertEquals("the fill that had not been sent is still there", 1, back.size());
		assertEquals("b", back.get(0).id);
	}

	@Test
	public void pendingFillsSurviveARestart() throws IOException
	{
		final File file = file();
		final TransactionQueue first = new TransactionQueue(gson, file);
		first.add(fill("a"));
		first.add(fill("b"));

		final TransactionQueue reopened = new TransactionQueue(gson, file);

		assertEquals(2, reopened.size());
		assertEquals("order matters: fills are matched oldest first",
			"a", reopened.peek(10).get(0).id);
		assertEquals(1000, reopened.peek(10).get(0).grossValue);
	}

	@Test
	public void confirmedFillsDoNotComeBack() throws IOException
	{
		final File file = file();
		final TransactionQueue first = new TransactionQueue(gson, file);
		first.add(fill("a"));
		first.confirm(first.peek(10));

		assertTrue("a queue that resurrects sent fills would double every trade",
			new TransactionQueue(gson, file).isEmpty());
	}

	@Test
	public void aCorruptFileStartsEmptyRatherThanThrowing() throws IOException
	{
		final File file = file();
		Files.write(file.toPath(), "{ this is not the queue".getBytes(StandardCharsets.UTF_8));

		final TransactionQueue queue = new TransactionQueue(gson, file);

		assertTrue(queue.isEmpty());
		// And it still works from here on, which is the point: refusing to start
		// would mean nothing is recorded either.
		queue.add(fill("a"));
		assertEquals(1, queue.size());
	}

	@Test
	public void rowsWithNoIdAreDiscardedOnLoad() throws IOException
	{
		final File file = file();
		// An id-less row could never be de-duplicated by the server, so sending
		// it risks double counting.
		Files.write(file.toPath(),
			"[{\"itemId\":4151,\"quantity\":1},{\"id\":\"b\",\"itemId\":4151,\"quantity\":1}]"
				.getBytes(StandardCharsets.UTF_8));

		final TransactionQueue queue = new TransactionQueue(gson, file);

		assertEquals(1, queue.size());
		assertEquals("b", queue.peek(10).get(0).id);
	}

	// A queue written by the previous version -- one JSON array -- must still be
	// readable, or upgrading the plugin silently discards whatever was pending.
	@Test
	public void aLegacyWholeArrayFileIsStillRead() throws IOException
	{
	final File file = file();
	Files.write(file.toPath(),
	    "[{\"id\":\"a\",\"itemId\":4151,\"quantity\":1,\"grossValue\":1000}]"
	        .getBytes(StandardCharsets.UTF_8));

	final TransactionQueue queue = new TransactionQueue(gson, file);

	assertEquals(1, queue.size());
	assertEquals("a", queue.peek(10).get(0).id);

	// And it is rewritten in the new format, so later adds can append.
	final String rewritten = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
	assertFalse("the file should no longer be a JSON array", rewritten.trim().startsWith("["));
	}

	// A process killed mid-append leaves a torn final line. That must cost one
	// fill, not the whole backlog -- which is what the old whole-array format did,
	// because a truncated array fails to parse in its entirety.
	@Test
	public void aTornFinalLineCostsOnlyThatFill() throws IOException
	{
	final File file = file();
	final TransactionQueue first = new TransactionQueue(gson, file);
	first.add(fill("a"));
	first.add(fill("b"));

	// Simulate the tear: append half a record.
	Files.write(file.toPath(), "{\"id\":\"c\",\"itemI".getBytes(StandardCharsets.UTF_8),
	    StandardOpenOption.APPEND);

	final TransactionQueue reopened = new TransactionQueue(gson, file);

	assertEquals("the two complete fills must survive", 2, reopened.size());
	assertEquals("a", reopened.peek(10).get(0).id);
	assertEquals("b", reopened.peek(10).get(1).id);
	}

	/**
	 * A fresh install has no folder yet, and the first write is what says so.
	 * Confirming it exists before every fill cost as much as the fill's own
	 * write, to establish something true since startup.
	 */
	@Test
	public void theFolderIsMadeWhenTheFirstWriteFindsItMissing() throws IOException
	{
		final File dir = new File(folder.getRoot(), "not-there-yet");
		assertFalse(dir.exists());
		final File file = new File(dir, "queue-1.json");

		final TransactionQueue queue = new TransactionQueue(gson, file);
		queue.add(fill("a"));

		assertTrue("the folder must be made when a fill needs it", dir.isDirectory());
		assertEquals("and the fill must be on disk", 1, new TransactionQueue(gson, file).size());
	}

	/** And one tidied away under a running client is made again. */
	@Test
	public void aFolderRemovedUnderARunningClientIsMadeAgain() throws IOException
	{
		final File dir = folder.newFolder("flippingrs");
		final File file = new File(dir, "queue-1.json");
		final TransactionQueue queue = new TransactionQueue(gson, file);
		queue.add(fill("a"));

		assertTrue(file.delete());
		assertTrue(dir.delete());

		queue.add(fill("b"));

		assertTrue("the folder must be made again", dir.isDirectory());
		assertTrue("and the fill written since must be on disk", file.isFile());
		assertEquals("nothing leaves the queue itself over a missing folder", 2, queue.size());
	}

	/**
	 * A refusal that cannot be filed must still leave the queue. Holding it
	 * would wedge every later trade behind it forever, which is the whole
	 * reason refused rows are set aside rather than retried -- and the panel
	 * is meanwhile telling the user they were put somewhere they can be found,
	 * so the rows go to the log when they cannot go to the file.
	 */
	@Test
	public void refusedFillsThatCannotBeSetAsideStillLeaveTheQueue() throws IOException
	{
		final File dir = folder.newFolder("flippingrs");
		final File file = new File(dir, "queue-1.json");
		// A directory in the way of the set-aside file, so the write cannot work.
		assertTrue(new File(dir, "dropped-1.json").mkdir());

		final TransactionQueue queue = new TransactionQueue(gson, file);
		queue.add(fill("a"));
		queue.add(fill("b"));

		queue.reject(queue.peek(1));

		assertEquals("the queue must not wedge behind a row it could not file", 1, queue.size());
		assertEquals("b", queue.peek(10).get(0).id);
	}

	/**
	 * A full queue must not rewrite itself on every fill.
	 *
	 * <p>Evicting the oldest needs the file rewritten, because an append cannot
	 * express a removal. Doing that on the add that evicts costs one rewrite in
	 * every CAPACITY fills the first time and every fill thereafter, because
	 * the queue does not go back under the cap -- and a full queue is exactly
	 * the state a client is in when sending has been failing for hours, so each
	 * new trade turned into a rewrite of ten thousand rows.
	 */
	@Test
	public void aFullQueueDoesNotRewriteItselfOnEveryFill() throws IOException
	{
		final File file = file();
		// A hundredth of the cap is the compaction interval, so this one
		// compacts every third eviction.
		final TransactionQueue queue = new TransactionQueue(gson, file, 300);
		for (int i = 0; i < 300; i++)
		{
			queue.add(fill("a" + i));
		}
		assertEquals(300, lines(file));

		queue.add(fill("over-1"));
		assertEquals("the evicted row is left in the file, not rewritten out of it", 301, lines(file));
		queue.add(fill("over-2"));
		assertEquals(302, lines(file));

		queue.add(fill("over-3"));
		assertEquals("the third eviction compacts it", 300, lines(file));

		// And the queue itself never went over the cap, nor kept the oldest.
		assertEquals(300, queue.size());
		final List<GeTransaction> held = queue.peek(1000);
		assertEquals("a3", held.get(0).id);
		assertEquals("over-3", held.get(299).id);

		// And the counting starts again from there. If it did not, every
		// eviction after the first compaction would be past the interval and
		// compact too, which is the rewrite-per-fill this exists to avoid.
		queue.add(fill("over-4"));
		assertEquals(301, lines(file));
		queue.add(fill("over-5"));
		assertEquals("counting up to the next compaction, not compacting", 302, lines(file));
	}

	/**
	 * A line carrying two whole fills costs that line and no more.
	 *
	 * <p>An append writes the fill and its newline in one call, so a client
	 * killed part way through can get the fill down without the newline. The
	 * next append then lands on the end of it, and one line holds two whole
	 * fills.
	 *
	 * <p>That is not a broken line -- both fills on it are whole -- so it is
	 * worth saying which way it goes. The line is dropped and the rest of the
	 * file is kept, which is the same trade the queue makes everywhere else:
	 * the two fills on it are lost, and nothing is invented from the halves.
	 */
	@Test
	public void twoFillsRunTogetherOnOneLineCostThatLineAndNoMore() throws IOException
	{
		final File file = file();
		final String torn = gson.toJson(fill("a")) + gson.toJson(fill("b"));
		Files.write(file.toPath(),
			(torn + "\n" + gson.toJson(fill("c")) + "\n").getBytes(StandardCharsets.UTF_8));

		final TransactionQueue queue = new TransactionQueue(gson, file);

		assertEquals("the line that could be read is kept", 1, queue.size());
		assertEquals("c", queue.peek(10).get(0).id);
	}

	/**
	 * A compaction that cannot be written must not stop the file recording.
	 *
	 * <p>Once the queue is full every add evicts, and an eviction is expressed
	 * by rewriting the file rather than appending to it. If that rewrite fails,
	 * the new fill was never appended either -- and the eviction counter stays
	 * over the mark, so every add after it goes the same way. One bad rewrite
	 * stopped the file recording anything for the rest of the session, in the
	 * one state where every trade in the queue is already at risk.
	 *
	 * <p>A directory where the staging file goes is a rewrite that cannot be
	 * written and an append that still can, which is a real shape on Windows:
	 * a scanner holding the file open fails the move and not the append.
	 */
	@Test
	public void aFillStillReachesDiskWhenTheCompactionCannotBeWritten() throws IOException
	{
		final File file = file();
		final TransactionQueue queue = new TransactionQueue(gson, file, 300);
		for (int i = 0; i < 300; i++)
		{
			queue.add(fill("a" + i));
		}
		assertEquals(300, lines(file));

		// Nothing can be written where the rewrite stages its copy.
		assertTrue(new File(file.getParentFile(), file.getName() + ".tmp").mkdir());

		// The third eviction is a compaction, and it cannot be written.
		queue.add(fill("over-1"));
		queue.add(fill("over-2"));
		queue.add(fill("over-3"));

		assertEquals("the fill the compaction could not write is appended instead", 303, lines(file));

		// And so is every one after it, rather than the file going quiet.
		queue.add(fill("over-4"));
		queue.add(fill("over-5"));
		assertEquals(305, lines(file));

		final TransactionQueue reopened = new TransactionQueue(gson, file, 300);
		final List<GeTransaction> restored = reopened.peek(1000);
		assertEquals("the newest fill is on disk", "over-5",
			restored.get(restored.size() - 1).id);
	}

	/**
	 * A client killed while the file was running ahead of the queue restores
	 * more rows than the cap. The next fill has to bring it back down rather
	 * than sit over the cap for good.
	 */
	@Test
	public void aFileRestoredFromOverTheCapIsBroughtBackDown() throws IOException
	{
		// A thousand, so the compaction interval is ten: dropping three at once
		// is well under it, and only the rule about dropping more than one can
		// bring the file back down. At three hundred the interval would be
		// three, and the same add would have compacted either way -- which is
		// what this test used to be quietly asserting.
		final File file = file();
		final TransactionQueue first = new TransactionQueue(gson, file, 1000);
		for (int i = 0; i < 1002; i++)
		{
			first.add(fill("a" + i));
		}
		assertEquals("two evictions, not yet compacted", 1002, lines(file));

		final TransactionQueue reopened = new TransactionQueue(gson, file, 1000);
		assertEquals("the file's extra rows are all restored", 1002, reopened.size());

		reopened.add(fill("next"));

		assertEquals("back to the cap", 1000, reopened.size());
		assertEquals("and compacted, because it had to drop more than one", 1000, lines(file));
	}

	private static int lines(File file) throws IOException
	{
		int count = 0;
		for (String line : new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8).split("\n"))
		{
			if (!line.trim().isEmpty())
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * A byte that is not valid UTF-8 must cost the line it is on and no more.
	 * The strict readers throw on one, which would abandon the read and lose
	 * every fill after it -- and this file is appended to a line at a time by
	 * a process that can be killed between the two halves of a character.
	 */
	@Test
	public void oneBadByteDoesNotCostTheRestOfTheFile() throws IOException
	{
		final File file = file();
		try (java.io.OutputStream out = Files.newOutputStream(file.toPath()))
		{
			out.write("{\"id\":\"a\",\"quantity\":1}\n{\"id\":\"b\",\"itemName\":\"x"
				.getBytes(StandardCharsets.UTF_8));
			// 0xFF never begins a valid UTF-8 sequence.
			out.write(new byte[]{(byte) 0xFF});
			out.write("\"}\n{\"id\":\"c\",\"quantity\":1}\n".getBytes(StandardCharsets.UTF_8));
		}

		final TransactionQueue queue = new TransactionQueue(gson, file);

		assertEquals("the fills either side of the bad byte must survive", 3, queue.size());
		final List<GeTransaction> restored = queue.peek(10);
		assertEquals("a", restored.get(0).id);
		assertEquals("b", restored.get(1).id);
		assertEquals("c", restored.get(2).id);
	}
}

package com.flippingrs;

import java.time.Instant;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static net.runelite.api.GrandExchangeOfferState.BOUGHT;
import static net.runelite.api.GrandExchangeOfferState.BUYING;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_BUY;
import static net.runelite.api.GrandExchangeOfferState.CANCELLED_SELL;
import static net.runelite.api.GrandExchangeOfferState.EMPTY;
import static net.runelite.api.GrandExchangeOfferState.SELLING;
import static net.runelite.api.GrandExchangeOfferState.SOLD;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The tracker is where a bug turns into wrong money in somebody's journal, and
 * it is pure, so it gets the tests.
 */
public class OfferTrackerTest
{
	private static final int WHIP = 4151;
	private static final Instant NOW = Instant.parse("2026-08-31T12:00:00Z");

	/** A Grand Exchange slot as the client would report it. */
	private static class Offer implements GrandExchangeOffer
	{
		private final GrandExchangeOfferState state;
		private final int itemId;
		private final int price;
		private final int total;
		private final int sold;
		private final int spent;

		Offer(GrandExchangeOfferState state, int itemId, int price, int total, int sold, int spent)
		{
			this.state = state;
			this.itemId = itemId;
			this.price = price;
			this.total = total;
			this.sold = sold;
			this.spent = spent;
		}

		@Override
		public int getQuantitySold()
		{
			return sold;
		}

		@Override
		public int getItemId()
		{
			return itemId;
		}

		@Override
		public int getTotalQuantity()
		{
			return total;
		}

		@Override
		public int getPrice()
		{
			return price;
		}

		@Override
		public int getSpent()
		{
			return spent;
		}

		@Override
		public GrandExchangeOfferState getState()
		{
			return state;
		}
	}

	private final OfferTracker tracker = new OfferTracker(() -> "ref-1");

	/** Counts how often the item name was actually asked for. */
	private final AtomicInteger nameLookups = new AtomicInteger();

	private OfferTracker.Observation observe(SavedOffer previous, GrandExchangeOffer offer)
	{
		return tracker.observe(3, previous, offer,
			() ->
			{
				nameLookups.incrementAndGet();
				return "Abyssal whip";
			},
			302, NOW);
	}

	@Test
	public void newOfferIsBaselinedAndReportsNothing()
	{
		final OfferTracker.Observation seen = observe(null, new Offer(BUYING, WHIP, 1000, 10, 0, 0));

		assertNull("placing an offer is not a trade", seen.transaction);
		assertNotNull(seen.saved);
		assertEquals("ref-1", seen.saved.offerRef);
		assertFalse("an empty offer has no history to adopt", seen.adopted);
	}

	@Test
	public void partialFillIsReportedAsTheDifference()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 0, 0), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(BUYING, WHIP, 1000, 10, 4, 3800));

		assertNotNull(seen.transaction);
		assertEquals(4, seen.transaction.quantity);
		// 3800, not 4 * 1000: a buy fills at or under the price offered, and the
		// difference is the user's, not a rounding artefact.
		assertEquals(3800, seen.transaction.grossValue);
		assertEquals("buy", seen.transaction.side);
		assertEquals("ref-1", seen.transaction.offerRef);
		assertFalse(seen.transaction.completed);
		assertFalse(seen.transaction.estimated);
	}

	@Test
	public void onlyTheNewQuantityIsReportedOnASecondFill()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 4, 3800), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(BOUGHT, WHIP, 1000, 10, 10, 9800));

		assertNotNull(seen.transaction);
		assertEquals("6 more, not the running total of 10", 6, seen.transaction.quantity);
		assertEquals(6000, seen.transaction.grossValue);
		assertTrue("BOUGHT is terminal", seen.transaction.completed);
		assertEquals("both fills belong to one purchase", "ref-1", seen.transaction.offerRef);
	}

	/**
	 * The login burst. The client re-fires every occupied slot on login with the
	 * quantity already sold; with a persisted baseline the difference is zero.
	 */
	@Test
	public void replayingTheSameStateReportsNothing()
	{
		final Offer offer = new Offer(BUYING, WHIP, 1000, 10, 4, 3800);
		final SavedOffer previous = SavedOffer.of(offer, "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, offer);

		assertNull("a login replay is not a new trade", seen.transaction);
		assertNotNull(seen.saved);
	}

	/**
	 * Installing the plugin mid-flip. The progress happened unobserved, so it
	 * is adopted as the baseline and reported once as a recovered fill with
	 * no time on it, for the server to decide whether it is new. It is never
	 * backdated to now.
	 */
	@Test
	public void anOfferAlreadyInProgressIsRecoveredNotInvented()
	{
		final OfferTracker.Observation seen = observe(null, new Offer(BUYING, WHIP, 1000, 10, 6, 5900));

		assertNotNull("what had filled is reported, flagged, for the server to judge", seen.transaction);
		assertEquals(GeTransaction.SOURCE_ADOPTED, seen.transaction.source);
		assertEquals(6, seen.transaction.quantity);
		assertEquals("the exact gp it found, not price times quantity", 5900, seen.transaction.grossValue);
		assertNull("but no time is claimed for it", seen.transaction.occurredAt);
		assertEquals("ref-1", seen.transaction.offerRef);
		assertFalse(seen.transaction.completed);
		assertTrue(seen.adopted);
		assertNotNull(seen.saved);
		assertEquals(6, seen.saved.quantitySold);

		// From the baseline on, further fills are reported normally, and live.
		final OfferTracker.Observation next = observe(seen.saved, new Offer(BOUGHT, WHIP, 1000, 10, 10, 9900));
		assertNotNull(next.transaction);
		assertEquals(4, next.transaction.quantity);
		assertEquals(GeTransaction.SOURCE_LIVE, next.transaction.source);
		assertEquals("one purchase, both parts", "ref-1", next.transaction.offerRef);
	}

	/** An offer found already finished is recovered whole, and marked complete. */
	@Test
	public void anOfferFoundAlreadyCompleteIsRecoveredAsComplete()
	{
		final OfferTracker.Observation seen = observe(null, new Offer(SOLD, WHIP, 1000, 10, 10, 10_500));

		assertNotNull(seen.transaction);
		assertEquals("sell", seen.transaction.side);
		assertEquals(10, seen.transaction.quantity);
		assertEquals(10_500, seen.transaction.grossValue);
		assertTrue(seen.transaction.completed);
		assertNull(seen.transaction.occurredAt);
	}

	@Test
	public void collectingASlotClearsTheBaseline()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BOUGHT, WHIP, 1000, 10, 10, 9800), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(EMPTY, 0, 0, 0, 0, 0));

		assertNull(seen.transaction);
		assertNull("an emptied slot must forget its offer, or the next one is mistaken for it", seen.saved);
	}

	/**
	 * Re-placing an identical offer after collecting. Item, price and size all
	 * match the old one, and only the progress going backwards says otherwise.
	 */
	@Test
	public void anIdenticalReplacementOfferIsANewOffer()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BOUGHT, WHIP, 1000, 10, 10, 9800), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(BUYING, WHIP, 1000, 10, 0, 0));

		assertNull("nothing has traded on the new offer yet", seen.transaction);
		assertNotNull(seen.saved);
		assertEquals(0, seen.saved.quantitySold);
	}

	/**
	 * A buy placed and cancelled untouched, then a sell of the same item at the
	 * same price and size, with the collect between them never observed. Both
	 * sit at zero progress, and only the side says they are different offers.
	 */
	@Test
	public void aBuyAndASellOfTheSameSizeAreDifferentOffers()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(CANCELLED_BUY, WHIP, 1000, 10, 0, 0), "old", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(SELLING, WHIP, 1000, 10, 0, 0));

		assertNull(seen.transaction);
		assertNotNull(seen.saved);
		assertEquals("a new offer gets its own reference", "ref-1", seen.saved.offerRef);
	}

	/**
	 * A cancelled offer reports what filled before it stopped, and says it is
	 * finished. Both sides: an offer the server still believes is live is one
	 * it will keep matching later sales against, and a sale can be cancelled
	 * exactly as a purchase can.
	 */
	@Test
	public void aCancelledOfferStillReportsWhatFilled()
	{
		for (boolean buy : new boolean[]{true, false})
		{
			final SavedOffer previous = SavedOffer.of(
				new Offer(buy ? BUYING : SELLING, WHIP, 1000, 10, 2, 2000), "ref-1", false);

			final OfferTracker.Observation seen = observe(previous,
				new Offer(buy ? CANCELLED_BUY : CANCELLED_SELL, WHIP, 1000, 10, 5, 5000));

			final String side = buy ? "a cancelled buy" : "a cancelled sale";
			assertNotNull(side, seen.transaction);
			assertEquals(side, 3, seen.transaction.quantity);
			assertTrue(side + " is cancelled", seen.transaction.cancelled);
			assertTrue(side + " is finished", seen.transaction.completed);
		}
	}

	@Test
	public void aCancellationWithNoFillReportsNothing()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 0, 0), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(CANCELLED_BUY, WHIP, 1000, 10, 0, 0));

		assertNull("cancelling an untouched offer is not a trade", seen.transaction);
		assertNotNull("but the cancellation still has to be remembered", seen.saved);
		assertEquals(CANCELLED_BUY, seen.saved.state);
	}

	@Test
	public void sellsAreReportedAsSells()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(SELLING, WHIP, 1000, 10, 0, 0), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(SOLD, WHIP, 1000, 10, 10, 10_500));

		assertNotNull(seen.transaction);
		assertEquals("sell", seen.transaction.side);
		// A sale fills at the asking price or better, so more than asked is
		// normal and must not be mistaken for a corrupt total.
		assertEquals(10_500, seen.transaction.grossValue);
		assertFalse(seen.transaction.estimated);
	}

	/**
	 * The client's running total is an int, and a big enough offer overflows it.
	 * A wrapped total must not become a wrong profit.
	 */
	@Test
	public void anImpossibleRunningTotalFallsBackToPriceTimesQuantity()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 3_000_000, 1000, 0, 0), "ref-1", false);
		// 800 whips at 3M is 2.4 billion, past what an int holds, so the client
		// reports a wrapped negative.
		final int wrapped = (int) (800L * 3_000_000L);

		final OfferTracker.Observation seen =
			observe(previous, new Offer(BUYING, WHIP, 3_000_000, 1000, 800, wrapped));

		assertNotNull(seen.transaction);
		assertEquals(800, seen.transaction.quantity);
		assertEquals(800L * 3_000_000L, seen.transaction.grossValue);
		assertTrue("the figure is approximate and says so", seen.transaction.estimated);
	}

	/**
	 * A total that wrapped once between two observations. The difference
	 * modulo 2^32 is exact, and it used to be discarded as negative.
	 */
	@Test
	public void aTotalThatWrappedOnceIsRecoveredExactly()
	{
		final SavedOffer previous = SavedOffer.of(
			new Offer(BUYING, WHIP, 2_000_000, 1100, 1000, 2_000_000_000), "ref-1", false);
		final int wrapped = (int) 2_200_000_000L;

		final OfferTracker.Observation seen =
			observe(previous, new Offer(BOUGHT, WHIP, 2_000_000, 1100, 1100, wrapped));

		assertNotNull(seen.transaction);
		assertEquals(100, seen.transaction.quantity);
		assertEquals(200_000_000L, seen.transaction.grossValue);
		assertFalse("exact, so not flagged", seen.transaction.estimated);
	}

	/**
	 * A wrap that lands positive. 2000 at 3M is 6.0B; the int reads 1.7B,
	 * which is under the 6.0B asked and used to pass as a plausible buy. The
	 * fill alone is bigger than the total could ever have tracked, so the
	 * total is not consulted.
	 */
	@Test
	public void aFillTooLargeForTheRunningTotalIsEstimatedEvenWhenTheWrapLandsPositive()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 3_000_000, 2000, 0, 0), "ref-1", false);
		final int wrapped = (int) 6_000_000_000L;
		assertTrue("the premise: the wrap lands positive", wrapped > 0);

		final OfferTracker.Observation seen =
			observe(previous, new Offer(BOUGHT, WHIP, 3_000_000, 2000, 2000, wrapped));

		assertNotNull(seen.transaction);
		assertEquals(6_000_000_000L, seen.transaction.grossValue);
		assertTrue(seen.transaction.estimated);
	}

	@Test
	public void aBuyCostingMoreThanOfferedIsRejectedAsImpossible()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 0, 0), "ref-1", false);

		// The exchange never fills a buy above the offered price, so 12,000 for
		// 10 at 1,000 cannot be right.
		final OfferTracker.Observation seen = observe(previous, new Offer(BUYING, WHIP, 1000, 10, 10, 12_000));

		assertNotNull(seen.transaction);
		assertEquals(10_000, seen.transaction.grossValue);
		assertTrue(seen.transaction.estimated);
	}

	@Test
	public void aSaleYieldingLessThanAskedIsRejectedAsImpossible()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(SELLING, WHIP, 1000, 10, 0, 0), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(SELLING, WHIP, 1000, 10, 10, 8_000));

		assertNotNull(seen.transaction);
		assertEquals(10_000, seen.transaction.grossValue);
		assertTrue(seen.transaction.estimated);
	}

	@Test
	public void everyFillCarriesTheContextTheServerNeeds()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 0, 0), "ref-1", false);

		final OfferTracker.Observation seen = observe(previous, new Offer(BUYING, WHIP, 1000, 10, 4, 4000));

		assertNotNull(seen.transaction);
		assertEquals(WHIP, seen.transaction.itemId);
		assertEquals("Abyssal whip", seen.transaction.itemName);
		assertEquals(3, seen.transaction.slot);
		assertEquals(302, seen.transaction.world);
		assertEquals(1000, seen.transaction.offerPrice);
		assertEquals(10, seen.transaction.offerTotal);
		assertEquals(NOW.toString(), seen.transaction.occurredAt);
		assertFalse("every fill needs an idempotency key", seen.transaction.id.isEmpty());
	}

	/**
	 * A baseline with no offer reference -- an older config value, or a
	 * half-written one. Carrying it forward would send every later fill with an
	 * empty offerRef, and the server groups fills into one purchase by exactly
	 * that field, so a single buy would land as a string of unrelated lots.
	 *
	 * <p>Both shapes of "none" count. A value written by a version that had no
	 * references at all reads back as null; one written by a config save that
	 * did not finish reads back as the empty string, and an empty reference is
	 * exactly the one that would be sent on every later fill.
	 */
	@Test
	public void aBaselineWithNoOfferRefIsReadopted()
	{
		for (String none : new String[]{null, ""})
		{
			final SavedOffer stale = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 4, 4000), none, false);

			final OfferTracker.Observation seen = observe(stale, new Offer(BUYING, WHIP, 1000, 10, 6, 6000));

			final String shape = none == null ? "a null reference" : "an empty reference";
			assertNotNull(shape + ": the progress is reported as recovered under a new one",
				seen.transaction);
			assertEquals(shape, GeTransaction.SOURCE_ADOPTED, seen.transaction.source);
			assertEquals(shape, 6, seen.transaction.quantity);
			assertNotNull(shape, seen.saved);
			assertEquals(shape, "ref-1", seen.saved.offerRef);
		}
	}

	@Test
	public void eachFillGetsItsOwnIdempotencyKey()
	{
		final SavedOffer first = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 0, 0), "ref-1", false);
		final OfferTracker.Observation a = observe(first, new Offer(BUYING, WHIP, 1000, 10, 4, 4000));

		assertNotNull(a.transaction);
		final OfferTracker.Observation b = observe(a.saved, new Offer(BOUGHT, WHIP, 1000, 10, 10, 10_000));

		assertNotNull(b.transaction);
		assertFalse("two fills sharing an id would silently drop one",
			a.transaction.id.equals(b.transaction.id));
	}

	/**
	 * Resolving the item name means asking the client's item manager, and most
	 * events are a state change or a login replay with nothing to report. The
	 * lookup belongs on the path that produces a fill, not on every event the
	 * game thread hands over.
	 */
	@Test
	public void theItemNameIsOnlyLookedUpWhenSomethingFilled()
	{
		final SavedOffer previous = SavedOffer.of(new Offer(BUYING, WHIP, 1000, 10, 4, 4000), "ref-1", false);

		observe(null, new Offer(BUYING, WHIP, 1000, 10, 0, 0));      // a new offer
		observe(previous, new Offer(BUYING, WHIP, 1000, 10, 4, 4000)); // a replay
		observe(previous, new Offer(CANCELLED_BUY, WHIP, 1000, 10, 4, 4000)); // no progress
		observe(previous, new Offer(EMPTY, 0, 0, 0, 0, 0));           // collected

		assertEquals("none of those reported a fill", 0, nameLookups.get());

        observe(previous, new Offer(BOUGHT, WHIP, 1000, 10, 10, 10_000));

		assertEquals("and this one did", 1, nameLookups.get());
	}

	/**
	 * A collect that was never seen costs nothing, as long as the two offers
	 * can be told apart at all.
	 *
	 * <p>The other property test collects between every offer, so the slot is
	 * always empty before the next one and the tracker never has to decide.
	 * The interesting case is the collect going unseen -- the event not
	 * arriving, or the plugin not running for it -- which leaves the previous
	 * offer's baseline sitting in the slot when a new offer arrives.
	 *
	 * <p>Two identical finished offers cannot be told apart and never will be.
	 * Everything else can: a different price, a different size, the other side
	 * of the book, or an offer that had finished being followed by one that is
	 * running. So every offer here differs from the one before it in exactly
	 * one of those ways, and the count still has to come out exact.
	 *
	 * <p>The first look at an offer is sometimes mid-flight rather than at
	 * placement, which is what a login burst looks like.
	 */
	@Test
	public void aMissedCollectCostsNothingWhenTheOffersDiffer()
	{
		final java.util.Random random = new java.util.Random(20260906L);
		for (int run = 0; run < 3000; run++)
		{
			SavedOffer saved = null;
			long reported = 0;
			long actual = 0;
			int price = 2 + random.nextInt(1000);
			int total = 2 + random.nextInt(20);
			boolean buy = random.nextBoolean();

			final int offers = 2 + random.nextInt(3);
			for (int o = 0; o < offers; o++)
			{
				// How this offer differs from the one before it. The first
				// offer has nothing to differ from.
				if (o > 0)
				{
					switch (random.nextInt(4))
					{
						case 0:
							price = price + 1 + random.nextInt(100);
							break;
						case 1:
							total = total + 1 + random.nextInt(10);
							break;
						case 2:
							buy = !buy;
							break;
						default:
							// Nothing changes: the previous offer having
							// finished and this one running is the whole of
							// what separates them.
							break;
					}
				}

				final GrandExchangeOfferState running = buy ? BUYING : SELLING;
				final int looks = 2 + random.nextInt(6);
				// Skipping the placement is a login burst: the first sight of
				// the offer already has fills on it.
				if (random.nextBoolean())
				{
					final OfferTracker.Observation placed =
						observe(saved, new Offer(running, WHIP, price, total, 0, 0));
					saved = placed.saved;
					if (placed.transaction != null)
					{
						reported += placed.transaction.quantity;
					}
				}

				int sold = 0;
				int spent = 0;
				for (int look = 1; look <= looks; look++)
				{
					final int more = random.nextInt(Math.max(1, total - sold + 1));
					sold += more;
					spent += more * price;
					final GrandExchangeOfferState state = look < looks
						? running
						: (random.nextBoolean()
							? (buy ? BOUGHT : SOLD)
							: (buy ? CANCELLED_BUY : CANCELLED_SELL));

					final OfferTracker.Observation seen =
						observe(saved, new Offer(state, WHIP, price, total, sold, spent));
					saved = seen.saved;
					if (seen.transaction != null)
					{
						reported += seen.transaction.quantity;
					}
				}
				actual += sold;

				// The collect, half the time. When it is missed the next offer
				// meets this one's baseline still in the slot.
				if (random.nextBoolean())
				{
					saved = observe(saved, new Offer(EMPTY, 0, 0, 0, 0, 0)).saved;
				}
			}

			assertEquals("run " + run + ": every item filled reported exactly once",
				actual, reported);
		}
	}

	/**
	 * An offer that was finished cannot be running again.
	 *
	 * <p>Cancel a buy that is part filled, collect it, and place the same buy
	 * over again -- the same item at the same price for the same number, which
	 * is what flipping is. If the collect between them is missed, the only
	 * things saying these are two purchases are that the first one had
	 * finished and the second is under way. The progress does not say it: the
	 * new offer picks up where the old one left off and passes straight
	 * through the check that the count has not gone backwards.
	 *
	 * <p>Read as one offer, the fills the new one already has are counted as
	 * the difference from the old one's, so most of them are never reported at
	 * all, and the ones that are go out under the finished purchase's
	 * reference.
	 */
	@Test
	public void aFinishedOfferIsNotTheSameAsOneThatIsRunning()
	{
		// Cancelled with three of ten bought, and those three already sent.
		final SavedOffer cancelled = SavedOffer.of(
			new Offer(CANCELLED_BUY, WHIP, 1000, 10, 3, 3000), "ref-old", false);

		// The same buy placed again, and five of ten filled before we look.
		final OfferTracker.Observation seen =
			observe(cancelled, new Offer(BUYING, WHIP, 1000, 10, 5, 5000));

		assertNotNull("a purchase that is under way is not the cancelled one", seen.transaction);
		assertEquals("all five of the new offer's fills, not two",
			5, seen.transaction.quantity);
		assertEquals(GeTransaction.SOURCE_ADOPTED, seen.transaction.source);
		assertNotNull(seen.saved);
		assertEquals("and a reference of its own", "ref-1", seen.saved.offerRef);
	}

	/**
	 * The collect between two identical offers was never seen -- the client was
	 * killed holding a finished purchase, or the event did not arrive -- so the
	 * slot goes straight from a completed offer to an identical new one. The
	 * item, the price and the size all match; the only thing saying this is a
	 * different purchase is that the progress went backwards.
	 *
	 * <p>Without that check the new offer keeps the finished one's reference,
	 * and the server groups fills into one purchase by exactly that field: two
	 * purchases would arrive as one, with the second one's cost folded into the
	 * first.
	 */
	@Test
	public void anIdenticalOfferAfterAMissedCollectIsANewPurchase()
	{
		final SavedOffer finished = SavedOffer.of(
			new Offer(BOUGHT, WHIP, 1000, 10, 10, 10_000), "ref-old", false);

		final OfferTracker.Observation placed =
			observe(finished, new Offer(BUYING, WHIP, 1000, 10, 0, 0));

		assertNull("placing it is not a trade", placed.transaction);
		assertNotNull(placed.saved);
		assertEquals("a second purchase needs a reference of its own", "ref-1", placed.saved.offerRef);

		final OfferTracker.Observation filled =
			observe(placed.saved, new Offer(BUYING, WHIP, 1000, 10, 4, 3_900));

		assertNotNull(filled.transaction);
		assertEquals(4, filled.transaction.quantity);
		assertEquals("its fills must not join the purchase that had already finished",
			"ref-1", filled.transaction.offerRef);
	}

	/**
	 * Each of the things that identify an offer has to count. A finished
	 * purchase collected unseen, then a new one in the same slot that is
	 * already full: the progress cannot tell those apart, so the item, the
	 * price and the size are all that is left. Drop any one of them and the
	 * new purchase's fills are filed under the finished one, because fills are
	 * grouped into a purchase by its reference.
	 */
	@Test
	public void anOfferDifferingInAnyOneThingIsANewPurchase()
	{
		final SavedOffer finished = SavedOffer.of(
			new Offer(BOUGHT, WHIP, 1000, 10, 10, 10_000), "ref-old", false);

		final GrandExchangeOffer[] differing = {
			new Offer(BOUGHT, 11802, 1000, 10, 10, 10_000),   // another item
			new Offer(BOUGHT, WHIP, 2000, 10, 10, 20_000),    // another price
			new Offer(BOUGHT, WHIP, 1000, 20, 20, 20_000),    // another size
		};
		for (GrandExchangeOffer offer : differing)
		{
			final OfferTracker.Observation seen = observe(finished, offer);

			assertNotNull(seen.saved);
			assertEquals("this is not the purchase that finished", "ref-1", seen.saved.offerRef);
			assertNotNull("and what it has already filled is recovered", seen.transaction);
			assertEquals("ref-1", seen.transaction.offerRef);
		}
	}

	/**
	 * Over a randomised life of one slot -- offers placed, partly filled at
	 * mixed prices, completed or cancelled, collected, and the slot reused --
	 * every item the exchange filled is reported exactly once, and the gp
	 * reported adds up to exactly what the client's running total moved by.
	 *
	 * <p>This is the class where a mistake is wrong money rather than a wrong
	 * pixel, and its arithmetic is the kind that can be subtly wrong in a way
	 * no hand-written case happens to hit: an off-by-one on a boundary, a
	 * delta taken against the wrong baseline, a slot reuse counted twice.
	 * Three thousand randomised lives cover ground a person would not think
	 * to write down.
	 *
	 * <p>The offers generated stay inside the rules the exchange guarantees --
	 * an offer never moves more than max cash, a buy fills at or under the
	 * ask, a sale at or over it -- so nothing here should ever come back
	 * flagged as approximate either.
	 */
	@Test
	public void everyItemFilledIsReportedOnceOverTheLifeOfASlot()
	{
		final java.util.Random random = new java.util.Random(20260903L);
		for (int run = 0; run < 3000; run++)
		{
			SavedOffer saved = null;
			long reportedQuantity = 0;
			long reportedGross = 0;
			long actuallyFilled = 0;
			long actuallyMoved = 0;

			final int offers = 1 + random.nextInt(4);
			for (int o = 0; o < offers; o++)
			{
				final boolean buy = random.nextBoolean();
				final GrandExchangeOfferState running = buy ? BUYING : SELLING;
				// Two or more, so a fill can never come to nothing; and small
				// enough that one offer stays well inside max cash, which is
				// what the exchange itself caps an offer at.
				final int price = 2 + random.nextInt(1_000_000);
				final int total = 1 + random.nextInt(Math.max(1, Math.min(1000, Integer.MAX_VALUE / 2 / price)));

				// Placed: nothing filled, so nothing to adopt.
				OfferTracker.Observation seen = observe(saved, new Offer(running, WHIP, price, total, 0, 0));
				saved = seen.saved;
				assertNull("placing an offer is not a trade", seen.transaction);

				int sold = 0;
				int spent = 0;
				final int looks = 1 + random.nextInt(8);
				for (int look = 1; look <= looks; look++)
				{
					final int more = random.nextInt(Math.max(1, total - sold + 1));
					sold += more;
					// A buy fills at or under the asking price and a sale at or
					// over it, which is what the tracker checks the client's
					// total against.
					final long moved = buy
						? (long) more * price - random.nextInt(Math.max(1, more))
						: (long) more * price + random.nextInt(Math.max(1, more));
					// The client's running total is an int, so this one has to
					// be, and the narrowing has to be said out loud: the sizes
					// chosen above keep price times quantity inside half an
					// int, and if that ever stops being true this test would
					// otherwise compare the tracker's answer against a total
					// that quietly wrapped on the way in.
					assertTrue("run " + run + ": the offer has to stay inside an int, as the exchange's own do",
						spent + moved <= Integer.MAX_VALUE);
					spent += (int) moved;

					final GrandExchangeOfferState state;
					if (look < looks)
					{
						state = running;
					}
					else if (random.nextBoolean())
					{
						state = buy ? BOUGHT : SOLD;
					}
					else
					{
						state = buy ? CANCELLED_BUY : CANCELLED_SELL;
					}

					seen = observe(saved, new Offer(state, WHIP, price, total, sold, spent));
					saved = seen.saved;
					if (seen.transaction != null)
					{
						reportedQuantity += seen.transaction.quantity;
						reportedGross += seen.transaction.grossValue;
						assertFalse("run " + run + ": an offer inside the exchange's own rules is not a guess",
							seen.transaction.estimated);
					}
				}
				actuallyFilled += sold;
				actuallyMoved += spent;

				// Collected, freeing the slot for the next offer.
				seen = observe(saved, new Offer(EMPTY, 0, 0, 0, 0, 0));
				saved = seen.saved;
				assertNull("collecting is not a trade", seen.transaction);
				assertNull("and it forgets the slot", saved);
			}

			assertEquals("run " + run + ": every item filled must be reported exactly once",
				actuallyFilled, reportedQuantity);
			assertEquals("run " + run + ": the gp reported must be the gp the client tracked",
				actuallyMoved, reportedGross);
		}
	}
}

package com.flippingrs;

import java.awt.Rectangle;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Finding the item the exchange is showing, on every screen it has.
 *
 * <p>The point of the class is that one answer serves the right-click entries
 * and the prices drawn on items alike, so what these pin is the coverage: a
 * screen that is not found here is a screen where both quietly stop working,
 * and nothing else in the plugin would notice.
 */
public class GeItemsTest
{
	private final Client client = mock(Client.class);

	/** A widget drawing one item at a given box. */
	private Widget item(int itemId, int x, int y, int width, int height)
	{
		final Widget widget = mock(Widget.class);
		when(widget.isHidden()).thenReturn(false);
		when(widget.getItemId()).thenReturn(itemId);
		when(widget.getBounds()).thenReturn(new Rectangle(x, y, width, height));
		return widget;
	}

	/** A container drawing nothing itself, with these children. */
	private Widget holding(int x, int y, int width, int height, Widget... children)
	{
		final Widget widget = mock(Widget.class);
		when(widget.isHidden()).thenReturn(false);
		when(widget.getItemId()).thenReturn(-1);
		when(widget.getBounds()).thenReturn(new Rectangle(x, y, width, height));
		when(widget.getDynamicChildren()).thenReturn(children);
		return widget;
	}

	private void noWidgets()
	{
		when(client.getWidget(anyInt())).thenReturn(null);
		when(client.getGrandExchangeOffers()).thenReturn(null);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(0);
	}

	/**
	 * Every screen the exchange can put an item on. One case each, because the
	 * failure this guards against is a screen being forgotten rather than the
	 * walk being wrong.
	 */
	@Test
	public void everyScreenTheExchangeHasIsSearched()
	{
		final int[] screens = {
			InterfaceID.GeOffers.DETAILS,
			InterfaceID.GeCollect.COLLECT_0,
			InterfaceID.GeCollect.COLLECT_1,
			InterfaceID.GeViewonly.VIEW_0,
			InterfaceID.GePricechecker.ITEMS,
			InterfaceID.GeOffersSide.ITEMS,
			InterfaceID.GeHistory.LIST,
		};
		for (int screen : screens)
		{
			noWidgets();
			// Built before the stubbing, not inside it: Mockito counts the
			// when() calls these make as a stub begun and not finished.
			final Widget list = holding(10, 10, 200, 40, item(4151, 12, 12, 32, 32));
			when(client.getWidget(screen)).thenReturn(list);

			final List<GeItems.Spot> spots = GeItems.onScreen(client);

			assertEquals("nothing found on screen " + screen, 1, spots.size());
			assertEquals(4151, spots.get(0).itemId);
		}
	}

	/**
	 * The eight offer boxes are the exception: the client does not put the item
	 * on the widget, so it comes from its own record of the offer. That is also
	 * what makes these the only boxes that carry an offer to compare a price
	 * against.
	 */
	@Test
	public void anOfferBoxTakesItsItemFromTheOfferItself()
	{
		noWidgets();
		final GrandExchangeOffer offer = mock(GrandExchangeOffer.class);
		when(offer.getState()).thenReturn(GrandExchangeOfferState.BUYING);
		when(offer.getItemId()).thenReturn(4151);
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[]{offer});
		final Widget box = holding(10, 10, 100, 50);
		when(client.getWidget(InterfaceID.GeOffers.INDEX_0)).thenReturn(box);

		final List<GeItems.Spot> spots = GeItems.onScreen(client);

		assertEquals(1, spots.size());
		assertEquals(4151, spots.get(0).itemId);
		assertEquals("and it carries the offer, which no other box does", offer, spots.get(0).offer);
	}

	/** An empty slot has no item in it, so it is not somewhere an item is. */
	@Test
	public void anEmptyOfferBoxIsNotAnItem()
	{
		noWidgets();
		final GrandExchangeOffer offer = mock(GrandExchangeOffer.class);
		when(offer.getState()).thenReturn(GrandExchangeOfferState.EMPTY);
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[]{offer});
		final Widget box = holding(10, 10, 100, 50);
		when(client.getWidget(InterfaceID.GeOffers.INDEX_0)).thenReturn(box);

		assertTrue(GeItems.onScreen(client).isEmpty());
	}

	/**
	 * The setup page's item comes from the varp that drives it, since nothing
	 * on that page carries it either.
	 */
	@Test
	public void theSetupPageTakesItsItemFromTheVarp()
	{
		noWidgets();
		final Widget page = holding(10, 10, 300, 200);
		when(client.getWidget(InterfaceID.GeOffers.SETUP)).thenReturn(page);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(4151);

		final List<GeItems.Spot> spots = GeItems.onScreen(client);

		assertEquals(1, spots.size());
		assertEquals(4151, spots.get(0).itemId);
	}

	/**
	 * The status page you get by clicking a placed offer is written into, not
	 * painted on, exactly as the setup page is.
	 *
	 * <p>Still a spot, because it is still an item on screen and so still an
	 * item worth having a price for -- but painting one on it as well as
	 * writing one into it would put the same numbers on the same screen twice.
	 */
	@Test
	public void theStatusPageIsWrittenIntoRatherThanPaintedOn()
	{
		noWidgets();
		final Widget page = holding(10, 10, 300, 200, item(4151, 20, 20, 32, 32));
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(page);

		final List<GeItems.Spot> spots = GeItems.onScreen(client);

		assertEquals(1, spots.size());
		assertFalse("the status page draws its own", spots.get(0).paint);
	}

	/**
	 * And which item that page is about is asked of the page rather than of
	 * the varp.
	 *
	 * <p>The varp holds whatever was last searched for, which after a search
	 * and a click on a different slot is a different item -- and the price of
	 * the wrong item is worse than no price at all.
	 */
	@Test
	public void aScreenAboutOneItemCanBeAskedWhichItemThatIs()
	{
		noWidgets();
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(1042);
		final Widget page = holding(10, 10, 300, 200, item(4151, 20, 20, 32, 32));
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(page);

		assertEquals("the offer's item, not the last thing searched for",
			4151, GeItems.itemIn(client, InterfaceID.GeOffers.DETAILS));
		assertEquals("and nothing at all when the page is not up",
			0, GeItems.itemIn(client, InterfaceID.GeCollect.COLLECT_0));
	}

	/**
	 * A history row carries its item on a narrow icon at the left, but the row
	 * is the width of the list and nothing else in it says which item it is.
	 * Treating the icon as the whole target meant only a right-click on the
	 * picture itself found the item.
	 */
	@Test
	public void aHistoryRowIsTheWidthOfTheList()
	{
		noWidgets();
		final Widget list = holding(10, 10, 400, 90, item(4151, 12, 40, 32, 32));
		when(client.getWidget(InterfaceID.GeHistory.LIST)).thenReturn(list);

		final List<GeItems.Spot> spots = GeItems.onScreen(client);

		assertEquals(1, spots.size());
		assertEquals("the row spans the list", new Rectangle(10, 40, 400, 32), spots.get(0).bounds);

		when(client.getMouseCanvasPosition()).thenReturn(new Point(380, 50));
		assertEquals("so a click well to the right of the icon still finds it",
			4151, GeItems.under(client, client.getMouseCanvasPosition()));
	}

	/**
	 * A row scrolled out of its list is not somewhere the mouse can be.
	 *
	 * <p>The client does not hide a scrolled-out child: it keeps its position
	 * and lets the list clip it, so its bounds are a real rectangle somewhere
	 * outside the list. Going by bounds alone would hand back an item for a
	 * row nobody can see -- and would paint that row's price over whatever the
	 * exchange has drawn above or below the list.
	 */
	@Test
	public void aRowScrolledOutOfItsListIsNotUnderTheMouse()
	{
		noWidgets();
		// The row sits above the top of the list, as one scrolled off does.
		final Widget list = holding(10, 100, 400, 90, item(4151, 12, 40, 32, 32));
		when(client.getWidget(InterfaceID.GeHistory.LIST)).thenReturn(list);

		final List<GeItems.Spot> spots = GeItems.onScreen(client);
		assertEquals("it is still a spot, because it is still a row", 1, spots.size());
		assertEquals("and it carries the list to clip against", new Rectangle(10, 100, 400, 90),
			spots.get(0).clip);

		assertEquals("but the mouse over it is not over the list",
			-1, GeItems.under(client, new Point(200, 50)));
	}

	/** And a click outside every box finds nothing rather than the nearest thing. */
	@Test
	public void aClickOnNothingFindsNothing()
	{
		noWidgets();
		final Widget list = holding(10, 10, 400, 90, item(4151, 12, 40, 32, 32));
		when(client.getWidget(InterfaceID.GeHistory.LIST)).thenReturn(list);

		assertEquals(-1, GeItems.under(client, new Point(5, 5)));
		assertEquals("and no mouse at all is not a crash", -1, GeItems.under(client, null));
	}

	/** A hidden screen is not on screen. */
	@Test
	public void aHiddenScreenIsSkipped()
	{
		noWidgets();
		final Widget hidden = holding(10, 10, 200, 40, item(4151, 12, 12, 32, 32));
		when(hidden.isHidden()).thenReturn(true);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(hidden);

		assertTrue(GeItems.onScreen(client).isEmpty());
	}
}

package com.flippingrs;

import java.awt.Rectangle;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What the offer setup screen is told to say.
 *
 * <p>The line is written into the game's own interface, so where it lands and
 * how it survives a rebuild need a running client. What it says does not, and
 * that is the part worth pinning: these are the numbers somebody types an
 * offer from.
 */
public class GeOfferTextTest
{
	/**
	 * The text without its colour tags.
	 *
	 * <p>What is on screen is words; the tags are how the game is told to
	 * colour them. A test that asserted on the tagged string would break every
	 * time a colour moved, and would read as though the colours were the
	 * point.
	 */
	private static String plain(String text)
	{
		return text.replaceAll("</?col[^>]*>", "");
	}

	private static Quote whip()
	{
		final Quote quote = new Quote();
		quote.id = 4151;
		// The site's two ends of the spread: buy at the low, sell at the high.
		quote.instantSell = 1_480_000;
		quote.instantBuy = 1_520_000;
		quote.netMargin = 32_000;
		return quote;
	}

	/**
	 * Exact to the coin, because a price on this screen is a number somebody
	 * is about to type. "1.48M" is not typeable.
	 */
	@Test
	public void thePricesAreExactToTheCoin()
	{
		final String text = plain(GeOfferText.textFor(whip()));

		assertTrue(text, text.contains("Buy 1,480,000"));
		assertTrue(text, text.contains("Sell 1,520,000"));
		assertTrue("and the margin carries its sign", text.contains("+32,000"));
	}

	/**
	 * One line, always. It goes into a gap in somebody else's layout, and a
	 * gap that takes one line is a much safer thing to assume than one that
	 * takes two.
	 *
	 * <p>What qualifies the prices is folded onto the end rather than dropped:
	 * the buy limit and the age are what say whether the numbers before them
	 * can be trusted.
	 */
	@Test
	public void everythingIsOnOneLine()
	{
		final Quote quote = whip();
		quote.limitRemaining = 3412;
		quote.dataAgeSeconds = 250;

		final String text = plain(GeOfferText.textFor(quote));

		assertFalse("one line", text.contains("<br>"));
		assertTrue(text, text.startsWith("Buy "));
		assertTrue(text, text.contains("Limit 3.4K"));
		assertTrue(text, text.contains("Priced 4m ago"));
	}

	/**
	 * A server that sends neither leaves both off rather than writing an empty
	 * separator after the prices.
	 */
	@Test
	public void aServerThatSaysNeitherLeavesThemOff()
	{
		final Quote quote = whip();
		quote.dataAgeSeconds = -1;

		assertFalse(quote.hasLimitLeft());
		final String text = plain(GeOfferText.textFor(quote));
		assertFalse(text, text.contains("Limit"));
		assertFalse(text, text.contains("Priced"));
		assertTrue("the prices are still there", text.contains("Buy 1,480,000"));
	}

	/**
	 * Old prices are said to be old rather than coloured as if they were not.
	 * A confident green on a stale number is the wrong thing to say.
	 */
	@Test
	public void oldPricesAreMarkedAsOld()
	{
		final Quote fresh = whip();
		fresh.dataAgeSeconds = 30;
		final Quote stale = whip();
		stale.dataAgeSeconds = 4000;

		assertFalse(GeOfferText.stale(fresh));
		assertTrue(GeOfferText.stale(stale));
	}

	/**
	 * The colours are written as colours, not as RuneLite's own tokens.
	 *
	 * <p>{@code <colNORMAL>} and friends are turned into colours only for the
	 * message types RuneLite has one configured for, and mean nothing at all
	 * to a widget -- so they went to the screen as their own text. This is
	 * what that bug looked like, and what it must not look like again.
	 */
	@Test
	public void theColoursAreColoursRatherThanTokens()
	{
		final String text = GeOfferText.textFor(whip());

		assertFalse(text, text.contains("<colNORMAL>"));
		assertFalse(text, text.contains("<colHIGHLIGHT>"));
		assertTrue(text, text.contains("<col=") && text.contains("</col>"));
	}

	@Test
	public void theAgeOfThePricesIsSaidPlainly()
	{
		assertEquals("just now", GeOfferText.age(0));
		assertEquals("a minute is still now", "just now", GeOfferText.age(60));
		assertEquals("4m ago", GeOfferText.age(4 * 60 + 30));
		assertEquals("59m ago", GeOfferText.age(59 * 60));
		assertEquals("1h ago", GeOfferText.age(3600));
		assertEquals("2h ago", GeOfferText.age(2 * 3600 + 1800));
	}

	/**
	 * An item that has never traded has no age, and the server says so with a
	 * negative one. Reading that as "just now" because it is a small number
	 * would put the most reassuring words on the screen in the one case where
	 * nothing at all is known.
	 */
	@Test
	public void anItemThatHasNeverTradedHasNoAge()
	{
		assertNull(GeOfferText.age(-1));
		assertNotNull("and a real age still reads", GeOfferText.age(0));
	}

	/**
	 * The buy limit is the one number a flipper cannot work out in their head,
	 * and the reset only matters once there is nothing left to buy.
	 */
	@Test
	public void theBuyLimitLeftIsWhatThereIsToActOn()
	{
		final Quote quote = new Quote();
		quote.limitRemaining = 3412;
		assertEquals("3.4K", GeOfferText.limitLeft(quote));

		quote.limitRemaining = 0;
		quote.limitResetsInSeconds = 2 * 3600 + 14 * 60;
		assertEquals("none for 2h 14m", GeOfferText.limitLeft(quote));

		quote.limitResetsInSeconds = 0;
		assertEquals("a reset it does not know about is not invented",
			"none", GeOfferText.limitLeft(quote));
	}

	@Test
	public void howLongUntilTheLimitResets()
	{
		assertEquals("under a minute", GeOfferText.until(30));
		assertEquals("12m", GeOfferText.until(12 * 60 + 59));
		assertEquals("1h 12m", GeOfferText.until(3600 + 12 * 60));
		assertEquals("an exact number of hours does not trail a 0m", "4h", GeOfferText.until(4 * 3600));
	}

	/**
	 * A server that does not send the limit is not the same as one saying
	 * there is none left, and drawing "0" for the first would tell somebody to
	 * stop buying an item they can freely buy.
	 */
	@Test
	public void aServerThatSaysNothingAboutTheLimitSaysNothing()
	{
		assertFalse(new Quote().hasLimitLeft());
		assertFalse(GeOfferText.textFor(whip()).contains("Limit"));
	}

	/**
	 * The offer screens carry the volume too, shortened.
	 *
	 * <p>"Vol" rather than "Volume" here alone: this line goes on the end of
	 * the game's own description and has to stay one line, which is the whole
	 * reason it was put there.
	 */
	@Test
	public void theOfferLineCarriesTheVolumeShortened()
	{
		final Quote quote = whip();
		quote.volume24h = 1234;
		quote.dataAgeSeconds = 250;

		final String text = GeOfferText.textFor(quote).replaceAll("<[^>]*>", "");

		assertTrue(text, text.contains("Vol 1.2K/24h"));
		assertTrue("and it qualifies the margin, so it comes before the age: " + text,
			text.indexOf("Vol ") < text.indexOf("Priced "));
	}

	/** And says nothing when the site has no volume for the item. */
	@Test
	public void anOfferLineWithoutVolumeDoesNotMentionIt()
	{
		final String text = GeOfferText.textFor(whip());

		assertFalse(text, text.contains("Vol"));
	}
}

