		support.drain();
		support.settleSwing();

		assertTrue("the queue is cleared either way, so this is the only telling",
			support.queue().isEmpty());
		final String notice = support.panel.activityNoticeForTest();
		assertTrue(notice, notice.contains("1 trade(s)"));
