	/** The state reported for one slot. */
	private static OfferState reported(List<OfferState> sent, int slot)
	{
		for (OfferState state : sent)
		{
			if (state.slot == slot)
			{
				return state;
			}
		}
		throw new AssertionError("slot " + slot + " was not reported");
	}

