	 * the figure is floored, and the floor only matters if the setting is
	 * being read at all.
	 */
	@Test
	public void theSendIntervalIsTheUsersUntilItWouldBreachTheRateLimit() throws Exception
	{
		when(support.config.syncSeconds()).thenReturn(60);
