	{
		return currentBuy;
	}

	public long getUnrealisedPnl()
	{
		return unrealisedPnl;
	}

	public double getUnrealisedRoi()
	{
		return unrealisedRoi;
	}

	public long getBreakEvenSell()
	{
		return breakEvenSell;
	}

