	/**
	 * A different RuneScape account is now active, or none is.
	 *
	 * <p>The journal is remembered per account, but the picker was only ever
	 * redrawn by {@link #connect}. Logging out of a main and into an alt left
	 * it showing the main's journal while trades went to the alt's -- or were
	 * held with "no journal picked" while the panel plainly showed one. The
	 * picker is re-pointed here from the list already loaded, and an account
	 * seen for the first time adopts the default the way a fresh install does.
	 */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// False when nothing has been loaded yet; connect does this when it
		// succeeds.
		reads.accountChanged();
	}

	/**
	 * The client is closing. RuneLite does not call shutDown for that; this is
	 * the only notice, and it waits a bounded time for whatever is handed to
	 * it. Two things are worth that wait: the fill the game thread just handed
	 * to the io thread, which is otherwise on a daemon thread that dies with
	 * the JVM, and a last send, so the evening's final trades are not held
	 * until the next login.
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		shuttingDown = true;
		final CompletableFuture<Void> done = new CompletableFuture<>();
		final boolean queued = submit(diskExecutor, () ->
		{
			// Everything the game thread handed over before this ran is now on
			// disk. From here the send is the only thing left.
			final boolean draining = submit(sendExecutor, () ->
			{
				try
				{
					sender.drain();
				}
				finally
				{
					done.complete(null);
				}
			});
			if (!draining)
			{
				done.complete(null);
			}
		});
		if (!queued)
		{
			return;
		}
		event.waitFor(done);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!FlippingRsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		switch (event.getKey())
		{
			case "apiKey":
				// A key that has just been changed is the likeliest reason the
				// server refused a batch over something that was never the
				// rows' fault, so what was filed gets another go.
				submit(sendExecutor, sender::retrySetAside);
				submit(sendExecutor, reads::connect);
				break;
			// Turning recording back on has to re-check the key and reload the
			// journals, because nothing was contacted while it was off.
			case "enabled":
				submit(sendExecutor, reads::connect);
				break;
			case "syncSeconds":
				scheduleSync();
				break;
			case "baseUrl":
				if (developerMode)
				{
					api = newApi();
					watchlists.forget();
					submit(sendExecutor, reads::connect);
				}
				break;
			default:
				break;
		}
	}

	// ---------------------------------------------------------------- sending

	private void scheduleSync()
	{
		if (syncTask != null)
		{
			syncTask.cancel(false);
			syncTask = null;
		}
		// Same race the submit helper exists for: a ConfigChanged already in
		// flight can land after shutDown has stopped the executor.
		if (sendExecutor == null || sendExecutor.isShutdown())
		{
			return;
		}
		final long seconds = Math.max(5, config.syncSeconds());
		syncTask = sendExecutor.scheduleWithFixedDelay(sender::drain, seconds, seconds, TimeUnit.SECONDS);
	}

	// ------------------------------------------------------------ the journal

	/**
	 * The journal picker changed. Swing thread.
	 *
	 * <p>Here rather than in {@link PanelReads} because the panel reference is
	 * the plugin's, and it is nulled on shutdown: everything else asks for the
	 * panel through {@link #onPanel}, which hops to the Swing thread, and this
	 * is already on it.
	 */
	private void rememberChosenAccount()
	{
		final FlippingRsPanel target = panel;
		if (target != null)
		{
			reads.rememberChosenAccountFrom(target, true);
		}
	}

	// ---------------------------------------------------------------- helpers

	/**
	 * Runs work on the net thread once a delay has passed, tolerating a
	 * shutdown that has already stopped it.
	 *
	 * @return false if the executor is gone, so the caller can undo whatever
	 *         it set up in expectation of the work running
	 */
	private boolean scheduleOnce(long nanos, Runnable work)
	{
		if (sendExecutor == null || sendExecutor.isShutdown())
		{
			return false;
		}
		try
		{
			sendExecutor.schedule(work, nanos, TimeUnit.NANOSECONDS);
			return true;
		}
		catch (RejectedExecutionException e)
		{
			log.debug("dropped a deferred re-read submitted during shutdown", e);
			return false;
		}
	}

	/**
	 * A price arrived for an item somebody examined before anyone had one.
	 *
	 * <p>Net thread, from the fetch that answered it. The chat is the client's,
	 * so the line itself is said on the client thread.
	 */
	private void examinedPriced(int itemId)
	{
		clientThread.invoke(() ->
		{
			final ExaminePrices examine = examinePrices;
			if (examine != null)
			{
				examine.priced(itemId);
			}
		});
	}

	/**
	 * Gets the user's attention about a trade that could not be recorded.
	 *
	 * <p>Never throws. It is called from the sender, which promises the same,
	 * and a notifier that fails is not worth cancelling the schedule over.
	 */
	private void notifyOfferDone(GeTransaction tx)
	{
		final String what = tx.cancelled ? "cancelled" : ("buy".equals(tx.side) ? "bought" : "sold");
		notify(config.notifyOfferComplete(), "Your " + nameFor(tx) + " offer " + what + ".");
	}

	/** The item's name if the client gave one, else something that still reads. */
	private static String nameFor(GeTransaction tx)
	{
		return tx.itemName == null || tx.itemName.isEmpty() ? "Grand Exchange" : tx.itemName;
	}

	private void notifyProblem(String message)
	{
		notify(config.notifyProblems(), message);
	}

	/**
	 * Raises a notification, if the setting asks for one.
	 *
	 * <p>Never throws. One caller is the sender, which promises the same and
	 * runs on a schedule an escaping exception would cancel for good; another
	 * is the game thread's capture, where an exception lands in RuneLite's
	 * event bus as an uncaught subscriber error. Neither is worth a
	 * notification failing.
	 */
	private void notify(Notification when, String message)
	{
		try
		{
			notifier.notify(when, message);
		}
		catch (RuntimeException e)
		{
			log.debug("could not raise a notification", e);
		}
	}

	/** Item names come from the item manager, which wants the client thread. */
	private String itemName(int itemId)
	{
		try
		{
			final String name = itemManager.getItemComposition(itemId).getName();
			return name == null ? "" : name;
		}
		catch (RuntimeException e)
		{
			// The server resolves the real name from the item id anyway, so a
			// missing one costs nothing but a less readable panel line.
			log.debug("could not resolve a name for item {}", itemId, e);
			return "";
		}
	}

	/** Runs a panel update on the Swing thread, if the panel still exists. */
	private void onPanel(Consumer<FlippingRsPanel> action)
	{
		final FlippingRsPanel target = panel;
		if (target == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() -> action.accept(target));
	}

	private BufferedImage icon()
	{
		try
		{
			return ImageUtil.loadImageResource(FlippingRsPlugin.class, "/icon.png");
		}
		catch (RuntimeException e)
		{
			// A missing icon must not stop the plugin loading.
			log.debug("no icon resource found; using a blank one", e);
			return new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		}
	}
}

package com.flippingrs;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.ColorScheme;

/**
 * Catching the server up on what it could not see for itself.
 *
 * <p>Two things, both reported rather than decided: the state of the open
 * slots, sent as a snapshot for the server to reconcile against the fills it
 * holds for each offer and take on any shortfall as a recovered, untimed
 * fill; and the history screen, sent as read, for the server to match
 * against the completed offers it has and take on the rest. (The third
 * catch-up, an offer that was part-filled when the plugin first saw it, is
 * the tracker's, and goes out as an adopted fill.) In every case the plugin
 * reports what the client shows and the server decides what is new.
 *
 * <p>The tick bookkeeping is the client thread's; the sends are the net
 * thread's. Nothing here is touched from anywhere else.
 */
@Slf4j
final class CatchUp
{
	/** Ticks to wait after login for the client's offer burst to settle before a snapshot. */
	private static final int LOGIN_SETTLE_TICKS = 3;
	/** Snapshots closer together than this are skipped; the state has not changed. */
	private static final long OFFER_SNAPSHOT_SECONDS = 10;
	/**
	 * After a send, rarer still: the send just told the server the state, and
	 * the reconciliation is a safety net rather than the record. This keeps
	 * the worst-case minute well inside the plugin scope's rate limit.
	 */
	private static final long OFFER_SNAPSHOT_AFTER_SEND_SECONDS = 60;
	/** The history screen fills a tick or two after it opens; give up after this many looks. */
	private static final int HISTORY_READ_ATTEMPTS = 5;
	/**
	 * "No snapshot yet". The nanoTime clock's origin is arbitrary and it may
	 * well be negative, so zero is a time it is allowed to return and cannot
	 * stand in for "never".
	 */
	private static final long NEVER = Long.MIN_VALUE;

	private final Client client;
	private final FlippingRsConfig config;
	private final ProfileStore store;
	private final Supplier<FlippingRsApi> api;
	private final PanelUpdates panel;
	/** Resolves an item's name. Client thread. */
	private final IntFunction<String> itemName;
	/** Sends the pending fills. Net thread, synchronous. */
	private final Runnable drain;
	/** Re-reads the account tabs after the server took something on. Net thread. */
	private final Runnable afterRecovery;
	/** Hands work to the net thread. */
	private final Consumer<Runnable> netThread;

	private int offerSnapshotDueTick = -1;
	private int historyReadDueTick = -1;
	private int historyReadAttempts;
	private volatile long lastOfferSnapshotAt = NEVER;

	/**
	 * The history screen as last handed to the server. Net thread only.
	 * See {@link #sendHistory}.
	 */
	@Nullable
	private String lastHistorySent;

	CatchUp(Client client, FlippingRsConfig config, ProfileStore store, Supplier<FlippingRsApi> api,
		PanelUpdates panel, IntFunction<String> itemName, Runnable drain, Runnable afterRecovery,
		Consumer<Runnable> netThread)
	{
		this.client = client;
		this.config = config;
		this.store = store;
		this.api = api;
		this.panel = panel;
		this.itemName = itemName;
		this.drain = drain;
		this.afterRecovery = afterRecovery;
		this.netThread = netThread;
	}

	// ------------------------------------------------------------ the ticks

	/** The client just logged in on this tick. Client thread. */
	void loggedIn(int tick)
	{
		offerSnapshotDueTick = tick + LOGIN_SETTLE_TICKS;
	}

	/** The Grand Exchange just opened on this tick. Client thread. */
	void exchangeOpened(int tick)
	{
		offerSnapshotDueTick = tick + 1;
	}

	/** The history screen just opened on this tick. Client thread. */
	void historyOpened(int tick)
	{
		historyReadDueTick = tick + 2;
		historyReadAttempts = 0;
	}

	/** Client thread, every game tick. */
	void tick(int tick)
	{
		if (offerSnapshotDueTick >= 0 && tick >= offerSnapshotDueTick)
		{
			offerSnapshotDueTick = -1;
			snapshotOffers(OFFER_SNAPSHOT_SECONDS);
		}
		if (historyReadDueTick >= 0 && tick >= historyReadDueTick)
		{
			readHistory(tick);
		}
	}

	/** A send just happened; snapshot the slots if it has been a while. Client thread. */
	void snapshotAfterSend()
	{
		snapshotOffers(OFFER_SNAPSHOT_AFTER_SEND_SECONDS);
	}

	// ---------------------------------------------------------- open offers

	/**
	 * Reads the open slots and hands them to the net thread. Client thread,
	 * because the offers and the baselines are read here.
	 */
	private void snapshotOffers(long minGapSeconds)
	{
		if (!config.enabled())
		{
			return;
		}
		final long now = System.nanoTime();
		if (lastOfferSnapshotAt != NEVER && now - lastOfferSnapshotAt < TimeUnit.SECONDS.toNanos(minGapSeconds))
		{
			return;
		}
		final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		// Read here, on the thread the slots and the baselines are read on, and
		// checked again before the send. See sendOffers.
		final long accountHash = client.getAccountHash();
		final List<OfferState> open = new ArrayList<>();
		for (int slot = 0; slot < offers.length; slot++)
		{
			final GrandExchangeOffer offer = offers[slot];
			if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}
			final SavedOffer saved = store.loadOffer(slot);
			final OfferState state = new OfferState();
			state.slot = slot;
			state.offerRef = saved == null ? null : saved.offerRef;
			state.itemId = offer.getItemId();
			state.itemName = itemName.apply(offer.getItemId());
			state.side = SavedOffer.isBuy(offer.getState()) ? "buy" : "sell";
			state.price = offer.getPrice();
			state.totalQuantity = offer.getTotalQuantity();
			state.quantitySold = offer.getQuantitySold();
			state.spent = offer.getSpent();
			state.spentEstimated = offer.getSpent() < 0;
			state.state = offer.getState().name();
			open.add(state);
		}
		lastOfferSnapshotAt = now;
		netThread.accept(() -> sendOffers(open, accountHash));
	}

	/**
	 * Net thread. A failure here costs nothing but the reconciliation; the
	 * next snapshot retries.
	 *
	 * <p>The buffer is sent first. An adopted fill still waiting in the queue
	 * is exactly the shortfall the server would otherwise recover from this
	 * snapshot, and the server's dedupe deliberately trusts a fill under an
	 * offer's own reference, so sending both would count it twice.
	 *
	 * @param accountHash whose slots these are, as read when they were read
	 */
	private void sendOffers(List<OfferState> open, long accountHash)
	{
		try
		{
			if (!config.enabled())
			{
				return;
			}
			drain.run();
			final String key = FlippingRsApi.trimmedKey(config.apiKey());
			final String accountId = store.chosenAccountFor(client.getAccountHash());
			if (key.isEmpty() || accountId == null)
			{
				return;
			}
			if (!stillTheSameAccount(accountHash))
			{
				return;
			}
			final Reconciliation result = api.get().submitOffers(key, accountId, open);
			if (!result.getProblems().isEmpty())
			{
				log.warn("flippingrs.com could not read {} of the open offers: {}",
					result.getProblems().size(), result.getProblems());
			}
			if (result.getRecovered() > 0)
			{
				final int recovered = result.getRecovered();
				panel.onPanel(p -> p.setActivityNotice("Recovered " + recovered + " trade(s) from your open offers that had "
					+ "been missed. They are saved without a time.", ColorScheme.BRAND_ORANGE));
				afterRecovery.run();
			}
		}
		catch (IOException e)
		{
			// A plan cap arrives here too, in the server's words, and a
			// snapshot that cannot be reconciled is worth a line on Activity
			// rather than a log entry nobody reads.
			log.warn("could not send the open offers: {}", e.getMessage());
			final String why = FlippingRsApi.describe(e);
			panel.onPanel(p -> p.setActivityNotice("Couldn't check your open offers against your journal: " + why,
				ColorScheme.BRAND_ORANGE));
		}
		catch (RuntimeException e)
		{
			// Not every failure is an IOException: a key the HTTP client will
			// not put in a header is refused before the request exists. This
			// is a one-shot task, so an escape costs only this snapshot -- but
			// it would cost it silently, and the next one would go the same way.
			log.warn("unexpected failure while sending the open offers", e);
			panel.onPanel(p -> p.setActivityNotice(
				"Something went wrong checking your open offers. Details are in the client log.",
				ColorScheme.BRAND_ORANGE));
		}
	}

	/**
	 * Whether the character whose slots or history were read is still the one
	 * logged in.
	 *
	 * <p>What was read came off the client thread; the journal it would be
	 * filed under is read here, from whichever RuneScape profile is active
	 * now, and the two are separated by a drain that can block for a whole
	 * call timeout. Pairing a mismatched two would hand one character's open
	 * offers to another character's journal, and the server's answer to a
	 * shortfall is to take it on as a recovered trade -- so the mistake would
	 * not merely be ignored, it would write the main's holdings into the alt's
	 * journal, untimed and unattributable. The sender guards its batches the
	 * same way and for the same reason. Cheaper to notice and let the next
	 * snapshot do it.
	 */
	private boolean stillTheSameAccount(long accountHash)
	{
		if (client.getAccountHash() == accountHash)
		{
			return true;
		}
		log.debug("the account changed while a catch-up was in flight; dropping it");
		return false;
	}

	// -------------------------------------------------------------- history

	/** Client thread. The history list fills a tick or two after the screen opens. */
	private void readHistory(int tick)
	{
		if (!config.enabled())
		{
			historyReadDueTick = -1;
			return;
		}
		final Widget list = client.getWidget(InterfaceID.GeHistory.LIST);
		final List<HistoryRow> rows = GeHistoryReader.read(list, itemName);
		if (rows.isEmpty() && ++historyReadAttempts < HISTORY_READ_ATTEMPTS)
		{
			historyReadDueTick = tick + 1;
			return;
		}
		final long accountHash = client.getAccountHash();
		historyReadDueTick = -1;
		if (rows.isEmpty())
		{
			// A screen with items on it that yielded no rows means the reader
			// no longer understands the layout. Each row is logged at debug
			// as it is skipped, which nobody sees; this is the line that says
			// the catch-up has quietly stopped working.
			if (GeHistoryReader.showsItems(list))
			{
				log.warn("the Grand Exchange history screen shows items but none of its rows could be read; "
					+ "the screen's layout may have changed and the history catch-up is not working");
			}
			return;
		}
		netThread.accept(() -> sendHistory(rows, accountHash));
	}

	/**
	 * Net thread. The buffer is sent first, for the same reason as
	 * {@link #sendOffers}: a completed offer whose fills are still queued
	 * would be unmatched on the screen and added a second time.
	 *
	 * @param accountHash whose history screen this was, as read when it was read
	 */
	private void sendHistory(List<HistoryRow> rows, long accountHash)
	{
		try
		{
			if (!config.enabled())
			{
				return;
			}
			drain.run();
			final String key = FlippingRsApi.trimmedKey(config.apiKey());
			final String accountId = store.chosenAccountFor(client.getAccountHash());
			if (key.isEmpty() || accountId == null)
			{
				return;
			}
			if (!stillTheSameAccount(accountHash))
			{
				return;
			}
			final String screen = signatureOf(accountHash, accountId, rows);
			if (screen.equals(lastHistorySent))
			{
				// The same screen the server has already been shown. Opening the
				// history is a click, and there is no gap between one open and the
				// next: without this, a user flicking between their offers and
				// their history spent a request on each one, against a limit of
				// sixty a minute that the sends themselves draw on. The screen
				// changes when an offer completes and is collected, and that is
				// exactly when this stops matching.
				log.debug("the history screen has not changed since it was last sent");
				return;
			}
			final Reconciliation result = api.get().submitHistory(key, accountId, rows);
			lastHistorySent = screen;
			if (!result.getProblems().isEmpty())
			{
				log.warn("flippingrs.com could not read {} history row(s): {}",
					result.getProblems().size(), result.getProblems());
			}
			if (result.getAdded() > 0)
			{
				final int added = result.getAdded();
				panel.onPanel(p -> p.setActivityNotice("Recovered " + added + " trade(s) from your Grand Exchange history. "
					+ "They are saved without a time.", ColorScheme.BRAND_ORANGE));
				afterRecovery.run();
			}
		}
		catch (IOException e)
		{
			log.warn("could not send the exchange history: {}", e.getMessage());
			final String why = FlippingRsApi.describe(e);
			panel.onPanel(p -> p.setActivityNotice("Couldn't send your Grand Exchange history: " + why,
				ColorScheme.PROGRESS_ERROR_COLOR));
		}
		catch (RuntimeException e)
		{
			log.warn("unexpected failure while sending the exchange history", e);
			panel.onPanel(p -> p.setActivityNotice(
				"Something went wrong sending your Grand Exchange history. Details are in the client log.",
				ColorScheme.PROGRESS_ERROR_COLOR));
		}
	}

	/**
	 * The screen as one string, for telling one screenful from another.
	 *
	 * <p>The character and the journal are in it as well as the rows, so that
	 * an alt whose history happens to read the same is still sent. Only set
	 * after a send that went through, so a failed one is tried again.
	 */
	private static String signatureOf(long accountHash, String accountId, List<HistoryRow> rows)
	{
		final StringBuilder out = new StringBuilder(rows.size() * 24);
		out.append(accountHash).append('/').append(accountId);
		for (HistoryRow row : rows)
		{
			out.append('|').append(row.itemId).append(',').append(row.side).append(',')
				.append(row.quantity).append(',').append(row.grossValue);
		}
		return out.toString();
	}
}

package com.flippingrs;

import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * The last thing we saw in a Grand Exchange slot.
 *
 * <p>This is persisted, and persisting it is the whole reason the plugin does
 * not double-count. The client re-fires an offer-changed event for every
 * occupied slot on login, carrying the quantity already sold. Without a
 * remembered baseline to subtract, every login would look like a fresh burst of
 * trading and re-report trades that were recorded days ago.
 */
public class SavedOffer
{
	int itemId;
	int price;
	int totalQuantity;
	int quantitySold;
	/** Cumulative gp moved. See {@link OfferTracker} on why this can be wrong. */
	int spent;
	GrandExchangeOfferState state;

	/**
	 * Identifies the one exchange offer this slot is running, for as long as it
	 * runs. Minted when the offer is first seen and repeated on every fill of
	 * it, so the server can tell that a thousand partial fills are one purchase.
	 */
	String offerRef;

	/**
	 * True when the offer was already part-filled the first time we saw it, so
	 * its history happened somewhere we were not watching.
	 *
	 * <p>Carried forward for the life of the offer, but nothing reads it: the
	 * panel's notice about an adopted offer comes from the observation that
	 * adopted it, once, and not from here. It is kept because it costs a field
	 * in a config value and says, to anyone reading a baseline out of the
	 * config by hand, where that slot's history came from.
	 */
	boolean adopted;

	public SavedOffer()
	{
	}

	static SavedOffer of(GrandExchangeOffer offer, String offerRef, boolean adopted)
	{
		SavedOffer s = new SavedOffer();
		s.itemId = offer.getItemId();
		s.price = offer.getPrice();
		s.totalQuantity = offer.getTotalQuantity();
		s.quantitySold = offer.getQuantitySold();
		s.spent = offer.getSpent();
		s.state = offer.getState();
		s.offerRef = offerRef;
		s.adopted = adopted;
		return s;
	}

	/**
	 * Whether an incoming event is the same offer we are already tracking,
	 * rather than a new one that happens to be in the same slot.
	 *
	 * <p>The quantity check is not redundant with the other three. Placing the
	 * same offer again after collecting a finished one gives an identical item,
	 * price and size, and the only thing that says it is a different purchase is
	 * that the progress went backwards.
	 *
	 * <p>The side check covers the one case progress cannot: a buy placed and
	 * cancelled untouched, then a sell of the same item at the same price and
	 * size, with the collect in between never observed. Both sit at zero, and
	 * without this they would share one offer reference.
	 *
	 * <p>And the finished check covers another that progress cannot: a buy
	 * cancelled part way, collected, and placed again -- the same item at the
	 * same price for the same number, which is what flipping is. The new offer
	 * carries on from where the old one stopped rather than going backwards, so
	 * it passes the quantity check; but an offer that has finished cannot be
	 * running again, and that is enough to tell them apart. Without it the new
	 * purchase's fills are counted as the difference from the old one's, so
	 * most of them are never reported and the rest go out under the finished
	 * purchase's reference.
	 */
	boolean isSameOfferAs(GrandExchangeOffer offer)
	{
		return itemId == offer.getItemId()
			&& price == offer.getPrice()
			&& totalQuantity == offer.getTotalQuantity()
			&& offer.getQuantitySold() >= quantitySold
			&& (state == null || isBuy(state) == isBuy(offer.getState()))
			&& !(isFinished(state) && isRunning(offer.getState()));
	}

	static boolean isBuy(GrandExchangeOfferState state)
	{
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
	}

	/** Bought, sold or cancelled: the offer is over and the slot is waiting to be collected. */
	static boolean isFinished(GrandExchangeOfferState state)
	{
		return state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.SOLD
			|| state == GrandExchangeOfferState.CANCELLED_BUY
			|| state == GrandExchangeOfferState.CANCELLED_SELL;
	}

	/** Still matching: the offer is on the exchange and can still fill. */
	static boolean isRunning(GrandExchangeOfferState state)
	{
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.SELLING;
	}
}

package com.flippingrs;

import com.google.gson.JsonElement;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;

/**
 * The handful of things every wire shape needs.
 *
 * <p>The shapes themselves are one class each, so that {@link FlippingRsApi}
 * is the requests and nothing else. What they share is here rather than left
 * behind on the API class, so a shape does not have to reach back into the
 * transport to render its own name.
 */
final class Wire
{
	private Wire()
	{
	}

	/**
	 * A name for a Swing label, shown as typed. A JLabel treats any string
	 * that begins with {@code <html>} as markup, so a watchlist or journal
	 * named that way would render as a formatted fragment rather than its
	 * name. A leading space defeats the check and is invisible in a combo
	 * box. Only the owner can name their own lists, so this is a display
	 * oddity rather than an attack, but it is a cheap one to close.
	 */
	static String plain(String text)
	{
		return text != null && text.regionMatches(true, 0, "<html", 0, 5) ? " " + text : text;
	}

	static <T> List<T> withoutNulls(@Nullable List<T> in)
	{
		if (in == null)
		{
			return Collections.emptyList();
		}
		final List<T> out = new ArrayList<>(in.size());
		for (T item : in)
		{
			if (item != null)
			{
				out.add(item);
			}
		}
		return out;
	}

	/**
	 * The refusals a reply carries, as lines for a log or a panel.
	 *
	 * <p>Held as raw JSON on the way in -- see {@link IngestResult#problems} --
	 * so a string comes out as itself and anything structured as the JSON it
	 * was, rather than failing the parse of a reply that was otherwise fine.
	 *
	 * @return never null, and never containing null
	 */
	static List<String> problemsOf(@Nullable List<JsonElement> problems)
	{
		if (problems == null)
		{
			return Collections.emptyList();
		}
		final List<String> out = new ArrayList<>(problems.size());
		for (JsonElement problem : problems)
		{
			if (problem == null || problem.isJsonNull())
			{
				continue;
			}
			out.add(problem.isJsonPrimitive() ? problem.getAsString() : problem.toString());
		}
		return out;
	}
}

package com.flippingrs;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * The FlippingRS HTTP API, as much of it as the plugin needs.
 *
 * <p>Everything the plugin does goes through {@code /api/plugin}: one read
 * per tab of the side panel, writes for fills, open offers and the history
 * screen, two for watchlists, and the two position actions the site's own
 * Positions page has. Nothing else. The general API is what the Elite plan sells,
 * and a plugin key is available on every plan, so the plugin's surface is
 * kept to things that are only ever a picture of the sidebar: nothing that
 * pages, filters or exports. A user who scripts against a plugin key gets
 * their own sidebar back and no more.
 *
 * <p>Every call is synchronous and every call is made off the client thread by
 * the caller. Blocking the game for a network round trip would drop frames, and
 * a flipper who sees the client stutter every time a slot fills will uninstall
 * the plugin long before they read a journal.
 */
@Slf4j
public class FlippingRsApi
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/** Generous next to the few kilobytes a real reply is. */
	private static final long MAX_BODY_BYTES = 1 << 20;

	/**
	 * Thrown when the server refused <em>this batch</em> in a way that retrying
	 * will not fix: it is malformed, too large, or fails validation. The queue
	 * sets the batch aside rather than retrying it forever.
	 *
	 * <p>Deliberately narrow. A bad key, a lapsed plan or a missing account are
	 * not properties of the batch, and a user who fixes them wants the trades
	 * that piled up meanwhile to go out, not to have been deleted thirty
	 * seconds at a time while a side panel said "last attempt failed".
	 */
	public static class PermanentException extends IOException
	{
		PermanentException(String message)
		{
			super(message);
		}
	}

	/**
	 * Thrown when the server has no such route.
	 *
	 * <p>Separate from a plain IOException because it is the one failure a
	 * caller can do something sensible about: an older flippingrs.com that
	 * predates a call this plugin makes will answer every one of them the same
	 * way forever, so the caller can stop asking rather than spend a request
	 * every thirty seconds finding out again. Everything the plugin needs to
	 * do its job goes through routes that have always been there; this is only
	 * reached by the extras.
	 */
	public static class NotHereException extends IOException
	{
		NotHereException(String message)
		{
			super(message);
		}
	}

	/**
	 * The one instance this plugin talks to, over TLS, and not configurable in
	 * a normal install. The exception is a client started in developer mode,
	 * which is how the plugin is run against a local server; the plugin
	 * decides that, and this class only takes whatever base it is given.
	 *
	 * <p>It was a setting once. A text box that decides where an API key and
	 * every recorded trade get posted is worth more to whoever talks a user into
	 * changing it than it ever was to the handful of people self-hosting, and it
	 * makes the plugin's network destination something you cannot read off the
	 * source.
	 */
	static final HttpUrl BASE_URL = HttpUrl.get("https://flippingrs.com");

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl base;

	/** The item's page on the site, for the browser. */
	String itemUrl(int itemId)
	{
		return base.newBuilder()
			.addPathSegment("item")
			.addPathSegment(Integer.toString(itemId))
			.build().toString();
	}

	/** The site's flip finder, for the browser. */
	String finderUrl()
	{
		return base.newBuilder().addPathSegment("finder").build().toString();
	}

	public FlippingRsApi(OkHttpClient http, Gson gson)
	{
		this(http, gson, BASE_URL);
	}

	/** Points the client at another server: a test's, or a developer's. */
	FlippingRsApi(OkHttpClient http, Gson gson, HttpUrl base)
	{
		this.http = http;
		this.gson = gson;
		this.base = base;
	}

	// ------------------------------------------------------------ the shapes
	//
	// One class each, beside this one: Watchlist, Quote, Position, Positions,
	// Analytics, Me, GameAccount, PanelData, OfferState, HistoryRow,
	// Reconciliation and IngestResult, with Wire holding what they share.
	// They mirror the server's replies rather than the sidebar's needs, so a
	// field with no getter and no reader is not dead code -- it is the wire
	// contract written down, and Gson would drop it silently if it went.
	// Anything the panel actually draws has a getter. Keeping the unread ones
	// has already paid for itself: the server was found not to be sending a
	// quote's spread, tax or volume at all, which was only noticeable because
	// the fields were here to be compared against.


	// ------------------------------------------------------------- the calls

	/**
	 * The Account tab: who the key belongs to, what plan they are on, and the
	 * journals they can file under.
	 *
	 * <p>Doubles as the connection test: it is the cheapest authenticated
	 * read, so a successful one means the key is good and the server is
	 * reachable.
	 */
	public PanelData account(String apiKey) throws IOException
	{
		return read(apiKey, url("api", "plugin", "account").newBuilder());
	}

	/** The Journal tab: the journal's newest fills for an account. Null parts without one. */
	public PanelData trades(String apiKey, @Nullable String accountId) throws IOException
	{
		final HttpUrl.Builder url = url("api", "plugin", "trades").newBuilder();
		if (accountId != null && !accountId.isEmpty())
		{
			url.addQueryParameter("accountId", accountId);
		}
		return read(apiKey, url);
	}

	/**
	 * The Journal tab: the week's verdict and the open positions for an
	 * account, with the machine's UTC offset in minutes so the week's days
	 * fall on the player's calendar.
	 */
	public PanelData journal(String apiKey, @Nullable String accountId, int tzOffset) throws IOException
	{
		final HttpUrl.Builder url = url("api", "plugin", "journal").newBuilder()
			.addQueryParameter("tzOffset", Integer.toString(tzOffset));
		if (accountId != null && !accountId.isEmpty())
		{
			url.addQueryParameter("accountId", accountId);
		}
		return read(apiKey, url);
	}

	/**
	 * The Watchlists tab: every watchlist the owner has, and the site's
	 * quotes for the items of one of them: the one named, or the first.
	 *
	 * @param accountId the journal to count buy limits against, on the same
	 *                  terms as {@link #quotes}: without one the server has
	 *                  nothing to count and leaves those fields off, and the
	 *                  reply is otherwise identical
	 */
	public PanelData watchlists(String apiKey, @Nullable String watchlistId, @Nullable String accountId)
		throws IOException
	{
		final HttpUrl.Builder url = url("api", "plugin", "watchlists").newBuilder();
		if (watchlistId != null && !watchlistId.isEmpty())
		{
			url.addQueryParameter("watchlistId", watchlistId);
		}
		if (accountId != null && !accountId.isEmpty())
		{
			url.addQueryParameter("accountId", accountId);
		}
		return read(apiKey, url);
	}

	/**
	 * Quotes for particular items, whether or not they are on a watchlist.
	 *
	 * <p>What the watchlist read gives for a curated list, this gives for
	 * whatever the exchange happens to be showing. The moment a price is
	 * actually wanted is the moment one is being typed, and that is for any
	 * item, not only the ones somebody thought to add to a list beforehand.
	 *
	 * <p>Capped by the caller, not here: it is the caller that knows how many
	 * items are on screen.
	 *
	 * @param accountId the journal to count buy limits against, or null for
	 *                  none -- a limit is how much of it <em>this journal</em>
	 *                  has spent, so without one the server has nothing to
	 *                  count and leaves those fields off
	 * @throws NotHereException from a server that does not have this route,
	 *                          which the caller takes as "stop asking"
	 */
	public PanelData quotes(String apiKey, @Nullable String accountId, Collection<Integer> itemIds)
		throws IOException
	{
		final HttpUrl.Builder url = url("api", "plugin", "quote").newBuilder();
		if (accountId != null && !accountId.isEmpty())
		{
			url.addQueryParameter("accountId", accountId);
		}
		for (Integer itemId : itemIds)
		{
			if (itemId != null)
			{
				url.addQueryParameter("itemId", Integer.toString(itemId));
			}
		}
		return read(apiKey, url);
	}

	/**
	 * One tab's read. Every tab endpoint answers with the same {@link PanelData}
	 * shape, filling only its own parts, so the plugin draws all of them with
	 * one routine and a part that is absent is left alone.
	 */
	private PanelData read(String apiKey, HttpUrl.Builder url) throws IOException
	{
		final Request request = new Request.Builder()
			.url(url.build())
			.header("X-Api-Key", apiKey)
			.get()
			.build();

		try (Response response = http.newCall(request).execute())
		{
			final String body = bodyOf(response);
			check(response, body);
			final PanelData panel = gson.fromJson(body, PanelData.class);
			return panel == null ? new PanelData() : panel;
		}
		catch (JsonParseException e)
		{
			throw new IOException("flippingrs.com returned something that is not JSON", e);
		}
	}

	/** Sends a batch of fills. Safe to repeat: the server drops ids it has seen. */
	public IngestResult submit(String apiKey, String accountId, List<GeTransaction> batch)
		throws IOException
	{
		final JsonObject payload = new JsonObject();
		payload.addProperty("accountId", accountId);
		payload.add("transactions", jsonList(batch));

		final Request request = new Request.Builder()
			.url(url("api", "plugin", "transactions"))
			.header("X-Api-Key", apiKey)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		try (Response response = http.newCall(request).execute())
		{
			final String body = bodyOf(response);
			check(response, body);
			final IngestResult result = gson.fromJson(body, IngestResult.class);
			// A 2xx whose body accounts for none of the rows did not come from
			// this API -- a proxy or captive portal answering with an empty
			// object, say. Confirming on it would delete the batch on the word
			// of something that never saw it. Retryable, like any other reply
			// that is not the server's.
			if (!batch.isEmpty() && (result == null || result.acknowledged() == 0))
			{
				throw new IOException("flippingrs.com did not acknowledge the batch");
			}
			return result == null ? new IngestResult() : result;
		}
		catch (JsonParseException e)
		{
			throw new IOException("flippingrs.com returned something that is not JSON", e);
		}
	}

	/**
	 * Records a sale against an open position: the same thing the site's
	 * Positions page does with its Close button. The server folds it into
	 * the position's sale price and caps the quantity at what is left.
	 *
	 * @param sellQty how many were sold, or null for everything still held
	 */
	public void closePosition(String apiKey, String positionId, long sellPrice, @Nullable Long sellQty)
		throws IOException
	{
		final JsonObject payload = new JsonObject();
		payload.addProperty("sellPrice", sellPrice);
		if (sellQty != null)
		{
			payload.addProperty("sellQty", sellQty);
		}
		final Request request = new Request.Builder()
			.url(url("api", "plugin", "positions", positionId, "close"))
			.header("X-Api-Key", apiKey)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();
		try (Response response = http.newCall(request).execute())
		{
			check(response, bodyOf(response));
		}
	}

	/**
	 * Deletes a position that was never a flip -- supplies bought to use,
	 * say -- so the next sale of that item is not matched against it and
	 * journaled as a loss. The fills stay in the ledger; only the lot goes.
	 * This is the one destructive thing the plugin can do, and it is behind
	 * a confirmation in the sidebar.
	 */
	public void deletePosition(String apiKey, String positionId) throws IOException
	{
		final Request request = new Request.Builder()
			.url(url("api", "plugin", "positions", positionId))
			.header("X-Api-Key", apiKey)
			.delete()
			.build();
		try (Response response = http.newCall(request).execute())
		{
			check(response, bodyOf(response));
		}
	}

	/**
	 * Sends the state of every open offer, so the server can compare each
	 * against the fills it holds for that offer and take on any shortfall as
	 * a recovered, untimed fill. The plugin reports; the server decides.
	 */
	public Reconciliation submitOffers(String apiKey, String accountId, List<OfferState> open) throws IOException
	{
		final JsonObject payload = new JsonObject();
		payload.addProperty("accountId", accountId);
		payload.add("offers", jsonList(open));
		return reconcile(apiKey, url("api", "plugin", "offers"), payload);
	}

	/**
	 * Sends what the history screen shows, in its order, for the server to
	 * match against the completed offers it already has and take on the rest.
	 */
	public Reconciliation submitHistory(String apiKey, String accountId, List<HistoryRow> rows) throws IOException
	{
		final JsonObject payload = new JsonObject();
		payload.addProperty("accountId", accountId);
		payload.add("rows", jsonList(rows));
		return reconcile(apiKey, url("api", "plugin", "history"), payload);
	}

	private Reconciliation reconcile(String apiKey, HttpUrl url, JsonObject payload) throws IOException
	{
		final Request request = new Request.Builder()
			.url(url)
			.header("X-Api-Key", apiKey)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		try (Response response = http.newCall(request).execute())
		{
			final String body = bodyOf(response);
			check(response, body);
			final Reconciliation result = gson.fromJson(body, Reconciliation.class);
			return result == null ? new Reconciliation() : result;
		}
		catch (JsonParseException e)
		{
			throw new IOException("flippingrs.com returned something that is not JSON", e);
		}
	}

	/**
	 * Creates a watchlist. The server may refuse with a plan limit, which
	 * arrives as an IOException carrying its message.
	 */
	public Watchlist createWatchlist(String apiKey, String name, List<Integer> itemIds) throws IOException
	{
		final JsonObject payload = new JsonObject();
		payload.addProperty("name", name);
		payload.add("itemIds", jsonList(itemIds));

		final Request request = new Request.Builder()
			.url(url("api", "plugin", "watchlists"))
			.header("X-Api-Key", apiKey)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();
		return watchlistFrom(request);
	}

	/** Replaces a watchlist's items. The name is left alone. */
	public Watchlist updateWatchlist(String apiKey, String id, List<Integer> itemIds) throws IOException
	{
		final JsonObject payload = new JsonObject();
		payload.add("itemIds", jsonList(itemIds));

		final Request request = new Request.Builder()
			.url(url("api", "plugin", "watchlists", id))
			.header("X-Api-Key", apiKey)
			.patch(RequestBody.create(JSON, gson.toJson(payload)))
			.build();
		return watchlistFrom(request);
	}

	private Watchlist watchlistFrom(Request request) throws IOException
	{
		try (Response response = http.newCall(request).execute())
		{
			final String body = bodyOf(response);
			check(response, body);
			final Watchlist watchlist = gson.fromJson(body, Watchlist.class);
			if (watchlist == null || watchlist.id == null || watchlist.id.isEmpty())
			{
				throw new IOException("flippingrs.com did not return the watchlist");
			}
			return watchlist;
		}
		catch (JsonParseException e)
		{
			throw new IOException("flippingrs.com returned something that is not JSON", e);
		}
	}

	// ---------------------------------------------------------------- plumbing

	/**
	 * The API key as it can actually be sent, or empty when there is none.
	 *
	 * <p>Trims, and trims more than {@link String#trim} does. A key copied out
	 * of a web page can arrive with a non-breaking space on the end of it, and
	 * that is whitespace to a reader but not to trim, nor even to strip, since
	 * Character.isWhitespace says no. A header value may hold only printable
	 * ASCII, so the HTTP client refuses the request before it is built: every
	 * call throws, for a key the settings box plainly shows as correct, which
	 * is the least diagnosable shape a wrong key can take.
	 *
	 * <p>So the ends are trimmed of anything that is not a printable ASCII
	 * character other than a space, which covers what trim removed and the
	 * passengers it did not. Only the ends: a character in the middle is a key
	 * that is wrong rather than one that was pasted untidily, and quietly
	 * editing that would send a different key from the one the user set.
	 */
	static String trimmedKey(@Nullable String configured)
	{
		if (configured == null)
		{
			return "";
		}
		int from = 0;
		int to = configured.length();
		while (from < to && !keyable(configured.charAt(from)))
		{
			from++;
		}
		while (to > from && !keyable(configured.charAt(to - 1)))
		{
			to--;
		}
		return configured.substring(from, to);
	}

	/** Whether a character can begin or end a key: printable ASCII, and not a space. */
	private static boolean keyable(char c)
	{
		return c > 0x20 && c < 0x7f;
	}

	/**
	 * Something to show for an exception. Not every IOException carries a
	 * message, and passing null on to the panel made a failed send read as
	 * "Last sent: never", which is the opposite of what happened.
	 */
	static String describe(Throwable e)
	{
		final String message = e.getMessage();
		return message == null || message.isEmpty() ? e.getClass().getSimpleName() : message;
	}

	/**
	 * A list as JSON. Copied into an ArrayList first, because the Gson RuneLite
	 * ships (2.8.5) reflects on the list's own class and asks a private no-arg
	 * constructor to open itself. A modern JDK refuses -- {@code java.base}
	 * does not open {@code java.util} -- so a {@code Collections.emptyList()}
	 * handed straight to it throws InaccessibleObjectException rather than
	 * serialising.
	 *
	 * <p>Lists with no no-arg constructor to find are not asked, and go
	 * through: {@code singletonList} and {@code Arrays.asList} among them.
	 * That is what makes it worth doing here rather than at the call sites --
	 * the failure waits for whichever call happens to be handed an empty list,
	 * and every other call looks like proof that it cannot happen.
	 */
	private JsonElement jsonList(List<?> list)
	{
		return gson.toJsonTree(new ArrayList<>(list));
	}

	/** Appends path segments to the fixed base. */
	private HttpUrl url(String... segments)
	{
		final HttpUrl.Builder builder = base.newBuilder();
		for (String segment : segments)
		{
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	/**
	 * Reads the response, refusing to read an unbounded amount of it.
	 *
	 * <p>body.string() buffers the entire response into memory with no ceiling,
	 * and the client runs with -Xmx768m. A server having a bad day, or anything
	 * sitting between here and it, can answer with far more than this API ever
	 * would -- and a large enough reply would take the game down rather than
	 * merely fail a sync. Every real response here is a few kilobytes at most;
	 * a truncated one fails to parse, which is reported as a retryable error
	 * and is the right outcome.
	 */
	private static String bodyOf(Response response) throws IOException
	{
		if (response.body() == null)
		{
			return "";
		}
		return response.peekBody(MAX_BODY_BYTES).string();
	}

	/**
	 * Turns a failure response into the right kind of exception.
	 *
	 * <p>The split decides whether a trade is retried until it lands or set
	 * aside, so it is drawn around one question: is the problem with this batch,
	 * or with something else? A malformed, oversized or invalid batch (400, 413,
	 * 422) will be just as bad in five minutes, and holding it would wedge the
	 * queue behind it forever. Everything else -- a revoked key, a lapsed plan,
	 * a moved endpoint, a rate limit, an outage -- is about the key, the
	 * account or the server, and the batch is fine. Those are held: when the
	 * user fixes the key, the trades go out.
	 */
	private void check(Response response, String body) throws IOException
	{
		if (response.isSuccessful())
		{
			return;
		}

		final int code = response.code();
		final String message = messageIn(body, code);

		if (code == 400 || code == 413 || code == 422)
		{
			throw new PermanentException(message);
		}
		if (code == 404)
		{
			throw new NotHereException(message);
		}
		throw new IOException(message);
	}

	/**
	 * How much of the server's message is worth repeating: enough for a
	 * sentence or two, which is all a 205-pixel sidebar can show anyway.
	 *
	 * <p>The body is already capped at a megabyte, and this is what stops the
	 * rest of that megabyte arriving in a Swing label. The panel lays its
	 * messages out as wrapped HTML on the event thread, so a reply that is
	 * long rather than large would freeze the client's interface -- the same
	 * failure {@link #MAX_BODY_BYTES} exists to prevent, one step further in.
	 */
	private static final int MAX_MESSAGE_CHARS = 300;

	/** Digs the human-readable message out of the API's error envelope. */
	private String messageIn(String body, int code)
	{
		try
		{
			final JsonObject root = gson.fromJson(body, JsonObject.class);
			if (root != null && root.has("error"))
			{
				final JsonObject error = root.getAsJsonObject("error");
				if (error.has("message"))
				{
					return shorten(error.get("message").getAsString());
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("could not parse the error body", e);
		}
		return "flippingrs.com returned HTTP " + code;
	}

	private static String shorten(String message)
	{
		return message.length() <= MAX_MESSAGE_CHARS
			? message
			: message.substring(0, MAX_MESSAGE_CHARS) + "...";
	}
}

package com.flippingrs;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

/**
 * The owner's watchlists, and the site's quotes for the one on show.
 *
 * <p>Two caches and nothing of record. The lists are the server's: every
 * edit goes there first and the copy here is replaced with what came back,
 * so the sidebar never shows a change the server did not accept. The quotes
 * are re-read on a timer while something is showing them, and the same copy
 * answers the offer-screen overlay, so an item added or removed in the
 * sidebar shows or vanishes on the offer screen the moment the server has
 * confirmed the edit.
 */
@Slf4j
final class Watchlists
{
	/** What a watchlist is called when the plugin has to create the first one. */
	static final String NEW_WATCHLIST_NAME = "Plan";
	/** The server's cap on one watchlist. */
	static final int MAX_WATCHLIST_ITEMS = 50;

	private final Client client;
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final FlippingRsConfig config;
	private final ProfileStore store;
	private final Supplier<FlippingRsApi> api;
	private final PanelUpdates panel;
	/** Resolves an item's name. Client thread. */
	private final IntFunction<String> itemName;
	/** Re-reads the Watchlists tab from the server. Net thread, synchronous. */
	private final Runnable reread;
	/** Hands work to the net thread. */
	private final Consumer<Runnable> netThread;
	/**
	 * Hands work to the net thread once a delay has passed. False if the
	 * thread is gone, which is a shutdown rather than a failure.
	 */
	private final java.util.function.BiPredicate<Long, Runnable> netThreadLater;
	/** Says what an examined item turned out to be worth. Net thread. */
	private final java.util.function.IntConsumer examinedPriced;

	/** The owner's watchlists, as last read from the server. Null until the first read. */
	@Nullable
	private volatile List<Watchlist> lists;

	/** The site's quotes for the watched items, as last read from the panel endpoint. */
	private volatile Map<Integer, Quote> quotes = Collections.emptyMap();

	/**
	 * The shown watchlist's items, as a set, kept in step with {@link #lists}.
	 *
	 * <p>Only for {@link #isWatched}, which the offer-screen overlay asks on
	 * every frame it draws. Answering it from the lists meant resolving the
	 * chosen watchlist each time -- a RuneLite config read for the remembered
	 * id, then a linear scan of up to fifty boxed ids -- fifty times a second,
	 * for as long as an offer screen is open. This is a hash lookup and no
	 * config read at all.
	 */
	private volatile Set<Integer> watchedIds = Collections.emptySet();

	/**
	 * Whether anything is currently showing the quotes: the sidebar panel is
	 * open, or the Grand Exchange is, where the overlay draws them. While
	 * neither is, the refresh is skipped. It is the one call that would
	 * otherwise run for every user, every half minute, for as long as the
	 * client is open, against a rate limit of sixty requests a minute that
	 * the sends also draw on. Opening the sidebar refreshes at once, so
	 * nothing stale is shown for longer than a tick.
	 */
	private volatile boolean sidebarShown;
	private volatile boolean exchangeOpen;

	/**
	 * Quotes for items the exchange is showing that are not on the watchlist.
	 *
	 * <p>The watchlist is a curated list, and the moment a price is actually
	 * wanted is the moment one is being typed -- which is for whatever item is
	 * in front of you, not only the ones somebody thought to add to a list
	 * beforehand. So the exchange says which items it is showing and these are
	 * fetched for those, on the same tick the watchlist's own quotes are
	 * refreshed on.
	 *
	 * <p>Separate from {@link #quotes} rather than merged into it, because
	 * that map is what the sidebar's cards are drawn from and it is replaced
	 * wholesale by every watchlist read.
	 */
	private volatile Map<Integer, Quote> onDemand = Collections.emptyMap();

	/**
	 * The items the exchange is showing right now: the open offers, and the
	 * one being set up. Written from the client thread, read from the net one.
	 *
	 * <p>Two fields rather than one set, because two overlays report them and
	 * each draws on its own frame. Sharing one collection had them overwrite
	 * each other -- the setup screen's item replacing the slots' and then being
	 * replaced back -- so which items got a price depended on which overlay
	 * happened to render last.
	 */
	private final Set<Integer> offerItems = ConcurrentHashMap.newKeySet();

	/** The item on the offer setup screen, or 0 when it is not open. */
	private volatile int setupItem;

	/** The last item examined that had no price, or 0. */
	private volatile int examinedItem;

	/**
	 * Whether a fetch that was asked for rather than waited for is already on
	 * its way.
	 *
	 * <p>One at a time. Every prompt fetch asks for everything on screen
	 * anyway, so a second one queued behind the first would ask the same
	 * question again for no new answer -- and these come from the client
	 * thread, where the events that trigger them can arrive several to a tick.
	 */
	private final java.util.concurrent.atomic.AtomicBoolean promptFetch =
		new java.util.concurrent.atomic.AtomicBoolean();

	/**
	 * How long to leave a failed quote fetch before trying it again, and how
	 * many times, before falling back on the ordinary refresh.
	 *
	 * <p>A doubling wait rather than a fixed one: the failures worth retrying
	 * at all are a dropped connection, a proxy hiccup or a server restarting,
	 * and the first of those clears in a second while the last takes closer to
	 * a minute. Three tries spans both without turning a server that is
	 * properly down into a client hammering it.
	 */
	private static final long RETRY_NANOS = java.util.concurrent.TimeUnit.SECONDS.toNanos(2);
	private static final int RETRIES = 3;

	/**
	 * Tries left on the fetch that is failing. Net thread only -- the tick,
	 * the prompt fetches and the retries all run on the one executor thread,
	 * which is what makes this safe to keep unsynchronised.
	 */
	private int retriesLeft = RETRIES;

	/**
	 * Set once a server has said it has no per-item quote route, so the plugin
	 * stops asking.
	 *
	 * <p>An older flippingrs.com will answer every one of these the same way
	 * forever, and asking twice a minute for the life of the client spends the
	 * budget on a question already answered. Everything the plugin needs to do
	 * its job goes through routes that have always been there, so this costs
	 * the extra prices and nothing else.
	 */
	private volatile boolean quoteRouteMissing;

	Watchlists(Client client, ItemManager itemManager, ClientThread clientThread, FlippingRsConfig config,
		ProfileStore store, Supplier<FlippingRsApi> api, PanelUpdates panel, IntFunction<String> itemName,
		Runnable reread, Consumer<Runnable> netThread,
		java.util.function.BiPredicate<Long, Runnable> netThreadLater,
		java.util.function.IntConsumer examinedPriced)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.config = config;
		this.store = store;
		this.api = api;
		this.panel = panel;
		this.itemName = itemName;
		this.reread = reread;
		this.netThread = netThread;
		this.netThreadLater = netThreadLater;
		this.examinedPriced = examinedPriced;
	}

	/** Forgets everything, for a plugin start or stop. */
	void reset()
	{
		lists = null;
		watchedIds = Collections.emptySet();
		quotes = Collections.emptyMap();
		onDemand = Collections.emptyMap();
		offerItems.clear();
		setupItem = 0;
		sidebarShown = false;
		exchangeOpen = false;
	}

	/**
	 * Forgets everything read from the server, keeping what is on screen.
	 *
	 * <p>For a change of server, and for recording being switched off or the
	 * key being taken away. In those last two the sidebar says plainly that
	 * nothing is being read from flippingrs.com, and the offer screen has to
	 * agree with it: quotes that stop refreshing but go on being drawn are
	 * prices from a service the user has turned off, silently frozen at
	 * whatever they were, in front of the box where a price gets typed.
	 */
	void forget()
	{
		lists = null;
		watchedIds = Collections.emptySet();
		quotes = Collections.emptyMap();
		onDemand = Collections.emptyMap();
		// A different server may well have the route this one did not. Holding
		// the refusal across a change of server would leave a developer's
		// local instance unable to price anything, for a decision made about
		// somebody else's.
		quoteRouteMissing = false;
	}

	void sidebarShown(boolean shown)
	{
		final boolean opened = shown && !sidebarShown;
		sidebarShown = shown;
		if (opened)
		{
			// Draw what is already cached at once. The plugin starts a read
			// alongside this, but that is a network round trip, and the tab
			// should not be blank or stale for the length of one. It is also
			// what makes it safe for show() to skip a closed sidebar: whatever
			// it skipped is drawn here.
			show();
		}
	}

	void exchangeOpen(boolean open)
	{
		exchangeOpen = open;
	}

	/** Whether the quote timer has anything to do: something is showing quotes, and there are items to quote. */
	boolean wantsQuotes()
	{
		// The shown list's items are already resolved, so this asks them rather
		// than working the chosen watchlist out again -- which meant a RuneLite
		// config read on the net thread every half minute.
		return (sidebarShown || exchangeOpen) && !watchedIds.isEmpty();
	}

	/**
	 * Takes what a panel read returned. Either part may be absent, in which
	 * case what was already held is kept; if either is present the sidebar is
	 * redrawn.
	 */
	void accept(@Nullable List<Watchlist> fromServer, @Nullable Map<Integer, Quote> prices)
	{
		if (fromServer != null)
		{
			lists = fromServer;
		}
		if (prices != null)
		{
			quotes = prices;
		}
		if (fromServer != null || prices != null)
		{
			show();
		}
	}

	/**
	 * The watchlist the tab is showing: the remembered one, or the first the
	 * plugin can actually use.
	 *
	 * <p>One without an id is skipped rather than counted. The picker drops
	 * those, so settling on one had the tab name the next list along while
	 * listing this one's items -- and an add would have gone out as a PATCH
	 * to a watchlist with no id, which is not a request that can be built.
	 */
	@Nullable
	private Watchlist currentOf(List<Watchlist> known)
	{
		if (known.isEmpty())
		{
			return null;
		}
		final String remembered = store.rememberedWatchlistId();
		Watchlist first = null;
		for (Watchlist watchlist : known)
		{
			if (watchlist == null || watchlist.id == null || watchlist.id.isEmpty())
			{
				continue;
			}
			if (watchlist.id.equals(remembered))
			{
				return watchlist;
			}
			if (first == null)
			{
				first = watchlist;
			}
		}
		return first;
	}

	/** Whether an item is on the watchlist the panel is showing. */
	boolean isWatched(int itemId)
	{
		return watchedIds.contains(itemId);
	}

	/**
	 * The site's quote for an item, whether or not it is on the watchlist.
	 *
	 * <p>The watchlist's own price first, because that is the one the sidebar
	 * is showing and the two must not disagree; then whatever was fetched
	 * because the exchange put the item on screen. Null when there is neither,
	 * or when the setting that draws these is off.
	 *
	 * <p>Client thread, from the overlays, once per frame. Both maps are
	 * replaced rather than mutated, so this never blocks the frame.
	 */
	@Nullable
	Quote quoteFor(int itemId)
	{
		// Not gated on a setting here. Every caller has its own -- the
		// exchange screens on one, examine on another -- and gating the lookup
		// as well meant switching the exchange prices off silently switched
		// off the examine line too, which is neither what the setting says nor
		// anywhere the user would look for it.
		//
		// The shown watchlist first, and only if the item is actually on it.
		// The quote map is whatever the last watchlist read returned, which
		// can still hold the previous list's items; answering from it for an
		// item that has since been taken off would have the offer screen
		// pricing something the sidebar no longer lists.
		if (isWatched(itemId))
		{
			final Quote watched = quotes.get(itemId);
			if (watched != null)
			{
				return watched;
			}
		}
		return onDemand.get(itemId);
	}

	/**
	 * The items your open offers are on. Client thread, once a frame.
	 *
	 * <p>Recorded rather than fetched here. A price is a request, the frame
	 * path is the game thread, and the tick that refreshes the watchlist's
	 * quotes is already going to the server on a sensible cadence anyway.
	 */
	void showingOffers(Set<Integer> itemIds)
	{
		if (offerItems.equals(itemIds))
		{
			return;
		}
		offerItems.clear();
		offerItems.addAll(itemIds);
		if (anythingUnpriced(itemIds))
		{
			fetchSoon();
		}
	}

	/** The item on the offer setup screen, or 0 when it is not open. Client thread. */
	void showingSetup(int itemId)
	{
		final int was = setupItem;
		setupItem = itemId;
		if (itemId > 0 && itemId != was && quoteFor(itemId) == null)
		{
			// The one screen where a price is about to be typed, so the wait
			// for one is the wait that matters most.
			fetchSoon();
		}
	}

	/**
	 * An item somebody examined that nobody has a price for. Client thread.
	 *
	 * <p>Fetched now rather than on the next quote tick. Waiting up to thirty
	 * seconds for a line about something the user looked at a moment ago is
	 * indistinguishable from the feature not working.
	 *
	 * <p>Only one item is remembered. Examine is a deliberate act on one
	 * thing, and keeping a list would turn an idle rummage through a bank into
	 * a request for forty prices; one pending fetch at a time keeps a fast
	 * rummage to one request rather than one per item.
	 */
	void showingExamined(int itemId)
	{
		examinedItem = itemId;
		fetchSoon();
	}

	/**
	 * Asks for the prices of whatever is on screen now, rather than on the
	 * next refresh.
	 *
	 * <p>The refresh is every thirty seconds, which is the right cadence for
	 * prices that are already showing and quite the wrong one for prices that
	 * are not. Opening the collection box, or clicking into an offer, changes
	 * what is on screen; without this the new items have no prices at all
	 * until the tick comes round, and half a minute of nothing is
	 * indistinguishable from the plugin being broken.
	 *
	 * <p>Only when something on screen actually has no price, so moving
	 * between screens whose items are already priced costs no request.
	 */
	private void fetchSoon()
	{
		if (promptFetch.compareAndSet(false, true))
		{
			netThread.accept(this::fetchOnDemand);
		}
	}

	/** Whether anything the exchange is showing has no price yet. */
	private boolean anythingUnpriced(Set<Integer> itemIds)
	{
		for (int itemId : itemIds)
		{
			if (itemId > 0 && quoteFor(itemId) == null)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Fetches quotes for what the exchange is showing and the watchlist does
	 * not cover. Net thread, on the quote tick.
	 *
	 * <p>Everything on screen is asked for, not only what is missing, because
	 * a price that is already held is a price that is getting older: this is
	 * the refresh as much as it is the first fetch. It is one request however
	 * many items are on screen, and there are at most nine.
	 */
	void fetchOnDemand()
	{
		promptFetch.set(false);
		if (quoteRouteMissing)
		{
			return;
		}
		// The exchange being open is what makes the offer screens worth
		// pricing, but an examined item is examined anywhere -- a bank, the
		// ground -- so it is asked for wherever it was.
		final boolean wantsScreens = config.setupOverlay() && exchangeOpen;
		final boolean wantsExamined = config.examinePrices() && examinedItem > 0;
		if (!wantsScreens && !wantsExamined)
		{
			return;
		}
		final Set<Integer> wanted = new java.util.LinkedHashSet<>(wantsScreens ? offerItems
			: java.util.Collections.<Integer>emptySet());
		final int setup = setupItem;
		if (setup > 0)
		{
			wanted.add(setup);
		}
		final int examined = examinedItem;
		if (examined > 0)
		{
			wanted.add(examined);
		}
		wanted.removeAll(watchedIds);
		if (wanted.isEmpty())
		{
			if (!onDemand.isEmpty())
			{
				onDemand = Collections.emptyMap();
			}
			return;
		}
		final String key = FlippingRsApi.trimmedKey(config.apiKey());
		if (key.isEmpty())
		{
			return;
		}
		try
		{
			// The journal, so the server can say how much of each buy limit
			// this character has left. Limits are counted per journal, which
			// is the whole reason a main and an alt must not share one.
			final String accountId = store.chosenAccountFor(client.getAccountHash());
			final Map<Integer, Quote> got = api.get().quotes(key, accountId, wanted).getQuotes();
			// A reply with the part absent is "nothing changed", the same as
			// everywhere else, so what is held stays held.
			if (got != null)
			{
				onDemand = got;
			}
			retriesLeft = RETRIES;
			// An examine that could not be answered on the spot is answered
			// now, as its own line. Cleared either way: an item the server had
			// no price for is not worth asking about again on every tick.
			final int answered = examinedItem;
			if (answered > 0)
			{
				examinedItem = 0;
				if (onDemand.containsKey(answered))
				{
					examinedPriced.accept(answered);
				}
			}
		}
		catch (FlippingRsApi.NotHereException e)
		{
			log.info("this flippingrs.com has no per-item quotes; the offer screen will only price watched items");
			quoteRouteMissing = true;
		}
		catch (IOException e)
		{
			// Worth another go before the refresh comes round. These prices
			// are wanted now -- somebody has the exchange open in front of
			// them -- and waiting out the full tick for a dropped connection
			// looks exactly like the plugin having no prices for the item.
			log.debug("could not fetch quotes for what the exchange is showing", e);
			retry();
		}
	}

	/**
	 * Tries a failed fetch again shortly, if it has tries left.
	 *
	 * <p>Bounded, and it gives up quietly rather than noisily: the ordinary
	 * refresh is still running and will pick the prices up on its next pass,
	 * so a server that is genuinely down costs a few extra requests and then
	 * nothing at all. Net thread.
	 */
	private void retry()
	{
		if (retriesLeft <= 0)
		{
			// Back to the tick, and back to a full allowance the next time
			// something works. A run of failures should not leave the retry
			// spent for the rest of the session.
			retriesLeft = RETRIES;
			return;
		}
		final long wait = RETRY_NANOS << (RETRIES - retriesLeft);
		retriesLeft--;
		if (!netThreadLater.test(wait, this::fetchOnDemand))
		{
			// The thread is gone, which is a shutdown. Nothing to retry into.
			retriesLeft = RETRIES;
		}
	}

	/**
	 * An offer on an item changed. If the item is watched, its card's
	 * live-offer line is brought up to date. Only that line: rebuilding every
	 * card, sprites and all, on each fill of a watched item was real work for
	 * a flipper with a long list and fast items. Client thread.
	 */
	void offerChanged(int itemId)
	{
		// Nothing to bring up to date while the sidebar is shut, and a fill on
		// a watched item is otherwise a scan of the eight exchange slots here
		// and, when the line appears or disappears, a rebuild of every card on
		// the Swing thread. Opening the sidebar reads the live offers afresh.
		if (!sidebarShown || !isWatched(itemId))
		{
			return;
		}
		final String live = liveOffer(itemId);
		panel.onPanel(p -> p.updateWatchedOffer(itemId, live));
	}

	/** The player's current offer on an item, in a few words, or null. Client thread. */
	@Nullable
	String liveOffer(int itemId)
	{
		final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return null;
		}
		for (GrandExchangeOffer offer : offers)
		{
			if (offer == null || offer.getItemId() != itemId || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}
			final String verb;
			switch (offer.getState())
			{
				case BUYING:
					verb = "Buying";
					break;
				case SELLING:
					verb = "Selling";
					break;
				case BOUGHT:
					verb = "Bought";
					break;
				case SOLD:
					verb = "Sold";
					break;
				case CANCELLED_BUY:
					verb = "Buy cancelled";
					break;
				case CANCELLED_SELL:
					verb = "Sell cancelled";
					break;
				default:
					continue;
			}
			return verb + " " + offer.getQuantitySold() + "/" + offer.getTotalQuantity()
				+ " at " + FlippingRsPanel.gp(offer.getPrice());
		}
		return null;
	}

	/** The user picked a watchlist in the sidebar. Swing thread. */
	void chosen(String id)
	{
		if (id.equals(store.rememberedWatchlistId()))
		{
			// A combo box fires its action on any pick, including re-picking
			// what was already selected, and that would cost a settings write,
			// a rebuild of every card and a request against a sixty-a-minute
			// limit to arrive back where it started.
			return;
		}
		store.rememberWatchlist(id);
		show();
		netThread.accept(reread);
	}

	/** Net thread. */
	void add(int itemId)
	{
		change(itemId, true);
	}

	/** Net thread. */
	void remove(int itemId)
	{
		change(itemId, false);
	}

	/**
	 * Adds an item to, or removes it from, the chosen watchlist on the server.
	 *
	 * <p>Net thread. The server holds the list, so the edit is sent first and
	 * the panel redrawn from what comes back; nothing is changed locally on
	 * the assumption that it will go through. When the owner has no watchlist
	 * at all, the first add creates one.
	 */
	private void change(int itemId, boolean add)
	{
		try
		{
			if (!config.enabled())
			{
				// "Record trades" off is a promise not to contact the server at
				// all, and a watchlist edit is contact.
				panel.onPanel(p -> p.setWatchlistNotice("Switch \"Record trades\" back on in the plugin settings to change "
					+ "your watchlist.", ColorScheme.BRAND_ORANGE));
				return;
			}
			final String key = FlippingRsApi.trimmedKey(config.apiKey());
			if (key.isEmpty())
			{
				panel.onPanel(p -> p.setWatchlistNotice("Add your API key in the plugin settings to use watchlists.",
					ColorScheme.BRAND_ORANGE));
				return;
			}
			List<Watchlist> known = lists;
			if (known == null)
			{
				// Only the lists are wanted here, so neither a watchlist to
				// price nor a journal to count limits against is worth naming.
				final List<Watchlist> fromServer = api.get().watchlists(key, null, null).getWatchlists();
				known = fromServer == null ? Collections.emptyList() : fromServer;
			}
			final Watchlist current = currentOf(known);
			final Watchlist updated;
			if (current == null)
			{
				if (!add)
				{
					return;
				}
				updated = api.get().createWatchlist(key, NEW_WATCHLIST_NAME, Collections.singletonList(itemId));
				store.rememberWatchlist(updated.id);
				known = new ArrayList<>(known);
				known.add(updated);
			}
			else
			{
				final List<Integer> ids = new ArrayList<>(current.getItemIds());
				final String name = current.toString();
				if (add)
				{
					if (ids.contains(itemId))
					{
						panel.onPanel(p -> p.setWatchlistNotice("Already on " + name + ".", ColorScheme.LIGHT_GRAY_COLOR));
						return;
					}
					if (ids.size() >= MAX_WATCHLIST_ITEMS)
					{
						panel.onPanel(p -> p.setWatchlistNotice(name + " is full: a watchlist holds " + MAX_WATCHLIST_ITEMS
							+ " items. Remove something or pick another watchlist.", ColorScheme.BRAND_ORANGE));
						return;
					}
					ids.add(itemId);
				}
				else if (!ids.remove(Integer.valueOf(itemId)))
				{
					return;
				}
				updated = api.get().updateWatchlist(key, current.id, ids);
				known = replacing(known, updated);
			}
			lists = known;
			show();
			reread.run();
			final String name = updated.toString();
			panel.onPanel(p -> p.setWatchlistNotice((add ? "Added to " : "Removed from ") + name + ".",
				ColorScheme.PROGRESS_COMPLETE_COLOR));
		}
		catch (IOException e)
		{
			// A plan limit arrives here too, with the server's own words.
			log.debug("could not change the watchlist", e);
			final String why = FlippingRsApi.describe(e);
			panel.onPanel(p -> p.setWatchlistNotice("Couldn't update your watchlist: " + why, ColorScheme.PROGRESS_ERROR_COLOR));
		}
		catch (RuntimeException e)
		{
			// Not every way this can fail is an IOException. A key with a stray
			// control character in it is refused by the HTTP client before the
			// request is built, and a config read can throw. This runs as a
			// one-shot task on the net thread, so an escape kills the task and
			// nothing else -- but the user right-clicked Add to watchlist and
			// is owed an answer either way.
			log.warn("unexpected failure while changing the watchlist", e);
			panel.onPanel(p -> p.setWatchlistNotice(
				"Something went wrong updating your watchlist. Details are in the client log.",
				ColorScheme.PROGRESS_ERROR_COLOR));
		}
	}

	private static Set<Integer> setOf(List<Integer> ids)
	{
		final Set<Integer> out = new HashSet<>(Math.max(4, ids.size() * 2));
		for (Integer id : ids)
		{
			if (id != null)
			{
				out.add(id);
			}
		}
		return out;
	}

	private static List<Watchlist> replacing(
		List<Watchlist> known, Watchlist updated)
	{
		final List<Watchlist> out = new ArrayList<>(known.size());
		for (Watchlist watchlist : known)
		{
			out.add(updated.id.equals(watchlist.id) ? updated : watchlist);
		}
		return out;
	}

	/** Puts the cached watchlists on the panel, with the chosen one's items named. */
	private void show()
	{
		final List<Watchlist> known = lists;
		if (known == null)
		{
			return;
		}
		final Watchlist current = currentOf(known);
		final String selected = current == null ? null : current.id;
		final List<Integer> ids = current == null ? Collections.emptyList() : current.getItemIds();
		// Kept in step here, because this is the one place that settles which
		// watchlist is the shown one. Every path that changes the lists or the
		// choice ends up here.
		watchedIds = setOf(ids);

		if (!sidebarShown)
		{
			// The offer-screen overlay reads the ids above and the quotes, and
			// both are now current, which is the whole of what it needs. The
			// cards are not: describing an item asks the item manager for a
			// price, its stats, its composition and its sprite, and scans the
			// eight exchange slots for a live offer, all on the game thread --
			// and then rebuilds fifty cards on the Swing thread. Doing that
			// every half minute for a sidebar nobody has open is the common
			// case for a flipper, who keeps the exchange open and the sidebar
			// shut. Opening it redraws from this same cache.
			return;
		}
		// Names, prices and sprites come from the item manager, which wants
		// the client thread.
		clientThread.invoke(() ->
		{
			final List<FlippingRsPanel.WatchedItem> items = new ArrayList<>(ids.size());
			for (Integer id : ids)
			{
				if (id != null)
				{
					items.add(describeItem(id));
				}
			}
			panel.onPanel(p ->
			{
				p.setWatchlists(known, selected);
				p.setWatchlistItems(items);
			});
		});
	}

	/**
	 * What the watchlist shows for an item: the site's quote from the last
	 * watchlist read, if it has one, and from the client its name and sprite,
	 * RuneLite's exchange price, the buy limit, the alch value, and whether
	 * the player has an offer on it right now. The client's numbers are the
	 * fallback the card shows when the site has no quote for the item.
	 *
	 * <p>Client thread.
	 */
	private FlippingRsPanel.WatchedItem describeItem(int itemId)
	{
		String name = "";
		int price = 0;
		int limit = 0;
		int alch = 0;
		net.runelite.client.util.AsyncBufferedImage image = null;
		try
		{
			price = itemManager.getItemPrice(itemId);
			final net.runelite.client.game.ItemStats stats = itemManager.getItemStats(itemId);
			limit = stats == null ? 0 : stats.getGeLimit();
			// One composition read, not two. The alch value and the name both
			// come off it, and asking twice meant two of these for every item
			// on the watchlist -- fifty of them, on the game thread, every
			// time the quotes are refreshed.
			final net.runelite.api.ItemComposition composition = itemManager.getItemComposition(itemId);
			alch = composition.getHaPrice();
			name = composition.getName() == null ? "" : composition.getName();
			image = itemManager.getImage(itemId);
		}
		catch (RuntimeException e)
		{
			// A row with a name and no numbers beats no row.
			log.debug("could not describe item {}", itemId, e);
		}
		// Only when the read above did not get one: the supplier is the same
		// lookup with the same guard around it, so asking it after a read that
		// worked is the second read this method exists to avoid.
		return new FlippingRsPanel.WatchedItem(itemId, name.isEmpty() ? itemName.apply(itemId) : name,
			image, price, limit, alch, liveOffer(itemId), quotes.get(itemId));
	}
}

package com.flippingrs;

import java.awt.Rectangle;
import java.util.function.IntConsumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;

/**
 * Right-click entries on items in the Grand Exchange interface.
 *
 * <p>Two entries, wherever the exchange shows an item, which is every screen
 * it has: the eight offer slots, the offer setup page, the page you get by
 * clicking an offer you have already placed, your history, the collection
 * box, the inventory beside it all, another player's offers in a view-only
 * exchange, and the price checker. One opens the item's page on the site in
 * the browser, the other adds it to the watchlist shown in the side panel.
 * Where the item comes from on each of those is {@link GeItems}'s business,
 * not this class's. Both are
 * {@link MenuAction#RUNELITE} entries, which is the line Jagex's third-party
 * client guidelines draw: a menu entry may not cause an action to be sent to
 * the game server, and these never touch it. RuneLite's own Grand Exchange
 * plugin adds its "Search Grand Exchange" entry the same way.
 *
 * <p>Hooked on the menu opening rather than on each entry being added,
 * because most of those screens are display only: a history row has no
 * options of its own and so never raises an entry to hang one off. Where the
 * leading entry does say which widget it is on that is used, because it is
 * exact; otherwise the item is found from where the mouse is.
 *
 * <p>Runs on the client thread, because menu events do. The browser and the
 * watchlist are handed to it as callbacks so that this can be tested without
 * opening anything.
 */
@Slf4j
class GeMenu
{
	static final String VIEW = "View item";
	static final String WATCH = "Add to watchlist";

	private final Client client;
	private final ItemManager itemManager;
	private final IntConsumer openItem;
	private final IntConsumer addToWatchlist;

	GeMenu(Client client, ItemManager itemManager, IntConsumer openItem, IntConsumer addToWatchlist)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.openItem = openItem;
		this.addToWatchlist = addToWatchlist;
	}

	void onMenuOpened(MenuOpened event)
	{
		int itemId = itemUnderMenu(event.getFirstEntry());
		if (itemId <= 0)
		{
			// Every other screen the exchange has. The menu over one of those
			// says nothing about where it was opened, so the item is found
			// from the boxes the exchange is drawing and where the mouse is
			// among them.
			itemId = GeItems.under(client, client.getMouseCanvasPosition());
		}
		if (itemId <= 0)
		{
			return;
		}

		final int canonical = canonicalize(itemId);
		final String name = nameOf(canonical);

		// Added in reverse so that "View" ends up above "Add to watchlist":
		// each createMenuEntry(-1) goes on the top of the menu.
		client.getMenu().createMenuEntry(-1)
			.setOption(WATCH)
			.setTarget(name)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> addToWatchlist.accept(canonical));
		client.getMenu().createMenuEntry(-1)
			.setOption(VIEW)
			.setTarget(name)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> openItem.accept(canonical));
	}

	/**
	 * The unnoted form of an item, or the item itself if the client will not
	 * say.
	 *
	 * <p>This and {@link #nameOf} guard their lookups because this method runs
	 * on every right-click inside the exchange, straight off RuneLite's event
	 * bus. An id the client cannot resolve -- one read off a history row whose
	 * layout has moved, say -- would otherwise throw out of the subscriber and
	 * be logged as an uncaught plugin error every time the user opened a menu.
	 * A menu entry is worth having with a worse target on it; it is not worth
	 * a stack trace a second.
	 */
	private int canonicalize(int itemId)
	{
		try
		{
			return itemManager.canonicalize(itemId);
		}
		catch (RuntimeException e)
		{
			log.debug("could not canonicalize item {}", itemId, e);
			return itemId;
		}
	}

	/** The item's name for the entry's target, or empty if the client will not give one. */
	private String nameOf(int itemId)
	{
		try
		{
			final String name = itemManager.getItemComposition(itemId).getName();
			return name == null ? "" : name;
		}
		catch (RuntimeException e)
		{
			log.debug("could not resolve a name for item {}", itemId, e);
			return "";
		}
	}

	/** The item the menu's leading entry is on, if it is an exchange widget. */
	private int itemUnderMenu(MenuEntry first)
	{
		if (first == null)
		{
			return -1;
		}
		final int widgetId = first.getParam1();
		switch (WidgetUtil.componentToInterface(widgetId))
		{
			case InterfaceID.GE_OFFERS:
				if (widgetId >= InterfaceID.GeOffers.SETUP && widgetId <= InterfaceID.GeOffers.SETUP_GRAPHIC4)
				{
					// The item being set up to buy or sell. The same varp
					// RuneLite's own plugin reads to put the buy limit on
					// that page.
					return client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
				}
				return itemInOfferSlot(widgetId);
			case InterfaceID.GE_OFFERS_SIDE:
				return itemOnEntry(first);
			default:
				return -1;
		}
	}

	/**
	 * The item in one of the eight offer slots, from the client's own record of
	 * the offer. The slot widgets do not carry an item id themselves.
	 */
	private int itemInOfferSlot(int widgetId)
	{
		final int slot = widgetId - InterfaceID.GeOffers.INDEX_0;
		if (slot < 0 || slot > InterfaceID.GeOffers.INDEX_7 - InterfaceID.GeOffers.INDEX_0)
		{
			return -1;
		}
		final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null || slot >= offers.length || offers[slot] == null)
		{
			return -1;
		}
		final GrandExchangeOffer offer = offers[slot];
		return offer.getState() == GrandExchangeOfferState.EMPTY ? -1 : offer.getItemId();
	}

	/** The item an inventory-style entry is on. */
	private static int itemOnEntry(MenuEntry entry)
	{
		if (entry.getItemId() > 0)
		{
			return entry.getItemId();
		}
		final Widget widget = entry.getWidget();
		return widget == null ? -1 : widget.getItemId();
	}
}

package com.flippingrs;

import com.google.gson.Gson;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * What the plugin remembers between sessions, in RuneLite's config.
 *
 * <p>Two of the three things here are a character's rather than a person's:
 * the baseline for each exchange slot, which is what stops a login from
 * re-reporting every offer still on the exchange, and which FlippingRS
 * journal this character files under. The third, which watchlist the
 * right-click entry adds to, is a plain plugin setting: a watchlist is a
 * person's, not a character's.
 *
 * <p>The journal choice is per character so an alt gets its own journal
 * without anyone remembering to change a dropdown before logging in. Getting
 * it wrong mixes two accounts' numbers together, and since buy limits are
 * tracked per game account, the damage is not cosmetic. It is picked in the
 * side panel, not the settings, for the same reason: a single global dropdown
 * would silently file a main's flips under an alt the first time someone
 * forgot.
 *
 * <p>The slot baselines live in the active RuneScape profile, because they are
 * only ever read for the character that is logged in. The journal choice is
 * keyed by account hash instead, because it is not: sending an alt's queued
 * fills means knowing which journal they belong to while somebody else is
 * logged in.
 */
@Slf4j
final class ProfileStore
{
	/** Config key prefix for the per-slot baseline. */
	static final String OFFER_KEY = "offer";
	/**
	 * Config key prefix for the chosen FlippingRS game account, per RuneScape
	 * account hash. Also the whole key of the per-profile setting older
	 * versions wrote, which {@link #migrateChosenAccount} reads once.
	 */
	static final String ACCOUNT_KEY = "gameAccountId";
	/** Config key for which watchlist the right-click entry adds to. Only the choice is kept; the list lives on the site. */
	static final String WATCHLIST_KEY = "watchlistId";

	private final ConfigManager configManager;
	private final Gson gson;

	ProfileStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	// ------------------------------------------------------------- baselines

	@Nullable
	SavedOffer loadOffer(int slot)
	{
		final String json = configManager.getRSProfileConfiguration(FlippingRsConfig.GROUP, OFFER_KEY + "." + slot);
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, SavedOffer.class);
		}
		catch (RuntimeException e)
		{
			// A baseline we cannot read is the same as not having one: the offer
			// is adopted rather than re-reported, which is the safe direction.
			log.warn("could not read the saved baseline for slot {}", slot, e);
			return null;
		}
	}

	void saveOffer(int slot, SavedOffer offer)
	{
		configManager.setRSProfileConfiguration(FlippingRsConfig.GROUP, OFFER_KEY + "." + slot, gson.toJson(offer));
	}

	void clearOffer(int slot)
	{
		configManager.unsetRSProfileConfiguration(FlippingRsConfig.GROUP, OFFER_KEY + "." + slot);
	}

	// --------------------------------------------------------------- journal

	/**
	 * The FlippingRS journal a RuneScape account files under, or null if none
	 * has been chosen for it.
	 *
	 * <p>Keyed by account hash rather than held in the active RuneScape
	 * profile, so that it can be read for an account that is not the one
	 * logged in. That is what lets a session send an alt's queued fills:
	 * the queue is per account, and without a journal to file them under they
	 * would otherwise wait on disk until that character next logged in, which
	 * could be never.
	 *
	 * <p>The account hash is the character, which is what the RuneScape
	 * profile was standing in for, so this is the same choice stored somewhere
	 * it can be looked up. {@link #migrateChosenAccount} moves an older
	 * install's choice across.
	 */
	@Nullable
	String chosenAccountFor(long accountHash)
	{
		final String id = configManager.getConfiguration(FlippingRsConfig.GROUP, accountKey(accountHash));
		return id == null || id.isEmpty() ? null : id;
	}

	void rememberChosenAccountFor(long accountHash, String id)
	{
		configManager.setConfiguration(FlippingRsConfig.GROUP, accountKey(accountHash), id);
	}

	void forgetChosenAccountFor(long accountHash)
	{
		configManager.unsetConfiguration(FlippingRsConfig.GROUP, accountKey(accountHash));
	}

	/**
	 * Moves the choice an older version stored in the active RuneScape profile
	 * to the per-account key this one reads.
	 *
	 * <p>Called with the account that is logged in, since the profile config is
	 * only readable for that one. Does nothing once there is a choice under the
	 * new key, so a user who has since picked a different journal keeps it. The
	 * old key is left where it is: it is one string, and removing it would mean
	 * a downgrade silently loses the setting.
	 */
	void migrateChosenAccount(long accountHash)
	{
		if (chosenAccountFor(accountHash) != null)
		{
			return;
		}
		final String legacy = configManager.getRSProfileConfiguration(FlippingRsConfig.GROUP, ACCOUNT_KEY);
		if (legacy == null || legacy.isEmpty())
		{
			return;
		}
		log.debug("moving this character's journal choice to the per-account key");
		rememberChosenAccountFor(accountHash, legacy);
	}

	/** Where one account's journal choice is kept. */
	private static String accountKey(long accountHash)
	{
		return ACCOUNT_KEY + "." + accountHash;
	}

	// ------------------------------------------------------------- watchlist

	/** The watchlist the picker is set to, or null if none has been picked. */
	@Nullable
	String rememberedWatchlistId()
	{
		final String id = configManager.getConfiguration(FlippingRsConfig.GROUP, WATCHLIST_KEY);
		return id == null || id.isEmpty() ? null : id;
	}

	void rememberWatchlist(String id)
	{
		configManager.setConfiguration(FlippingRsConfig.GROUP, WATCHLIST_KEY, id);
	}
}

package com.flippingrs;

import com.google.gson.JsonElement;
import java.util.List;

/** What the server made of a snapshot: how much it already had and how much it took on. */
public class Reconciliation
{
	int reconciled;
	int recovered;
	int matched;
	int added;
	int ignored;
	/** Only present when a row was malformed; raw JSON for the same reason as IngestResult's. */
	List<JsonElement> problems;

	public int getRecovered()
	{
		return recovered;
	}

	public int getAdded()
	{
		return added;
	}

	/** Why rows were refused, one line each. Never null. */
	public List<String> getProblems()
	{
		return Wire.problemsOf(problems);
	}
}

package com.flippingrs;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Locale;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The side panel, in five tabs.
 *
 * <ul>
 *   <li><b>Watchlists</b> is one of the owner's watchlists on the site, each
 *       item with the site's buy and sell prices, margin after tax and ROI.
 *   <li><b>Journal</b> is the journal's recent rows, read back from the
 *       server: what was actually recorded, not what the plugin remembers
 *       sending. The two differ exactly when something went wrong.
 *   <li><b>Positions</b> is what is still held, marked to market by the
 *       server, with the two actions the site's own Positions page has, and
 *       under it what has been sold and what each of those made.
 *   <li><b>Analytics</b> is the last week's verdict: realised profit, flips,
 *       win rate and gp per hour, all worked out on the site.
 *   <li><b>Account</b> is the connection: whether the key works, what plan it
 *       is on, and which journal this RuneScape account files under.
 *   <li><b>Activity</b> is the plugin's own doing, and the one tab with no
 *       page on the site: what it has captured this session, what is still
 *       buffered waiting to send, and when it last sent. The buffered fills
 *       are listed, because a fill sitting here is the one thing the plugin
 *       holds that the journal does not yet.
 * </ul>
 *
 * <p>Every number about money on any of these tabs is the server's. The
 * plugin formats; it does not compute.
 *
 * <p>Messages go to the tab they are about, so each tab answers its own
 * question without the others' news overwriting it.
 *
 * <p>Every method here must be called on the Swing thread. The plugin marshals.
 */
public class FlippingRsPanel extends PluginPanel
{
	static final DateTimeFormatter TIME = DateTimeFormatter
		.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault());
	static final DateTimeFormatter SHORT_TIME = DateTimeFormatter
		.ofPattern("HH:mm").withZone(ZoneId.systemDefault());
	static final DateTimeFormatter DAY = DateTimeFormatter
		.ofPattern("d MMM HH:mm", Locale.ENGLISH).withZone(ZoneId.systemDefault());

	static final int RECENT_SHOWN = 8;

	/** This panel's own border, on each side. */
	static final int PANEL_PADDING = 10;
	/** A card's padding, on each side. */
	static final int CARD_PADDING = 6;
	/** The sprite at the head of a card, and the gap between it and the title. */
	static final int ICON_WIDTH = 36;
	static final int ICON_GAP = 6;

	/**
	 * How long a notice stays up. A notice is news -- a recovered trade, an
	 * item added, a refused batch -- and news that never leaves stops being
	 * read. Anything that still matters after this is somewhere permanent:
	 * the log, the set-aside file, the tab's own problem line.
	 */
	static final int NOTICE_SECONDS = 20;

	/** What the watchlist shows for one item. Resolved by the plugin, drawn here. */
	static class WatchedItem
	{
		final int itemId;
		final String name;
		/** The item's sprite, filled in when the client has drawn it. Null in a test. */
		@Nullable
		final AsyncBufferedImage image;
		/** RuneLite's current exchange price for the item, or 0 if it has none. */
		final int price;
		/** The four-hour buy limit, or 0 if unknown. */
		final int limit;
		/** High alchemy value, or 0. */
		final int alch;
		/** The player's live offer on the item, e.g. "Buying 4/10 at 1.50M", or null. */
		@Nullable
		final String offer;
		/** The site's quote, or null if it has none or could not be reached. */
		@Nullable
		final Quote quote;

		WatchedItem(int itemId, String name, @Nullable AsyncBufferedImage image,
			int price, int limit, int alch, @Nullable String offer, @Nullable Quote quote)
		{
			this.itemId = itemId;
			this.name = name;
			this.image = image;
			this.price = price;
			this.limit = limit;
			this.alch = alch;
			this.offer = offer;
			this.quote = quote;
		}
	}

	static final Border SELECTED_TAB = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.BRAND_ORANGE),
		BorderFactory.createEmptyBorder(4, 3, 3, 3));
	static final Border UNSELECTED_TAB = BorderFactory.createEmptyBorder(4, 3, 4, 3);

	/**
	 * A tab with less padding and the narrower font, so five fit in a
	 * 205-pixel sidebar in two rows. RuneLite's own tab re-applies its wide
	 * border on every select and unselect, hence the overrides.
	 *
	 * <p>Selecting one is also what draws it. Four of the five are off screen
	 * at any moment and building their contents costs real time -- see
	 * {@link #drawWhatIsShowing}.
	 */
	private class Tab extends MaterialTab
	{
		Tab(String name, MaterialTabGroup group, JComponent content)
		{
			super(name, group, content);
			setFont(FontManager.getRunescapeSmallFont());
			setHorizontalAlignment(SwingConstants.CENTER);
			unselect();
		}

		@Override
		public boolean select()
		{
			final boolean selected = super.select();
			setBorder(SELECTED_TAB);
			showing = this;
			drawWhatIsShowing();
			return selected;
		}

		@Override
		public void unselect()
		{
			super.unselect();
			setBorder(UNSELECTED_TAB);
		}
	}

	/** The tab whose contents are on screen; see {@link SidebarTab}. */
	@Nullable
	private MaterialTab showing;

	/**
	 * Keeps the showing tab's freshness line counting.
	 *
	 * <p>One label, once a second, and only while the sidebar is actually the
	 * thing on screen -- RuneLite says when that starts and stops. Six labels
	 * ticking behind five tabs nobody is looking at would be work for no
	 * reader, on the thread the client draws frames with.
	 */
	private final Timer freshness = new Timer(1000, e -> tickFreshness());

	/**
	 * The six tabs, each owning its own widgets and its own deferred redraw.
	 *
	 * <p>Named and ordered as flippingrs.com names and orders its own screens,
	 * so that moving between the site and the sidebar is not two vocabularies
	 * for one journal. Its Market group comes first, then its Journal group --
	 * where the ledger, the open lots and the week's numbers are three pages
	 * and used to be two tabs here -- then Account. Activity is last because
	 * it is the one thing here with no page on the site: it is what the plugin
	 * on this computer is doing, which the site cannot know.
	 */
	private final WatchlistTab watchlist;
	private final JournalTab journal;
	private final PositionsTab positions;
	private final AnalyticsTab analytics;
	private final AccountTab account;
	private final ActivityTab activity;

	private final MaterialTabGroup tabs;
	private final MaterialTab watchlistTab;
	private final MaterialTab journalTab;
	private final MaterialTab positionsTab;
	private final MaterialTab analyticsTab;
	private final MaterialTab accountTab;
	private final MaterialTab activityTab;

	/**
	 * Set while the plugin is not reading from the server at all: recording
	 * off, or no key. The tabs that show the server's data show this instead
	 * of stale rows. Cleared by the next data that arrives.
	 */
	@Nullable
	private String paused;

	/** What the plugin does when the sidebar is used. Never null. */
	private final PanelActions actions;

	public FlippingRsPanel(PanelActions actions)
	{
		this.actions = actions;
		watchlist = new WatchlistTab(actions);
		journal = new JournalTab();
		positions = new PositionsTab(actions);
		analytics = new AnalyticsTab();
		account = new AccountTab(actions);
		activity = new ActivityTab(actions);
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(PANEL_PADDING, PANEL_PADDING, PANEL_PADDING, PANEL_PADDING));

		final JPanel top = column();
		top.add(header("FlippingRS"));
		top.add(Box.createVerticalStrut(6));

		final JPanel display = new JPanel();
		tabs = new MaterialTabGroup(display);
		watchlistTab = new Tab("Watchlists", tabs, watchlist.body());
		journalTab = new Tab("Journal", tabs, journal.body());
		positionsTab = new Tab("Positions", tabs, positions.body());
		analyticsTab = new Tab("Analytics", tabs, analytics.body());
		accountTab = new Tab("Account", tabs, account.body());
		activityTab = new Tab("Activity", tabs, activity.body());
		for (MaterialTab tab : new MaterialTab[]{
			watchlistTab, journalTab, positionsTab, analyticsTab, accountTab, activityTab})
		{
			tabs.addTab(tab);
		}
		// Two rows of three, which the six tabs now fill exactly; the fifth
		// used to leave a cell empty. The group's own layout is a FlowLayout,
		// which wraps what does not fit onto a second row and then reports the
		// height of one, so anything past the first row was laid out below
		// the visible strip and never painted.
		tabs.setLayout(new GridLayout(2, 3, 2, 2));
		tabs.setAlignmentX(Component.LEFT_ALIGNMENT);
		tabs.setMaximumSize(new Dimension(Integer.MAX_VALUE, tabs.getPreferredSize().height));
		top.add(tabs);
		top.add(Box.createVerticalStrut(8));
		display.setAlignmentX(Component.LEFT_ALIGNMENT);
		top.add(display);

		add(top, BorderLayout.NORTH);

		setStatus("Not connected", ColorScheme.LIGHT_GRAY_COLOR);
		setSubscription(null);
		setCounts(0, 0);
		setLastSync(null, null);
		setActivityNotice(null, ColorScheme.LIGHT_GRAY_COLOR);
		setWatchlistNotice(null, ColorScheme.LIGHT_GRAY_COLOR);
		setJournalNotice(null, ColorScheme.LIGHT_GRAY_COLOR);
		setWatchlists(new ArrayList<>(), null);
		// Every tab is now holding data it has not drawn. Selecting the first
		// draws that one; the other four draw when they are selected.
		for (SidebarTab tab : new SidebarTab[]{watchlist, journal, positions, analytics, account, activity})
		{
			tab.refresh();
		}
		// Opens on the journal, which is what somebody came to look at. It
		// opened on Activity while that was the first tab; that is the tab you
		// go to when something looks wrong, not the one to greet you with.
		tabs.select(journalTab);
	}

	static JPanel column()
	{
		final JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		return body;
	}

	/**
	 * Draws the list on the tab that has just come on screen, if its data
	 * moved while it was off.
	 *
	 * <p>Each of these skips itself when its own tab is not the one showing,
	 * so calling all four is how the one that is gets drawn. The labels above
	 * each list are set as the data arrives and cost nothing; it is the lists
	 * that are dear, because each row is a card built out of several labels
	 * and, on two of the tabs, a pair of buttons. Two hundred open positions
	 * measure at around 98ms to build, and that was being paid on every
	 * journal read whichever tab the user was looking at.
	 */
	private void drawWhatIsShowing()
	{
		watchlist.showing(showing == watchlistTab);
		journal.showing(showing == journalTab);
		positions.showing(showing == positionsTab);
		analytics.showing(showing == analyticsTab);
		account.showing(showing == accountTab);
		activity.showing(showing == activityTab);
		// At once as well as on the tick, or a tab picked halfway through a
		// second would show the count as it stood when it was last on screen.
		tickFreshness();
	}

	/** The showing tab's freshness line, brought up to the second. */
	private void tickFreshness()
	{
		final SidebarTab tab = showingTab();
		if (tab != null)
		{
			tab.tick(System.currentTimeMillis());
		}
	}

	/** Which of the six is on screen, or null before the first is picked. */
	@Nullable
	private SidebarTab showingTab()
	{
		if (showing == watchlistTab)
		{
			return watchlist;
		}
		if (showing == journalTab)
		{
			return journal;
		}
		if (showing == positionsTab)
		{
			return positions;
		}
		if (showing == analyticsTab)
		{
			return analytics;
		}
		if (showing == accountTab)
		{
			return account;
		}
		return showing == activityTab ? activity : null;
	}

	/** RuneLite calls this when the panel becomes the sidebar's content. */
	@Override
	public void onActivate()
	{
		tickFreshness();
		freshness.start();
		actions.shown();
	}

	/** And this when it stops being. */
	@Override
	public void onDeactivate()
	{
		freshness.stop();
		actions.hidden();
	}

	/** A line under a tab's title saying what the tab shows and where it comes from. */
	static JPanel hint(String text)
	{
		final JPanel holder = column();
		final JLabel label = small(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
		holder.add(label);
		holder.add(Box.createVerticalStrut(8));
		holder.setAlignmentX(Component.LEFT_ALIGNMENT);
		return holder;
	}

	static JLabel header(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	// ------------------------------------------------------------- the tabs
	//
	// One line each, on to the tab that owns the widgets. The plugin and its
	// reads talk to the panel, not to five tabs, so which tab holds what
	// stays this class's business rather than becoming everybody's.

	/** The connection status, on the Account tab. */
	void setStatus(String text, Color colour)
	{
		account.setStatus(text, colour);
	}

	/** The plan the key's owner is on, in the server's words, or null if not known. */
	void setSubscription(@Nullable String text)
	{
		account.setSubscription(text);
	}

	void setAccounts(List<GameAccount> available, @Nullable String selectedId)
	{
		account.setAccounts(available, selectedId);
	}

	@Nullable
	String selectedAccountId()
	{
		return account.selectedAccountId();
	}

	void setCounts(int recordedCount, int queuedCount)
	{
		activity.setCounts(recordedCount, queuedCount);
	}

	void setLastSync(@Nullable Instant at, @Nullable String problem)
	{
		activity.setLastSync(at, problem);
	}

	void setActivityNotice(@Nullable String text, Color colour)
	{
		activity.setActivityNotice(text, colour);
	}

	void setPending(List<GeTransaction> newestFirst)
	{
		activity.setPending(newestFirst);
	}

	/** How many fills the server refused for good and the plugin filed. */
	void setSetAside(int count)
	{
		activity.setSetAside(count);
	}

	void setRecentTrades(List<GeTransaction> newestFirst)
	{
		resumed();
		journal.setRecentTrades(newestFirst);
	}

	void setRecentTrades(List<GeTransaction> newestFirst, Map<Integer, AsyncBufferedImage> images)
	{
		resumed();
		journal.setRecentTrades(newestFirst, images);
	}

	void setRecentTradesProblem(String why)
	{
		journal.setRecentTradesProblem(why);
	}

	/**
	 * One read of the journal fills two tabs: the server answers with the
	 * week and the open lots together, and splitting them here costs no
	 * second request.
