	/**
	 * Short gp, the way the game and the site both write it.
	 *
	 * <p>Locale.ROOT, not the default locale. String.format follows the JVM's
	 * locale, so on a machine set to most of Europe this produced "1,50M" --
	 * a decimal comma reads as a thousands separator to an English-speaking
	 * player, which turns 1.5M into an apparent 150M at a glance.
	 */
	static String gp(long amount)
	{
		final long abs = Math.abs(amount);
		if (abs >= 1_000_000_000L)
		{
			return String.format(Locale.ROOT, "%.2fB", amount / 1_000_000_000d);
		}
		if (abs >= 1_000_000L)
		{
			return String.format(Locale.ROOT, "%.2fM", amount / 1_000_000d);
		}
		if (abs >= 1_000L)
		{
			return String.format(Locale.ROOT, "%.1fK", amount / 1_000d);
		}
		return amount + "gp";
	}

	/** gp with its sign always shown: "+30.0K", "-1.2K", "0gp". */
	static String signed(long amount)
	{
		return amount > 0 ? "+" + gp(amount) : gp(amount);
	}

	/** gp to the coin, with thousands separators: "1,480,000". For numbers that get typed. */
	static String exact(long amount)
	{
		return String.format(Locale.ROOT, "%,d", amount);
	}

	/** Exact gp with its sign always shown: "+9,600", "-500", "0". */
	static String signedExact(long amount)
	{
		return amount > 0 ? "+" + exact(amount) : exact(amount);
	}

	/** A count, not money: "1.2K", "340". */
	static String count(long n)
	{
		if (n >= 1_000_000L)
		{
			return String.format(Locale.ROOT, "%.1fM", n / 1_000_000d);
		}
		if (n >= 1_000L)
		{
			return String.format(Locale.ROOT, "%.1fK", n / 1_000d);
		}
		return Long.toString(n);
	}

	/**
	 * "1.2K/24h", or null when the site has no volume for the item.
	 *
	 * <p>Null rather than "0/24h". A day with no trades and a server that does
	 * not send the figure look identical from here, and of the two readings
	 * the wrong one is a great deal worse: it would say an item nobody can
	 * shift is worth a hundred million a flip, which is exactly the item
	 * somebody would put their whole bank into.
	 *
	 * <p>Shared, because it now appears on the watchlist card, in the
	 * exchange's hover box, on both offer screens and on an examine line, and
	 * four copies of a format is four places for one to say something
	 * different about the same number.
	 */
	@Nullable
	static String volume(@Nullable Quote quote)
	{
		return quote == null || quote.getVolume24h() <= 0
			? null : count(quote.getVolume24h()) + "/24h";
	}

	/** A fraction as a percentage: 0.0213 is "2.1%". */
	static String pct(double fraction)
	{
		return String.format(Locale.ROOT, "%.1f%%", fraction * 100d);
	}

	/**
	 * "5h", "2d 3h", "40m".
	 *
	 * <p>Rounded once, up front, and the days and hours taken from that one
	 * figure. Rounding the remainder separately produced "2d 24h" for anything
	 * that landed in the last half hour of a day -- a duration that reads as
	 * nonsense next to the "3d 0h" it is.
	 */
	static String hours(double hours)
	{
		final long minutes = Math.round(hours * 60);
		if (minutes < 60)
		{
			return minutes + "m";
		}
		final long total = Math.round(hours);
		if (total < 48)
		{
			return total + "h";
		}
		return (total / 24) + "d " + (total % 24) + "h";
	}

	/**
	 * The labels render HTML so they can wrap, which means server messages and
	 * item names have to be escaped rather than interpreted.
	 */
	static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

}

package com.flippingrs;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.widgets.Widget;

/**
 * Finding the line of text that belongs to a thing on screen.
 *
 * <p>An exchange screen is not built out of rows. It is a flat bag of widgets
 * -- an item icon here, a name there, a quantity beside it -- and what makes
 * them a row is only that they were laid out at the same height. So a caption
 * that wants to be part of a row has to work out which of that bag it belongs
 * to, and the answer is geometric rather than structural.
 *
 * <p>Deliberately forgiving about where it looks. Children come in three
 * flavours and which one a screen uses is the screen's business; an earlier
 * version of this looked only at the dynamic ones and found nothing at all on
 * a screen that keeps its text elsewhere, which is indistinguishable from the
 * feature being off.
 *
 * <p>Client thread only.
 */
final class RowText
{
	private RowText()
	{
	}

	/**
	 * Every widget under a container, of whichever kind it keeps them in.
	 *
	 * <p>One level deep, and then one more: a screen that wraps each row in a
	 * layer keeps the text a level below where a flat one does, and looking
	 * only at the top level finds the wrappers rather than their contents.
	 */
	static List<Widget> under(@Nullable Widget container)
	{
		final List<Widget> all = new ArrayList<>();
		if (container == null)
		{
			return all;
		}
		for (Widget child : childrenOf(container))
		{
			all.add(child);
			all.addAll(childrenOf(child));
		}
		return all;
	}

	private static List<Widget> childrenOf(Widget widget)
	{
		final List<Widget> out = new ArrayList<>();
		for (Widget[] children : new Widget[][]{
			widget.getDynamicChildren(), widget.getStaticChildren(), widget.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child != null && !child.isHidden())
				{
					out.add(child);
				}
			}
		}
		return out;
	}

	/**
	 * The line of text to add to, among widgets already gathered.
	 *
	 * <p>The lowest one that sits within the band, and the furthest right of
	 * those -- which is the end of what that row says, and so where something
	 * added to it reads as part of the same sentence rather than as an
	 * interruption of it.
	 *
	 * @param from  top of the band, in the same space as the widgets' relative
	 *              positions
	 * @param to    bottom of the band
	 */
	@Nullable
	static Widget lastIn(List<Widget> widgets, int from, int to)
	{
		Widget best = null;
		for (Widget widget : widgets)
		{
			if (!isText(widget))
			{
				continue;
			}
			final int middle = widget.getRelativeY() + widget.getHeight() / 2;
			if (middle < from || middle >= to)
			{
				continue;
			}
			if (best == null || lower(widget, best))
			{
				best = widget;
			}
		}
		return best;
	}

	/** Whether one widget reads as coming after another on the same row. */
	private static boolean lower(Widget candidate, Widget best)
	{
		if (candidate.getRelativeY() != best.getRelativeY())
		{
			return candidate.getRelativeY() > best.getRelativeY();
		}
		return candidate.getRelativeX() > best.getRelativeX();
	}

	/** Whether a widget is a line of text rather than an item or a picture. */
	static boolean isText(Widget widget)
	{
		if (widget.getItemId() > 0)
		{
			return false;
		}
		final String text = widget.getText();
		return text != null && !text.isEmpty();
	}
}

package com.flippingrs;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * Fills waiting to be sent, held on disk as well as in memory.
 *
 * <p>A trade that happened is a fact, and the plugin should not lose it because
 * the network blinked or the user closed the client. So every change is written
 * through to a file, and the file is re-read on startup. The cost is a small
 * write per fill, which is nothing next to losing an evening of flips.
 *
 * <p>The file is per RuneScape account. Two accounts logged in on two clients
 * would otherwise take turns overwriting each other's pending work.
 *
 * <p>Every method is synchronised. Fills arrive on the client thread and drain
 * on a scheduler thread, and those are genuinely concurrent.
 */
@Slf4j
public class TransactionQueue
{
	/**
	 * How many fills to hold before dropping the oldest.
	 *
	 * <p>Eight slots cannot produce this in any normal session, so reaching it
	 * means something has been failing to send for a very long time. Dropping
	 * the oldest keeps the file bounded, and the alternative -- an unbounded
	 * file -- eventually fails to write at all and loses everything rather than
	 * the stalest thing.
	 */
	private static final int CAPACITY = 10_000;

	private final Deque<GeTransaction> pending = new ArrayDeque<>();
	private final Gson gson;
	private final File file;

	/** {@link #CAPACITY}, unless a test asked for a smaller one. */
	private final int capacity;

	/**
	 * How many evictions the file may run ahead by before it is compacted.
	 *
	 * <p>A removal cannot be expressed by appending, so an eviction needs the
	 * whole file rewritten. Doing that on the add that evicts sounds like it
	 * costs one rewrite in every {@link #CAPACITY} fills, and it does the first
	 * time -- but the queue does not go back under the cap afterwards, so from
	 * then on <em>every</em> fill rewrote ten thousand rows. That is the state
	 * a client is in precisely when sending has been failing for hours, and it
	 * turned each new trade into several megabytes of writing.
	 *
	 * <p>So the evicted row is left in the file and the new one appended after
	 * it, and the file is compacted every hundredth eviction instead. While the
	 * compactions are landing the file runs at most this far past the cap, and
	 * the rows it holds over are real trades that were dropped -- so a client
	 * killed in between restores a few more than it strictly had, which is the
	 * harmless direction.
	 *
	 * <p>It can run further than that when a compaction cannot be written at
	 * all: see {@link #add}, which appends rather than let the fill go
	 * unrecorded. The file comes back down on the next compaction that works.
	 */
	private final int evictionsPerRewrite;

	private int evictionsSinceRewrite;

	/**
	 * Where refused fills go. Beside the queue, named {@code dropped-} in place
	 * of {@code queue-}, so a user who is told a trade could not be recorded
	 * can still find it rather than take it on faith that it ever existed.
	 */
	private final File dropped;

	/**
	 * The rewrite's staging file. A fixed name rather than a fresh temp file per
	 * rewrite: a client killed between creating one and moving it into place
	 * used to leave a {@code queueNNNN.tmp} behind forever, and a fixed name
	 * means the next rewrite simply overwrites the orphan.
	 */
	private final File staging;

	/**
	 * How many fills are in {@link #dropped}, or -1 for "not counted yet".
	 * Counting means reading the file, and it is nearly always absent.
	 */
	private int setAside = -1;

	public TransactionQueue(Gson gson, File file)
	{
		this(gson, file, CAPACITY);
	}

	/** Test seam: lets a test reach the cap without ten thousand writes. */
	TransactionQueue(Gson gson, File file, int capacity)
	{
		this.gson = gson;
		this.file = file;
		this.capacity = capacity;
		this.evictionsPerRewrite = Math.max(1, capacity / 100);
		final String name = file.getName();
		this.dropped = new File(file.getParentFile(),
			name.startsWith("queue-") ? "dropped-" + name.substring("queue-".length()) : "dropped-" + name);
		this.staging = new File(file.getParentFile(), name + ".tmp");
		load();
	}

	public synchronized void add(GeTransaction tx)
	{
		if (pending.size() < capacity)
		{
			pending.addLast(tx);
			append(tx);
			return;
		}

		// More than one only when a file was restored from over the cap, which
		// is the compaction below running behind at the moment the client was
		// last killed.
		int evicted = 0;
		while (pending.size() >= capacity)
		{
			final GeTransaction oldest = pending.pollFirst();
			if (evicted == 0)
			{
				log.warn("queue is full at {}; dropping the oldest pending fill: {}", capacity, oldest);
			}
			evicted++;
		}
		pending.addLast(tx);

		evictionsSinceRewrite += evicted;
		if (evicted > 1 || evictionsSinceRewrite >= evictionsPerRewrite)
		{
			// A compaction that could not be written leaves the new fill
			// nowhere on disk, and the counter over the mark -- so every add
			// after it takes this branch too, and never appends either. One
			// failed rewrite would have stopped the file recording anything
			// for the rest of the session, in the state where the queue is
			// full and every trade in it is already at risk. Appending is the
			// same durability the fill would have had; the cost is that the
			// file runs further past the cap until a rewrite works, and it is
			// brought back down when one does.
			if (!rewrite())
			{
				append(tx);
			}
		}
		else
		{
			append(tx);
		}
	}

	/**
	 * Takes up to {@code max} fills for sending, leaving them in the queue.
	 *
	 * <p>They stay until {@link #confirm} says the server has them. Removing
	 * them here and putting them back on failure would lose the batch outright
	 * if the client were killed mid-send, which is exactly when a flipper is
	 * most likely to kill it.
	 */
	public synchronized List<GeTransaction> peek(int max)
	{
		final List<GeTransaction> batch = new ArrayList<>(Math.min(max, pending.size()));
		for (GeTransaction tx : pending)
		{
			if (batch.size() >= max)
			{
				break;
			}
			batch.add(tx);
		}
		return batch;
	}

	/**
	 * Drops fills the server has accepted.
	 *
	 * <p>Matched on id rather than on object identity. The two are the same
	 * within one session, but the id is what actually identifies a fill, and
	 * relying on identity would break the moment anything copied a row.
	 *
	 * <p>Only rewritten if something actually left, so a confirmation of rows
	 * that have already gone does not cost a write of the whole backlog.
	 */
	public synchronized void confirm(Collection<GeTransaction> sent)
	{
		if (sent.isEmpty())
		{
			return;
		}
		final Set<String> ids = new HashSet<>();
		for (GeTransaction tx : sent)
		{
			ids.add(tx.id);
		}
		if (pending.removeIf(tx -> ids.contains(tx.id)))
		{
			rewrite();
		}
	}

	/**
	 * Sets aside fills the server has refused for good.
	 *
	 * <p>They leave the queue, because retrying cannot help and holding them
	 * would wedge every later trade behind them. But they are appended to a
	 * sibling file rather than deleted: the plugin's promise is that a trade is
	 * never silently lost, and a row on disk that a user can read, fix and
	 * enter by hand keeps that promise where a log line does not.
	 */
	public synchronized void reject(Collection<GeTransaction> refused)
	{
		if (refused.isEmpty())
		{
			return;
		}
		if (writeDropped(refused))
		{
			if (setAside >= 0)
			{
				setAside += refused.size();
			}
		}
		else
		{
			// These are about to leave the queue whether or not they could be
			// filed -- holding them would wedge every later trade -- and the
			// panel is at this moment telling the user they were set aside
			// where they can be found. That has to be true somewhere, so if it
			// is not the file it is the log.
			for (GeTransaction tx : refused)
			{
				log.warn("refused fill that could not be written to {}: {}", dropped, gson.toJson(tx));
			}
		}
		confirm(refused);
	}

	/** @return whether the refused fills reached the sibling file */
	private boolean writeDropped(Collection<GeTransaction> refused)
	{
		final Path parent = parent();
		if (parent == null)
		{
			return false;
		}
		try
		{
			intoFolder(parent, () ->
			{
				try (Writer out = Files.newBufferedWriter(dropped.toPath(), StandardCharsets.UTF_8,
					StandardOpenOption.CREATE, StandardOpenOption.APPEND))
				{
					for (GeTransaction tx : refused)
					{
						out.write(gson.toJson(tx));
						out.write('\n');
					}
				}
			});
			return true;
		}
		catch (IOException e)
		{
			log.warn("could not record the refused fills in {}: {}", dropped, e.toString());
			return false;
		}
	}

	/** Where refused fills are kept. Exposed for the log line that points at it. */
	public File droppedFile()
	{
		return dropped;
	}

	/**
	 * How many fills are set aside, so the sidebar can offer to try them
	 * again.
	 *
	 * <p>Counted off the file the first time it is asked for and kept from
	 * then on, because this is read on every panel refresh and the answer is
	 * nearly always zero. A file that cannot be read counts as empty: the
	 * button it decides is an offer to retry, and offering to retry something
	 * that cannot be read would fail in a way that explains nothing.
	 */
	public synchronized int setAsideCount()
	{
		if (setAside < 0)
		{
			setAside = countDropped();
		}
		return setAside;
	}

	/**
	 * Puts the set-aside fills back in the queue for another go, and forgets
	 * the file.
	 *
	 * <p>The only reason to ask for this is that whatever the server was
	 * refusing them over has been changed: a key that was wrong, a journal
	 * that was not this owner's, a plan that had lapsed. Those are properties
	 * of the account rather than of the rows, and the rows were only ever set
	 * aside because the plugin could not tell the two apart. Retrying is safe
	 * however wrong that guess was, because every fill carries the id the
	 * server de-duplicates on.
	 *
	 * <p>The rows go into the queue before the file is forgotten, never the
	 * other way round. A client killed in between restores them twice, which
	 * the server drops as repeats; the other order loses them for good.
	 *
	 * @return how many went back, which is zero if there were none or the
	 *         file could not be read
	 */
	public synchronized int restoreSetAside()
	{
		if (!dropped.isFile())
		{
			setAside = 0;
			return 0;
		}
		final List<GeTransaction> restored = new ArrayList<>();
		try (BufferedReader in = new BufferedReader(new InputStreamReader(
			Files.newInputStream(dropped.toPath()), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				if (line.trim().isEmpty())
				{
					continue;
				}
				final GeTransaction tx = parse(line);
				// The same bar a restored fill has to clear: without an id the
				// server could not de-duplicate it, so it can only be sent once
				// and never safely again.
				if (tx != null && tx.id != null && !tx.id.isEmpty())
				{
					restored.add(tx);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("could not read the set-aside fills in {}: {}", dropped, e.toString());
			return 0;
		}
		for (GeTransaction tx : restored)
		{
			// Through add, so each is written to the queue file as it goes and
			// the cap is honoured the same way a fresh fill is.
			add(tx);
		}
		if (!dropped.delete() && dropped.isFile())
		{
			// They are in the queue and will be sent; leaving the file would
			// only mean restoring them a second time, which the server drops.
			// Worth a line, because the count the sidebar shows comes from it.
			log.warn("restored {} set-aside fill(s) but could not remove {}", restored.size(), dropped);
			setAside = -1;
			return restored.size();
		}
		setAside = 0;
		log.info("put {} set-aside fill(s) back in the queue", restored.size());
		return restored.size();
	}

	/** Lines in the set-aside file, or zero if there is not one to read. */
	private int countDropped()
	{
		if (!dropped.isFile())
		{
			return 0;
		}
		int rows = 0;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(
			Files.newInputStream(dropped.toPath()), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				if (!line.trim().isEmpty())
				{
					rows++;
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("could not count the set-aside fills in {}", dropped, e);
			return 0;
		}
		return rows;
	}

	/**
	 * The most recently added fills, newest first, for showing what is still
	 * buffered. A copy; the queue is not touched.
	 */
	public synchronized List<GeTransaction> newest(int max)
	{
		final List<GeTransaction> out = new ArrayList<>(Math.min(max, pending.size()));
		final java.util.Iterator<GeTransaction> it = pending.descendingIterator();
		while (it.hasNext() && out.size() < max)
		{
			out.add(it.next());
		}
		return out;
	}

	public synchronized int size()
	{
		return pending.size();
	}

	public synchronized boolean isEmpty()
	{
		return pending.isEmpty();
	}

	/**
	 * Reads the queue back, tolerating damage.
	 *
	 * <p>Two formats are accepted. The current one is JSON Lines, one fill per
	 * line; the leading '[' of the original whole-array format is recognised so
	 * that upgrading does not silently throw away whatever was still pending.
	 *
	 * <p>Lines are parsed individually and a bad one is skipped rather than
	 * failing the file. That is the point of the line format as much as the
	 * append is: a process killed mid-append leaves a torn final line, and this
	 * costs that one fill instead of the entire backlog.
	 *
	 * <p>Read a line at a time rather than whole. Slurping the file gave a
	 * String of the entire backlog, a trimmed second copy of it to look for
	 * the legacy '[', and then an array of every line on top of that -- all
	 * before the first fill was parsed, and all on the path a client takes
	 * while it is starting up.
	 */
	private void load()
	{
		if (!file.isFile())
		{
			return;
		}
		try
		{
			if (startsAnArray())
			{
				loadLegacyArray(new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
				// Written back in the new format so the next add can append.
				rewrite();
				return;
			}
			int damaged = 0;
			try (BufferedReader in = reader())
			{
				String line;
				while ((line = in.readLine()) != null)
				{
					if (line.trim().isEmpty())
					{
						continue;
					}
					if (!accept(parse(line)))
					{
						damaged++;
					}
				}
			}
			if (damaged > 0)
			{
				log.warn("skipped {} unreadable line(s) in {}", damaged, file);
			}
			log.debug("restored {} pending fills from {}", pending.size(), file);
		}
		catch (IOException | RuntimeException e)
		{
			// Losing part of the queue is bad; refusing to build one at all is
			// worse. This runs in the constructor, which is on the path every
			// fill takes, so an exception out of here is not a queue that comes
			// back short -- it is an account with no queue at all, and every
			// fill from then on lost, for as long as the file stays as it is.
			log.warn("could not finish reading the pending queue at {}; keeping the {} fill(s) read so far: {}",
				file, pending.size(), e.toString());
		}
	}

	/**
	 * Whether the file is the original whole-array format, from its first
	 * character that is not whitespace.
	 */
	private boolean startsAnArray() throws IOException
	{
		try (BufferedReader in = reader())
		{
			int c;
			while ((c = in.read()) != -1)
			{
				if (!Character.isWhitespace(c))
				{
					return c == '[';
				}
			}
		}
		return false;
	}

	/**
	 * The file as characters.
	 *
	 * <p>Built by hand rather than through {@code Files.newBufferedReader},
	 * which reports a malformed byte as an IOException. That would lose the
	 * whole backlog to one corrupt byte, where this substitutes it and costs
	 * only the line it is on -- the same tolerance the rest of this method has.
	 */
	private BufferedReader reader() throws IOException
	{
		return new BufferedReader(
			new InputStreamReader(Files.newInputStream(file.toPath()), StandardCharsets.UTF_8));
	}

	private void loadLegacyArray(String content)
	{
		try
		{
			final GeTransaction[] saved = gson.fromJson(content, GeTransaction[].class);
			if (saved != null)
			{
				for (GeTransaction tx : saved)
				{
					accept(tx);
				}
			}
		}
		catch (JsonParseException e)
		{
			log.warn("could not read the pending queue at {}, starting empty: {}", file, e.toString());
		}
	}

	@Nullable
	private GeTransaction parse(String line)
	{
		try
		{
			return gson.fromJson(line, GeTransaction.class);
		}
		catch (JsonParseException e)
		{
			// The family, not the one member of it Gson happens to raise for
			// the damage seen so far. Anything Gson refuses has to come out
			// here as a line skipped: the guard around the whole read is a
			// backstop, and reaching it costs every line after this one as
			// well as this one.
			return null;
		}
	}

	/**
	 * Keeps a restored fill, unless it has no id.
	 *
	 * <p>An id-less row could never be de-duplicated by the server, so sending
	 * it risks counting a trade twice -- which is the one outcome worse than
	 * losing it.
	 */
	private boolean accept(@Nullable GeTransaction tx)
	{
		if (tx == null || tx.id == null || tx.id.isEmpty())
		{
			return false;
		}
		pending.addLast(tx);
		return true;
	}

	/**
	 * Appends one fill. This is the hot path and it is O(1) in the size of the
	 * queue.
	 *
	 * <p>It used to serialise and rewrite the entire deque on every add, which
	 * is quadratic in the number of fills waiting: filling the queue to its
	 * 10,000 cap wrote about twelve gigabytes to get there. Appending writes one
	 * line regardless of how much is already pending.
	 */
	private void append(GeTransaction tx)
	{
		final Path parent = parent();
		if (parent == null)
		{
			return;
		}
		final byte[] line = (gson.toJson(tx) + "\n").getBytes(StandardCharsets.UTF_8);
		try
		{
			intoFolder(parent, () -> Files.write(file.toPath(), line,
				StandardOpenOption.CREATE, StandardOpenOption.APPEND));
		}
		catch (IOException e)
		{
			// The fill is still in memory and the next rewrite will persist it,
			// so this is a durability gap rather than a lost trade.
			log.warn("could not append to the pending queue at {}: {}", file, e.toString());
		}
	}

	/** A write that may find the folder it writes into is not there. */
	@FunctionalInterface
	private interface Write
	{
		void run() throws IOException;
	}

	/**
	 * Runs a write, making the folder if that turns out to be what was missing.
	 *
	 * <p>The folder is only absent on the very first write of a fresh install,
	 * or if someone tidies it away under a running client, so it is asked for
	 * when a write says it is needed rather than before every write. Confirming
	 * it each time cost as much as the write itself -- 264 microseconds against
	 * an append's 255, measured -- to establish something that had been true
	 * all session, and every fill pays the append.
	 */
	private static void intoFolder(Path parent, Write write) throws IOException
	{
		try
		{
			write.run();
		}
		catch (NoSuchFileException missing)
		{
			Files.createDirectories(parent);
			write.run();
		}
	}

	/**
	 * Writes the whole queue out. Needed whenever fills are removed, which an
	 * append cannot express: after a confirmed send, and on the one add in every
	 * CAPACITY that has to evict.
	 *
	 * @return whether the file now matches the queue
	 */
	private boolean rewrite()
	{
		final Path parent = parent();
		if (parent == null)
		{
			return false;
		}
		try
		{
			// Write beside the target and move it into place, so a client killed
			// mid-rewrite leaves the previous good queue rather than half a file.
			//
			// Straight out to the file, a line at a time. Building the whole
			// thing as a String first meant a full backlog existed three times
			// over at once -- the builder, the String it copies to, and the
			// bytes that copies to -- on a client whose heap is 768M and which
			// is drawing a game at the same time.
			final Path temp = staging.toPath();
			intoFolder(parent, () ->
			{
				try (Writer out = Files.newBufferedWriter(temp, StandardCharsets.UTF_8))
				{
					for (GeTransaction tx : pending)
					{
						out.write(gson.toJson(tx));
						out.write('\n');
					}
				}
			});
			try
			{
				Files.move(temp, file.toPath(),
					StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(temp, file.toPath(), StandardCopyOption.REPLACE_EXISTING);
			}
			// Only now: the file matches the deque, so the rows evictions have
			// been leaving behind are gone. Resetting before the write would
			// have a failed one look like a compaction and leave the file
			// growing for another hundred evictions.
			evictionsSinceRewrite = 0;
			return true;
		}
		catch (IOException e)
		{
			// Keep the in-memory queue and keep going: the fills are still there
			// for this session, and the next write may work.
			log.warn("could not persist the pending queue to {}: {}", file, e.toString());
			return false;
		}
	}

	@Nullable
	private Path parent()
	{
		final Path parent = file.toPath().getParent();
		if (parent == null)
		{
			// A bare filename has no directory to write the temporary file
			// beside, and the plugin never builds one, so this is a bug rather
			// than a condition to work around.
			log.warn("queue path {} has no parent directory; not persisting", file);
		}
		return parent;
	}
}

package com.flippingrs;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The site's prices, drawn on items the exchange shows without a line of text
 * to put them on.
 *
 * <p>Everywhere the exchange writes a sentence about an item -- the offer
 * setup screen, an open offer, a row of your history -- the prices go on the
 * end of that sentence, because a line the client wrote is already positioned,
 * sized, wrapped and clipped by the screen that owns it. What is left is the
 * screens that are grids of pictures and nothing else: the collection box, a
 * view-only exchange, the price checker, the inventory beside it all. There is
 * nothing there to add to, so those are painted on.
 *
 * <p>The two ends of the spread, and the margin alone in a box too narrow for
 * both. Nothing at all for an item with no quote, which is every item before
 * the first fetch lands: a blank box is the honest rendering of not knowing.
 */
class GeItemInfoOverlay extends Overlay
{
	/** Inset from a box's edges, so the text does not sit on the border. */
	private static final int MARGIN = 3;

	private final Client client;
	private final FlippingRsConfig config;
	private final IntFunction<Quote> quoteFor;
	/** Told which items are on screen, so their prices can be fetched. */
	private final Consumer<Set<Integer>> showing;

	GeItemInfoOverlay(Client client, FlippingRsConfig config, IntFunction<Quote> quoteFor,
		Consumer<Set<Integer>> showing)
	{
		this.client = client;
		this.config = config;
		this.quoteFor = quoteFor;
		this.showing = showing;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(false);
		setSnappable(false);
	}

	/** One box's caption, and the two forms it can take if the box is narrow. */
	static final class Caption
	{
		/** What to draw when there is room. */
		final String full;
		/** What to draw when there is not. Never longer than {@link #full}. */
		final String brief;
		final Color colour;

		Caption(String full, String brief, Color colour)
		{
			this.full = full;
			this.brief = brief;
			this.colour = colour;
		}
	}

	/**
	 * What to write on one item, or null when there is nothing worth saying.
	 *
	 * <p>Static and taking everything it needs, so the wording and the colour
	 * can be pinned by a test without a client running.
	 */
	@Nullable
	static Caption captionFor(@Nullable Quote quote)
	{
		return quote == null ? null : justThePrices(quote);
	}

	/**
	 * An item you have no offer on: the two ends of the spread, and the margin
	 * alone where there is no room for them.
	 */
	@Nullable
	private static Caption justThePrices(Quote quote)
	{
		if (quote.getBuyAt() <= 0 && quote.getSellAt() <= 0)
		{
			return null;
		}
		final Color colour = quote.getNetMargin() < 0
			? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR;
		return new Caption(
			FlippingRsPanel.gp(quote.getBuyAt()) + "/" + FlippingRsPanel.gp(quote.getSellAt()),
			FlippingRsPanel.signed(quote.getNetMargin()),
			colour);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.setupOverlay())
		{
			// The setting is off, so nothing is drawn and nothing is worth
			// fetching a price for. Said rather than assumed, because the list
			// would otherwise keep whatever was on screen when it was switched
			// off for the rest of the session.
			showing.accept(java.util.Collections.emptySet());
			return null;
		}

		final List<GeItems.Spot> spots = GeItems.onScreen(client);

		graphics.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics metrics = graphics.getFontMetrics();

		// Whatever is in front of the player is what is worth having a price
		// for. Ordered, so the request is the same from one frame to the next
		// while the screen has not changed.
		final Set<Integer> onScreen = new LinkedHashSet<>();
		for (GeItems.Spot spot : spots)
		{
			onScreen.add(spot.itemId);
			if (!spot.paint)
			{
				// The setup screen carries its own; see GeOfferText.
				continue;
			}
			final Caption caption = captionFor(quoteFor.apply(spot.itemId));
			if (caption != null)
			{
				draw(graphics, metrics, spot, caption);
			}
		}
		showing.accept(onScreen);
		return null;
	}

	/**
	 * Puts one caption along the bottom of its box, over a backing so it stays
	 * readable against whatever the box is drawing underneath.
	 *
	 * <p>The shorter form is used when the longer one does not fit, and
	 * neither is drawn when even that would spill out of the box. An item slot
	 * is thirty-odd pixels wide and a history row is most of the screen; the
	 * same caption cannot serve both, and half a number is worse than none.
	 */
	private static void draw(Graphics2D graphics, FontMetrics metrics, GeItems.Spot spot, Caption caption)
	{
		final Rectangle bounds = spot.bounds;
		final int room = bounds.width - 2 * MARGIN;
		String text = caption.full;
		if (metrics.stringWidth(text) > room)
		{
			text = caption.brief;
		}
		final int width = metrics.stringWidth(text);
		if (width > room)
		{
			return;
		}
		final int height = metrics.getHeight();
		final int x = bounds.x + bounds.width - width - MARGIN;
		final int y = bounds.y + bounds.height - MARGIN;

		// Clipped to the list holding the row, the way the client clips the
		// row itself. Some of these screens scroll, and a row scrolled out of
		// one is not hidden -- its bounds are a real rectangle outside the
		// list -- so without this the caption for a row nobody can see is
		// painted over whatever the exchange has put above or below it.
		final java.awt.Shape was = graphics.getClip();
		if (spot.clip != null)
		{
			graphics.clipRect(spot.clip.x, spot.clip.y, spot.clip.width, spot.clip.height);
		}
		try
		{
			graphics.setColor(new Color(0, 0, 0, 160));
			graphics.fillRect(x - 2, y - metrics.getAscent() - 1, width + 4, height);

			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x + 1, y + 1);
			graphics.setColor(caption.colour);
			graphics.drawString(text, x, y);
		}
		finally
		{
			graphics.setClip(was);
		}
	}
}

package com.flippingrs;

import javax.annotation.Nullable;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * How your own offer is priced against what the site says its side is worth.
 *
 * <p>All that is left of a class that used to write this into the offer boxes.
 * The boxes are the size the game made them and are best left that way, so the
 * words themselves moved to {@link GeTooltip} -- but working out which price
 * an offer should be measured against is a question of its own, and getting it
 * backwards would call every sensible offer badly priced by exactly the width
 * of the spread.
 */
final class GeSlotText
{
	private GeSlotText()
	{
	}

	/**
	 * How far an offer is from the site's price for the side it is on, or null
	 * if there is no offer, no price, or nothing to compare.
	 *
	 * <p>Positive means the offer is on the side of the price that fills
	 * sooner: a buy at or above the site's buy price, a sale at or below its
	 * sell price. Negative is the patient end of the flip, which is where the
	 * profit is and also where an offer can sit all evening -- so it decides a
	 * colour rather than a verdict.
	 */
	@Nullable
	static Long edgeOf(@Nullable GrandExchangeOffer offer, @Nullable Quote quote)
	{
		final Long market = marketFor(offer, quote);
		if (market == null)
		{
			return null;
		}
		return buying(offer) ? offer.getPrice() - market : market - offer.getPrice();
	}

	/**
	 * The same comparison in words: "2 over sell", "5,000 under buy", "at
	 * buy". Null when there is nothing to compare.
	 *
	 * <p>A bare signed number was not enough, and it is worth saying why. On
	 * its own, "-2" is a difference from something unnamed, measured in a
	 * direction the reader has to guess, and whether it is good news depends
	 * on which side of the trade they are on -- three questions where there
	 * should be none. Naming the price it is measured against answers all
	 * three at once, and the line sits directly under that price in the box,
	 * so the arithmetic is there to be checked.
	 *
	 * <p>"Over" and "under" rather than a sign, because the sign convention
	 * has to invert between buying and selling and no convention survives
	 * that. Whether over is the good direction is the colour's job.
	 */
	@Nullable
	static String gapFrom(@Nullable GrandExchangeOffer offer, @Nullable Quote quote)
	{
		final Long market = marketFor(offer, quote);
		if (market == null)
		{
			return null;
		}
		final String side = buying(offer) ? "buy" : "sell";
		final long from = offer.getPrice() - market;
		if (from == 0)
		{
			return "at " + side;
		}
		return FlippingRsPanel.exact(Math.abs(from)) + (from > 0 ? " over " : " under ") + side;
	}

	/**
	 * The site's price for the side an offer is on, or null if there is no
	 * live offer or no price.
	 *
	 * <p>The two ends of the spread are not interchangeable: they are what a
	 * flip lives between, and measuring an offer against the wrong one would
	 * call every sensible offer badly priced by exactly the width of it.
	 */
	@Nullable
	private static Long marketFor(@Nullable GrandExchangeOffer offer, @Nullable Quote quote)
	{
		if (offer == null || quote == null)
		{
			return null;
		}
		final GrandExchangeOfferState state = offer.getState();
		if (state == null || state == GrandExchangeOfferState.EMPTY)
		{
			return null;
		}
		final long market = buying(offer) ? quote.getBuyAt() : quote.getSellAt();
		return market <= 0 ? null : market;
	}

	/** Whether an offer is a buy. Anything that is not is a sale. */
	private static boolean buying(GrandExchangeOffer offer)
	{
		final GrandExchangeOfferState state = offer.getState();
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.CANCELLED_BUY
			|| state == GrandExchangeOfferState.BOUGHT;
	}
}

package com.flippingrs;

import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * One tab of the sidebar: what it shows, and when it is worth drawing.
 *
 * <p>Four of the five tabs are off screen at any moment, and the lists on
 * them are the expensive part of this panel: a row is a card of several
 * labels and, on two of the tabs, a pair of buttons. Two hundred open
 * positions measure at around 98ms to build, and that was once paid on every
 * journal read whichever tab the user was actually looking at.
 *
 * <p>So a tab that is off screen does not draw. It remembers that its data
 * moved on, and draws once, when the user selects it. The setters call
 * {@link #refresh} and never {@link #redraw}, which is what keeps that true
 * as tabs gain new things to show.
 *
 * <p>Swing thread throughout. Nothing here is touched from anywhere else.
 */
abstract class SidebarTab
{
	/** Whether this is the tab whose contents are on screen. */
	private boolean showing;

	/** Whether the data moved on while nobody could see it. */
	private boolean stale;

	/**
	 * When this tab's data last arrived, or 0 for never.
	 *
	 * <p>Wall-clock rather than nanoTime, because what this becomes is words
	 * about how long ago something happened, and the arithmetic is done on the
	 * Swing thread a second at a time. A clock that steps is a line that reads
	 * oddly once; a monotonic one here would buy nothing.
	 */
	private long updatedAt;

	/** Why nothing is being read at all, if that is the case. */
	@Nullable
	private String pausedWhy;

	/**
	 * The line at the foot of the tab saying how fresh what is above it is.
	 *
	 * <p>Every tab here shows the server's answer to a question, and the
	 * answer's age is part of it: a margin from four minutes ago is a
	 * different thing to act on than the same margin from four seconds ago,
	 * and nothing else on the tab says which it is. Dim, because it qualifies
	 * what is above rather than competing with it.
	 */
	private final JLabel refreshLine = FlippingRsPanel.small("");

	{
		refreshLine.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
	}

	/** The tab's contents. Built once, when the panel is built. */
	abstract JPanel body();

	/**
	 * Draws the tab from whatever the setters have stored.
	 *
	 * <p>Only ever called while this is the tab on screen, so an implementation
	 * never has to ask. Tabs that write straight to their labels -- Account,
	 * whose few lines cost nothing to set -- have nothing to do here.
	 */
	void redraw()
	{
	}

	/**
	 * The panel saying whether this is now the tab on screen. A tab that
	 * becomes visible with data it has not drawn draws it now.
	 */
	final void showing(boolean nowShowing)
	{
		showing = nowShowing;
		if (nowShowing && stale)
		{
			stale = false;
			redraw();
		}
	}

	/**
	 * Whether the plugin is reading from the server at all, and why not.
	 *
	 * <p>A reason arriving means the rows this tab is holding are about to
	 * become a picture of a journal nobody is looking at, so the tabs that
	 * show the server's data drop them. Null means reading has resumed.
	 * Activity has nothing to drop -- it is the one tab that is not the
	 * server's -- and Account is where the reason is explained.
	 *
	 * <p>Final, so that the freshness line goes quiet with the rest of it. A
	 * countdown to a read that is not going to happen is the most confident
	 * thing on a tab that has just said it is not reading.
	 */
	final void paused(@Nullable String why)
	{
		pausedWhy = why;
		onPaused(why);
		tick(System.currentTimeMillis());
	}

	/** What a tab does with that, if anything. */
	void onPaused(@Nullable String why)
	{
	}

	// ------------------------------------------------------------ freshness

	/**
	 * The label to put at the foot of the tab. Built here, placed by the tab,
	 * because where it belongs depends on what is above it.
	 */
	final JLabel refreshLine()
	{
		return refreshLine;
	}

	/**
	 * How often this tab's data is re-read on a timer, or 0 when nothing is
	 * scheduled.
	 *
	 * <p>Every tab that shows the server's answers has one. The quotes keep
	 * their own faster clock; the rest share the sidebar's, which only runs
	 * while the sidebar is open.
	 */
	long refreshEverySeconds()
	{
		return 0;
	}

	/**
	 * What else brings a read sooner than the timer would, or null when
	 * nothing does.
	 *
	 * <p>Said as well as the countdown rather than instead of it. A trade
	 * recorded now refreshes the journal now, and a tab that only offered a
	 * countdown would have somebody waiting out forty seconds for a row that
	 * was already there.
	 */
	@Nullable
	String refreshedBy()
	{
		return null;
	}

	/** This tab's data has just arrived. */
	final void stamp()
	{
		updatedAt = System.currentTimeMillis();
		tick(updatedAt);
	}

	/**
	 * Brings the line up to date. Called a second at a time by the panel, for
	 * the showing tab only: five labels counting down behind a tab nobody is
	 * looking at is work for no reader.
	 */
	final void tick(long nowMs)
	{
		// Wrapped, like every other line here. The sidebar is 205 pixels and
		// this one is a sentence; set plainly it would run off the edge, which
		// is what the width test caught the first time.
		FlippingRsPanel.setWrappedText(refreshLine, freshnessText(nowMs));
	}

	/**
	 * "Updated just now · next in 22s", or "Updated 4m ago · next when a trade
	 * is recorded", or nothing at all.
	 *
	 * <p>Nothing before the first read, because "updated never" is not what
	 * somebody wants to be told about a tab that is loading, and the tab's own
	 * summary already says it has nothing yet.
	 */
	final String freshnessText(long nowMs)
	{
		if (pausedWhy != null || updatedAt == 0 || refreshedBy() == null && refreshEverySeconds() == 0)
		{
			return "";
		}
		final long seconds = Math.max(0, TimeUnit.MILLISECONDS.toSeconds(nowMs - updatedAt));
		final String age = GeOfferText.age(seconds);
		final StringBuilder out = new StringBuilder("Updated ").append(age == null ? "just now" : age);
		final long every = refreshEverySeconds();
		if (every > 0)
		{
			final long left = every - seconds;
			// "Due now" rather than a negative, or a zero that sits there. The
			// read is a request over a network and the tick that starts it is
			// a fixed delay from the last one finishing, so the last second of
			// the count is a moment this cannot be exact about.
			out.append(" · next ").append(left > 0 ? "in " + left + "s" : "due now");
			if (refreshedBy() != null)
			{
				out.append(" or ").append(refreshedBy());
			}
		}
		else
		{
			out.append(" · next ").append(refreshedBy());
		}
		return out.toString();
	}

	/** The line as it now reads, for a test that does not want to wait a second. */
	final String refreshLineForTest()
	{
		return refreshLine.getText();
	}

	/**
	 * The data changed. Draws it if anyone can see it, and otherwise leaves a
	 * note to draw it when they next can.
	 */
	final void refresh()
	{
		if (showing)
		{
			stale = false;
			redraw();
			return;
		}
		stale = true;
	}
}

package com.flippingrs;

/**
 * One incremental fill on one Grand Exchange slot, as sent to FlippingRS.
 *
 * <p>This is deliberately a report of what the exchange did, not a flip. The
 * plugin never decides which purchase a sale belongs to, what a flip earned, or
 * what tax was due; the server does all of that from these rows. Keeping the
 * judgement on the server means matching can be fixed and replayed over the
 * history, rather than being frozen inside whichever plugin version a user
 * happens to have installed.
 *
 * <p>Field names are the JSON wire format. Gson serialises this directly.
 */
public class GeTransaction
{
	/**
	 * Idempotency key, minted here before the fill is first sent and never
	 * changed. The server drops a repeat, which is what makes the retry queue
	 * safe: a request whose response went missing can be sent again without
	 * doubling the user's recorded profit.
	 */
	String id;

	String offerRef;

	int itemId;
	String itemName;
	/** "buy" or "sell". */
	String side;

	long quantity;
	/**
	 * The exact gp that moved for {@link #quantity} items, from the client's
	 * running total rather than price times quantity. A buy fills at or under
	 * the listed price and a part-filled offer mixes prices, so the listed price
	 * is what was asked for and this is what happened.
	 */
	long grossValue;
	long offerPrice;
	long offerTotal;

	/** The offer reached a terminal state with this fill; no more is coming. */
	boolean completed;
	boolean cancelled;
	/**
	 * grossValue had to be reconstructed as price times quantity because the
	 * client's running total was unusable. Sent so a suspect figure can be found
	 * later rather than quietly blending into someone's profit.
	 */
	boolean estimated;

	int slot;
	int world;

	/**
	 * ISO-8601 UTC, e.g. 2026-08-31T16:10:12.482Z. Null when the fill was not
	 * watched happening -- see {@link #source} -- because a time nobody
	 * observed is not something to make up.
	 */
	String occurredAt;

	/** A fill the plugin watched happen, and timed. */
	static final String SOURCE_LIVE = "live";
	/**
	 * A fill that had already happened when the plugin first saw the offer:
	 * the progress it found on an offer it has no baseline for. Real, but
	 * untimed, and possibly already in the journal from elsewhere, which is
	 * the server's to decide.
	 */
	static final String SOURCE_ADOPTED = "adopted";

	/** One of the SOURCE_ constants. The server treats absent as live. */
	String source = SOURCE_LIVE;

	@Override
	public String toString()
	{
		return side + " " + quantity + " x " + itemName + " for " + grossValue + "gp";
	}
}

