package com.flippingrs;

import java.util.function.IntConsumer;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * The site's prices on the end of an item's examine line.
 *
 * <p>Examine is the question the game already has for "what is this", and it
 * is asked from the inventory, the bank and the ground -- places the exchange
 * never sees. Answering it with what the item is worth costs no new gesture
 * and no new screen.
 *
 * <p>The examine text says nothing about which item it is for, so the item is
 * taken from the click that asked. The two arrive in the same tick, in that
 * order, which is what makes pairing them safe; a click whose message never
 * came is forgotten on the next one rather than kept to be paired with
 * somebody else's.
 *
 * <p>Which click that is, is not obvious. Examining an item in the inventory,
 * the bank or the exchange is not {@code EXAMINE_ITEM} -- it is a plain
 * interface op, {@code CC_OP_LOW_PRIORITY}, told apart from every other op on
 * that widget by its name. And the item it was on is not on the event either:
 * it has to be read off the widget the op names. Only an item lying on the
 * ground carries its own id. This is the same pair of cases RuneLite's own
 * Examine plugin handles, and for the same reason -- there is no third way to
 * ask.
 *
 * <p>Client thread. The lookup is a cache read; an item nobody has priced yet
 * is asked about and answered on the next examine rather than kept waiting
 * for, because a price arriving in the chat box seconds after the line it
 * belongs to is a line about nothing in particular.
 */
@Slf4j
class ExaminePrices
{
	/** The name of the op, which is the only thing that marks it as an examine. */
	private static final String EXAMINE = "Examine";

	/** Colours for the added text, written as the game reads them. */
	private static final String MUTED = "9f9f9f";
	private static final String VALUE = "ffffff";
	private static final String GOOD = "4caf50";
	private static final String BAD = "d32f2f";
	private static final String NAME = "ff981f";

	private final Client client;
	private final FlippingRsConfig config;
	private final ChatMessageManager chat;
	private final IntFunction<Quote> quoteFor;
	/** Asks for a price for an item nobody has one for yet. */
	private final IntConsumer wanted;
	/** Resolves an item's name, for a price that arrives after its line. */
	private final IntFunction<String> itemName;

	/** The item the last examine was asked about, or -1. */
	private int examined = -1;

	ExaminePrices(Client client, FlippingRsConfig config, ChatMessageManager chat,
		IntFunction<Quote> quoteFor, IntConsumer wanted, IntFunction<String> itemName)
	{
		this.client = client;
		this.config = config;
		this.chat = chat;
		this.quoteFor = quoteFor;
		this.wanted = wanted;
		this.itemName = itemName;
	}

	/**
	 * Notes which item an examine was asked about.
	 *
	 * <p>Anything that is not an examine clears it, so a stale id can never be
	 * paired with the next examine message that happens along.
	 */
	void clicked(MenuOptionClicked event)
	{
		examined = itemFor(event, client::getWidget);
	}

	/**
	 * The item an examine click was on, or -1 if the click was not one.
	 *
	 * <p>Takes the widget lookup rather than reaching for it, so the two ways
	 * an examine arrives can be told apart without a client running. Getting
	 * this wrong is silent: the click is simply never matched, and the examine
	 * line comes out exactly as the game wrote it.
	 *
	 * @param widgets resolves a component id, i.e. {@code Client::getWidget}
	 */
	static int itemFor(MenuOptionClicked event, IntFunction<Widget> widgets)
	{
		// The op's name is what separates an examine from every other thing
		// that can be done to an item in an interface. There is no menu action
		// of its own for it.
		if (!EXAMINE.equals(event.getMenuOption()))
		{
			return -1;
		}
		final MenuAction action = event.getMenuAction();
		if (action == MenuAction.EXAMINE_ITEM_GROUND)
		{
			// The only case where the event carries the item itself.
			return event.getId();
		}
		if (action != MenuAction.CC_OP && action != MenuAction.CC_OP_LOW_PRIORITY)
		{
			return -1;
		}
		// An op on an interface: the widget it was on, and the slot within it.
		final Widget widget = widgets.apply(event.getParam1());
		if (widget == null)
		{
			return -1;
		}
		final int slot = event.getParam0();
		if (slot >= 0)
		{
			final Widget item = widget.getChild(slot);
			if (item != null && item.getItemId() > 0)
			{
				return item.getItemId();
			}
		}
		// A widget that is one item rather than a grid of them.
		return widget.getItemId() > 0 ? widget.getItemId() : -1;
	}

	/**
	 * Puts the prices on the end of the examine line.
	 *
	 * <p>On the end of it, rather than as a line of its own: examine is one
	 * line today and two would be twice the chat for the same question.
	 *
	 * <p>Never throws. It runs from the event bus on the game thread, where an
	 * exception becomes an uncaught plugin error on every examine.
	 */
	void examined(ChatMessage event)
	{
		try
		{
			if (event.getType() != ChatMessageType.ITEM_EXAMINE || !config.examinePrices())
			{
				return;
			}
			final int itemId = examined;
			// One message per click. Without this, any later examine message
			// the client produced -- an object, another item -- would be given
			// the last item's prices.
			examined = -1;
			if (itemId <= 0)
			{
				return;
			}
			final Quote quote = quoteFor.apply(itemId);
			if (quote == null)
			{
				// Nobody has asked the site about this item yet. Ask now; the
				// answer follows as its own line, naming the item, rather than
				// this examine going unanswered.
				wanted.accept(itemId);
				return;
			}
			final MessageNode node = event.getMessageNode();
			if (node == null)
			{
				return;
			}
			// Straight into the value, with the colours already in it. The
			// format message is not the way: ChatMessageManager.update is a
			// no-op in this client, and what it would have resolved --
			// RuneLite's <colNORMAL> tokens -- is only resolved for message
			// types it has a configured colour for. An item examine is not one
			// of them, so the tokens arrived on screen as their own text.
			node.setValue(node.getValue() + suffix(quote));
			client.refreshChat();
		}
		catch (RuntimeException e)
		{
			log.debug("could not put prices on an examine line", e);
		}
	}

	/**
	 * What gets added to the line: the two prices, the margin, and the day's
	 * volume when the site has it.
	 *
	 * <p>Coloured with the colour itself rather than with RuneLite's
	 * {@code <colNORMAL>} tokens. Those are only turned into colours for the
	 * message types RuneLite has a colour configured for, and an item examine
	 * is not one of them -- so the tokens went to the chat box as their own
	 * text. A literal colour tag is what the game's text renderer reads, and
	 * it needs nothing to have substituted anything first.
	 *
	 * <p>Static and returning the built string, so the wording is pinned by a
	 * test rather than by running a client.
	 */
	static String suffix(Quote quote)
	{
		final StringBuilder out = new StringBuilder();
		out.append(colour(" Buy ", MUTED)).append(colour(FlippingRsPanel.exact(quote.getBuyAt()), VALUE))
			.append(colour(" · Sell ", MUTED)).append(colour(FlippingRsPanel.exact(quote.getSellAt()), VALUE))
			.append(colour(" · Margin ", MUTED))
			.append(colour(FlippingRsPanel.signedExact(quote.getNetMargin()),
				quote.getNetMargin() >= 0 ? GOOD : BAD));
		// Examine is asked from a bank or off the ground, away from the
		// exchange and from anything else that would say whether the item
		// moves at all. It is the place this number is least likely to be
		// known already.
		final String traded = FlippingRsPanel.volume(quote);
		if (traded != null)
		{
			out.append(colour(" · Volume ", MUTED)).append(colour(traded, VALUE));
		}
		return out.toString();
	}

	/** One run of text in one colour, as the game's own text renderer reads it. */
	static String colour(String text, String hex)
	{
		return "<col=" + hex + ">" + text + "</col>";
	}

	/**
	 * A price that arrived after the line it belonged to.
	 *
	 * <p>The first examine of an item nobody has asked the site about cannot
	 * be answered on the spot: there is nothing to answer with until a request
	 * comes back. Saying nothing at all was the first attempt at that and it
	 * reads exactly like a broken feature -- you examine a thing, and the
	 * plugin you installed to price things says nothing.
	 *
	 * <p>So the answer follows a moment later, as its own line, naming the
	 * item. Naming it is what makes a late line readable rather than a price
	 * floating free of anything: by the time it lands the examine text may
	 * have a couple of lines above it.
	 */
	void priced(int itemId)
	{
		try
		{
			if (!config.examinePrices())
			{
				return;
			}
			final Quote quote = quoteFor.apply(itemId);
			if (quote == null)
			{
				return;
			}
			// value, not runeLiteFormattedMessage, for the same reason: the
			// colours are already in the string and nothing has to substitute
			// a token to make them appear.
			chat.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.value(colour(itemName.apply(itemId), NAME) + suffix(quote))
				.build());
		}
		catch (RuntimeException e)
		{
			log.debug("could not say what an examined item is worth", e);
		}
	}

	/** The item the next examine message will be answered for, for a test. */
	int examinedForTest()
	{
		return examined;
	}
}

package com.flippingrs;

import com.google.gson.JsonElement;
import java.util.List;

/** What the server did with a batch, so the panel can say something true. */
public class IngestResult
{
	int accepted;
	int duplicate;
	int rejected;
	int flipsOpened;
	int flipsClosed;
	long unmatchedSellQty;
	/**
	 * Held as raw JSON rather than as strings. If the server ever sends
	 * structured problems, a List&lt;String&gt; here would fail to parse a
	 * response for a batch that was in fact accepted, and the batch would
	 * be re-sent every tick with the queue wedged behind it.
	 */
	List<JsonElement> problems;

	public int getFlipsOpened()
	{
		return flipsOpened;
	}

	public int getFlipsClosed()
	{
		return flipsClosed;
	}

	public long getUnmatchedSellQty()
	{
		return unmatchedSellQty;
	}

	/**
	 * Fills the server recorded nothing for. They are gone: the batch is
	 * confirmed and dropped from the queue either way, so this is the only
	 * chance anyone has to learn a trade did not make it.
	 */
	public int getRejected()
	{
		return rejected;
	}

	/** Why, one line per refused row. Never null. */
	public List<String> getProblems()
	{
		return Wire.problemsOf(problems);
	}

	/** Rows the server accounted for, one way or another. */
	int acknowledged()
	{
		return accepted + duplicate + rejected;
	}
}

package com.flippingrs;

import java.util.List;

/**
 * The lots that are finished, and what they came to.
 *
 * <p>However many the server chose to send. This is a sidebar, so it is the
 * most recent handful rather than the whole journal -- the site's own Journal
 * page is where somebody goes to read all of it, and paging a full history
 * through a panel this size would spend the rate limit on scrolling.
 */
public class ClosedPositions
{
	List<ClosedPosition> positions;
	Summary summary;

	/**
	 * The totals for what was sent, not for all time.
	 *
	 * <p>Separate from the week's figures on the Analytics tab, which are a
	 * seven-day window whatever was traded in it. These describe exactly the
	 * cards underneath them, which is the only reading that cannot mislead
	 * somebody who counts them.
	 */
	public static class Summary
	{
		int closedPositions;
		long realisedProfit;
		long taxPaid;

		public int getClosedPositions()
		{
			return closedPositions;
		}

		public long getRealisedProfit()
		{
			return realisedProfit;
		}

		public long getTaxPaid()
		{
			return taxPaid;
		}
	}

	/** Never null. */
	public List<ClosedPosition> getPositions()
	{
		return Wire.withoutNulls(positions);
	}

	/** Never null. */
	public Summary getSummary()
	{
		return summary == null ? new Summary() : summary;
	}
}

package com.flippingrs;

/** The key's owner, as much as the Account tab shows. */
public class Me
{
	String displayName;
	String effectiveTier;
	boolean onTrial;
	int trialDaysLeft;

	/** "Pro plan", "Pro trial, 5 days left", "Free plan". */
	public String describePlan()
	{
		final String tier = effectiveTier == null || effectiveTier.isEmpty() ? "unknown" : effectiveTier;
		final String name = Character.toUpperCase(tier.charAt(0)) + tier.substring(1);
		if (onTrial)
		{
			return name + " trial, " + trialDaysLeft + (trialDaysLeft == 1 ? " day left" : " days left");
		}
		return name + " plan";
	}
}

package com.flippingrs;

// The panel's shared vocabulary: the layout helpers every tab builds
// rows out of, and the static text of a row, which the tests pin there.
import static com.flippingrs.FlippingRsPanel.*;

import java.awt.Component;
import java.awt.Dimension;
import javax.swing.Box;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import java.awt.Color;
import java.util.List;
import javax.annotation.Nullable;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;

/**
 * The Account tab: whether the plugin is connected, the plan the key's
 * owner is on, and which journal this character files under.
 *
 * <p>The only tab with no list on it, and so the only one with nothing to
 * defer: its handful of labels are written straight through.
 */
final class AccountTab extends SidebarTab
{
	private final JLabel status = new JLabel();
	private final JLabel subscription = new JLabel();
	private final JComboBox<GameAccount> accounts = new JComboBox<>();
	private final JButton reconnect = new JButton("Reconnect");
	private final JPanel body;
	private final PanelActions actions;

	/**
	 * Set while the picker's model is being replaced.
	 *
	 * <p>Repopulating a combo box fires a selection event, and letting that
	 * through would look like the user re-picking the journal and write the
	 * setting back on every reconnect.
	 */
	private boolean repopulating;

	AccountTab(PanelActions actions)
	{
		this.actions = actions;
		final JPanel body = column();
		body.add(hint("Your connection to flippingrs.com, and which journal this character's trades go into."));
		body.add(header("Connection"));
		body.add(Box.createVerticalStrut(4));
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(status);
		body.add(Box.createVerticalStrut(4));
		subscription.setFont(FontManager.getRunescapeSmallFont());
		subscription.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		subscription.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(subscription);
		body.add(Box.createVerticalStrut(10));

		body.add(header("Journal"));
		body.add(Box.createVerticalStrut(4));
		accounts.setAlignmentX(Component.LEFT_ALIGNMENT);
		accounts.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		accounts.setToolTipText("Which journal this character's trades go into. Each character remembers its own "
			+ "choice, so an alt can have its own journal.");
		accounts.addActionListener(e -> {
			if (!repopulating)
			{
				actions.accountChosen();
			}
		});
		body.add(accounts);
		body.add(Box.createVerticalStrut(10));

		reconnect.addActionListener(e -> actions.reconnect());
		reconnect.setToolTipText("Check your API key again and reload everything from flippingrs.com.");
		reconnect.setAlignmentX(Component.LEFT_ALIGNMENT);
		reconnect.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		body.add(reconnect);
		// The freshness line last, under everything it qualifies. Empty until
		// the first read, so it takes no room on a tab that has nothing yet.
		body.add(Box.createVerticalStrut(8));
		body.add(refreshLine());
		this.body = body;
	}

	@Override
	JPanel body()
	{
		return body;
	}

	/** The connection status, on the Account tab. */
	void setStatus(String text, Color colour)
	{
		setWrappedText(status, text);
		status.setForeground(colour);
	}

	/** The plan the key's owner is on, in the server's words, or null if not known. */
	void setSubscription(@Nullable String text)
	{
		setWrappedText(subscription, text == null ? "Plan: not checked yet" : text);
	}

	/**
	 * Replaces the account list, restoring the current selection if it survives.
	 *
	 * <p>With nothing remembered ({@code selectedId} null) the server's default
	 * is selected, or failing that the first entry, so a fresh account has
	 * something sensible to adopt. With something remembered that is no longer
	 * in the list, nothing is selected: showing the first entry there would
	 * have the panel naming a journal the plugin is not filing under.
	 *
	 * <p>The selection listener is muted while the model is swapped:
	 * repopulating a combo box fires a selection event, and letting that
	 * through would look like the user re-picking the account and write the
	 * setting back on every reconnect.
	 */
	/**
	 * Read once, when the plugin connects, and again when the key or the
	 * chosen journal changes. Nothing about a plan or a list of journals goes
	 * stale on its own, so nothing re-reads it on a clock.
	 */
	@Override
	String refreshedBy()
	{
		return "on connect";
	}

	@Override
	long refreshEverySeconds()
	{
		return PanelReads.panelRefreshSeconds();
	}

	void setAccounts(List<GameAccount> available, @Nullable String selectedId)
	{
		stamp();
		repopulating = true;
		try
		{
			final DefaultComboBoxModel<GameAccount> model = new DefaultComboBoxModel<>();
			GameAccount remembered = null;
			GameAccount fallback = null;
			for (GameAccount account : available)
			{
				if (account == null || account.id == null)
				{
					continue;
				}
				model.addElement(account);
				if (account.id.equals(selectedId))
				{
					remembered = account;
				}
				if (fallback == null && account.isDefault)
				{
					fallback = account;
				}
			}
			accounts.setModel(model);
			if (remembered != null)
			{
				accounts.setSelectedItem(remembered);
			}
			else if (selectedId != null)
			{
				// Remembered, but gone. The default is not a stand-in for it.
				accounts.setSelectedIndex(-1);
			}
			else if (fallback != null)
			{
				accounts.setSelectedItem(fallback);
			}
			// Otherwise the model has already selected the first entry.
			accounts.setEnabled(model.getSize() > 0);
		}
		finally
		{
			repopulating = false;
		}
	}

	@Nullable
	String selectedAccountId()
	{
		final Object selected = accounts.getSelectedItem();
		return selected == null ? null : ((GameAccount) selected).id;
	}

	// ---------------------------------------------------------- test seams

	String statusTextForTest()
	{
		return status.getText();
	}

	String subscriptionTextForTest()
	{
		return subscription.getText();
	}

	/** Selects by id the way a user clicking the combo box would. */
	void setSelectedForTest(String id)
	{
		for (int i = 0; i < accounts.getItemCount(); i++)
		{
			if (accounts.getItemAt(i).id.equals(id))
			{
				accounts.setSelectedIndex(i);
				return;
			}
		}
		throw new IllegalArgumentException("no such account in the list: " + id);
	}
}

package com.flippingrs;

import java.util.ArrayList;
import java.util.List;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;

/**
 * The site's prices inside the exchange's own hover box.
 *
 * <p>The exchange already puts a yellow box under the pointer saying what the
 * thing you are pointing at is. It is the one thing on screen that is about a
 * single item, it appears exactly when somebody wants to know about that item,
 * and it costs no room and no attention until then. So the prices go in it
 * rather than in a second box beside it: two tooltips for one pointer is one
 * too many, and the game's is the one that was already right.
 *
 * <p>Which item it is describing does not come from the box -- it says nothing
 * about that -- but from what the pointer is over, which {@link GeItems}
 * already answers for every screen the exchange has. The two agree because the
 * box is only up while the pointer is on the thing it belongs to.
 *
 * <p>The box does have to be made bigger, which is the one thing this plugin
 * has learned to be careful about. It is a far easier case than the offer
 * boxes that taught the lesson: a tooltip floats, so nothing above it has to
 * be grown to match and nothing below it gets pushed anywhere. What is still
 * true is that a size must never be read back after it has been changed, or
 * the box grows from its own growth -- so the client's own dimensions are
 * taken once, when it builds the box, and every write after is computed from
 * those.
 *
 * <p>Client thread only.
 */
@Slf4j
class GeTooltip
{
	/**
	 * The exchange's hover boxes, one per screen that has one. A screen that
	 * gains one is a constant added here rather than a class.
	 */
	private static final int[] TOOLTIPS = {
		InterfaceID.GeOffers.TOOLTIP,
		InterfaceID.GeCollect.TOOLTIP,
		InterfaceID.GeViewonly.TOOLTIP,
	};

	private final Client client;
	private final FlippingRsConfig config;
	private final IntFunction<Quote> quoteFor;

	/** What has been added to whichever box is up. */
	private final Appended line = new Appended();

	/** The room made for it, and how to give it back. */
	private final Grown box = new Grown();

	GeTooltip(Client client, FlippingRsConfig config, IntFunction<Quote> quoteFor)
	{
		this.client = client;
		this.config = config;
		this.quoteFor = quoteFor;
	}

	/**
	 * Brings the addition in line with what the pointer is over.
	 *
	 * <p>Never throws. It runs from the event bus on the game thread, where an
	 * exception becomes an uncaught plugin error on every frame.
	 */
	void update()
	{
		try
		{
			final Widget tip = config.setupOverlay() ? shownTooltip() : null;
			final Widget text = tip == null ? null : textIn(tip);
			if (text == null)
			{
				reset();
				return;
			}
			final Point mouse = client.getMouseCanvasPosition();
			final int itemId = GeItems.under(client, mouse);
			final Quote quote = itemId > 0 ? quoteFor.apply(itemId) : null;
			if (quote == null)
			{
				// Nothing is added for an item with no price, which is every
				// item until the first fetch lands. The game's box is left
				// exactly as it was rather than made taller and left empty.
				reset();
				return;
			}
			// In the colour the box already writes in, read off the line being
			// added to rather than assumed. The exchange's hover box is dark
			// text on pale yellow and the sidebar's palette is built for the
			// opposite, so the plugin's own colours came out washed out on it
			// -- and white, which was most of them, came out invisible.
			final String extra = textFor(quote, offerOn(itemId), text.getTextColor());
			line.to(text, "<br>" + extra);
			box.fit(tip, text, extra);
		}
		catch (RuntimeException e)
		{
			log.debug("could not put prices in the exchange's hover box", e);
		}
	}

	/** Puts the box back the way the game had it. */
	void reset()
	{
		// The text first: the box is sized to hold it, so giving the size back
		// while the addition is still in it would clip what is there.
		line.clear();
		box.restore();
	}

	/**
	 * The hover box that is up, or null if none is.
	 *
	 * <p>Hidden is the usual state. The exchange builds these once and shows
	 * and hides them as the pointer moves, so an id that resolves is not by
	 * itself a box on screen.
	 */
	@Nullable
	private Widget shownTooltip()
	{
		for (int id : TOOLTIPS)
		{
			final Widget tooltip = client.getWidget(id);
			if (tooltip != null && !tooltip.isHidden())
			{
				return tooltip;
			}
		}
		return null;
	}

	/**
	 * The line of a hover box to add to: the lowest text in it.
	 *
	 * <p>A box is a fill, a border and its text somewhere inside, and which
	 * child carries the text is the interface's business rather than something
	 * worth knowing here.
	 */
	@Nullable
	private static Widget textIn(Widget tooltip)
	{
		if (RowText.isText(tooltip))
		{
			return tooltip;
		}
		return RowText.lastIn(RowText.under(tooltip), Integer.MIN_VALUE, Integer.MAX_VALUE);
	}

	/**
	 * Your own offer on an item, if one of the eight slots has it.
	 *
	 * <p>Only the slots carry one, and only they can say how far your price is
	 * from the market. Everywhere else in the exchange the same item is just
	 * an item.
	 */
	@Nullable
	private GrandExchangeOffer offerOn(int itemId)
	{
		for (GeItems.Spot spot : GeItems.onScreen(client))
		{
			if (spot.offer != null && spot.itemId == itemId)
			{
				return spot.offer;
			}
		}
		return null;
	}

	/**
	 * What the box gains: the two prices, the margin, and -- when the item is
	 * one you have an offer on -- how far your price is from the side you are
	 * trading, then the buy limit, the day's volume and how old the prices
	 * are.
	 *
	 * <p>A line each rather than one line of everything, because a price and
	 * its label stop fitting together the moment the price is long: a hundred
	 * million buying and a hundred and ten million selling is most of a line
	 * before anything else is said. A hover box is as tall as it is made, so
	 * the prices are exact to the coin -- these are numbers somebody is about
	 * to type.
	 *
	 * <p>The item's name is not repeated: the game's box already leads with
	 * it, and this goes underneath.
	 *
	 * <p>Written in the box's own colour rather than the plugin's. The sidebar
	 * is pale text on a dark panel and the exchange's hover box is the exact
	 * opposite, so the palette that reads well in one is unreadable in the
	 * other -- the sidebar's white came out as nothing at all on the yellow.
	 * Taking the colour off the line being added to makes the addition look
	 * like part of what was already there, and goes on doing so if Jagex
	 * recolours the box.
	 *
	 * <p>The two signed numbers keep colours of their own, because what they
	 * say is whether something is good or bad rather than what it is. Dark
	 * shades, chosen against the pale box rather than against the panel.
	 *
	 * <p>Static, so the wording is pinned by a test rather than by running a
	 * client.
	 *
	 * @param textColour the colour the box writes in, as {@code getTextColor}
	 *                   gives it
	 */
	static String textFor(Quote quote, @Nullable GrandExchangeOffer offer, int textColour)
	{
		final String own = colour(textColour);
		final StringBuilder out = new StringBuilder();
		out.append(own).append("Buy ").append(FlippingRsPanel.exact(quote.getBuyAt())).append("<br>")
			.append(own).append("Sell ").append(FlippingRsPanel.exact(quote.getSellAt())).append("<br>")
			.append(own).append("Margin ")
			.append(quote.getNetMargin() >= 0 ? ColourText.GOOD : ColourText.BAD)
			.append(FlippingRsPanel.signedExact(quote.getNetMargin()));

		final Long edge = GeSlotText.edgeOf(offer, quote);
		if (edge != null)
		{
			// The price you actually asked for, then how it compares with the
			// line above it. Both, because the comparison is the answer and
			// the price is what makes the comparison checkable -- and because
			// the exchange shows a slot's total rather than its price each.
			out.append("<br>").append(own).append("Yours ")
				.append(FlippingRsPanel.exact(offer.getPrice())).append(" ")
				.append(edge >= 0 ? ColourText.GOOD : ColourText.BAD)
				.append("(").append(GeSlotText.gapFrom(offer, quote)).append(")");
		}
		if (quote.hasLimitLeft())
		{
			out.append("<br>").append(own).append("Limit ").append(GeOfferText.limitLeft(quote));
		}
		// How much of it moves in a day, which is what says whether a margin
		// is one anybody can take. A wide spread on an item that trades twice
		// a day is not an opportunity; it is the reason the spread is wide.
		final String traded = FlippingRsPanel.volume(quote);
		if (traded != null)
		{
			out.append("<br>").append(own).append("Volume ").append(traded);
		}
		final String age = GeOfferText.age(quote.getDataAgeSeconds());
		if (age != null)
		{
			out.append("<br>").append(own).append("Priced ").append(age);
		}
		return out.toString();
	}

	/** One colour, written as the game's own text renderer reads it. */
	static String colour(int rgb)
	{
		return String.format("<col=%06x>", rgb & 0xffffff);
	}

	/**
	 * The two colours that are a judgement rather than a value.
	 *
	 * <p>Dark, because they go on the exchange's pale yellow box. The
	 * sidebar's greens and reds are lit for a dark panel and turn to pastel on
	 * this one, which is a poor way to say "your offer will sit all evening".
	 */
	static final class ColourText
	{
		static final String GOOD = "<col=0b6b1f>";
		static final String BAD = "<col=9b1c1c>";

		private ColourText()
		{
		}
	}

	/**
	 * A hover box made big enough for what was put in it.
	 *
	 * <p>The box, and whatever inside it is the size of the box: the yellow
	 * fill and the border round it.
	 *
	 * <p>Those two are the whole difficulty, and getting them wrong is what
	 * made the box briefly transparent. A child that is the size of its parent
	 * is usually not told to be that size -- it is told to be the parent's
	 * size minus nothing, which is a mode rather than a number, and its own
	 * declared width is zero. Sizing it from that zero makes it vanish. So a
	 * child is measured as the client laid it out, and only the dimensions it
	 * actually states for itself are restated; the ones it expresses in terms
	 * of its parent are left alone, because those already follow.
	 *
	 * <p>Every dimension is taken from the client's, once, when the client
	 * builds the box. A size read back after this has changed it is this
	 * plugin's arithmetic being fed its own output, which is how an earlier
	 * attempt at resizing the offer boxes grew a little more on every frame.
	 * What was written last is remembered, so the client rebuilding the box
	 * can be told from the box as this left it.
	 */
	static final class Grown
	{
		/** As wide as a hover box will be taken, so a bad measure cannot fill the screen. */
		private static final int MAX_WIDTH = 400;

		/** Room inside the border, so the longest line does not sit on it. */
		private static final int PAD = 10;

		/** One row of the font the exchange writes these in. */
		private static final int LINE = 14;

		/** Where each of a span's remembered numbers is kept. */
		private static final int WIDTH = 0;
		private static final int HEIGHT = 1;
		private static final int WIDTH_MODE = 2;
		private static final int HEIGHT_MODE = 3;
		private static final int LAID_WIDTH = 4;
		private static final int LAID_HEIGHT = 5;

		@Nullable
		private Widget widget;

		/** The box as the client built it, read before anything was written to it. */
		private int baseWidth = -1;
		private int baseHeight;
		private int baseWidthMode;
		private int baseHeightMode;

		/**
		 * And as the client laid it out, which is what a child's own size can
		 * be compared against. The two differ whenever a size is a mode rather
		 * than a number.
		 */
		private int laidWidth;
		private int laidHeight;

		/** What was written last, so a rebuild by the client can be told from it. */
		private int wroteWidth = -1;
		private int wroteHeight = -1;

		/** The children that are the size of the box, and how they were. */
		private final List<Widget> spans = new ArrayList<>();
		private final List<int[]> spansWere = new ArrayList<>();

		/**
		 * Makes the box hold {@code extra} as well as what the game put in it.
		 *
		 * <p>Safe to call every frame with the same arguments: a size is only
		 * written when it would differ from what is already there.
		 */
		void fit(Widget tooltip, Widget text, String extra)
		{
			if (tooltip != widget
				|| tooltip.getOriginalWidth() != wroteWidth
				|| tooltip.getOriginalHeight() != wroteHeight)
			{
				// A different box, or the same one rebuilt. Either way what is
				// there now is the client's, and this is the last moment it
				// can be read before being written over.
				forget();
				widget = tooltip;
				baseWidth = tooltip.getOriginalWidth();
				baseHeight = tooltip.getOriginalHeight();
				baseWidthMode = tooltip.getWidthMode();
				baseHeightMode = tooltip.getHeightMode();
				laidWidth = tooltip.getWidth();
				laidHeight = tooltip.getHeight();
				takeSpans(tooltip);
			}
			final int rows = 1 + rowsIn(extra);
			final int width = Math.min(MAX_WIDTH,
				Math.max(baseWidth, widest(text, extra) + PAD));
			final int height = baseHeight + rows * LINE;
			if (width == wroteWidth && height == wroteHeight)
			{
				return;
			}
			resize(tooltip, width, height);
			for (int i = 0; i < spans.size(); i++)
			{
				follow(spans.get(i), spansWere.get(i), width, height);
			}
			tooltip.revalidate();
			wroteWidth = width;
			wroteHeight = height;
		}

		/** Puts the box back the way the game had it, and forgets it. */
		void restore()
		{
			if (widget != null && baseWidth >= 0
				&& widget.getOriginalWidth() == wroteWidth
				&& widget.getOriginalHeight() == wroteHeight)
			{
				// Only if it is still as this left it. A box the client has
				// since rebuilt is already the game's, and writing an old size
				// into it would size it for an item that is no longer there.
				widget.setWidthMode(baseWidthMode);
				widget.setHeightMode(baseHeightMode);
				widget.setOriginalWidth(baseWidth);
				widget.setOriginalHeight(baseHeight);
				for (int i = 0; i < spans.size(); i++)
				{
					final Widget span = spans.get(i);
					final int[] was = spansWere.get(i);
					// Only the numbers this restated. A mode was never
					// touched, so there is nothing there to put back.
					span.setOriginalWidth(was[WIDTH]);
					span.setOriginalHeight(was[HEIGHT]);
					span.revalidate();
				}
				widget.revalidate();
			}
			forget();
		}

		private void forget()
		{
			widget = null;
			baseWidth = -1;
			wroteWidth = -1;
			wroteHeight = -1;
			spans.clear();
			spansWere.clear();
		}

		/**
		 * The children that are the size of the box: its fill and its border.
		 *
		 * <p>Found by measurement rather than by index, because which child is
		 * which is the interface's business and changes when Jagex rebuilds
		 * it. Anything appreciably smaller than the box is a piece of its
		 * contents and is left exactly where it is.
		 */
		private void takeSpans(Widget tooltip)
		{
			for (Widget child : RowText.under(tooltip))
			{
				if (child == null || RowText.isText(child))
				{
					continue;
				}
				if (child.getWidth() < laidWidth - PAD || child.getHeight() < laidHeight - PAD)
				{
					continue;
				}
				spans.add(child);
				spansWere.add(new int[]{
					child.getOriginalWidth(), child.getOriginalHeight(),
					child.getWidthMode(), child.getHeightMode(),
					child.getWidth(), child.getHeight(),
				});
			}
		}

		/**
		 * Takes one of the box's own children with it.
		 *
		 * <p>Only the dimensions the child states as numbers. A dimension it
		 * expresses in terms of its parent already follows the box, and
		 * restating that as a number is exactly the mistake that made the
		 * yellow fill zero pixels wide.
		 *
		 * <p>What it does restate keeps whatever inset the child had from the
		 * box's edges, measured as the client laid the two of them out, which
		 * is how a border a pixel outside a fill stays a pixel outside it
		 * however far the box is taken.
		 */
		private void follow(Widget span, int[] was, int width, int height)
		{
			if (was[WIDTH_MODE] == WidgetSizeMode.ABSOLUTE)
			{
				span.setOriginalWidth(width - (laidWidth - was[LAID_WIDTH]));
			}
			if (was[HEIGHT_MODE] == WidgetSizeMode.ABSOLUTE)
			{
				span.setOriginalHeight(height - (laidHeight - was[LAID_HEIGHT]));
			}
			span.revalidate();
		}

		/**
		 * Sets the box's own size outright.
		 *
		 * <p>Absolute rather than whatever mode the client had, because a size
		 * expressed relative to a parent is not a size this can set. The mode
		 * is put back with the dimension when the box is given up.
		 */
		private static void resize(Widget widget, int width, int height)
		{
			widget.setWidthMode(WidgetSizeMode.ABSOLUTE);
			widget.setHeightMode(WidgetSizeMode.ABSOLUTE);
			widget.setOriginalWidth(width);
			widget.setOriginalHeight(height);
			widget.revalidate();
		}

		/** How many rows an addition takes, over and above its first. */
		static int rowsIn(String extra)
		{
			int rows = 0;
			for (int at = extra.indexOf("<br>"); at >= 0; at = extra.indexOf("<br>", at + 1))
			{
				rows++;
			}
			return rows;
		}

		/**
		 * How wide the widest line of an addition is drawn, in the font the
		 * box writes in.
		 *
		 * <p>Asked of the client's own font rather than guessed at, because
		 * the whole range is in play: "Sell 421" and "Sell 1,600,000,000" are
		 * the same line about two different items, and the box was built to
		 * fit neither.
		 */
		private static int widest(Widget text, String extra)
		{
			final FontTypeFace font = text.getFont();
			if (font == null)
			{
				return 0;
			}
			int widest = 0;
			for (String row : extra.split("<br>"))
			{
				widest = Math.max(widest, font.getTextWidth(plain(row)));
			}
			return widest;
		}

		/** A line without its colour tags, which are instructions rather than text. */
		static String plain(String row)
		{
			return row.replaceAll("<[^>]*>", "");
		}
	}
}

package com.flippingrs;

import java.time.Instant;
import java.util.UUID;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Turns the stream of Grand Exchange slot updates into discrete fills.
 *
 * <p>The client does not tell you "you just bought 25 whips". It tells you what
 * a slot looks like now, over and over, and the trade is the difference between
 * consecutive looks. Everything difficult about this plugin lives here:
 *
 * <ul>
 *   <li><b>Login replay.</b> On every login the client re-fires an event for
 *       each occupied slot, carrying the quantity already sold. Those are not
 *       new trades. The baseline is persisted across sessions so the difference
 *       comes out as zero.
 *   <li><b>Offers we never saw start.</b> Install the plugin mid-flip, or log in
 *       on a fresh machine, and a slot is already part filled with no baseline
 *       to subtract. That progress is <em>adopted</em> as the new baseline, and
 *       reported once as a fill marked {@code adopted} with no time: it is
 *       real, but nobody watched it happen, and it may already be in the
 *       journal from another machine. The server decides whether it is new.
 *       Dating it "now" would be worse than either, because a sale stamped
 *       after the purchase it belongs to turns a real flip into an unmatched
 *       sale.
 *   <li><b>Slot reuse.</b> A finished offer is collected and the slot re-used,
 *       possibly for an identical offer. {@link SavedOffer#isSameOfferAs} draws
 *       the line.
 *   <li><b>A running total that is an int.</b> See {@link #grossValue}.
 * </ul>
 *
 * <p>Deliberately stateless. The previous state of a slot is passed in and the
 * new state comes back out, because the only correct home for it is RuneLite's
 * per-RuneScape-account config, and reading that lazily at event time avoids
 * racing the login burst against a pre-load. It also means the whole of the
 * logic above is testable with no client and no game running.
 */
public class OfferTracker
{
	private final Supplier<String> refs;

	public OfferTracker()
	{
		this(() -> UUID.randomUUID().toString());
	}

	/** Test seam: lets a test pin the generated identifiers. */
	OfferTracker(Supplier<String> refs)
	{
		this.refs = refs;
	}

	/** What one observation of a slot means. */
	public static class Observation
	{
		/** The fill to report, or null when nothing traded. */
		@Nullable
		public final GeTransaction transaction;
		/** The state to persist for this slot, or null to forget the slot. */
		@Nullable
		public final SavedOffer saved;
		/** This offer was part-finished the first time we saw it. */
		public final boolean adopted;

		Observation(@Nullable GeTransaction transaction, @Nullable SavedOffer saved, boolean adopted)
		{
			this.transaction = transaction;
			this.saved = saved;
			this.adopted = adopted;
		}
	}

	/**
	 * Works out what changed in a slot.
	 *
	 * @param previous what was last persisted for this slot, or null if nothing
	 * @param itemName resolves the name, and is consulted only when there is
	 *                 actually a fill to report. Most events are a state change
	 *                 or a login replay, and looking the name up for those is
	 *                 work the game thread does not need to do.
	 * @param world    the world it happened on, for the audit trail
	 * @param now      when the observation was made
	 */
	public Observation observe(
		int slot,
		@Nullable SavedOffer previous,
		GrandExchangeOffer offer,
		Supplier<String> itemName,
		int world,
		Instant now)
	{
		final GrandExchangeOfferState state = offer.getState();

		if (state == GrandExchangeOfferState.EMPTY)
		{
			// The slot was collected and freed. Nothing traded in the act of
			// collecting -- the fills were reported as they happened -- so this
			// only clears the baseline, which is what lets the next offer in
			// this slot be recognised as a new one.
			return new Observation(null, null, false);
		}

		// A baseline with no reference is one written by a version that did not
		// have them, or a half-written config value. Treating it as the same
		// offer would send every later fill with an empty offerRef, and the
		// server groups fills into one purchase by exactly that field -- so an
		// entire buy would arrive as a string of unrelated one-item lots.
		// Re-adopting it instead costs the fills already seen and keeps the
		// rest correct.
		if (previous == null || previous.offerRef == null || previous.offerRef.isEmpty()
			|| !previous.isSameOfferAs(offer))
		{
			// First sight of this offer. Anything already filled happened while
			// we were not watching: it becomes the baseline, and goes out once
			// as a recovered fill with no time on it. A brand new offer has
			// nothing filled yet, and this is simply where it gets its
			// reference.
			final String ref = refs.get();
			final boolean adopted = offer.getQuantitySold() > 0;
			final SavedOffer saved = SavedOffer.of(offer, ref, adopted);
			if (!adopted)
			{
				return new Observation(null, saved, false);
			}
			final GeTransaction recovered = fill(slot, offer, ref, itemName, world,
				offer.getQuantitySold(), 0, null, GeTransaction.SOURCE_ADOPTED);
			return new Observation(recovered, saved, true);
		}

		final long filled = (long) offer.getQuantitySold() - previous.quantitySold;

		// The baseline advances even when nothing filled: a state change with no
		// progress -- BUYING to CANCELLED_BUY, say -- still has to be recorded,
		// or it is re-examined on every later event.
		final SavedOffer updated = SavedOffer.of(offer, previous.offerRef, previous.adopted);

		if (filled <= 0)
		{
			return new Observation(null, updated, false);
		}

		final GeTransaction tx = fill(slot, offer, previous.offerRef, itemName, world,
			filled, previous.spent, now.toString(), GeTransaction.SOURCE_LIVE);
		return new Observation(tx, updated, false);
	}

	/**
	 * One fill on an offer, whether watched or recovered.
	 *
	 * @param filled        how many items this fill covers
	 * @param previousSpent the running total before it, for the exact gp
	 * @param occurredAt    when, or null for a fill nobody watched
	 */
	private static GeTransaction fill(int slot, GrandExchangeOffer offer, String offerRef,
		Supplier<String> itemName, int world, long filled, int previousSpent,
		@Nullable String occurredAt, String source)
	{
		final GrandExchangeOfferState state = offer.getState();
		final boolean buy = SavedOffer.isBuy(state);

		final GeTransaction tx = new GeTransaction();
		tx.id = UUID.randomUUID().toString();
		tx.offerRef = offerRef;
		tx.itemId = offer.getItemId();
		tx.itemName = itemName.get();
		tx.side = buy ? "buy" : "sell";
		tx.quantity = filled;
		tx.offerPrice = offer.getPrice();
		tx.offerTotal = offer.getTotalQuantity();
		tx.slot = slot;
		tx.world = world;
		tx.occurredAt = occurredAt;
		tx.source = source;
		tx.completed = SavedOffer.isFinished(state);
		tx.cancelled = state == GrandExchangeOfferState.CANCELLED_BUY
			|| state == GrandExchangeOfferState.CANCELLED_SELL;

		final long[] value = grossValue(offer, previousSpent, filled, buy);
		tx.grossValue = value[0];
		tx.estimated = value[1] != 0;
		return tx;
	}

	/**
	 * The gp that moved in this fill, and whether it had to be estimated.
	 *
	 * <p>The client's running total is an {@code int}. The exchange caps what a
	 * single offer can move at max cash, which is also the largest int, so in
	 * practice the total cannot wrap -- but a figure that becomes somebody's
	 * profit is not something to leave to "in practice". Three defences:
	 *
	 * <ul>
	 *   <li>If price times quantity for this fill alone is more than an int can
	 *       hold, the total could not have tracked it and is not consulted.
	 *   <li>The difference is taken modulo 2^32, which is exact across a single
	 *       wrap rather than nonsense. (A signed subtraction was exact only when
	 *       the wrap happened to land negative; one that landed positive passed
	 *       the checks below as a plausible, wrong number.)
	 *   <li>The result is checked against rules the exchange guarantees: a buy
	 *       never fills above the offer, a sale never below the ask, and no
	 *       offer moves more than max cash.
	 * </ul>
	 *
	 * <p>Anything that fails falls back to price times quantity and is flagged,
	 * because a figure that is approximately right and known to be approximate
	 * is worth far more than one that is exactly wrong.
	 *
	 * @return {@code [grossValue, estimatedFlag]}
	 */
	private static long[] grossValue(GrandExchangeOffer offer, int previousSpent, long filled, boolean buy)
	{
		final long price = offer.getPrice();
		// Compare totals rather than a per-item average, so an offer that filled
		// at a mix of prices is not rejected by integer division.
		final long asked = filled * price;
		final long[] fallback = {asked, 1};

		if (asked > Integer.MAX_VALUE)
		{
			return fallback;
		}
		final long spent = Integer.toUnsignedLong(offer.getSpent() - previousSpent);
		if (spent == 0 || spent > Integer.MAX_VALUE)
		{
			return fallback;
		}
		final boolean plausible = buy ? spent <= asked : spent >= asked;
		return plausible ? new long[]{spent, 0} : fallback;
	}

}

package com.flippingrs;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup(FlippingRsConfig.GROUP)
public interface FlippingRsConfig extends Config
{
	String GROUP = "flippingrs";

	@ConfigSection(
		name = "Connection",
		description = "Linking the plugin to your flippingrs.com account",
		position = 0
	)
	String connectionSection = "connection";

	@ConfigItem(
		keyName = "apiKey",
		name = "API key",
		description = "Paste the key from flippingrs.com. On the site, go to Account, then API keys, and create one for the RuneLite plugin.",
		position = 1,
		secret = true,
		section = connectionSection
	)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(
		keyName = "enabled",
		name = "Record trades",
		description = "Sends your Grand Exchange trades to your flippingrs.com journal as they happen: the item, "
			+ "how many, the price, the slot and world, and when. It also sends your open offers and what your "
			+ "Grand Exchange history shows, so trades made while RuneLite was closed can be caught up. "
			+ "flippingrs.com is a third-party service not run or checked by the RuneLite team, and like any "
			+ "website it can see your IP address. Your character name is never sent. Switch this off and the "
			+ "plugin stops recording and stops talking to flippingrs.com altogether. Trades made while it is "
			+ "off are not recorded as they happen; anything already waiting is sent when you switch it back on. "
			+ "Once it is back on, the catch-up from your open offers and your Grand Exchange history can still "
			+ "add an offer that completed while it was off, saved without a time.",
		position = 2,
		section = connectionSection
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "syncSeconds",
		name = "Send every (seconds)",
		description = "How long to wait between sends. Your trades are grouped up and sent together, so busy flipping does not mean constant sending. Nothing is lost while it waits.",
		position = 3,
		section = connectionSection
	)
	@Range(min = 5, max = 600)
	default int syncSeconds()
	{
		return 30;
	}

	@ConfigSection(
		name = "Grand Exchange",
		description = "What the plugin adds inside the Grand Exchange",
		position = 10
	)
	String exchangeSection = "exchange";

	@ConfigItem(
		keyName = "geMenuEntries",
		name = "Right-click entries",
		description = "Adds \"View item\" and \"Add to watchlist\" when you right-click an item in the Grand "
			+ "Exchange: your offer slots, the items beside them, the offer setup screen and your history. "
			+ "\"View item\" opens the item on flippingrs.com in your browser. \"Add to watchlist\" puts it on "
			+ "the watchlist in the sidebar. Neither one touches the game.",
		position = 11,
		section = exchangeSection
	)
	default boolean geMenuEntries()
	{
		return true;
	}

	@ConfigItem(
		keyName = "setupOverlay",
		name = "Prices in the exchange",
		description = "Shows flippingrs.com's prices where you need them. On the offer setup screen and on a "
			+ "placed offer's status page: the exact buy "
			+ "and sell prices, the margin, how old the prices are, and how much of the buy limit you have left "
			+ "if your plan tracks that. And on any item the exchange shows, point at it and the game's own "
			+ "hover box gains the same, plus what you asked for and how it compares with the side you are "
			+ "trading if the item is one of yours -- \"Yours 436 (2 over sell)\". Nothing the exchange draws "
			+ "is replaced or moved. Works for "
			+ "any item, not only the ones on your watchlist; nothing is shown for an item the site has no price "
			+ "for. Buy limits count only the trades your journal knows about, so an item you bought before "
			+ "installing the plugin, or on another client, can show more room left than you really have.",
		position = 12,
		section = exchangeSection
	)
	default boolean setupOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "examinePrices",
		name = "Prices when you examine",
		description = "Adds flippingrs.com's buy and sell prices and the margin to the end of an item's examine "
			+ "line. Examine is the question the game already has for \"what is this\", and it is asked from the "
			+ "inventory, the bank and the ground -- places the Grand Exchange never sees. An item nobody has "
			+ "priced yet says nothing the first time and is answered the next.",
		position = 13,
		section = exchangeSection
	)
	default boolean examinePrices()
	{
		return true;
	}

	@ConfigSection(
		name = "Notifications",
		description = "When the plugin should get your attention",
		position = 15
	)
	String notificationSection = "notifications";

	// Only two, and only for things you would otherwise never learn. The
	// sidebar is where the plugin explains itself, and a flipper keeps the
	// exchange open and the sidebar shut -- so anything that goes wrong with
	// recording is said into a panel nobody is looking at. That is worth a
	// notification. An offer filling is not, by default: the client already
	// tells you, and a busy flipper would get one every few seconds.

	@ConfigItem(
		keyName = "notifyProblems",
		name = "Trades that couldn't be recorded",
		description = "Tells you when flippingrs.com would not record a trade. The sidebar says so too, but a "
			+ "flipper keeps it shut, and a trade missing from your journal is not something you want to find "
			+ "out about days later.",
		position = 16,
		section = notificationSection
	)
	default Notification notifyProblems()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "notifyOfferComplete",
		name = "An offer finishing",
		description = "Tells you when one of your Grand Exchange offers finishes. Off by default: the client "
			+ "already shows it, and a fast flipper would get one of these every few seconds.",
		position = 17,
		section = notificationSection
	)
	default Notification notifyOfferComplete()
	{
		return Notification.OFF;
	}

	@ConfigSection(
		name = "Developer",
		description = "Only read when RuneLite was started with --developer-mode",
		position = 20,
		closedByDefault = true
	)
	String developerSection = "developer";

	// The server address is a setting again, but only for a client started in
	// developer mode, which is how the plugin is run against a local server.
	// In a normal install it is ignored outright: a text box that redirects an
	// API key and every recorded trade is a liability out of all proportion to
	// who would use it, and ignoring it rather than hiding it means a value
	// left over from an older version cannot quietly do anything either.
	@ConfigItem(
		keyName = "baseUrl",
		name = "Server URL",
		description = "Where to send everything instead of https://flippingrs.com, for running against a local "
			+ "server. Only honoured when the client was started with --developer-mode; ignored otherwise.",
		position = 21,
		section = developerSection
	)
	default String baseUrl()
	{
		return "";
	}

	// The game account is deliberately not here. It is stored against the
	// RuneScape account and picked in the side panel, so logging into an alt
	// files its trades under the right journal without anyone remembering to
	// switch a setting. A single global dropdown would silently file a main's
	// flips under an alt the first time someone forgot.
}

package com.flippingrs;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TimeZone;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Keeping the sidebar showing what flippingrs.com has, without spending more
 * of the rate limit than that is worth.
 *
 * <p>Five tabs, four reads. Account is the connection test and is only read by
 * {@link #connect}; Trades and Journal are the journal's, and are re-read
 * together after a send and when the sidebar opens; Watchlists carries the
 * quotes, and is re-read on its own timer while there is somewhere they are
 * shown. Every endpoint answers in the same {@link PanelData} shape and fills
 * only its own parts, so one routine draws all of them and a part that is
 * absent leaves what the panel was already showing alone.
 *
 * <p>The throttling is the point of the class as much as the drawing is. The
 * plugin scope is rate limited at sixty requests a minute, which the sends
 * themselves draw on, so a read that nobody can see is not worth making: a
 * flipper keeps the exchange open and the sidebar shut. Reads that are worth
 * making but come too soon are deferred rather than dropped, so the last send
 * of a burst still gets its refresh.
 *
 * <p>The budget is not the only reason for any of this, and having more of it
 * would not be a reason to drop it: a request made to redraw a panel nobody
 * has open is wasted whatever the limit is, and it is wasted on the user's
 * connection as well as the server's.
 *
 * <p>Net thread, except where a method says otherwise. Nothing here throws:
 * two of these run as fixed-delay tasks, where an escaping exception cancels
 * the task for good and the sidebar goes quiet with nothing in the log to say
 * why.
 */
@Slf4j
final class PanelReads
{
	/**
	 * How often the account tabs are re-read after sends, at most.
	 *
	 * <p>The plugin scope is rate limited at sixty requests a minute, and a
	 * "Send every" of five seconds with slots filling continuously would be
	 * twelve ingests plus twenty-four re-reads on its own. Coalescing the
	 * re-reads caps them at eight -- two tabs, four times a minute -- which
	 * leaves the quote ticks and the catch-up snapshots comfortably inside the
	 * budget rather than merely inside it. A re-read that comes too soon is
	 * deferred, not dropped, so the last send of a burst still gets its
	 * refresh.
	 */
	private static final long ACCOUNT_TABS_REFRESH_SECONDS = 15;

	/**
	 * "Not read yet", on the nanoTime clock. That clock's origin is arbitrary
	 * and it may well be negative, so zero is a time it is allowed to return
	 * and cannot stand in for "never". Every comparison against it is a
	 * subtraction rather than a sum, so a wrap comes out right instead of
	 * deferring a refresh for the next three hundred years.
	 */
	private static final long NEVER = Long.MIN_VALUE;

	/**
	 * How often the sidebar re-reads itself while it is open.
	 *
	 * <p>On top of the reads that already happen because something occurred --
	 * a trade recorded, the sidebar opened, a key entered -- not instead of
	 * them. Those cover what this client did; this covers what happened
	 * elsewhere: a sale closed on the website, a plan changed, a journal
	 * traded on from another computer. Without it a sidebar left open beside a
	 * quiet exchange shows the same figures all evening and gives no sign that
	 * they are old.
	 *
	 * <p>A minute, and only while the sidebar is on screen. Three requests
	 * against a budget of sixty a minute that the sends and the quotes draw on
	 * too, and none of them worth spending on a panel nobody has open.
	 */
	private static final long PANEL_REFRESH_SECONDS = 60;

	/** The tabs that are re-read on their own. */
	enum Tab
	{
		TRADES, JOURNAL, WATCHLISTS, ACCOUNT
	}

	/**
	 * Runs work on the net thread once a delay has passed.
	 *
	 * @return false if the executor is gone, which happens while shutting down
	 */
	@FunctionalInterface
	interface Later
	{
		boolean after(long nanos, Runnable work);
	}

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final FlippingRsConfig config;
	private final ProfileStore store;
	private final Supplier<FlippingRsApi> api;
	private final PanelUpdates panel;
	private final Watchlists watchlists;
	/** Sends whatever is queued. Net thread, synchronous. */
	private final Runnable drain;
	/** Puts refused fills back in the queue and sends them. Net thread, synchronous. */
	private final Runnable retrySetAside;
	/** Reports the open slots to the server. Hands itself to the client thread. */
	private final Runnable snapshotAfterSend;
	/** One account's queue. Opening it reads its file, so it is used on the disk thread. */
	private final java.util.function.LongFunction<TransactionQueue> queueFor;
	/** Hands work to the net thread. */
	private final Consumer<Runnable> netThread;
	/** Hands work to the net thread, after a wait. */
	private final Later later;
	/** Hands work to the disk thread. */
	private final Consumer<Runnable> diskThread;
	/** How many fills have been captured this session, for the Activity tab's count. */
	private final IntSupplier recordedThisSession;

	/**
	 * Whether the sidebar is currently showing this panel. Set from the
	 * panel's own activate and deactivate, and read on the net thread to
	 * decide whether a tab is worth re-reading at all.
	 */
	private volatile boolean sidebarShown;

	private volatile long accountTabsRefreshedAt = NEVER;
	private final AtomicBoolean accountTabsRefreshPending = new AtomicBoolean();

	/**
	 * The journals the key can file under, as last loaded. Kept so that a
	 * login on a different RuneScape account can re-point the picker at that
	 * account's remembered journal without another round trip. Null until the
	 * first successful load.
	 */
	@Nullable
	private volatile List<GameAccount> knownAccounts;

	PanelReads(Client client, ClientThread clientThread, ItemManager itemManager, FlippingRsConfig config,
		ProfileStore store, Supplier<FlippingRsApi> api, PanelUpdates panel, Watchlists watchlists,
		Runnable drain, Runnable retrySetAside, Runnable snapshotAfterSend,
		java.util.function.LongFunction<TransactionQueue> queueFor,
		Consumer<Runnable> netThread, Later later, Consumer<Runnable> diskThread, IntSupplier recordedThisSession)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.config = config;
		this.store = store;
		this.api = api;
		this.panel = panel;
		this.watchlists = watchlists;
		this.drain = drain;
		this.retrySetAside = retrySetAside;
		this.snapshotAfterSend = snapshotAfterSend;
		this.queueFor = queueFor;
		this.netThread = netThread;
		this.later = later;
		this.diskThread = diskThread;
		this.recordedThisSession = recordedThisSession;
	}

	/**
	 * Forgets everything that belonged to the last time the plugin ran: a
	 * sidebar it still thinks is open, a list of journals it has not re-read,
	 * and a deferred re-read that was scheduled on an executor that has since
	 * stopped and will never run to clear its own flag. Left set, that flag
	 * swallows the first coalesced re-read of the new session.
	 */
	void newSession()
	{
		knownAccounts = null;
		accountTabsRefreshedAt = NEVER;
		accountTabsRefreshPending.set(false);
		sidebarShown = false;
	}

	/**
	 * Moves an upgrading install's journal choice out of the RuneScape profile
	 * and onto the account, while there is a logged-in character to attach it
	 * to. Does nothing once it has been moved, and nothing at the login screen,
	 * where the profile config cannot be read anyway.
	 */
	private void migrateIfLoggedIn()
	{
		final long accountHash = client.getAccountHash();
		if (accountHash != FlippingRsPlugin.NO_ACCOUNT)
		{
			store.migrateChosenAccount(accountHash);
		}
	}

	/** The journals the key can file under, as last loaded, or null if none has been. */
	@Nullable
	List<GameAccount> knownAccounts()
	{
		return knownAccounts;
	}

	// ------------------------------------------------------------ panel reads

	/**
	 * Puts a panel reply on the screen. Only the parts present are touched,
	 * so a partial read leaves the rest of the sidebar as it was.
	 *
	 * @param connecting true for the read that doubles as the connection
	 *                   test, which also sets the connection status
	 */
	private void applyPanel(PanelData reply, boolean connecting)
	{
		final Me me = reply.getMe();
		if (me != null)
		{
			final String plan = "Plan: " + me.describePlan();
			panel.onPanel(p -> p.setSubscription(plan));
		}

		final List<GameAccount> accounts = reply.getAccounts();
		if (accounts != null)
		{
			knownAccounts = accounts;
			final String chosen = store.chosenAccountFor(client.getAccountHash());

			// The remembered journal is gone -- deleted on the site, or the key
			// now belongs to a different FlippingRS account. Sending to it
			// would be refused every tick, and the picker would meanwhile show
			// whichever entry sorted first. Forget the choice and say so, and
			// hold the trades until a real one is made.
			final boolean orphaned = chosen != null && !accounts.isEmpty() && !contains(accounts, chosen);
			if (orphaned)
			{
				log.warn("the journal remembered for this account ({}) no longer exists; forgetting it", chosen);
				store.forgetChosenAccountFor(client.getAccountHash());
			}

			panel.onPanel(p -> {
				// The orphaned id is passed through on purpose: the panel shows
				// no selection for a remembered journal it cannot find, where a
				// null would have it select the default as if nothing had ever
				// been chosen.
				p.setAccounts(accounts, chosen);
				if (orphaned)
				{
					p.setStatus("The journal this character was using no longer exists on flippingrs.com. Pick "
						+ "another below. Your trades are being kept safe until you do.", ColorScheme.BRAND_ORANGE);
					return;
				}
				if (connecting)
				{
					p.setStatus(accounts.isEmpty()
							? "Connected, but your flippingrs.com account has no journals yet. Create one on the site first."
							: "Connected and recording.",
						accounts.isEmpty() ? ColorScheme.BRAND_ORANGE : ColorScheme.PROGRESS_COMPLETE_COLOR);
				}
				// A RuneScape account seen for the first time has nothing chosen
				// yet. Adopting whatever the panel selected saves a setup step,
				// and it can still be changed. If nobody is logged in yet, the
				// profile-changed event does this on login instead. (An orphaned
				// choice returned above, so this never adopts over one.)
				if (chosen == null)
				{
					rememberChosenAccountFrom(p, false);
				}
			});
		}
		else if (connecting)
		{
			panel.onPanel(p -> p.setStatus("Connected and recording.", ColorScheme.PROGRESS_COMPLETE_COLOR));
		}

		watchlists.accept(reply.getWatchlists(), reply.getQuotes());

		final List<GeTransaction> all = reply.getRecentTransactions();
		if (all != null)
		{
			// Only the rows that will actually be drawn. The tab shows the
			// newest few and drops the rest, and resolving a sprite for a row
			// nobody will see is item-manager work on the game thread for
			// nothing -- however many the server decides to send back.
			final List<GeTransaction> rows = all.size() > FlippingRsPanel.RECENT_SHOWN
				? all.subList(0, FlippingRsPanel.RECENT_SHOWN)
				: all;
			// Sprites come from the item manager, which wants the client thread.
			clientThread.invoke(() ->
			{
				final Map<Integer, AsyncBufferedImage> images = new HashMap<>();
				for (GeTransaction tx : rows)
				{
					if (!images.containsKey(tx.itemId))
					{
						images.put(tx.itemId, spriteOf(tx.itemId));
					}
				}
				panel.onPanel(p -> p.setRecentTrades(rows, images));
			});
		}

		final Analytics week = reply.getWeek();
		final Positions open = reply.getPositions();
		if (week != null && open != null)
		{
			panel.onPanel(p -> p.setJournal(week, open));
		}
		// Separately from the two above, and only when the server sent it. A
		// flippingrs.com that does not know about closed lots leaves the part
		// out, and the tab then has no closed section at all rather than an
		// empty one -- which is the difference between a server that has
		// nothing to say and one that says you have never finished a flip.
		final ClosedPositions closed = reply.getClosedPositions();
		if (closed != null)
		{
			panel.onPanel(p -> p.setClosedPositions(closed));
		}
	}

	/**
	 * Checks the key and loads every tab.
	 *
	 * <p>The Account read is the connection test: if it fails, nothing else
	 * is tried and the Account tab says why. The other tabs are then read one
	 * by one, and each reports its own failure on its own tab, since a key
	 * that just worked is not a broken connection.
	 *
	 * <p>Never throws. Not because anything schedules it -- nothing does --
	 * but because this is the read that puts the reason on the Account tab,
	 * and a failure that escapes leaves that tab saying whatever it said
	 * before while the plugin quietly does nothing.
	 */
	void connect()
	{
		try
		{
			if (!config.enabled())
			{
				panel.onPanel(p -> {
					p.setAccounts(Collections.emptyList(), null);
					p.setStatus("Recording is off. Nothing is being recorded or sent to flippingrs.com. Switch "
						+ "\"Record trades\" back on in the plugin settings to carry on.",
						ColorScheme.LIGHT_GRAY_COLOR);
					// Old rows next to a status that says nothing is being read
					// would be a picture of a journal the plugin is not looking at.
					p.setPaused("Recording is off, so nothing is being read from flippingrs.com.");
				});
				// The list the picker was drawn from goes too. It is not read
				// again while this is the state, and a login on another character
				// would otherwise re-point the picker from it -- filling in a
				// journal on a tab that has just said nothing is being read.
				knownAccounts = null;
				// And the offer screen, which draws the same quotes the sidebar
				// does. Left alone it would go on showing the site's prices, frozen
				// at whatever they were when recording was switched off, in front
				// of the box where a price gets typed.
				watchlists.forget();
				return;
			}

			migrateIfLoggedIn();

			final String key = FlippingRsApi.trimmedKey(config.apiKey());
			if (key.isEmpty())
			{
				panel.onPanel(p -> {
					p.setAccounts(Collections.emptyList(), null);
					p.setStatus("Add your API key in the plugin settings. You can create one on flippingrs.com "
						+ "under Account, then API keys.", ColorScheme.LIGHT_GRAY_COLOR);
					p.setPaused("Add an API key to see your journal here.");
				});
				knownAccounts = null;
				watchlists.forget();
				return;
			}

			try
			{
				applyPanel(api.get().account(key), true);
			}
			catch (java.io.IOException e)
			{
				log.debug("could not reach flippingrs.com", e);
				final String why = FlippingRsApi.describe(e);
				panel.onPanel(p -> p.setStatus("Could not connect: " + why, ColorScheme.PROGRESS_ERROR_COLOR));
				return;
			}
			refresh(Tab.TRADES);
			refresh(Tab.JOURNAL);
			accountTabsRefreshedAt = System.nanoTime();
			refresh(Tab.WATCHLISTS);
			refreshPending();
			// The key may have been missing or wrong while trades piled up.
			netThread.accept(drain);
		}
		catch (RuntimeException e)
		{
			// The Account tab is where the plugin explains itself, and this is
			// the read that fills it in. Anything unexpected out of here left
			// it saying whatever it said last -- "Not connected", on a client
			// that had just been given a key -- with the reason in the log and
			// nowhere else, which is the one failure this tab exists to
			// prevent. The sender and the tab reads are wrapped the same way.
			log.warn("unexpected failure while connecting to flippingrs.com", e);
			panel.onPanel(p -> p.setStatus("Something went wrong while connecting. Details are in the client log.",
				ColorScheme.PROGRESS_ERROR_COLOR));
		}
	}

	/**
	 * The sidebar opened on this panel, or closed. Swing thread.
	 *
	 * <p>Opening reads everything the sidebar shows, because while it was shut
	 * none of it was. The two account tabs go through the same throttle the
	 * sends use, so opening and closing it repeatedly cannot become a burst of
	 * requests against a limit of sixty a minute.
	 */
	void sidebarShown(boolean shown)
	{
		sidebarShown = shown;
		watchlists.sidebarShown(shown);
		if (!shown)
		{
			return;
		}
		netThread.accept(() ->
		{
			refresh(Tab.WATCHLISTS);
			refreshAccountTabs();
		});
	}

	/**
	 * What a successful send sets going: the open-slot snapshot always, and a
	 * re-read of the two account tabs if anyone can see them. Net thread.
	 */
	void afterSend()
	{
		// Not a panel read, and so not conditional on anyone looking: this is
		// how the server learns what the open slots hold and recovers a fill
		// the plugin never saw. CatchUp keeps its own, longer, minimum gap.
		clientThread.invoke(snapshotAfterSend);

		if (!sidebarShown)
		{
			// Nobody can see the two tabs. Reading them anyway is two requests
			// per send, against a budget the sends themselves draw on, to
			// redraw a panel that is shut -- and a flipper keeps the exchange
			// open and the sidebar shut. Opening it reads them.
			return;
		}
		refreshAccountTabs();
	}

	/**
	 * Re-reads Trades and Journal, no more often than the limit allows. Net
	 * thread. A read that comes too soon is deferred rather than dropped, so
	 * the last send of a burst still gets its refresh.
	 */
	void refreshAccountTabs()
	{
		final long now = System.nanoTime();
		final long since = now - accountTabsRefreshedAt;
		final long window = TimeUnit.SECONDS.toNanos(ACCOUNT_TABS_REFRESH_SECONDS);
		if (accountTabsRefreshedAt == NEVER || since >= window)
		{
			accountTabsRefreshedAt = now;
			refresh(Tab.TRADES);
			refresh(Tab.JOURNAL);
			return;
		}
		final long wait = window - since;
		if (!accountTabsRefreshPending.compareAndSet(false, true))
		{
			// One is already on its way, and it will see this send's rows too.
			return;
		}
		final boolean scheduled = later.after(wait, () ->
		{
			accountTabsRefreshPending.set(false);
			accountTabsRefreshedAt = System.nanoTime();
			refresh(Tab.TRADES);
			refresh(Tab.JOURNAL);
		});
		if (!scheduled)
		{
			// Shutting down; the next connect re-reads everything anyway.
			accountTabsRefreshPending.set(false);
		}
	}

	/**
	 * Re-reads one tab from its endpoint and redraws it. Net thread. Never
	 * throws, because the watchlist refresh also runs on a fixed-delay
	 * schedule, where an escaping exception would cancel it for good.
	 *
	 * <p>A failure is reported on that tab, not as a failed connection: the
	 * key was good a moment ago and the fills are still going out.
	 */
	void refresh(Tab tab)
	{
		try
		{
			if (!config.enabled())
			{
				return;
			}
			final String key = FlippingRsApi.trimmedKey(config.apiKey());
			if (key.isEmpty())
			{
				return;
			}
			final String accountId = store.chosenAccountFor(client.getAccountHash());
			final PanelData part;
			switch (tab)
			{
				case TRADES:
					if (accountId == null)
					{
						return;
					}
					part = api.get().trades(key, accountId);
					break;
				case JOURNAL:
					if (accountId == null)
					{
						return;
					}
					part = api.get().journal(key, accountId, tzOffsetMinutes());
					break;
				case WATCHLISTS:
					// The journal as well as the list: buy limits are counted
					// per journal, so without one the quotes come back without
					// them. Null here is fine and simply means no limits.
					part = api.get().watchlists(key, store.rememberedWatchlistId(), accountId);
					break;
				case ACCOUNT:
					// No journal needed: this is about the key, not about what
					// was traded with it. Applied as a connection would apply
					// it, so a read that succeeds after one that failed puts
					// the tab back to saying it is connected rather than
					// leaving the failure up until the next connect.
					part = api.get().account(key);
					applyPanel(part, true);
					return;
				default:
					return;
			}
			applyPanel(part, false);
		}
		catch (java.io.IOException e)
		{
			log.warn("could not refresh the {} tab: {}", tab, e.getMessage());
			final String why = FlippingRsApi.describe(e);
			panel.onPanel(p ->
			{
				switch (tab)
				{
					case TRADES:
						p.setRecentTradesProblem(why);
						break;
					case JOURNAL:
						p.setJournalProblem(why);
						break;
					case WATCHLISTS:
						p.setWatchlistProblem(why);
						break;
					case ACCOUNT:
						p.setStatus("Could not reach flippingrs.com: " + why,
							ColorScheme.PROGRESS_ERROR_COLOR);
						break;
					default:
						break;
				}
			});
		}
		catch (RuntimeException e)
		{
			log.warn("unexpected failure refreshing the {} tab", tab, e);
		}
	}

	/**
	 * The tick that re-reads the sidebar, while anyone has it open.
	 *
	 * <p>Guarded for the same reason {@link #quotesTick} is: a fixed-delay
	 * task that throws is cancelled for good, and the sidebar would then stop
	 * refreshing for the rest of the session with nothing on screen to say so
	 * -- which is exactly the failure the freshness line under each tab now
	 * makes visible, and no reason to let it happen.
	 */
	void panelTick()
	{
		try
		{
			if (!sidebarShown)
			{
				return;
			}
			// Through the same throttle the sends use, so a tick landing just
			// after a trade was recorded does not read the same rows twice.
			refreshAccountTabs();
			refresh(Tab.ACCOUNT);
		}
		catch (RuntimeException e)
		{
			log.warn("unexpected failure refreshing the sidebar", e);
		}
	}

	/** How often {@link #panelTick} should be run. */
	static long panelRefreshSeconds()
	{
		return PANEL_REFRESH_SECONDS;
	}

	/**
	 * The tick that keeps quotes current, while there is something to quote
	 * and somewhere it is shown.
	 *
	 * <p>Guarded for the same reason {@link TransactionSender#drain} is: this
	 * runs as a fixed-delay task, and an exception escaping one cancels it for
	 * good -- the quotes would stop refreshing for the rest of the session with
	 * nothing in the log to say why. Deciding whether there is anything to
	 * quote reads nothing that can throw today; the guard is here so that it
	 * stays true of whatever this comes to ask, because the cost of being
	 * wrong about it is silent and lasts all session.
	 */
	void quotesTick()
	{
		try
		{
			if (watchlists.wantsQuotes())
			{
				refresh(Tab.WATCHLISTS);
			}
			// And the items the exchange is showing that the watchlist does
			// not cover, which is one more request and only while the exchange
			// is open with something in it.
			watchlists.fetchOnDemand();
		}
		catch (RuntimeException e)
		{
			log.warn("unexpected failure deciding whether to refresh the quotes", e);
		}
	}

	/**
	 * Shows what is still buffered for the logged-in account. Disk thread,
	 * because opening the queue reads its file.
	 */
	void refreshPending()
	{
		// Read once, here, rather than again on the disk thread: the two are
		// separated by a handoff, and a hop in between would show one
		// account's buffer under the other's name.
		final long accountHash = client.getAccountHash();
		if (accountHash == FlippingRsPlugin.NO_ACCOUNT)
		{
			panel.onPanel(p ->
			{
				p.setPending(Collections.emptyList());
				p.setCounts(recordedThisSession.getAsInt(), 0);
			});
			return;
		}
		diskThread.accept(() ->
		{
			final TransactionQueue queue = queueFor.apply(accountHash);
			final int waiting = queue.size();
			final List<GeTransaction> buffered = queue.newest(FlippingRsPanel.RECENT_SHOWN);
			final int setAside = queue.setAsideCount();
			panel.onPanel(p ->
			{
				p.setCounts(recordedThisSession.getAsInt(), waiting);
				p.setPending(buffered);
				p.setSetAside(setAside);
			});
		});
	}

	/**
	 * A different RuneScape account is now active. The journal is remembered
	 * per account, so the picker is re-pointed from the list already loaded,
	 * and an account seen for the first time adopts the default the way a
	 * fresh install does. Swing thread work, handed off from the caller.
	 *
	 * @return false if no list has been loaded yet, in which case connect will
	 *         do this when it succeeds
	 */
	boolean accountChanged()
	{
		// Before anything reads the choice. This is the first moment an
		// upgrading install has an account to move its old per-profile choice
		// to, and reading before moving it would find nothing chosen and adopt
		// the server's default over a journal the user had already picked --
		// which is the exact mix-up storing it per character exists to prevent.
		migrateIfLoggedIn();

		final List<GameAccount> accounts = knownAccounts;
		if (accounts == null)
		{
			return false;
		}
		final String chosen = store.chosenAccountFor(client.getAccountHash());
		panel.onPanel(p ->
		{
			p.setAccounts(accounts, chosen);
			if (chosen == null)
			{
				rememberChosenAccountFrom(p, false);
			}
		});
		// The recent trades, the journal and the buffer are the account's, so
		// they change with it.
		netThread.accept(() ->
		{
			refresh(Tab.TRADES);
			refresh(Tab.JOURNAL);
		});
		refreshPending();
		return true;
	}

	private static boolean contains(List<GameAccount> accounts, String id)
	{
		for (GameAccount account : accounts)
		{
			if (account != null && id.equals(account.id))
			{
				return true;
			}
		}
		return false;
	}

	// ------------------------------------------------------------ the journal

	/**
	 * Stores the panel's selection as this RuneScape account's journal.
	 *
	 * <p>The journal is what Trades and Journal are read for, so a change of
	 * one has to re-read both. Without that, picking a different journal left
	 * the two tabs showing the previous one's rows until something else
	 * happened to refresh them -- a sidebar naming one journal over another
	 * journal's numbers, which is the one thing this panel exists to get
	 * right. The same call covers the first journal a character adopts: the
	 * adoption is handed to the Swing thread and lands after the connect that
	 * asked for it has already read both tabs and found nothing chosen.
	 *
	 * <p>And whatever is queued goes out, because the panel has been telling
	 * the user their trades are being kept safe until they pick one.
	 *
	 * @param interactive true when the user just picked it, in which case a
	 *                    choice that cannot be stored is worth telling them
	 *                    about. The automatic adoptions pass false: on a client
	 *                    started before login there is nothing to attach the
	 *                    choice to yet, and that is not something to nag over.
	 */
	void rememberChosenAccountFrom(FlippingRsPanel from, boolean interactive)
	{
		final String id = from.selectedAccountId();
		if (id == null)
		{
			return;
		}
		if (client.getAccountHash() == FlippingRsPlugin.NO_ACCOUNT)
		{
			// There is no RuneScape profile to attach the choice to yet. Saying
			// so beats writing it somewhere it will never be read back from.
			if (interactive)
			{
				from.setStatus("Log in first, so this choice can be saved for that character.",
					ColorScheme.BRAND_ORANGE);
			}
			return;
		}
		if (id.equals(store.chosenAccountFor(client.getAccountHash())))
		{
			// Repopulating the picker on every reconnect re-selects the same
			// entry, and re-reading two tabs for that would be two requests
			// for no news.
			return;
		}
		store.rememberChosenAccountFor(client.getAccountHash(), id);
		netThread.accept(() ->
		{
			refresh(Tab.TRADES);
			refresh(Tab.JOURNAL);
			// The other thing a wrong journal explains is a batch the server
			// refused over something that was never the rows' fault. Picking a
			// different one is the fix, so what was filed gets another go.
			retrySetAside.run();
			drain.run();
		});
	}

	// ---------------------------------------------------------------- helpers

	/** The machine's UTC offset, so the server's daily buckets fall on the player's calendar. */
	private static int tzOffsetMinutes()
	{
		return TimeZone.getDefault().getOffset(System.currentTimeMillis()) / 60_000;
	}

	/** The item's sprite, or null if the client will not give one. Client thread. */
	@Nullable
	private AsyncBufferedImage spriteOf(int itemId)
	{
		try
		{
			return itemManager.getImage(itemId);
		}
		catch (RuntimeException e)
		{
			log.debug("no sprite for item {}", itemId, e);
			return null;
		}
	}
}

package com.flippingrs;

// The panel's shared vocabulary: the layout helpers every tab builds
// rows out of, and the static text of a row, which the tests pin there.
import static com.flippingrs.FlippingRsPanel.*;

import java.awt.Insets;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JTextField;
import javax.swing.Timer;

/**
 * The Positions tab: everything you are still holding.
 *
 * <p>Its own tab because it is its own page on flippingrs.com, and because
 * the week's verdict -- which used to share this one -- answers a different
 * question. Every figure on it is the server's, marked to market.
 *
 * <p>The two buttons on a position are the only writes the sidebar makes that
 * are not a report of something the plugin watched happen, and the
 * destructive one asks first.
 */
final class PositionsTab extends SidebarTab
{
	private final JLabel openSummary = new JLabel();
	private final JLabel notice = new JLabel();
	private final Timer noticeTimer = new Timer(FlippingRsPanel.NOTICE_SECONDS * 1000,
		e -> setPositionNotice(null, ColorScheme.LIGHT_GRAY_COLOR));
	private final JPanel positionList = new JPanel();
	private List<Position> positions = new ArrayList<>();
	/**
	 * The closed section, hidden until a server sends one.
	 *
	 * <p>Hidden rather than empty, and the distinction matters: a
	 * flippingrs.com that has never heard of closed lots leaves the part out
	 * of its reply altogether, and a section saying "No closed positions yet"
	 * would then be telling somebody with a year of finished flips that they
	 * have none. An empty list from a server that does know is a different
	 * thing and does say that.
	 */
	private final JPanel closedSection = new JPanel();
	private final JLabel closedSummary = new JLabel();
	private final JPanel closedList = new JPanel();
	private List<ClosedPosition> closed = new ArrayList<>();
	private boolean loaded;
	@Nullable
	private String problem;
	/**
	 * The positions currently drawn as cards, as {@link #signatureOf} sees
	 * them. Null until the first draw; only set once the cards are up.
	 */
	@Nullable
	private String drawnPositions;
	@Nullable
	private String drawnClosed;
	/** Why nothing is being read at all, if that is the case. The panel sets it. */
	@Nullable
	private String paused;
	private final JPanel body;
	private final PanelActions actions;

	PositionsTab(PanelActions actions)
	{
		this.actions = actions;
		final JPanel body = column();
		body.add(hint("What you are holding, what it cost you, and what it is worth right now."));
		body.add(header("Open positions"));
		body.add(Box.createVerticalStrut(4));
		openSummary.setFont(FontManager.getRunescapeSmallFont());
		openSummary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		openSummary.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(openSummary);
		body.add(Box.createVerticalStrut(4));
		notice.setFont(FontManager.getRunescapeSmallFont());
		notice.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(notice);
		body.add(Box.createVerticalStrut(4));
		positionList.setLayout(new BoxLayout(positionList, BoxLayout.Y_AXIS));
		positionList.setAlignmentX(Component.LEFT_ALIGNMENT);
		positionList.setToolTipText("What you're holding, what it cost you, and what it's worth right now.");
		body.add(positionList);

		// Under the open ones, because the open book is the thing somebody
		// acts on and the closed one is the thing they learn from.
		closedSection.setLayout(new BoxLayout(closedSection, BoxLayout.Y_AXIS));
		closedSection.setAlignmentX(Component.LEFT_ALIGNMENT);
		closedSection.setOpaque(false);
		closedSection.add(Box.createVerticalStrut(8));
		closedSection.add(header("Closed positions"));
		closedSection.add(Box.createVerticalStrut(4));
		closedSummary.setFont(FontManager.getRunescapeSmallFont());
		closedSummary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		closedSummary.setAlignmentX(Component.LEFT_ALIGNMENT);
		closedSection.add(closedSummary);
		closedSection.add(Box.createVerticalStrut(4));
		closedList.setLayout(new BoxLayout(closedList, BoxLayout.Y_AXIS));
		closedList.setAlignmentX(Component.LEFT_ALIGNMENT);
		closedList.setToolTipText("Flips you've finished: what they made after tax.");
		closedSection.add(closedList);
		closedSection.setVisible(false);
		body.add(closedSection);
		// The freshness line last, under everything it qualifies. Empty until
		// the first read, so it takes no room on a tab that has nothing yet.
		body.add(Box.createVerticalStrut(8));
		body.add(refreshLine());
		this.body = body;
		drawSummary();
	}

	@Override
	JPanel body()
	{
		return body;
	}

	/** Read with the week, on a trade and on opening the sidebar. */
	@Override
	String refreshedBy()
	{
		return "on a trade";
	}

	@Override
	long refreshEverySeconds()
	{
		return PanelReads.panelRefreshSeconds();
	}

	@Override
	void onPaused(@Nullable String why)
	{
		paused = why;
		if (why != null)
		{
			positions = new ArrayList<>();
			// The cards go, but the section stays as it was found: whether
			// this server has closed lots at all is not something that stops
			// being true because the plugin stopped reading.
			closed = new ArrayList<>();
			loaded = false;
			problem = null;
		}
		drawSummary();
		refresh();
	}

	/** The open lots and their totals, as the server has them. */
	void setPositions(Positions open)
	{
		stamp();
		problem = null;
		loaded = true;
		final Positions.Summary totals = open.getSummary();
		positions = open.getPositions();
		setWrappedText(openSummary, positions.isEmpty()
			? "No open positions."
			: totals.openPositions + " open · cost " + gp(totals.costBasis) + " · value " + gp(totals.marketValue)
			+ " · P&L " + signed(totals.unrealisedPnl)
			+ (totals.marketDataAvailable ? "" : " (no market data)"));
		refresh();
	}

	/**
	 * The finished lots, as the server has them.
	 *
	 * <p>Only ever called with something the server actually sent, so
	 * reaching here is what makes the section exist at all.
	 */
	void setClosedPositions(ClosedPositions finished)
	{
		closed = finished.getPositions();
		setWrappedText(closedSummary, closedSummaryLine(finished));
		closedSection.setVisible(true);
		refresh();
	}

	/**
	 * A note about the last close or delete: done, or refused in the
	 * server's words. Null clears it; otherwise it clears itself after
	 * {@link #NOTICE_SECONDS}.
	 */
	void setPositionNotice(@Nullable String text, Color colour)
	{
		setNotice(notice, noticeTimer, text, colour);
	}

	/** The journal could not be read. Shown in the tab itself. */
	void setProblem(String why)
	{
		problem = why;
		loaded = false;
		positions = new ArrayList<>();
		closed = new ArrayList<>();
		drawSummary();
		refresh();
	}

	/**
	 * The summary line, for the states that are not a loaded journal: nothing
	 * being read, a read that failed, or nothing read yet.
	 *
	 * <p>One label, and it costs nothing next to the cards, so unlike the
	 * cards it is kept current whether or not this tab is showing. Somebody
	 * who opens the sidebar on another tab and then comes to this one should
	 * not be told the journal is "not loaded yet" when it plainly is. A
	 * journal that did load writes the line itself, in {@link #setPositions}.
	 */
	private void drawSummary()
	{
		if (paused != null)
		{
			setWrappedText(openSummary, paused);
			openSummary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
		else if (problem != null)
		{
			setWrappedText(openSummary, "Couldn't load your journal: " + problem);
			openSummary.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		}
		else if (!loaded)
		{
			setWrappedText(openSummary, "Not loaded yet.");
			openSummary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
	}

	@Override
	void redraw()
	{
		// Every card is torn down and built again, and a position card is the
		// dearest kind: a title, four lines and two buttons. Two hundred open
		// lots measured at 154ms of the Swing thread, which is the client's,
		// and the journal is redrawn on every read and every time this tab is
		// picked -- mostly with the same lots at the same prices. So what is
		// already on screen is left alone when a redraw would not change it.
		final String signature = signatureOf(positions);
		if (!signature.equals(drawnPositions))
		{
			drawnPositions = signature;
			positionList.removeAll();
			for (Position position : positions)
			{
				positionList.add(positionRow(position));
				positionList.add(Box.createVerticalStrut(4));
			}
			positionList.revalidate();
			positionList.repaint();
		}

		// Its own signature, because the two lists move on their own: closing
		// a lot changes both, but an open lot being marked to market changes
		// only the first, and that happens on every read.
		final String closedSignature = closedSignatureOf(closed);
		if (!closedSignature.equals(drawnClosed))
		{
			drawnClosed = closedSignature;
			closedList.removeAll();
			for (ClosedPosition finished : closed)
			{
				closedList.add(closedRow(finished));
				closedList.add(Box.createVerticalStrut(4));
			}
			closedList.revalidate();
			closedList.repaint();
		}
	}

	/**
	 * One finished lot: what it was, what it cost, what it made.
	 *
	 * <p>No buttons. There is nothing left to do to a lot that is sold, and
	 * the site's Journal page is where one gets corrected.
	 */
	private JPanel closedRow(ClosedPosition p)
	{
		final JPanel card = card();
		final JLabel title = new JLabel();
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		setWrappedText(title, p.getItemName().isEmpty() ? "Item " + p.getItemId() : p.getItemName());
		card.add(title);
		card.add(small(closedHeld(p)));
		card.add(small(closedPrices(p)));
		final JLabel made = small(closedResult(p));
		made.setForeground(p.getNetProfit() < 0
			? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR);
		card.add(made);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/** One open position: what is held, what it cost, what it is worth now. */
	private JPanel positionRow(Position p)
	{
		final JPanel card = card();
		final JLabel title = new JLabel();
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		setWrappedText(title, p.getItemName().isEmpty() ? "Item " + p.getItemId() : p.getItemName());
		card.add(title);
		card.add(small(p.getRemainingQty() + " left · held " + hours(p.getHoursHeld())));
		card.add(small(positionPrices(p)));
		final JLabel now = small("P&L " + signedExact(p.getUnrealisedPnl()) + " (" + pct(p.getUnrealisedRoi()) + ")"
			+ (p.getBreakEvenSell() > 0 ? " · break even " + exact(p.getBreakEvenSell()) : ""));
		now.setForeground(p.getUnrealisedPnl() < 0 ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR);
		card.add(now);
		if (p.isStale())
		{
			final JLabel stale = small("Stale: you've held this much longer than this item usually takes to flip.");
			stale.setForeground(ColorScheme.BRAND_ORANGE);
			card.add(stale);
		}
		if (!p.getId().isEmpty())
		{
			card.add(Box.createVerticalStrut(5));
			final JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
			buttons.setOpaque(false);
			buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
			buttons.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
			final JButton close = new JButton("Close");
			close.setToolTipText("Record a sale of this position at a price you enter.");
			close.addActionListener(e -> promptClose(p));
			final JButton delete = new JButton("Delete");
			delete.setToolTipText("Not a flip? Delete this record so later sales of the item are not counted against it.");
			delete.addActionListener(e -> promptDelete(p));
			for (JButton button : new JButton[]{close, delete})
			{
				button.setFont(FontManager.getRunescapeSmallFont());
				button.setMargin(new Insets(1, 4, 1, 4));
				buttons.add(button);
			}
			card.add(buttons);
		}
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/**
	 * What Close does with what was typed into it.
	 *
	 * <p>Apart from the box itself, which cannot be opened without someone to
	 * close it. A sale recorded from the wrong field, or for none of the
	 * position instead of all of it, is a wrong journal entry that the player
	 * asked for by hand and would have no reason to doubt.
	 */
	void closeAsTyped(Position p, String priceText, String quantityText)
	{
		final long sellPrice = parseGp(priceText);
		final long sellQty = parseGp(quantityText);
		if (sellPrice <= 0)
		{
			setPositionNotice("A sale price is needed to close a position.", ColorScheme.BRAND_ORANGE);
			return;
		}
		// Nothing readable in the count means all of what is left, which is
		// what the box offers and what the site takes a missing count as.
		closePosition(p.getId(), sellPrice, sellQty > 0 ? sellQty : null);
	}

	/**
	 * Asks for the sale price and quantity, prefilled with the price a sale
	 * lists at and everything still held, then hands the answer to the
	 * plugin. Nothing is sent unless the user confirms.
	 */
	private void promptClose(Position p)
	{
		final long suggested = suggestedSalePrice(p);
		final JTextField price = new JTextField(suggested > 0 ? exact(suggested) : "");
		final JTextField quantity = new JTextField(Long.toString(p.getRemainingQty()));
		final JPanel form = new JPanel(new GridLayout(0, 1, 0, 2));
		form.add(new JLabel("Sale price per item"));
		form.add(price);
		form.add(new JLabel("How many sold (" + p.getRemainingQty() + " held)"));
		form.add(quantity);
		final int answer = JOptionPane.showConfirmDialog(body, form,
			"Close " + (p.getItemName().isEmpty() ? "position" : p.getItemName()),
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
		if (answer != JOptionPane.OK_OPTION)
		{
			return;
		}
		closeAsTyped(p, price.getText(), quantity.getText());
	}

	private void promptDelete(Position p)
	{
		final int answer = JOptionPane.showConfirmDialog(body,
			"Delete this record? Later sales of " + (p.getItemName().isEmpty() ? "this item" : p.getItemName())
				+ " will not be counted against it. Your recorded trades are kept.",
			"Delete position", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
		if (answer == JOptionPane.OK_OPTION)
		{
			actions.deletePosition(p.getId());
		}
	}

	/** The way a user would close a position, without the dialog. */
	void closePosition(String positionId, long sellPrice, @Nullable Long sellQty)
	{
		actions.closePosition(positionId, sellPrice, sellQty);
	}

