		return noticeTimer;
	}

	JPanel listForTest()
	{
		return positionList;
	}
}

package com.flippingrs;

import java.util.Objects;
import javax.annotation.Nullable;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;

/**
 * Text put on the end of a line the game owns.
 *
 * <p>Adding to a widget the client wrote is the least invasive way to say
 * something in an interface: the line is already positioned, already sized,
 * already wrapping and clipping the way that screen does it, and none of that
 * has to be worked out again or kept right as Jagex moves it. A widget of
 * one's own has to be placed, and a placement is a guess about somebody
 * else's layout that goes stale without warning.
 *
 * <p>The whole difficulty is that the client rewrites these lines whenever it
 * likes, and it does not know or care what was appended to them. So this holds
 * what the line said before, and notices when the client has written something
 * new: anything not matching what was last put there is taken as the game's
 * text rather than as something to append to again. Without that, a line grows
 * a second copy of the addition every time it is refreshed.
 *
 * <p>Client thread only.
 */
final class Appended
{
	/** One row of the small font, which is what every addition here is made of. */
	private static final int LINE = 12;

	/** The line being added to, or null if nothing is. */
	@Nullable
	private Widget widget;

	/** The game's own text, without the addition. */
	@Nullable
	private String original;

	/** What was last written, so a rewrite by the client can be told from it. */
	@Nullable
	private String written;

	/** The line's own height before it was given room, or -1 if it was not. */
	private int baseHeight = -1;
	private int baseHeightMode = -1;

	/**
	 * Puts {@code extra} on the end of a widget's text, replacing whatever was
	 * put there before.
	 *
	 * <p>Safe to call every tick with the same arguments: it writes only when
	 * the result would differ from what is already there.
	 */
	void to(Widget target, String extra)
	{
		to(target, extra, 0);
	}

	/**
	 * The same, giving the line room for the rows the addition puts on it.
	 *
	 * <p>A line the game wrote is exactly as tall as what the game put in it,
	 * so a row added to it draws over whatever is underneath.
	 *
	 * <p>The height is read once, when this first takes the line, and every
	 * write after that is computed from it -- never from a height this has
	 * already changed. Measuring after moving is what makes a resize grow from
	 * its own growth.
	 *
	 * @param rows how many extra rows the addition takes, or 0 for none
	 */
	void to(Widget target, String extra, int rows)
	{
		if (target != widget)
		{
			// A different line, or the same one rebuilt into a new widget.
			widget = target;
			original = target.getText();
			written = null;
			// The line as the client had it, read before anything is written
			// to it and not read again while it is this one.
			baseHeight = target.getHeight();
			baseHeightMode = target.getHeightMode();
		}
		else if (!Objects.equals(target.getText(), written))
		{
			// The client wrote something new here. Whatever it is, it is the
			// game's text now -- appending to the previous composition instead
			// would keep a copy of the addition forever.
			original = target.getText();
		}
		final String composed = (original == null ? "" : original) + extra;
		if (!composed.equals(target.getText()))
		{
			target.setText(composed);
		}
		written = composed;
		if (rows > 0 && baseHeight >= 0)
		{
			final int wanted = baseHeight + rows * LINE;
			if (target.getHeight() != wanted)
			{
				target.setHeightMode(WidgetSizeMode.ABSOLUTE);
				target.setOriginalHeight(wanted);
				target.revalidate();
			}
		}
	}

	/**
	 * Puts the line back the way the game had it, and forgets it.
	 *
	 * <p>Only if it still says what was written: a line the client has since
	 * rewritten is already the game's, and restoring over it would put back
	 * text belonging to an item that is no longer there.
	 */
	void clear()
	{
		if (widget != null && original != null && Objects.equals(widget.getText(), written))
		{
			widget.setText(original);
			if (baseHeight >= 0)
			{
				widget.setHeightMode(baseHeightMode);
				widget.setOriginalHeight(baseHeight);
				widget.revalidate();
			}
		}
		widget = null;
		original = null;
		written = null;
		baseHeight = -1;
	}

	/** The text as it now stands, or null if nothing is being added to. */
	@Nullable
	String textForTest()
	{
		return widget == null ? null : widget.getText();
	}
}

package com.flippingrs;

/**
 * One lot that has been bought and sold: what it made, after tax.
 *
 * <p>The counterpart to {@link Position}, and deliberately a separate shape.
 * An open lot is a question -- what is it worth now, what would break even,
 * has it been held too long -- and every figure on it moves. A closed one is
 * an answer, and none of its figures will ever change again. Sharing a class
 * would mean half its fields being meaningless in either direction.
 */
public class ClosedPosition
{
	/** The lot's id, which the plugin only uses to tell one card from another. */
	String id;
	int itemId;
	String itemName;
	long buyPrice;
	long buyQty;
	long sellPrice;
	long sellQty;
	/** The exchange's cut, which is the difference between gross and net. */
	long taxPaid;
	/** After tax. The one figure worth reading first. */
	long netProfit;
	/** A fraction: 0.02 is 2%. */
	double roi;
	/** Bought to sold, worked out by the server, which has both timestamps. */
	double hoursHeld;
	/**
	 * Whether both ends of the flip were actually watched.
	 *
	 * <p>A leg the plugin recovered after the fact carries the time it was
	 * recovered rather than the time it happened, so the hold is a placeholder
	 * and is left off rather than shown as a duration nobody measured. The
	 * profit is still real; only its timing is not.
	 */
	boolean timesKnown;

	public String getId()
	{
		return id == null ? "" : id;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getItemName()
	{
		return itemName == null ? "" : itemName;
	}

	public long getBuyPrice()
	{
		return buyPrice;
	}

	public long getBuyQty()
	{
		return buyQty;
	}

	public long getSellPrice()
	{
		return sellPrice;
	}

	public long getSellQty()
	{
		return sellQty;
	}

	public long getTaxPaid()
	{
		return taxPaid;
	}

	public long getNetProfit()
	{
		return netProfit;
	}

	public double getRoi()
	{
		return roi;
	}

	public double getHoursHeld()
	{
		return hoursHeld;
	}

	public boolean isTimesKnown()
	{
		return timesKnown;
	}
}

package com.flippingrs;

import javax.annotation.Nullable;

/**
 * Everything the sidebar can ask the plugin to do.
 *
 * <p>One interface, taken in the panel's constructor, rather than a dozen
 * setters each defaulting to a no-op. The setters could not tell anybody when
 * one was forgotten: a button wired to nothing looks exactly like a button
 * wired to something that decided to do nothing, and neither the panel nor
 * the plugin could notice the difference. Adding a method here breaks the
 * build until the plugin implements it, which is the only moment anyone is
 * actually paying attention.
 *
 * <p>Every method is called on the Swing thread, from a button, a dropdown or
 * RuneLite's own activate and deactivate. None of them may block: the
 * implementations hand the work to the net thread and return.
 */
interface PanelActions
{
	/** "Send now" on the Activity tab. */
	void sendNow();

	/** "Try again" beside the set-aside count on the Activity tab. */
	void retrySetAside();

	/** "Reconnect" on the Account tab. */
	void reconnect();

	/** The journal picker changed. */
	void accountChosen();

	/** The watchlist picker changed. */
	void watchlistChosen();

	/** "View item", or an item's name on the Watchlists tab. */
	void openItem(int itemId);

	/** "Remove" beside a watchlist item. */
	void removeItem(int itemId);

	/** "Find flips" on the Watchlists tab. */
	void findFlips();

	/**
	 * "Close" on an open position, with the sale the user typed.
	 *
	 * @param sellQty how many were sold, or null for everything still held
	 */
	void closePosition(String positionId, long sellPrice, @Nullable Long sellQty);

	/** "Delete" on an open position. The panel has already asked the user. */
	void deletePosition(String positionId);

	/** The sidebar opened on this panel. */
	void shown();

	/** The sidebar closed, or moved off this panel. */
	void hidden();
}

package com.flippingrs;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.IntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.widgets.Widget;

/**
 * Reads the Grand Exchange history screen off its widgets.
 *
 * <p>The history is the one place the game shows offers that completed while
 * the plugin was not watching, so it is worth reading, but it is a screen and
 * not an API. Each row is three text widgets on one line -- "Sold:",
 * "Irit seedx 6", "438 coins(444 - 6)= 73 each" -- and an item icon that sits
 * at a slightly different height and, in the widget list, sometimes before
 * its texts and sometimes after. So nothing here depends on order: the texts
 * are grouped by their exact line, and each icon is attached to the nearest
 * line by height. The side is whichever of "Bought" or "Sold" appears, the
 * quantity is the "x N" on the name, or one when there is none, and the gp is
 * the figure before tax where the breakdown is shown, else the figure next to
 * "coins". A row that does not yield all four is skipped and logged rather
 * than sent half-read, because a half-read trade is worse than a missing one.
 *
 * <p>What the server does with the rows is its business: it knows which
 * completed offers it already has, and the plugin does not.
 */
@Slf4j
class GeHistoryReader
{
	/** "438 coins(444 - 6)": the net, then the gross and the tax it was cut by. */
	private static final Pattern BREAKDOWN = Pattern.compile(
		"([\\d,]+)\\s*coins?\\s*\\(\\s*([\\d,]+)\\s*-\\s*([\\d,]+)\\s*\\)", Pattern.CASE_INSENSITIVE);
	private static final Pattern COINS = Pattern.compile("([\\d,]+)\\s*(?:coins?|gp)", Pattern.CASE_INSENSITIVE);
	/** "= 73 each" */
	private static final Pattern EACH = Pattern.compile("=\\s*([\\d,]+)\\s*each", Pattern.CASE_INSENSITIVE);
	/** "Irit seedx 6", "Bought x 25" */
	private static final Pattern QUANTITY = Pattern.compile("x\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern NUMBER = Pattern.compile("[\\d,]{2,}");

	/** Jagex's colour and formatting tags, which are not part of the text. */
	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern NOT_DIGIT = Pattern.compile("[^0-9]");

	/**
	 * How far, in pixels, an icon may sit from the line it belongs to. Rows
	 * are a good deal taller than this, so the nearest line is the right one
	 * and an icon with no line that close belongs to nothing.
	 */
	private static final int ICON_REACH = 30;

	/**
	 * Reads every parseable row of the list widget, top to bottom.
	 *
	 * @param list  the history list, or null if the screen is not open
	 * @param names resolves an item id to its name; client thread
	 */
	static List<HistoryRow> read(@Nullable Widget list, IntFunction<String> names)
	{
		final List<HistoryRow> out = new ArrayList<>();
		if (list == null)
		{
			return out;
		}
		final Widget[] children = list.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return out;
		}

		// Texts by their exact line, top to bottom; icons kept aside.
		final TreeMap<Integer, List<Widget>> lines = new TreeMap<>();
		final List<Widget> icons = new ArrayList<>();
		for (Widget child : children)
		{
			if (child == null || child.isSelfHidden())
			{
				continue;
			}
			if (child.getItemId() > 0)
			{
				icons.add(child);
			}
			else if (child.getText() != null && !child.getText().isEmpty())
			{
				lines.computeIfAbsent(child.getRelativeY(), y -> new ArrayList<>()).add(child);
			}
		}

		// Each icon joins the line nearest to it by height. The icon is not on
		// the texts' line, but it is far closer to its own row than to the
		// next.
		//
		// Two icons can still land on one line: a row whose texts are all
		// hidden has no line of its own, so its icon goes looking and settles
		// on the next row's. That row's own icon is nearer, and is the one to
		// keep -- taking whichever was seen first would report the row against
		// an item the player never touched, which is a good deal worse than
		// the loose row being skipped.
		final Map<Integer, Widget> iconByLine = new TreeMap<>();
		for (Widget icon : icons)
		{
			final Integer line = nearestLine(lines, icon.getRelativeY());
			if (line == null)
			{
				continue;
			}
			final Widget held = iconByLine.get(line);
			if (held == null
				|| Math.abs(line - icon.getRelativeY()) < Math.abs(line - held.getRelativeY()))
			{
				iconByLine.put(line, icon);
			}
		}

		int position = 0;
		for (Map.Entry<Integer, List<Widget>> line : lines.entrySet())
		{
			final HistoryRow row = parse(iconByLine.get(line.getKey()), line.getValue(), names);
			if (row == null)
			{
				continue;
			}
			row.position = position++;
			out.add(row);
		}
		return out;
	}

	/**
	 * Whether the list has any item icons on it at all: the difference
	 * between an empty history and one the reader could not make sense of.
	 */
	static boolean showsItems(@Nullable Widget list)
	{
		final Widget[] children = list == null ? null : list.getDynamicChildren();
		if (children == null)
		{
			return false;
		}
		for (Widget child : children)
		{
			if (child != null && child.getItemId() > 0 && !child.isSelfHidden())
			{
				return true;
			}
		}
		return false;
	}

	@Nullable
	private static Integer nearestLine(TreeMap<Integer, List<Widget>> lines, int y)
	{
		final Integer below = lines.ceilingKey(y);
		final Integer above = lines.floorKey(y);
		Integer best = null;
		int distance = Integer.MAX_VALUE;
		for (Integer candidate : new Integer[]{above, below})
		{
			if (candidate != null && Math.abs(candidate - y) < distance)
			{
				best = candidate;
				distance = Math.abs(candidate - y);
			}
		}
		return distance <= ICON_REACH ? best : null;
	}

	@Nullable
	private static HistoryRow parse(@Nullable Widget icon, List<Widget> line, IntFunction<String> names)
	{
		final int itemId = icon == null ? 0 : icon.getItemId();
		final long iconQuantity = icon == null ? 0 : icon.getItemQuantity();
		long textQuantity = 0;
		// The text the "x N" was read off, if any. See the fallback below.
		String countedOn = null;
		String side = null;
		long gross = 0;
		long each = 0;
		final List<String> texts = new ArrayList<>();

		for (Widget w : line)
		{
			final String plain = stripTags(w.getText());
			if (plain.isEmpty())
			{
				continue;
			}
			texts.add(plain);
			// Locale.ROOT, not the machine's. A default-locale fold is a rule
			// about where the client is running rather than about the text:
			// the Turkish one maps I to a dotless i, so a word looked for with
			// an I in it would stop being found on a screen that had not
			// changed. Neither word has one today, and which words these are
			// is not a thing for a machine's language settings to have a say
			// in either way.
			final String lower = plain.toLowerCase(Locale.ROOT);
			if (side == null && lower.contains("bought"))
			{
				side = "buy";
			}
			else if (side == null && lower.contains("sold"))
			{
				side = "sell";
			}
			// The gp that moved is the figure before tax. A sale shows
			// "438 coins(444 - 6)": 444 changed hands and 6 of it was tax,
			// which the server works out for itself from the sale price. A
			// buy has no tax and shows the one figure.
			//
			// Each matcher is built only if its figure is still wanted. Four
			// per text widget, built and thrown away whether or not they were
			// consulted, is work the client thread does not need.
			if (gross == 0)
			{
				gross = firstNumber(BREAKDOWN, plain, 2);
			}
			if (gross == 0)
			{
				gross = firstNumber(COINS, plain, 1);
			}
			if (each == 0)
			{
				each = firstNumber(EACH, plain, 1);
			}
			if (textQuantity == 0)
			{
				final long counted = firstNumber(QUANTITY, plain, 1);
				if (counted > 0)
				{
					textQuantity = counted;
					countedOn = plain;
				}
			}
		}

		if (gross == 0)
		{
			// No "coins" label. Fall back to the largest number on the line;
			// a price is always the biggest figure.
			//
			// Except on the text the item count came off, whose numbers are
			// that count. A layout that put the name and the side together but
			// the price somewhere else would otherwise leave "Abyssal whipx 10"
			// as the only numbers on the line, and this would report a purchase
			// of ten whips for ten coins -- all four facts present, every one
			// of them read, and the trade wrong. A row that cannot be read is
			// meant to be skipped, and skipping is what happens when the only
			// numbers left are the ones already spoken for.
			for (String text : texts)
			{
				if (text.equals(countedOn))
				{
					continue;
				}
				final Matcher n = NUMBER.matcher(text);
				while (n.find())
				{
					gross = Math.max(gross, digits(n.group()));
				}
			}
		}

		// The "x N" on the name is the offer's quantity. A name without one is
		// a single item -- "Ruby bolts (e)" alone -- which the icon's stack or
		// the total over the per-item price confirms when either is there.
		long quantity = textQuantity;
		if (quantity <= 0 && iconQuantity > 1)
		{
			quantity = iconQuantity;
		}
		if (quantity <= 0 && each > 0 && gross > 0)
		{
			quantity = Math.max(1, Math.round((double) gross / each));
		}
		if (quantity <= 0 && gross > 0)
		{
			quantity = 1;
		}

		if (itemId <= 0 || side == null || quantity <= 0 || gross <= 0)
		{
			if (!texts.isEmpty() || itemId > 0)
			{
				log.debug("could not read a history row: item {} texts {}", itemId, texts);
			}
			return null;
		}

		final HistoryRow row = new HistoryRow();
		row.itemId = itemId;
		row.itemName = names.apply(itemId);
		row.side = side;
		row.quantity = quantity;
		row.grossValue = gross;
		return row;
	}

	/** The given group of the first match, as a number, or 0 if it does not match. */
	private static long firstNumber(Pattern pattern, String text, int group)
	{
		final Matcher matcher = pattern.matcher(text);
		return matcher.find() ? digits(matcher.group(group)) : 0;
	}

	private static long digits(String s)
	{
		final String clean = NOT_DIGIT.matcher(s).replaceAll("");
		if (clean.isEmpty())
		{
			return 0;
		}
		try
		{
			return Long.parseLong(clean);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static String stripTags(@Nullable String text)
	{
		return text == null ? "" : TAG.matcher(text).replaceAll("").trim();
	}
}

