package com.flippingrs;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;

/**
 * Where the Grand Exchange is showing an item, wherever that happens to be.
 *
 * <p>The exchange is not one screen but eight or nine, and an item can be on
 * any of them: the offer boxes, the page you set an offer up on, the page you
 * get when you click one you have already placed, your history, the collection
 * box, the inventory beside it all, another player's offers in a view-only
 * exchange, and the price checker. Anything that wants to say something about
 * an item -- a right-click entry, a price drawn on it -- needs the same answer
 * from all of them, and asking each screen its own way is how one of them ends
 * up quietly missed.
 *
 * <p>So the answer is worked out once, here, in the way that does not depend
 * on a screen's layout: the client tells a widget which item it is drawing,
 * and this reads that off whichever widgets the exchange currently has up. The
 * two exceptions are the ones where no widget carries the item -- the eight
 * offer boxes, where it comes from the client's own record of the offer, and
 * the setup page, where it comes from the varp that page is driven by.
 *
 * <p>Client thread. {@link #onScreen} runs once a frame, so it walks a fixed
 * and short list of containers rather than the whole widget tree.
 */
final class GeItems
{
	/**
	 * How many items to report at once. The price checker can hold a full
	 * inventory and the history a long list, and past a certain point the
	 * screen is too crowded to read anyway -- but the real reason for a bound
	 * is that this list decides how many items a price is asked for.
	 */
	private static final int MAX_SPOTS = 40;

	private GeItems()
	{
	}

	/** One item the exchange is drawing, and the box it is drawn in. */
	static final class Spot
	{
		final int itemId;
		final Rectangle bounds;
		/**
		 * The offer this box is showing, when the box is one of the eight
		 * slots. Null everywhere else, where there is an item but no offer of
		 * yours on it and so nothing to compare a price against.
		 */
		@Nullable
		final GrandExchangeOffer offer;

		/**
		 * The box this one is drawn inside, when it is drawn inside another.
		 *
		 * <p>Some of these screens scroll. A row scrolled out of its list is
		 * not hidden -- the client keeps its position and lets the list clip
		 * it -- so its bounds are a real rectangle somewhere outside the list,
		 * and anything drawn there lands on whatever the exchange has put
		 * above or below. The list's own box is carried along so that whatever
		 * uses a spot can clip to it the way the client does.
		 */
		@Nullable
		final Rectangle clip;

		Spot(int itemId, Rectangle bounds, @Nullable GrandExchangeOffer offer, @Nullable Rectangle clip)
		{
			this(itemId, bounds, offer, clip, true);
		}

		Spot(int itemId, Rectangle bounds, @Nullable GrandExchangeOffer offer, @Nullable Rectangle clip,
			boolean paint)
		{
			this.itemId = itemId;
			this.bounds = bounds;
			this.offer = offer;
			this.clip = clip;
			this.paint = paint;
		}

		/**
		 * Whether this spot is worth drawing on.
		 *
		 * <p>False for the offer setup page, whose prices are written into the
		 * screen itself. It is still a spot, because it is still an item the
		 * exchange is showing and so still an item worth having a price for --
		 * but painting one on it as well would put the same numbers on the
		 * same screen twice.
		 */
		final boolean paint;

		/** Whether a point is on this spot, and inside the list holding it. */
		boolean contains(int x, int y)
		{
			return bounds.contains(x, y) && (clip == null || clip.contains(x, y));
		}
	}

	/**
	 * Every item the exchange has on screen right now.
	 *
	 * <p>The offer boxes come first and carry their offer, because those are
	 * the ones something useful can be said about beyond the price. The rest
	 * follow in whatever order the screens are listed in, which is stable
	 * because the list of screens is -- and that order is what decides the
	 * answer when two boxes overlap, so the more specific screens come first.
	 */
	static List<Spot> onScreen(Client client)
	{
		final List<Spot> spots = new ArrayList<>();
		offerSlots(client, spots);
		setupPage(client, spots);
		// The page you get by clicking an offer you have already placed. Not
		// painted on, for the same reason the setup page is not: GeOfferText
		// writes this screen's prices into the screen itself.
		collect(client.getWidget(InterfaceID.GeOffers.DETAILS), spots, false, false);
		for (int container : CONTAINERS)
		{
			collect(client.getWidget(container), spots, false, true);
		}
		for (int container : ROW_LISTS)
		{
			collect(client.getWidget(container), spots, true, false);
		}
		return spots;
	}

	/**
	 * The item the mouse is over, or -1.
	 *
	 * <p>For the right-click menu, which needs an answer on screens whose rows
	 * have no menu entry of their own to hang one off: a history row is
	 * display only, so the menu over it says nothing about where it was
	 * opened.
	 */
	static int under(Client client, @Nullable Point mouse)
	{
		if (mouse == null)
		{
			return -1;
		}
		for (Spot spot : onScreen(client))
		{
			if (spot.contains(mouse.getX(), mouse.getY()))
			{
				return spot.itemId;
			}
		}
		return -1;
	}

	/**
	 * The containers walked for items, one per screen the exchange can show.
	 *
	 * <p>Every one of these draws its items on child widgets that carry the
	 * item id, so they need no special handling: a screen added to this list
	 * gets right-click entries and prices at the same time. The offer boxes
	 * and the setup page are not here because on those the client does not put
	 * the item on the widget.
	 */
	private static final int[] CONTAINERS = {
		// The collection box, both of its slots.
		InterfaceID.GeCollect.COLLECT_0,
		InterfaceID.GeCollect.COLLECT_1,
		InterfaceID.GeCollect.COLLECT_2,
		InterfaceID.GeCollect.COLLECT_3,
		InterfaceID.GeCollect.COLLECT_4,
		InterfaceID.GeCollect.COLLECT_5,
		InterfaceID.GeCollect.COLLECT_6,
		// Another player's offers, in a view-only exchange.
		InterfaceID.GeViewonly.VIEW_0,
		InterfaceID.GeViewonly.VIEW_1,
		InterfaceID.GeViewonly.VIEW_2,
		InterfaceID.GeViewonly.VIEW_3,
		InterfaceID.GeViewonly.VIEW_4,
		InterfaceID.GeViewonly.VIEW_5,
		InterfaceID.GeViewonly.VIEW_6,
		InterfaceID.GeViewonly.VIEW_7,
		// The price checker.
		InterfaceID.GePricechecker.ITEMS,
		// The inventory beside the exchange.
		InterfaceID.GeOffersSide.ITEMS,
	};

	/**
	 * Containers whose children are rows across the whole width rather than
	 * boxes, and which write their own prices.
	 *
	 * <p>A history row carries its item on a narrow icon at the left, but the
	 * row is the width of the list: the icon's height is the row's height and
	 * nothing else in the row says which item it is. So the icon's box is
	 * widened to the list's, which is the area a right-click has to count as
	 * being on that row. Treating the icon as the whole target meant only a
	 * click on the picture itself found the item.
	 *
	 * <p>Not painted on. These lists scroll, and paint on a scrolling list has
	 * to work out for itself which rows are visible and clip to the viewport;
	 * {@link GeHistoryText} puts a child in the list instead and lets the
	 * client do both. The rows are still reported, because a right-click still
	 * needs to find them and their prices still need fetching.
	 */
	private static final int[] ROW_LISTS = {
		InterfaceID.GeHistory.LIST,
	};

	/**
	 * The eight offer boxes.
	 *
	 * <p>The slot widgets do not carry an item id, so the item comes from the
	 * client's own record of the offer -- which is also what makes these the
	 * only spots that know what you asked for as well as what it is.
	 */
	private static void offerSlots(Client client, List<Spot> into)
	{
		final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		for (int slot = 0; slot < SLOTS.length && slot < offers.length; slot++)
		{
			final GrandExchangeOffer offer = offers[slot];
			if (offer == null || offer.getState() == null
				|| offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}
			final Rectangle bounds = boundsOf(client.getWidget(SLOTS[slot]));
			if (bounds != null)
			{
				// Not painted on: GeSlotText adds to the slot's own text.
				// Reported all the same, so a right-click finds the item and a
				// price is fetched for it.
				into.add(new Spot(offer.getItemId(), bounds, offer, null, false));
			}
		}
	}

	/** The eight slot widgets, in slot order. */
	static final int[] SLOTS = {
		InterfaceID.GeOffers.INDEX_0,
		InterfaceID.GeOffers.INDEX_1,
		InterfaceID.GeOffers.INDEX_2,
		InterfaceID.GeOffers.INDEX_3,
		InterfaceID.GeOffers.INDEX_4,
		InterfaceID.GeOffers.INDEX_5,
		InterfaceID.GeOffers.INDEX_6,
		InterfaceID.GeOffers.INDEX_7,
	};

	/**
	 * The one item a screen of the exchange is about, or 0.
	 *
	 * <p>For the screens that show a single item rather than a grid of them.
	 * The client puts the id on a widget there, so which item it is need not
	 * be worked out from the slot the offer is in -- which is just as well,
	 * because the status page does not say which slot that was.
	 */
	static int itemIn(Client client, int container)
	{
		final List<Spot> spots = new ArrayList<>();
		collect(client.getWidget(container), spots, false, false);
		return spots.isEmpty() ? 0 : spots.get(0).itemId;
	}

	/**
	 * The offer setup page, whose item comes from the varp that drives it --
	 * the same one RuneLite's own exchange plugin reads to put the buy limit
	 * on that page.
	 */
	private static void setupPage(Client client, List<Spot> into)
	{
		final Rectangle bounds = boundsOf(client.getWidget(InterfaceID.GeOffers.SETUP));
		if (bounds == null)
		{
			return;
		}
		final int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId > 0)
		{
			// Not painted on: GeOfferText writes this screen's prices into the
			// screen. Reported all the same, so a price is fetched for it.
			into.add(new Spot(itemId, bounds, null, null, false));
		}
	}

	/**
	 * Every item drawn inside a container, the container itself included.
	 *
	 * <p>All three kinds of child, because which kind a screen uses is the
	 * screen's business: a history row is a dynamic child, an inventory slot
	 * is a static one, and a nested component can be either. Looking at only
	 * one kind is how a screen ends up silently missed.
	 */
	private static void collect(@Nullable Widget container, List<Spot> into, boolean rows, boolean paint)
	{
		if (container == null || container.isHidden() || into.size() >= MAX_SPOTS)
		{
			return;
		}
		final Rectangle inside = boundsOf(container);
		final Rectangle across = rows ? inside : null;
		// The container itself is not clipped by itself.
		add(container, into, across, null, paint);
		for (Widget[] children : new Widget[][]{
			container.getDynamicChildren(), container.getStaticChildren(), container.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (into.size() >= MAX_SPOTS)
				{
					return;
				}
				if (child == null || child.isHidden())
				{
					continue;
				}
				add(child, into, across, inside, paint);
			}
		}
	}

	/**
	 * Keeps a widget that is drawing an item, ignoring one that is not.
	 *
	 * @param across the list this widget is a row of, if it is one, so the
	 *               row's box spans the list's width rather than the icon's
	 * @param clip   the container drawing it, so a row scrolled out of a list
	 *               is not treated as being where its bounds say it is
	 * @param paint  whether this screen wants a price painted on it, or writes
	 *               its own
	 */
	private static void add(Widget widget, List<Spot> into, @Nullable Rectangle across,
		@Nullable Rectangle clip, boolean paint)
	{
		final int itemId = widget.getItemId();
		if (itemId <= 0)
		{
			return;
		}
		final Rectangle bounds = boundsOf(widget);
		if (bounds == null)
		{
			return;
		}
		into.add(new Spot(itemId,
			across == null ? bounds : new Rectangle(across.x, bounds.y, across.width, bounds.height),
			null, clip, paint));
	}

	/** A widget's box on the canvas, or null if it has none worth drawing in. */
	@Nullable
	private static Rectangle boundsOf(@Nullable Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		final Rectangle bounds = widget.getBounds();
		return bounds == null || bounds.width <= 0 || bounds.height <= 0 ? null : bounds;
	}
}

package com.flippingrs;

import javax.annotation.Nullable;

/** One open Grand Exchange slot, as the client reports it, for the server to reconcile against. */
public class OfferState
{
	int slot;
	/** The plugin's reference for this offer, so the server can find its fills. Null if none yet. */
	@Nullable
	String offerRef;
	int itemId;
	String itemName;
	String side;
	long price;
	long totalQuantity;
	long quantitySold;
	/** The client's running total, an int that can wrap; see spentEstimated. */
	long spent;
	boolean spentEstimated;
	String state;
}

package com.flippingrs;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.ui.ColorScheme;

/**
 * Getting the queued fills to flippingrs.com, and saying what became of them.
 *
 * <p>This is where the plugin's three promises are actually kept. Fills are
 * held on disk by {@link TransactionQueue} until the server confirms them, so
 * a dropped connection costs nothing; every fill carries an id the server
 * de-duplicates on, so a retry is free; and a batch the server refuses for
 * good is set aside in a file rather than dropped, so nothing is ever lost
 * without somebody being told where it went.
 *
 * <p>One queue per RuneScape account, because which FlippingRS journal a trade
 * belongs to is remembered per account: a main's fills and an alt's cannot go
 * in the same batch or under the same id.
 *
 * <p>Net thread. {@link #drain} never throws, because the plugin runs it as a
 * fixed-delay task and an exception escaping one of those cancels it for
 * good -- the plugin would go quiet with nothing in the log to say why.
 */
@Slf4j
final class TransactionSender
{
	/** Matches the server's cap on one ingest call. */
	private static final int MAX_BATCH = 500;

	private final Client client;
	private final FlippingRsConfig config;
	private final ProfileStore store;
	private final Supplier<FlippingRsApi> api;
	private final PanelUpdates panel;
	private final Gson gson;
	/** Where the pending-queue files live: RuneLite's folder, or a test's. */
	private final File queueDir;
	/** What a successful send sets going, when anyone can see the result. Net thread. */
	private final Runnable afterSend;
	/** Whether the client or the plugin is stopping, so a send is the last thing worth doing. */
	private final BooleanSupplier shuttingDown;
	/** How many fills have been captured this session, for the Activity tab's count. */
	private final IntSupplier recordedThisSession;
	/** Gets the user's attention when a trade could not be recorded. */
	private final Consumer<String> notifier;

	/**
	 * Pending fills, one queue per RuneScape account.
	 *
	 * <p>Separate queues because the FlippingRS journal a trade belongs to is
	 * remembered per RuneScape account, so a main's fills and an alt's cannot be
	 * sent in the same batch or under the same id. It also stops two clients
	 * logged into two accounts overwriting each other's file.
	 */
	private final Map<Long, TransactionQueue> queues = new ConcurrentHashMap<>();

	/**
	 * Guards the sender against re-entry. Every drain -- the scheduled tick,
	 * the panel's button, the offer and history catch-ups, shutdown -- runs on
	 * the plugin's net executor, which has one thread, so today this is never
	 * contended. It stays because the invariant it protects matters: two
	 * threads draining the same queue would send the same batch twice, and
	 * while the server would drop the repeat, the panel's counts would be
	 * nonsense. A future caller on another thread hits this rather than that.
	 */
	private final AtomicBoolean sending = new AtomicBoolean();

	@Nullable
	// Written on the net thread, read on the Swing thread. Without volatile the
	// panel can keep showing a stale "last sent" indefinitely.
	private volatile Instant lastSyncAt;

	/**
	 * The account hashes with a queue file, as the folder had them when this
	 * session first looked. Null until then. Net thread only.
	 */
	@Nullable
	private List<Long> scanned;

	TransactionSender(Client client, FlippingRsConfig config, ProfileStore store, Supplier<FlippingRsApi> api,
		PanelUpdates panel, Gson gson, File queueDir, Runnable afterSend, BooleanSupplier shuttingDown,
		IntSupplier recordedThisSession, Consumer<String> notifier)
	{
		this.client = client;
		this.config = config;
		this.store = store;
		this.api = api;
		this.panel = panel;
		this.gson = gson;
		this.queueDir = queueDir;
		this.afterSend = afterSend;
		this.shuttingDown = shuttingDown;
		this.recordedThisSession = recordedThisSession;
		this.notifier = notifier;
	}

	/**
	 * Forgets what belonged to the last time the plugin ran. The queues are
	 * deliberately kept: they are what is on disk for each account, and
	 * re-reading every file on a disable-and-enable would be work for nothing.
	 */
	void newSession()
	{
		lastSyncAt = null;
		// Looked for again, because a queue file may have appeared since: a
		// second client, or this one while the plugin was switched off.
		scanned = null;
	}

	@Nullable
	Instant lastSyncAt()
	{
		return lastSyncAt;
	}

	TransactionQueue queueFor(long accountHash)
	{
		return queues.computeIfAbsent(accountHash,
			hash -> new TransactionQueue(gson, new File(queueDir, "queue-" + hash + ".json")));
	}

	/**
	 * Sends whatever is waiting, for every account that has anything waiting.
	 *
	 * <p>The account that is logged in first, because that is the one whose
	 * trades are happening now and whose panel is showing the result. Then any
	 * other account with a queue on disk: an alt played while the network was
	 * down, or before a key was entered, leaves fills behind, and they used to
	 * sit there until that character next logged in -- which for a retired alt
	 * is never. The journal each queue files under is remembered per account
	 * rather than per RuneScape profile precisely so that this is answerable
	 * while somebody else is logged in.
	 *
	 * <p>Never throws. The plugin runs it as a {@code scheduleWithFixedDelay}
	 * task, and an exception escaping such a task cancels it for good -- the
	 * plugin would go quiet with nothing in the log to say why.
	 */
	void drain()
	{
		// The claim above that this never throws has to hold for every line of
		// it, so the only thing outside the try is the one statement that
		// cannot throw. Reading a setting goes through a config proxy, and an
		// exception from that used to escape and cancel the schedule.
		if (!sending.compareAndSet(false, true))
		{
			return;
		}
		try
		{
			// Checked before anything else, and before connect's equivalent
			// check, because "Record trades" being off is a promise that the
			// plugin is not talking to flippingrs.com at all -- not merely that
			// it has stopped capturing. Anything already queued stays on disk
			// and goes out when recording is turned back on; it was captured
			// while the user wanted it recorded, so discarding it would be its
			// own kind of surprise.
			if (!config.enabled())
			{
				return;
			}
			final String key = FlippingRsApi.trimmedKey(config.apiKey());
			if (key.isEmpty())
			{
				panel.onPanel(p -> p.setStatus(
					"No API key yet. Add one in the plugin settings. Your trades are being kept safe until you do.",
					ColorScheme.BRAND_ORANGE));
				return;
			}

			final long loggedIn = client.getAccountHash();
			if (loggedIn != FlippingRsPlugin.NO_ACCOUNT)
			{
				// The one whose panel is on screen, so it reports.
				drainOne(loggedIn, key, true);
			}
			for (long accountHash : otherAccounts(loggedIn))
			{
				// Nobody is looking at these, and no panel line would be true
				// of them, so they go out quietly.
				drainOne(accountHash, key, false);
			}
		}
		catch (IOException e)
		{
			// Worth retrying: the batch stays queued for the next tick.
			log.debug("could not send to flippingrs.com; will retry", e);
			final String why = FlippingRsApi.describe(e);
			panel.onPanel(p -> p.setLastSync(null, why));
		}
		catch (RuntimeException e)
		{
			log.warn("unexpected failure while sending", e);
			panel.onPanel(p -> p.setLastSync(null, "Something went wrong while sending. Details are in the client log."));
		}
		finally
		{
			sending.set(false);
		}
	}

	/**
	 * Sends one account's queue.
	 *
	 * @param reporting whether what happened is worth putting on the panel.
	 *                  True only for the account that is logged in: the counts,
	 *                  the buffer and "last sent" are all that account's, and
	 *                  filling them in from an alt's backlog would describe a
	 *                  character the user is not playing.
	 */
	private void drainOne(long accountHash, String key, boolean reporting) throws IOException
	{
		final TransactionQueue queue = queueFor(accountHash);
		if (queue.isEmpty())
		{
			return;
		}
		final String accountId = store.chosenAccountFor(accountHash);
		if (accountId == null)
		{
			if (reporting)
			{
				panel.onPanel(p -> p.setStatus(
					"No journal chosen for this character yet. Pick one on the Account tab. Your trades are being "
						+ "kept safe until you do.",
					ColorScheme.BRAND_ORANGE));
			}
			// For an account nobody is logged into this is not worth saying
			// anything about: it was never given a journal, and it cannot be
			// given one until it is played again.
			return;
		}

		final List<GeTransaction> batch = queue.peek(MAX_BATCH);

		final Sent sent = new Sent();
		attempt(queue, key, accountId, batch, sent);

		if (sent.accepted > 0)
		{
			lastSyncAt = Instant.now();
		}
		final int waiting = queue.size();
		final List<GeTransaction> buffered = queue.newest(FlippingRsPanel.RECENT_SHOWN);

		log.debug("sent {} fills for account {}: {} flips opened, {} closed, {} unmatched",
			sent.accepted, accountHash, sent.flipsOpened, sent.flipsClosed, sent.unmatchedSellQty);

		// A 200 can still refuse individual rows, and the batch is dropped
		// from the queue regardless -- so if this is not surfaced here, the
		// trade is gone and nobody is ever told. Silently losing one is far
		// worse than a blunt warning, because the journal then disagrees
		// with what the player remembers doing and nothing explains why.
		if (sent.rejected > 0)
		{
			log.warn("flippingrs.com refused {} of {} fills: {}", sent.rejected, batch.size(), sent.problems);
		}
		if (sent.setAside > 0)
		{
			log.warn("set aside {} fills that flippingrs.com will not accept; they are in {}",
				sent.setAside, queue.droppedFile(), sent.cause);
		}

		// Only for the account being played. What this sets going -- a snapshot
		// of the open slots, and a re-read of the two journal tabs -- is all
		// about the character that is logged in, and none of it describes the
		// alt whose backlog just went out. Firing it for one would spend two
		// requests re-reading a journal that has not changed, and take a slot
		// snapshot of somebody else's exchange.
		if (reporting && sent.accepted > 0 && !shuttingDown.getAsBoolean())
		{
			afterSend.run();
		}

		// Said out loud, whichever account it was and whether or not anyone is
		// looking at the sidebar. A trade that did not reach the journal is
		// the one thing here that silence actively harms: the numbers are
		// wrong from then on and nothing on screen explains why.
		if (sent.setAside > 0)
		{
			notifier.accept("FlippingRS couldn't record " + sent.setAside
				+ " trade(s). They have been set aside so nothing is lost -- see the Activity tab.");
		}
		else if (sent.rejected > 0)
		{
			notifier.accept("FlippingRS couldn't record " + sent.rejected
				+ " trade(s), and they won't be sent again. See the Activity tab.");
		}

		if (!reporting)
		{
			return;
		}

		final Instant syncedAt = lastSyncAt;
		final String droppedFile = whereItIs(queue.droppedFile());
		final int stillAside = queue.setAsideCount();
		panel.onPanel(p -> {
			p.setCounts(recordedThisSession.getAsInt(), waiting);
			p.setPending(buffered);
			p.setSetAside(stillAside);
			if (sent.accepted > 0)
			{
				p.setLastSync(syncedAt, null);
				p.setStatus("Connected and recording.", ColorScheme.PROGRESS_COMPLETE_COLOR);
			}
			else
			{
				p.setLastSync(null, FlippingRsApi.describe(sent.cause));
			}
			if (sent.setAside > 0)
			{
				p.setActivityNotice("flippingrs.com couldn't accept " + sent.setAside + " trade(s). They have been "
					+ "set aside in " + droppedFile + " in your RuneLite folder so nothing is lost. The client log "
					+ "says why.", ColorScheme.PROGRESS_ERROR_COLOR);
			}
			else if (sent.rejected > 0)
			{
				// Not "set aside": the reply says how many rows it refused, not
				// which, so there is nothing to file. This notice is the only
				// time anybody is told, so it has to say that they are gone.
				p.setActivityNotice("flippingrs.com couldn't record " + sent.rejected
					+ " trade(s), and they won't be sent again. The client log says why.",
					ColorScheme.PROGRESS_ERROR_COLOR);
			}
			else if (sent.unmatchedSellQty > 0)
			{
				p.setActivityNotice(sent.unmatchedSellQty
						+ " item(s) were sold without a recorded purchase, so they can't be counted as a flip yet.",
					ColorScheme.BRAND_ORANGE);
			}
			// A send with nothing to report leaves whatever is up alone.
			// Clearing here wiped every notice, and the one it wiped most
			// reliably was the explanation of an adopted offer: adopting
			// queues a recovered fill, so the very next send is the one
			// carrying it, and it removed the sentence saying why that
			// trade has no purchase behind it. Every notice expires on its
			// own after twenty seconds, which is what that interval is for.
		});
	}

	/**
	 * Puts every account's set-aside fills back in its queue and sends them.
	 *
	 * <p>Nothing retries a permanent refusal on its own, and it should not:
	 * the server said this batch was bad, and asking again every thirty
	 * seconds would spend the rate limit to be told so. But the likeliest
	 * cause is not a bad row at all -- it is a key that was wrong, a journal
	 * that was not this owner's, or a plan that had lapsed -- and those are
	 * exactly the things a user goes and fixes. So this runs when one of them
	 * changes, and from a button on the Activity tab.
	 *
	 * <p>Safe however wrong the original guess was: every fill carries the id
	 * the server de-duplicates on, so a row that did land is dropped as a
	 * repeat rather than doubled.
	 */
	void retrySetAside()
	{
		int restored = 0;
		for (long accountHash : allAccounts())
		{
			restored += queueFor(accountHash).restoreSetAside();
		}
		if (restored == 0)
		{
			return;
		}
		final int count = restored;
		panel.onPanel(p -> p.setActivityNotice(
			"Put " + count + " set-aside trade(s) back in the queue to try again.", ColorScheme.BRAND_ORANGE));
		drain();
	}

	/** How many fills are set aside for the logged-in account, for the sidebar's offer. */
	int setAsideCount()
	{
		final long accountHash = client.getAccountHash();
		if (accountHash == FlippingRsPlugin.NO_ACCOUNT)
		{
			return 0;
		}
		return queueFor(accountHash).setAsideCount();
	}

	/** Every account with a queue, the logged-in one included. */
	private List<Long> allAccounts()
	{
		final long loggedIn = client.getAccountHash();
		final List<Long> all = new ArrayList<>(otherAccounts(loggedIn));
		if (loggedIn != FlippingRsPlugin.NO_ACCOUNT && !all.contains(loggedIn))
		{
			all.add(loggedIn);
		}
		return all;
	}

	/**
	 * The other accounts with a queue file, so a backlog left by a character
	 * nobody is playing still goes out.
	 *
	 * <p>The folder is read once a session. A queue file is only written for
	 * an account that has actually traded, so there are as many of these as
	 * the user has characters, and re-reading the folder on every tick to
	 * learn the same thing would be a directory listing every thirty seconds
	 * for the life of the client.
	 */
	private List<Long> otherAccounts(long loggedIn)
	{
		if (scanned == null)
		{
			scanned = scan();
		}
		final List<Long> out = new ArrayList<>();
		for (long hash : scanned)
		{
			if (hash != loggedIn)
			{
				out.add(hash);
			}
		}
		// A queue opened since the scan -- an account logged into this session
		// and then logged out of -- is known without it.
		for (Long hash : queues.keySet())
		{
			if (hash != loggedIn && !out.contains(hash))
			{
				out.add(hash);
			}
		}
		return out;
	}

	/** The account hashes with a queue file in the folder. Never null, possibly empty. */
	private List<Long> scan()
	{
		final List<Long> found = new ArrayList<>();
		final File[] files = queueDir.listFiles();
		if (files == null)
		{
			// No folder yet, which is every install that has not traded.
			return found;
		}
		for (File file : files)
		{
			final String name = file.getName();
			if (!name.startsWith("queue-") || !name.endsWith(".json"))
			{
				continue;
			}
			try
			{
				found.add(Long.parseLong(name.substring("queue-".length(), name.length() - ".json".length())));
			}
			catch (NumberFormatException e)
			{
				// Not one of ours, or a name that has been meddled with.
				log.debug("ignoring {} in the queue folder", name);
			}
		}
		return found;
	}

	/**
	 * Where to tell someone a set-aside file is, relative to the RuneLite
	 * folder the panel names.
	 *
	 * <p>The file sits in a subfolder, and naming it alone sent a user who had
	 * just been told nothing was lost to look in the wrong place -- from where
	 * the only reasonable conclusion is that it was.
	 */
	private static String whereItIs(File file)
	{
		final File folder = file.getParentFile();
		return folder == null ? file.getName() : folder.getName() + "/" + file.getName();
	}

	/** What one drain achieved, added up over however many sends it took. */
	private static final class Sent
	{
		/** Rows the server took, whatever it then made of them. */
		int accepted;
		/** Rows the server took and then refused individually, in a 200. They are gone. */
		int rejected;
		/** Rows set aside on disk after a refusal that retrying cannot fix. */
		int setAside;
		int flipsOpened;
		int flipsClosed;
		long unmatchedSellQty;
		final List<String> problems = new ArrayList<>();
		/** The last permanent refusal, for the panel and the log. */
		@Nullable
		FlippingRsApi.PermanentException cause;

		void took(int rows, IngestResult result)
		{
			accepted += rows;
			rejected += result.getRejected();
			flipsOpened += result.getFlipsOpened();
			flipsClosed += result.getFlipsClosed();
			unmatchedSellQty += result.getUnmatchedSellQty();
			problems.addAll(result.getProblems());
		}
	}

	/**
	 * Sends a batch, and goes looking for the rows at fault if the server
	 * refuses it for good. Retrying a refusal cannot help, and leaving it at
	 * the head of the queue would wedge every later trade behind it forever.
	 */
	private void attempt(TransactionQueue queue, String key, String accountId, List<GeTransaction> batch, Sent sent)
		throws IOException
	{
		if (!send(queue, key, accountId, batch, sent))
		{
			narrow(queue, key, accountId, batch, sent);
		}
	}

	/**
	 * One send of one batch. On a 2xx the rows are confirmed out of the queue
	 * and the result is added up.
	 *
	 * @return false if the server refused the batch for good, with the cause
	 *         recorded on {@code sent}; anything retryable propagates
	 */
	private boolean send(TransactionQueue queue, String key, String accountId, List<GeTransaction> batch, Sent sent)
		throws IOException
	{
		try
		{
			final IngestResult result = api.get().submit(key, accountId, batch);
			queue.confirm(batch);
			sent.took(batch.size(), result);
			return true;
		}
		catch (FlippingRsApi.PermanentException e)
		{
			sent.cause = e;
			return false;
		}
	}

	/**
	 * Finds the rows behind a refused batch and sets exactly those aside.
	 *
	 * <p>A 400 or 422 says the server will not take this batch. It does not
	 * say which row is at fault, and setting aside five hundred fills for one
	 * bad row is a lot of journal to lose. So a refused batch of more than one
	 * is split in half and each half sent on its own; one bad row is found in
	 * about nine rounds of that, and every good row goes through.
	 *
	 * <p>Both halves being refused is the case that has to be decided rather
	 * than assumed, because it has two readings. Either there is a bad row in
	 * each half, where halving further would save the good ones, or this is a
	 * batch that nothing will take -- a journal id that is not this owner's, a
	 * lapsed plan -- where halving further asks about every row to be told the
	 * same thing each time, and would spend the whole rate limit every sync
	 * for as long as the setting stays wrong.
	 *
	 * <p>So one row is sent on its own to tell them apart. If the server takes
	 * it, this is provably not a refusal of everything, and the halving carries
	 * on to find the bad rows and save the good ones beside them. If it does
	 * not, the blanket refusal is assumed and the batch is set aside whole,
	 * which is where this stopped before the probe existed. The probe costs one
	 * extra request in the case that ends in a set-aside anyway, and buys back
	 * every good row in the case that does not.
	 *
	 * <p>The batch is the one that was sent, not a fresh read of the queue.
	 * Fills arrive on the disk thread while a request is in flight, and peek
	 * returns from the head, so re-reading would set aside trades that had
	 * never been sent.
	 *
	 * @param batch a batch the server has just refused as a whole
	 */
	private void narrow(TransactionQueue queue, String key, String accountId, List<GeTransaction> batch, Sent sent)
		throws IOException
	{
		if (batch.size() <= 1)
		{
			setAside(queue, batch, sent);
			return;
		}
		final int mid = batch.size() / 2;
		final List<GeTransaction> first = batch.subList(0, mid);
		final List<GeTransaction> second = batch.subList(mid, batch.size());
		final boolean firstTaken = send(queue, key, accountId, first, sent);
		final boolean secondTaken = send(queue, key, accountId, second, sent);
		if (firstTaken && secondTaken)
		{
			// Both halves went through on their own, so what was refused was
			// the size of the whole rather than anything in it. Nothing is at
			// fault and nothing is set aside.
			return;
		}
		if (!firstTaken && !secondTaken)
		{
			if (first.size() == 1)
			{
				// The first half was already a single row sent on its own, and
				// it was refused: that row is bad on its own account, not
				// because of the company it was in. There is nothing left to
				// probe with, and the other half is still worth searching.
				setAside(queue, first, sent);
				narrow(queue, key, accountId, second, sent);
				return;
			}
			if (send(queue, key, accountId, first.subList(0, 1), sent))
			{
				// The server took a row out of this batch on its own, so it is
				// not refusing everything. There is a bad row in each half, and
				// the good rows around them are worth the requests.
				attempt(queue, key, accountId, first.subList(1, first.size()), sent);
				attempt(queue, key, accountId, second, sent);
				return;
			}
			setAside(queue, batch, sent);
			return;
		}
		if (!firstTaken)
		{
			narrow(queue, key, accountId, first, sent);
		}
		if (!secondTaken)
		{
			narrow(queue, key, accountId, second, sent);
		}
	}

	/**
	 * Takes refused fills out of the queue and onto the sibling file, where a
	 * user who is told a trade could not be recorded can still find it.
	 */
	private static void setAside(TransactionQueue queue, List<GeTransaction> batch, Sent sent)
	{
		queue.reject(batch);
		sent.setAside += batch.size();
	}
}

package com.flippingrs;

import java.util.function.Consumer;

/**
 * Hands a panel update to the Swing thread, if the panel still exists.
 *
 * <p>The plugin owns the panel and nulls it on shutdown; everything else only
 * ever asks for an update through this, so nothing but the plugin needs to
 * know whether there is a panel to update right now.
 */
@FunctionalInterface
interface PanelUpdates
{
	void onPanel(Consumer<FlippingRsPanel> action);
}

package com.flippingrs;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;

/**
 * What a tab's read returns. Every tab endpoint answers in this one shape,
 * filling only its own parts; the rest come back null, and the plugin
 * leaves what it was already showing alone. That is the difference
 * between "nothing changed" and "nothing there", and it is why the
 * getters here return null rather than an empty list.
 */
public class PanelData
{
	@Nullable
	Me me;
	@Nullable
	List<GameAccount> accounts;
	@Nullable
	List<GeTransaction> recentTransactions;
	@Nullable
	Analytics week;
	@Nullable
	Positions positions;
	@Nullable
	ClosedPositions closedPositions;
	@Nullable
	List<Watchlist> watchlists;
	@Nullable
	List<Quote> quotes;

	@Nullable
	public Me getMe()
	{
		return me;
	}

	/** Null if the part was not in the reply; otherwise never contains null. */
	@Nullable
	public List<GameAccount> getAccounts()
	{
		return accounts == null ? null : Wire.withoutNulls(accounts);
	}

	@Nullable
	public List<GeTransaction> getRecentTransactions()
	{
		return recentTransactions == null ? null : Wire.withoutNulls(recentTransactions);
	}

	@Nullable
	public Analytics getWeek()
	{
		return week;
	}

	@Nullable
	public ClosedPositions getClosedPositions()
	{
		return closedPositions;
	}

	@Nullable
	public Positions getPositions()
	{
		return positions;
	}

	@Nullable
	public List<Watchlist> getWatchlists()
	{
		return watchlists == null ? null : Wire.withoutNulls(watchlists);
	}

	/** The quotes keyed by item id, or null if the part was not in the reply. */
	@Nullable
	public Map<Integer, Quote> getQuotes()
	{
		if (quotes == null)
		{
			return null;
		}
		final Map<Integer, Quote> out = new LinkedHashMap<>();
		for (Quote quote : Wire.withoutNulls(quotes))
		{
			out.put(quote.id, quote);
		}
		return out;
	}
}

package com.flippingrs;

import java.util.ArrayList;
import java.util.List;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * The site's prices on each row of the Grand Exchange history, added to the
 * row's own text.
 *
 * <p>On the row's text rather than in a widget of this plugin's own, for the
 * same reason as the offer setup screen: a line the client wrote is already
 * placed, sized, scrolled and clipped by the list that owns it. A caption
 * placed alongside had to have its position worked out from the row's, which
 * is a guess about somebody else's layout -- and on a scrolling list it is a
 * guess that has to stay right through every scroll.
 *
 * <p>A row whose item has no price is left exactly as the game wrote it.
 *
 * <p>Client thread only.
 */
@Slf4j
class GeHistoryText
{
	/** How many rows to price. The history shows far fewer than this. */
	private static final int MAX_ROWS = 64;

	/** Colours, written as the game's own text renderer reads them. */
	private static final String MUTED = "9f9f9f";
	private static final String GOOD = "4caf50";
	private static final String BAD = "d32f2f";

	private final Client client;
	private final FlippingRsConfig config;
	private final IntFunction<Quote> quoteFor;

	/**
	 * One per row, in the order the rows come in. Each remembers the line it
	 * is adding to and what that line said before, so a list the client
	 * rewrites is added to once rather than again and again.
	 */
	private final List<Appended> rows = new ArrayList<>();

	GeHistoryText(Client client, FlippingRsConfig config, IntFunction<Quote> quoteFor)
	{
		this.client = client;
		this.config = config;
		this.quoteFor = quoteFor;
	}

	/**
	 * Brings the additions in line with the rows.
	 *
	 * <p>Called every tick the history is open, because the client rebuilds
	 * and rewrites this list freely and nothing announces it.
	 *
	 * <p>Never throws. It runs from the event bus on the game thread, where an
	 * exception becomes an uncaught plugin error on every tick.
	 */
	void update()
	{
		try
		{
			final Widget list = client.getWidget(InterfaceID.GeHistory.LIST);
			if (list == null || list.isHidden() || !config.setupOverlay())
			{
				reset();
				return;
			}
			final java.util.List<Widget> children = RowText.under(list);
			if (children.isEmpty())
			{
				reset();
				return;
			}
			int index = 0;
			for (Widget icon : children)
			{
				if (index >= MAX_ROWS)
				{
					break;
				}
				if (icon.getItemId() <= 0)
				{
					continue;
				}
				final Widget text = textOn(children, icon);
				if (text == null)
				{
					continue;
				}
				final Quote quote = quoteFor.apply(icon.getItemId());
				final Appended row = index < rows.size() ? rows.get(index) : add();
				if (quote == null)
				{
					// Nothing to say about this item, so its row is the game's.
					row.clear();
				}
				else
				{
					row.to(text, "<br>" + textFor(quote));
				}
				index++;
			}
			// A list that got shorter leaves rows with nothing to sit on.
			for (int i = index; i < rows.size(); i++)
			{
				rows.get(i).clear();
			}
		}
		catch (RuntimeException e)
		{
			log.debug("could not put prices on the history rows", e);
		}
	}

	/** Puts every row back the way the game had it. */
	void reset()
	{
		for (Appended row : rows)
		{
			try
			{
				row.clear();
			}
			catch (RuntimeException e)
			{
				log.debug("could not clear a history row", e);
			}
		}
	}

	private Appended add()
	{
		final Appended row = new Appended();
		rows.add(row);
		return row;
	}

	/**
	 * The line of text belonging to the row an item icon is on.
	 *
	 * <p>A row is not one widget: it is an icon and one or more pieces of text
	 * laid out at the same height, and only their positions say which belong
	 * together. The band is the icon's own height grown by half again, because
	 * a row's text is not always boxed to the same height as its picture --
	 * requiring it to start inside the icon exactly is what made this find
	 * nothing at all.
	 */
	@Nullable
	private static Widget textOn(java.util.List<Widget> children, Widget icon)
	{
		final int height = Math.max(1, icon.getHeight());
		final int slack = height / 2;
		return RowText.lastIn(children, icon.getRelativeY() - slack,
			icon.getRelativeY() + height + slack);
	}

	/**
	 * What one row gains: the two prices and the margin, which is what turns a
	 * list of what you did into a list of what would be worth doing again.
	 *
	 * <p>On its own line under the row's text rather than running on from it.
	 * A row already says what you did and for how much; the prices are a
	 * different thing being said about the same item, and reading them off the
	 * end of somebody else's sentence is harder than reading them off a line
	 * of their own.
	 *
	 * <p>Rounded rather than exact. The exact figures belong on the screen
	 * where a price is being typed, not on the one being read back.
	 *
	 * <p>Static, so the wording is pinned by a test rather than by running a
	 * client.
	 */
	static String textFor(Quote quote)
	{
		return colour("Buy ", MUTED) + colour(FlippingRsPanel.gp(quote.getBuyAt()), MUTED)
			+ colour("  Sell ", MUTED) + colour(FlippingRsPanel.gp(quote.getSellAt()), MUTED)
			+ colour("  ", MUTED)
			+ colour(FlippingRsPanel.signed(quote.getNetMargin()),
				quote.getNetMargin() >= 0 ? GOOD : BAD);
	}

	/** One run of text in one colour, as the game's own text renderer reads it. */
	static String colour(String text, String hex)
	{
		return "<col=" + hex + ">" + text + "</col>";
	}

	/** How many rows are being added to, for a test that has a client. */
	int countForTest()
	{
		return rows.size();
	}
}

package com.flippingrs;

// The panel's shared vocabulary: the layout helpers every tab builds
// rows out of, and the static text of a row, which the tests pin there.
import static com.flippingrs.FlippingRsPanel.*;

import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import java.awt.BorderLayout;
import java.awt.Color;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import javax.swing.Timer;

/**
 * The Watchlists tab: one of the owner's lists, priced.
 *
 * <p>The same quotes the offer screen draws, so the number in the sidebar
 * and the number over the price box are never two different answers.
 */
final class WatchlistTab extends SidebarTab
{
	private final JComboBox<Watchlist> watchlists = new JComboBox<>();
	private final JLabel watchlistNotice = new JLabel();
	private final Timer watchlistNoticeTimer = new Timer(FlippingRsPanel.NOTICE_SECONDS * 1000,
		e -> setWatchlistNotice(null, ColorScheme.LIGHT_GRAY_COLOR));
	private final JPanel watchlistItems = new JPanel();
	private final JButton findFlips = new JButton("Find flips");
	private List<FlippingRsPanel.WatchedItem> watched = new ArrayList<>();
	/** The live-offer line of each card, so one fill can update one line. */
	private final Map<Integer, JLabel> offerLines = new HashMap<>();
	@Nullable
	private String watchlistProblem;
	/** Why nothing is being read at all, if that is the case. The panel sets it. */
	@Nullable
	private String paused;
	private final JPanel body;
	private final PanelActions actions;

	/** Set while the picker's model is being replaced. See {@link AccountTab}. */
	private boolean repopulating;

	WatchlistTab(PanelActions actions)
	{
		this.actions = actions;
		final JPanel body = column();
		body.add(hint("One of your flippingrs.com watchlists, with live prices. Right-click an item in the "
			+ "Grand Exchange to add it."));
		watchlists.setAlignmentX(Component.LEFT_ALIGNMENT);
		watchlists.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		watchlists.setToolTipText("Which of your flippingrs.com watchlists to show. Right-clicking an item adds it here.");
		watchlists.addActionListener(e -> {
			if (!repopulating)
			{
				actions.watchlistChosen();
			}
		});
		body.add(watchlists);
		body.add(Box.createVerticalStrut(4));
		watchlistNotice.setFont(FontManager.getRunescapeSmallFont());
		watchlistNotice.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(watchlistNotice);
		body.add(Box.createVerticalStrut(4));
		watchlistItems.setLayout(new BoxLayout(watchlistItems, BoxLayout.Y_AXIS));
		watchlistItems.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(watchlistItems);
		body.add(Box.createVerticalStrut(8));
		findFlips.addActionListener(e -> actions.findFlips());
		findFlips.setToolTipText("Open the flip finder in your browser.");
		findFlips.setAlignmentX(Component.LEFT_ALIGNMENT);
		findFlips.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		body.add(findFlips);
		// The freshness line last, under everything it qualifies. Empty until
		// the first read, so it takes no room on a tab that has nothing yet.
		body.add(Box.createVerticalStrut(8));
		body.add(refreshLine());
		this.body = body;
	}

	@Override
	JPanel body()
	{
		return body;
	}

	/**
	 * The only tab whose next read is a scheduled thing, so the only one that
	 * can honestly count down to it.
	 *
	 * <p>The plugin's own constant, not a copy of the number: a cadence that
	 * changed in one place and not the other would leave the tab counting down
	 * to a moment that has already passed, or sitting at "due now" for fifteen
	 * seconds.
	 */
	@Override
	long refreshEverySeconds()
	{
		return FlippingRsPlugin.QUOTE_REFRESH_SECONDS;
	}

	@Override
	void onPaused(@Nullable String why)
	{
		paused = why;
		if (why != null)
		{
			watched = new ArrayList<>();
			watchlistProblem = null;
		}
		refresh();
	}

	/**
	 * Replaces the watchlist picker. The selection is the plugin's to decide,
	 * because it is also the plugin's to remember; an id not in the list
	 * leaves the first entry selected, since any board is a fine place to add
	 * to and the picker says which.
	 */
	void setWatchlists(List<Watchlist> available, @Nullable String selectedId)
	{
		repopulating = true;
		try
		{
			final DefaultComboBoxModel<Watchlist> model = new DefaultComboBoxModel<>();
			Watchlist select = null;
			for (Watchlist watchlist : available)
			{
				// An id is what an edit is addressed to, so a row without one
				// is a row nothing can be added to or removed from.
				if (watchlist == null || watchlist.id == null || watchlist.id.isEmpty())
				{
					continue;
				}
				model.addElement(watchlist);
				if (watchlist.id.equals(selectedId))
				{
					select = watchlist;
				}
			}
			watchlists.setModel(model);
			if (select != null)
			{
				watchlists.setSelectedItem(select);
			}
			watchlists.setEnabled(model.getSize() > 0);
		}
		finally
		{
			repopulating = false;
		}
	}

	@Nullable
	String selectedWatchlistId()
	{
		final Object selected = watchlists.getSelectedItem();
		return selected == null ? null : ((Watchlist) selected).id;
	}

	/** Replaces the watchlist's rows, in the server's order. */
	void setWatchlistItems(List<WatchedItem> items)
	{
		stamp();
		watchlistProblem = null;
		watched = new ArrayList<>(items);
		refresh();
	}

	/**
	 * Updates one card's live-offer line, for a fill on a watched item.
	 *
	 * <p>Only the line is touched when the card already has one; the card is
	 * rebuilt only when the line appears or disappears, since that changes
	 * its height. Everything else on the card is unchanged by a fill.
	 */
	void updateWatchedOffer(int itemId, @Nullable String offer)
	{
		for (int i = 0; i < watched.size(); i++)
		{
			final WatchedItem item = watched.get(i);
			if (item.itemId != itemId)
			{
				continue;
			}
			if (java.util.Objects.equals(item.offer, offer))
			{
				return;
			}
			watched.set(i, new WatchedItem(item.itemId, item.name, item.image, item.price, item.limit, item.alch,
				offer, item.quote));
			final JLabel line = offerLines.get(itemId);
			if (line != null && offer != null && item.offer != null)
			{
				setWrappedText(line, offer);
				return;
			}
			refresh();
			return;
		}
	}

	/** The watchlists could not be read. Shown in the tab itself. */
	void setWatchlistProblem(String why)
	{
		watchlistProblem = why;
		watched = new ArrayList<>();
		refresh();
	}

	/**
	 * A note about the last edit: added, removed, refused. Null clears it;
	 * otherwise it clears itself after {@link #NOTICE_SECONDS}.
	 */
	void setWatchlistNotice(@Nullable String text, Color colour)
	{
		setNotice(watchlistNotice, watchlistNoticeTimer, text, colour);
	}

	@Override
	void redraw()
	{
		watchlistItems.removeAll();
		offerLines.clear();
		if (paused != null)
		{
			watchlistItems.add(small(paused));
		}
		else if (watchlistProblem != null)
		{
			final JLabel problem = small("Couldn't load your watchlists: " + watchlistProblem);
			problem.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			watchlistItems.add(problem);
		}
		else if (watched.isEmpty())
		{
			watchlistItems.add(small(watchlists.getItemCount() == 0
				? "No watchlist yet. Right-click an item in the Grand Exchange and choose \"Add to watchlist\" "
				+ "to start one."
				: "Nothing on this watchlist. Right-click an item in the Grand Exchange to add one."));
		}
		for (WatchedItem item : watched)
		{
			watchlistItems.add(watchedRow(item));
			watchlistItems.add(Box.createVerticalStrut(4));
		}
		watchlistItems.revalidate();
		watchlistItems.repaint();
	}

	/**
	 * One watched item, as a card: the sprite beside the name, then the site's
	 * prices, margin and ROI on their own wrapped lines, then the buttons.
	 *
	 * <p>Stacked rather than side by side because the sidebar is narrow;
	 * nothing here is truncated, the card grows to fit.
	 */
	private JPanel watchedRow(WatchedItem item)
	{
		final JPanel card = card();
		final String name = item.name == null || item.name.isEmpty() ? "Item " + item.itemId : item.name;

		final JPanel head = new JPanel(new BorderLayout(ICON_GAP, 0));
		head.setOpaque(false);
		head.setAlignmentX(Component.LEFT_ALIGNMENT);
		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(ICON_WIDTH, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setToolTipText(name);
		if (item.image != null)
		{
			item.image.addTo(icon);
		}
		head.add(icon, BorderLayout.WEST);
		final JLabel title = new JLabel();
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		setWrappedTextBesideIcon(title, name);
		head.add(title, BorderLayout.CENTER);
		card.add(head);
		card.add(Box.createVerticalStrut(4));

		if (item.quote != null)
		{
			final JLabel prices = small(pricesLine(item.quote));
			prices.setToolTipText("The price you can buy at and the price you can sell at right now, from flippingrs.com.");
			card.add(prices);
			final JLabel margin = small(marginLine(item.quote));
			margin.setForeground(item.quote.getNetMargin() < 0
				? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR);
			margin.setToolTipText("Profit per item after tax, and the return on what you'd pay.");
			card.add(margin);
			final String limits = limitLine(item);
			if (!limits.isEmpty())
			{
				card.add(small(limits));
			}
		}
		else
		{
			final JLabel facts = small(facts(item));
			facts.setToolTipText("RuneLite's price, the buy limit and the alch value. flippingrs.com has no prices for this item yet.");
			card.add(facts);
		}
		if (item.offer != null)
		{
			final JLabel offer = small(item.offer);
			offer.setForeground(ColorScheme.BRAND_ORANGE);
			card.add(offer);
			offerLines.put(item.itemId, offer);
		}
		card.add(Box.createVerticalStrut(5));

		final JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
		buttons.setOpaque(false);
		buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
		buttons.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		final JButton open = new JButton("Open");
		open.setToolTipText("Open " + name + " in your browser.");
		open.addActionListener(e -> actions.openItem(item.itemId));
		final JButton remove = new JButton("Remove");
		remove.setToolTipText("Remove from the watchlist.");
		remove.addActionListener(e -> actions.removeItem(item.itemId));
		for (JButton button : new JButton[]{open, remove})
		{
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setMargin(new Insets(1, 4, 1, 4));
			buttons.add(button);
		}
		card.add(buttons);

		// As tall as its content and no taller, so a short card does not get
		// stretched to share space with a long one.
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	// ---------------------------------------------------------- test seams

	/** The watched item ids as rendered, in order. */
	List<Integer> watchedForTest()
	{
		final List<Integer> ids = new ArrayList<>();
		for (WatchedItem item : watched)
		{
			ids.add(item.itemId);
		}
		return ids;
	}

	/** The live-offer line of a watched item's card, or null if it has none. */
	@Nullable
	String offerForTest(int itemId)
	{
		for (WatchedItem item : watched)
		{
			if (item.itemId == itemId)
			{
				return item.offer;
			}
		}
		return null;
	}

	/** The site's price line for a watched item, or null if it has no quote. */
	@Nullable
	String pricesForTest(int itemId)
	{
		for (WatchedItem item : watched)
		{
			if (item.itemId == itemId)
			{
				return item.quote == null ? null : pricesLine(item.quote);
			}
		}
		return null;
	}

	String noticeForTest()
	{
		return watchlistNotice.getText();
	}

	boolean noticeShowingForTest()
	{
		return watchlistNotice.isVisible() && !watchlistNotice.getText().isEmpty();
	}

	@Nullable
	String problemForTest()
	{
		return watchlistProblem;
	}

	Timer noticeTimerForTest()
	{
		return watchlistNoticeTimer;
	}

	JPanel listForTest()
	{
		return watchlistItems;
	}

	/** Selects by id the way a user clicking the combo box would. */
	void setSelectedForTest(String id)
	{
		for (int i = 0; i < watchlists.getItemCount(); i++)
		{
			if (id.equals(watchlists.getItemAt(i).id))
			{
				watchlists.setSelectedIndex(i);
				return;
			}
		}
		throw new IllegalArgumentException("no such watchlist in the list: " + id);
	}
}

package com.flippingrs;

import java.util.function.IntFunction;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;

/**
 * The site's prices on the exchange's two full-page offer screens, added to
 * each screen's own text rather than drawn on top of it or placed beside it.
 *
 * <p>Two screens because they are the same screen twice: the setup page, where
 * an offer is priced, and the status page you get by clicking an offer you
 * have already placed, where you decide whether the price you chose is still
 * the right one. That second question is the one this plugin exists to answer,
 * and the client builds both pages the same way -- an item, a description, the
 * guide price and the tax -- so both are written into identically.
 *
 * <p>Put on the end of the item's description, which is the line that already
 * sits between what the item is and how much of it you want. Appending to a
 * line the client wrote means the screen positions it, sizes it, wraps it and
 * clips it exactly as it does its own -- none of which has to be worked out
 * here, or kept right as Jagex moves the screen. A widget of this plugin's own
 * had to be placed, and a placement is a guess about somebody else's layout
 * that goes stale without warning.
 *
 * <p>Nothing the game says is lost: the description keeps its text, the guide
 * price and the tax are untouched, and the addition comes off again when the
 * screen closes or the item has no price.
 *
 * <p>Client thread only. Widgets may not be touched from anywhere else.
 */
@Slf4j
class GeOfferText
{
	/**
	 * Past this, the age of the prices is called out rather than merely
	 * stated. Five minutes: the site's data moves on a half-minute cadence, so
	 * ten times that is long enough to mean something is wrong rather than
	 * that the last refresh was a moment ago.
	 */
	private static final long STALE_SECONDS = 300;

	/** Colours, written as the game's own text renderer reads them. */
	private static final String MUTED = "9f9f9f";
	private static final String VALUE = "ffffff";
	private static final String GOOD = "4caf50";
	private static final String BAD = "d32f2f";

	private final Client client;
	private final FlippingRsConfig config;
	private final IntFunction<Quote> quoteFor;

	/**
	 * What has been added to each screen's description, and what it said
	 * before.
	 *
	 * <p>One each rather than one shared. Both pages exist at once -- the
	 * client builds them together and hides the one you are not on -- so a
	 * single record of "the line being added to" would hand the setup page's
	 * text back to the status page's description on the way past.
	 */
	private final Appended setup = new Appended();
	private final Appended status = new Appended();

	GeOfferText(Client client, FlippingRsConfig config, IntFunction<Quote> quoteFor)
	{
		this.client = client;
		this.config = config;
		this.quoteFor = quoteFor;
	}

	/**
	 * Brings the addition in line with the item being set up.
	 *
	 * <p>Called every tick the screen is open. The client rewrites the
	 * description whenever it rebuilds the screen, and {@link Appended} is what
	 * tells a rewrite apart from the text this put there; noticing it here
	 * rather than hooking every path that can do it is what stops a rebuild
	 * nobody predicted leaving the line missing or doubled.
	 *
	 * <p>Never throws. It runs from the event bus on the game thread, where an
	 * exception becomes an uncaught plugin error on every tick.
	 */
	void update()
	{
		try
		{
			// The setup page's item comes from the varp that drives it, the
			// same one RuneLite's own exchange plugin reads for the buy limit.
			write(setup, InterfaceID.GeOffers.SETUP_DESC,
				client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH));
			// The status page's comes off the screen, because the varp holds
			// whatever was last searched for rather than what this offer is
			// on -- which after a search and a click on a different slot is a
			// different item, and the price of the wrong one is worse than no
			// price at all.
			write(status, InterfaceID.GeOffers.DETAILS_DESC,
				GeItems.itemIn(client, InterfaceID.GeOffers.DETAILS));
		}
		catch (RuntimeException e)
		{
			log.debug("could not put the prices on an offer screen", e);
		}
	}

	/** Brings one screen's addition in line with the item it is showing. */
	private void write(Appended line, int descriptionId, int itemId)
	{
		final Widget description = client.getWidget(descriptionId);
		if (description == null || description.isHidden() || !config.setupOverlay())
		{
			// The screen is gone, or the setting is off. The addition goes
			// with it: prices frozen at whatever they were, on a screen they
			// no longer belong to, are worse than no prices.
			line.clear();
			return;
		}
		final Quote quote = itemId > 0 ? quoteFor.apply(itemId) : null;
		if (quote == null)
		{
			// No price for this item, which is every item before the first
			// fetch lands. The description goes back to being the game's.
			line.clear();
			return;
		}
		line.to(description, "<br>" + textFor(quote));
	}

	/**
	 * The client has just rebuilt one of these screens. {@link Appended} copes
	 * with that on its own; doing it here as well is what stops the line
	 * flickering as the screen opens.
	 */
	void rebuilt()
	{
		update();
	}

	/** Puts both descriptions back the way the game had them. */
	void reset()
	{
		setup.clear();
		status.clear();
	}

	/**
	 * What is added: the two prices and the margin, then the buy limit and how
	 * old the prices are.
	 *
	 * <p>One line. It is going on the end of somebody else's, and the
	 * description's box is only so tall. What qualifies the prices is folded
	 * onto the end rather than dropped: the buy limit, the day's volume and
	 * the age are what say whether the numbers before them can be acted on.
	 * The volume is shortened to "Vol" here and spelt out everywhere else,
	 * because this is the one place where the line has to stay a line.
	 *
	 * <p>Coloured with the colours themselves rather than with RuneLite's
	 * {@code <colNORMAL>} tokens, which are only turned into colours for
	 * message types it has a colour configured for and mean nothing at all to
	 * a widget.
	 *
	 * <p>Static, so the wording is pinned by a test rather than by running a
	 * client.
	 */
	static String textFor(Quote quote)
	{
		final StringBuilder out = new StringBuilder();
		out.append(colour("Buy ", MUTED)).append(colour(FlippingRsPanel.exact(quote.getBuyAt()), VALUE))
			.append(colour("  Sell ", MUTED)).append(colour(FlippingRsPanel.exact(quote.getSellAt()), VALUE))
			.append("  ").append(colour(FlippingRsPanel.signedExact(quote.getNetMargin()),
				quote.getNetMargin() >= 0 ? GOOD : BAD));

		final StringBuilder under = new StringBuilder();
		if (quote.hasLimitLeft())
		{
			under.append("Limit ").append(limitLeft(quote));
		}
		final String traded = FlippingRsPanel.volume(quote);
		if (traded != null)
		{
			// Before the age, because it qualifies the margin the way the
			// limit does: a margin on an item that barely trades is a number
			// you cannot act on however fresh it is.
			under.append(under.length() > 0 ? "  ·  " : "").append("Vol ").append(traded);
		}
		final String age = age(quote.getDataAgeSeconds());
		if (age != null)
		{
			under.append(under.length() > 0 ? "  ·  " : "").append("Priced ").append(age);
		}
		if (under.length() > 0)
		{
			out.append(colour("  ·  " + under, stale(quote) ? BAD : MUTED));
		}
		return out.toString();
	}

	/** One run of text in one colour, as the game's own text renderer reads it. */
	static String colour(String text, String hex)
	{
		return "<col=" + hex + ">" + text + "</col>";
	}

	/** Whether the prices are old enough that the margin is not worth trusting. */
	static boolean stale(Quote quote)
	{
		return quote.getDataAgeSeconds() > STALE_SECONDS;
	}

	/**
	 * "just now", "4m ago", "2h ago" -- as much precision as the answer
	 * deserves, and nothing at all when there is no answer.
	 *
	 * <p>A negative age means the item has never traded, which is not a fresh
	 * price and not a stale one: there is no price. Reading that as "just now"
	 * because it is a small number would put the most reassuring words on the
	 * screen in the one case where nothing is known.
	 */
	@Nullable
	static String age(long seconds)
	{
		if (seconds < 0)
		{
			return null;
		}
		if (seconds <= 60)
		{
			return "just now";
		}
		if (seconds < 3600)
		{
			return seconds / 60 + "m ago";
		}
		return seconds / 3600 + "h ago";
	}

	/**
	 * How much of the buy limit is left, and when it comes back if it is
	 * spent. The reset only matters once there is nothing left to buy: while
	 * there is, the number to act on is the number remaining.
	 */
	static String limitLeft(Quote quote)
	{
		final int left = quote.getLimitRemaining();
		if (left > 0)
		{
			return FlippingRsPanel.count(left);
		}
		final long resets = quote.getLimitResetsInSeconds();
		return resets > 0 ? "none for " + until(resets) : "none";
	}

	/** "1h 12m", "12m", "under a minute". */
	static String until(long seconds)
	{
		if (seconds < 60)
		{
			return "under a minute";
		}
		final long hours = seconds / 3600;
		final long minutes = seconds % 3600 / 60;
		if (hours == 0)
		{
			return minutes + "m";
		}
		return minutes == 0 ? hours + "h" : hours + "h " + minutes + "m";
	}

	/** The setup page's description as it now reads, for a test with a client. */
	@Nullable
	String textForTest()
	{
		return setup.textForTest();
	}

	/** And the status page's. */
	@Nullable
	String statusTextForTest()
	{
		return status.textForTest();
	}
}
